const MEMBERSHIP_SCOPE_MEMBERS_MAX_BYTES: usize = 1_024;
const MEMBERSHIP_SCOPE_BINDINGS_MAX_BYTES: usize = 32 * 1_024;
const MEMBERSHIP_HISTORY_MAX_ENTRIES: usize = 4_096;
const MEMBERSHIP_TRANSITION_ID_BYTES: usize = 16;
// v2 covers consumer request commitments that include the SDK-minted
// prepared-checkpoint protection/tenant scope context. Existing v1 outcome
// IDs therefore fail closed on a binding/digest mismatch; there is no
// permissive fallback for a protected prepared request.
const OUTCOME_DIGEST_DOMAIN: &[u8] = b"openpacketcore/session-consensus/outcome-payload/v2\0";
// Fenced-transition requests retain their independently published V1
// canonical digest; the generic outcome namespace version does not migrate it.
const FENCED_TRANSITION_PAYLOAD_DIGEST_DOMAIN: &[u8] =
    b"openpacketcore/session-consensus/outcome-payload/v1\0";
const FENCED_TRANSITION_RECEIPT_BINDING_DIGEST_DOMAIN: &[u8] =
    b"openpacketcore/session-consensus/fenced-transition-receipt-binding/v1\0";
const FENCED_TRANSITION_RECEIPT_RESPONSE_DIGEST_DOMAIN: &[u8] =
    b"openpacketcore/session-consensus/fenced-transition-receipt-response/v1\0";
/// The full fenced-transition receipt is short lived, but it is still bounded
/// independently of the generic consensus outcome table.  Once the recovery
/// window closes the row is compacted to its fixed-size ID/body tombstone.
/// Full outcome envelope allowance in addition to the public outcome bound.
pub(crate) const FENCED_TRANSITION_RECEIPT_MAX_RESPONSE_BYTES: usize =
    FENCED_TRANSITION_MAX_OUTCOME_BYTES + 1_024;
/// Exact byte width emitted by `format_rfc3339_normalized` for every RFC 3339
/// timestamp accepted by `Timestamp::from_str`.
pub(crate) const FENCED_TRANSITION_RECEIPT_TIMESTAMP_BYTES: usize = 30;
const FENCED_TRANSITION_RECEIPT_SCHEMA_SQL_MAX_BYTES: i64 = 4_096;
const CONSENSUS_SCHEMA_OBJECT_SQL_MAX_BYTES: i64 = 16 * 1024;
/// V1's activation fenced database readers at format two.  V2 is deliberately
/// a second, independently certified history protocol and writes format three
/// only from its replicated activation command.
// These are persisted on disk, so unlike the in-memory command/schema wire
// revision they must never be derived from a future `SESSION_*` bump.
const FENCED_TRANSITION_V1_DATABASE_FORMAT: i64 = 2;
const FENCED_TRANSITION_V2_DATABASE_FORMAT: i64 = 3;
/// Protected-roster activation is independent of both fenced-transition
/// formats. It must never reuse format three: a roster-only admission would
/// otherwise masquerade as a V2 receipt ledger before its terminal can apply.
const PROTECTED_ROSTER_DATABASE_FORMAT: i64 = 4;
const FENCED_TRANSITION_V2_RECEIPT_BINDING_DIGEST_DOMAIN: &[u8] =
    b"openpacketcore/session-consensus/fenced-transition-v2-receipt-binding/v1\0";
const FENCED_TRANSITION_V2_RECEIPT_RESPONSE_DIGEST_DOMAIN: &[u8] =
    b"openpacketcore/session-consensus/fenced-transition-v2-receipt-response/v1\0";
const FENCED_TRANSITION_V2_PAYLOAD_DIGEST_DOMAIN: &[u8] =
    b"openpacketcore/session-consensus/fenced-transition-v2/payload/v1\0";
/// Fixed, versioned, non-Serde receipt-response representation for V2.  V1
/// deliberately continues to store its historical JSON envelope unchanged.
const FENCED_TRANSITION_V2_RESPONSE_SUCCESS: u8 = 1;
const FENCED_TRANSITION_V2_RESPONSE_TOPOLOGY_AUTHORITY_REVOKED: u8 = 16;
const FENCED_TRANSITION_V2_RESPONSE_NOT_FOUND: u8 = 17;
