/// Restart-safe progress for one exact membership transition.
///
/// Identifiers and digests are accepted as lookup keys and deliberately not
/// returned or formatted, keeping status reporting redaction-safe.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) struct MembershipTransitionEvidence {
    pub(crate) outcome: Option<TerminalMembershipOutcome>,
    pub(crate) transition_start_log_index: u64,
    pub(crate) learners_ready_log_index: Option<u64>,
    pub(crate) joint_membership_log_index: Option<u64>,
    pub(crate) uniform_membership_log_index: Option<u64>,
    pub(crate) cutover_log_index: Option<u64>,
    pub(crate) finalization_log_index: Option<u64>,
    pub(crate) abort_decision_log_index: Option<u64>,
    pub(crate) abort_cleanup_log_index: Option<u64>,
}

fn retained_transition_digest(
    scope: &MembershipValidationScope,
    transition_id: [u8; MEMBERSHIP_TRANSITION_ID_BYTES],
) -> io::Result<Option<[u8; 32]>> {
    let mut retained = None;
    for (candidate_id, candidate_digest) in scope
        .terminal
        .iter()
        .map(|terminal| (terminal.transition_id, terminal.transition_digest))
        .chain(
            scope
                .terminal_history
                .iter()
                .map(|terminal| (terminal.transition_id, terminal.transition_digest)),
        )
        .chain(
            scope
                .predecessor
                .iter()
                .map(|predecessor| (predecessor.transition_id, predecessor.transition_digest)),
        )
        .chain(
            scope
                .history
                .iter()
                .map(|predecessor| (predecessor.transition_id, predecessor.transition_digest)),
        )
    {
        if candidate_id != transition_id {
            continue;
        }
        if retained.is_some_and(|digest| digest != candidate_digest) {
            return Err(invalid_data(
                "session consensus transition ID history conflicts",
            ));
        }
        retained = Some(candidate_digest);
    }
    Ok(retained)
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum MembershipScopeMutation {
    Applied,
    Idempotent,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum MembershipScopeMutationError {
    InvalidScope,
    ConflictingTransition,
    CompactionRequired,
    TransitionNotQuiescent,
    BackendUnavailable,
    CorruptState,
}

#[cfg(test)]
#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) struct DroppedMembershipPredecessor {
    /// Snapshot metadata invalidated by the compaction proof. The caller owns
    /// redaction-safe deletion of the SDK-controlled file after commit.
    pub(crate) invalidated_snapshot_file: Option<String>,
}

impl fmt::Display for MembershipScopeMutationError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter.write_str(match self {
            Self::InvalidScope => "session consensus membership scope is invalid",
            Self::ConflictingTransition => {
                "a different session consensus membership transition is active"
            }
            Self::CompactionRequired => {
                "session consensus membership history requires snapshot compaction"
            }
            Self::TransitionNotQuiescent => {
                "session consensus membership transition is not quiescent"
            }
            Self::BackendUnavailable => "session consensus membership storage is unavailable",
            Self::CorruptState => "session consensus membership storage is corrupt",
        })
    }
}

impl std::error::Error for MembershipScopeMutationError {}

fn membership_scope_error(error: MembershipScopeMutationError) -> io::Error {
    match error {
        MembershipScopeMutationError::BackendUnavailable => {
            io::Error::other("session consensus membership storage is unavailable")
        }
        MembershipScopeMutationError::InvalidScope
        | MembershipScopeMutationError::ConflictingTransition
        | MembershipScopeMutationError::CompactionRequired
        | MembershipScopeMutationError::TransitionNotQuiescent
        | MembershipScopeMutationError::CorruptState => {
            invalid_data("session consensus membership storage is inconsistent")
        }
    }
}

const CONSENSUS_SCHEMA: &str = r#"
CREATE TABLE consensus_identity (
    singleton INTEGER PRIMARY KEY CHECK (singleton = 1),
    schema_version INTEGER NOT NULL,
    cluster_id BLOB NOT NULL CHECK (length(cluster_id) = 32),
    configuration_id BLOB NOT NULL CHECK (length(configuration_id) = 32),
    configuration_epoch INTEGER NOT NULL UNIQUE CHECK (configuration_epoch > 0),
    authority_profile INTEGER NOT NULL DEFAULT 1 CHECK (authority_profile IN (1, 2)),
    fixed_placement_policy INTEGER CHECK (fixed_placement_policy IN (1, 2)),
    fenced_transition_receipt_ledger_activated INTEGER NOT NULL DEFAULT 0 CHECK (
        fenced_transition_receipt_ledger_activated IN (0, 1)
    )
);

CREATE TABLE consensus_membership_scope (
    singleton INTEGER PRIMARY KEY CHECK (singleton = 1),
    storage_configuration_epoch INTEGER NOT NULL CHECK (storage_configuration_epoch > 0),
    current_configuration_id BLOB NOT NULL CHECK (length(current_configuration_id) = 32),
    current_configuration_epoch INTEGER NOT NULL CHECK (current_configuration_epoch > 0),
    current_members_json BLOB NOT NULL CHECK (
        length(current_members_json) BETWEEN 2 AND 1024
    ),
    current_bindings_json BLOB NOT NULL CHECK (
        length(current_bindings_json) BETWEEN 2 AND 32768
    ),
    application_authority_epoch INTEGER NOT NULL CHECK (
        application_authority_epoch > 0
    ),
    application_authority_members_json BLOB NOT NULL CHECK (
        length(application_authority_members_json) BETWEEN 2 AND 1024
    ),
    predecessor_configuration_id BLOB CHECK (
        predecessor_configuration_id IS NULL OR length(predecessor_configuration_id) = 32
    ),
    predecessor_transition_id BLOB CHECK (
        predecessor_transition_id IS NULL OR length(predecessor_transition_id) = 16
    ),
    predecessor_transition_digest BLOB CHECK (
        predecessor_transition_digest IS NULL OR length(predecessor_transition_digest) = 32
    ),
    predecessor_configuration_epoch INTEGER,
    predecessor_members_json BLOB CHECK (
        predecessor_members_json IS NULL
        OR length(predecessor_members_json) BETWEEN 2 AND 1024
    ),
    predecessor_transition_start_index INTEGER CHECK (
        predecessor_transition_start_index IS NULL
        OR predecessor_transition_start_index >= 0
    ),
    predecessor_cutover_index INTEGER CHECK (
        predecessor_cutover_index IS NULL OR predecessor_cutover_index >= 0
    ),
    pending_transition_id BLOB CHECK (
        pending_transition_id IS NULL OR length(pending_transition_id) = 16
    ),
    pending_transition_digest BLOB CHECK (
        pending_transition_digest IS NULL OR length(pending_transition_digest) = 32
    ),
    desired_configuration_id BLOB CHECK (
        desired_configuration_id IS NULL OR length(desired_configuration_id) = 32
    ),
    desired_configuration_epoch INTEGER,
    desired_members_json BLOB CHECK (
        desired_members_json IS NULL OR length(desired_members_json) BETWEEN 2 AND 1024
    ),
    desired_bindings_json BLOB CHECK (
        desired_bindings_json IS NULL OR length(desired_bindings_json) BETWEEN 2 AND 32768
    ),
    pending_transition_start_index INTEGER CHECK (
        pending_transition_start_index IS NULL OR pending_transition_start_index >= 0
    ),
    pending_learners_ready_index INTEGER CHECK (
        pending_learners_ready_index IS NULL OR pending_learners_ready_index >= 0
    ),
    pending_joint_membership_index INTEGER CHECK (
        pending_joint_membership_index IS NULL OR pending_joint_membership_index >= 0
    ),
    pending_uniform_membership_index INTEGER CHECK (
        pending_uniform_membership_index IS NULL OR pending_uniform_membership_index >= 0
    ),
    terminal_transition_id BLOB CHECK (
        terminal_transition_id IS NULL OR length(terminal_transition_id) = 16
    ),
    terminal_transition_digest BLOB CHECK (
        terminal_transition_digest IS NULL OR length(terminal_transition_digest) = 32
    ),
    terminal_transition_outcome INTEGER CHECK (
        terminal_transition_outcome IS NULL OR terminal_transition_outcome IN (1, 2)
    ),
    terminal_transition_start_index INTEGER CHECK (
        terminal_transition_start_index IS NULL OR terminal_transition_start_index >= 0
    ),
    terminal_learners_ready_index INTEGER CHECK (
        terminal_learners_ready_index IS NULL OR terminal_learners_ready_index >= 0
    ),
    terminal_joint_membership_index INTEGER CHECK (
        terminal_joint_membership_index IS NULL OR terminal_joint_membership_index >= 0
    ),
    terminal_uniform_membership_index INTEGER CHECK (
        terminal_uniform_membership_index IS NULL OR terminal_uniform_membership_index >= 0
    ),
    terminal_cutover_index INTEGER CHECK (
        terminal_cutover_index IS NULL OR terminal_cutover_index >= 0
    ),
    terminal_finalization_index INTEGER CHECK (
        terminal_finalization_index IS NULL OR terminal_finalization_index >= 0
    ),
    terminal_desired_configuration_id BLOB CHECK (
        terminal_desired_configuration_id IS NULL
        OR length(terminal_desired_configuration_id) = 32
    ),
    terminal_desired_configuration_epoch INTEGER,
    terminal_desired_members_json BLOB CHECK (
        terminal_desired_members_json IS NULL
        OR length(terminal_desired_members_json) BETWEEN 2 AND 1024
    ),
    terminal_desired_bindings_json BLOB CHECK (
        terminal_desired_bindings_json IS NULL
        OR length(terminal_desired_bindings_json) BETWEEN 2 AND 32768
    ),
    terminal_abort_learners_json BLOB CHECK (
        terminal_abort_learners_json IS NULL
        OR length(terminal_abort_learners_json) BETWEEN 2 AND 1024
    ),
    terminal_abort_decision_index INTEGER CHECK (
        terminal_abort_decision_index IS NULL OR terminal_abort_decision_index >= 0
    ),
    terminal_abort_cleanup_membership_index INTEGER CHECK (
        terminal_abort_cleanup_membership_index IS NULL
        OR terminal_abort_cleanup_membership_index >= 0
    ),
    CHECK (
        (predecessor_configuration_id IS NULL
         AND predecessor_transition_id IS NULL
         AND predecessor_transition_digest IS NULL
         AND predecessor_configuration_epoch IS NULL
         AND predecessor_members_json IS NULL
         AND predecessor_transition_start_index IS NULL
         AND predecessor_cutover_index IS NULL)
        OR
        (predecessor_configuration_id IS NOT NULL
         AND predecessor_transition_id IS NOT NULL
         AND predecessor_transition_digest IS NOT NULL
         AND predecessor_configuration_epoch IS NOT NULL
         AND predecessor_members_json IS NOT NULL
         AND predecessor_transition_start_index IS NOT NULL
         AND predecessor_cutover_index IS NOT NULL
         AND predecessor_configuration_epoch < current_configuration_epoch
         AND predecessor_transition_start_index <= predecessor_cutover_index)
    ),
    CHECK (
        application_authority_epoch = current_configuration_epoch
        OR application_authority_epoch = desired_configuration_epoch
    ),
    CHECK (
        (pending_transition_id IS NULL
         AND pending_transition_digest IS NULL
         AND desired_configuration_id IS NULL
         AND desired_configuration_epoch IS NULL
         AND desired_members_json IS NULL
         AND desired_bindings_json IS NULL
         AND pending_transition_start_index IS NULL
         AND pending_learners_ready_index IS NULL
         AND pending_joint_membership_index IS NULL
         AND pending_uniform_membership_index IS NULL)
        OR
        (pending_transition_id IS NOT NULL
         AND pending_transition_digest IS NOT NULL
         AND desired_configuration_id IS NOT NULL
         AND desired_configuration_epoch IS NOT NULL
         AND desired_members_json IS NOT NULL
         AND desired_bindings_json IS NOT NULL
         AND pending_transition_start_index IS NOT NULL
         AND desired_configuration_epoch = current_configuration_epoch + 1
         AND desired_configuration_id != current_configuration_id
         AND (pending_learners_ready_index IS NULL
              OR pending_learners_ready_index > pending_transition_start_index)
         AND (pending_joint_membership_index IS NULL
              OR (pending_learners_ready_index IS NOT NULL
                  AND pending_joint_membership_index > pending_learners_ready_index))
         AND (pending_uniform_membership_index IS NULL
              OR (pending_joint_membership_index IS NOT NULL
                  AND pending_uniform_membership_index > pending_joint_membership_index)))
    ),
    CHECK (
        (terminal_transition_id IS NULL
         AND terminal_transition_digest IS NULL
         AND terminal_transition_outcome IS NULL
         AND terminal_transition_start_index IS NULL
         AND terminal_learners_ready_index IS NULL
         AND terminal_joint_membership_index IS NULL
         AND terminal_uniform_membership_index IS NULL
         AND terminal_cutover_index IS NULL
         AND terminal_finalization_index IS NULL
         AND terminal_desired_configuration_id IS NULL
         AND terminal_desired_configuration_epoch IS NULL
         AND terminal_desired_members_json IS NULL
         AND terminal_desired_bindings_json IS NULL
         AND terminal_abort_learners_json IS NULL
         AND terminal_abort_decision_index IS NULL
         AND terminal_abort_cleanup_membership_index IS NULL)
        OR
        (terminal_transition_id IS NOT NULL
         AND terminal_transition_digest IS NOT NULL
         AND terminal_transition_outcome IS NOT NULL
         AND terminal_transition_start_index IS NOT NULL
         AND (terminal_learners_ready_index IS NULL
              OR terminal_learners_ready_index > terminal_transition_start_index)
         AND (terminal_joint_membership_index IS NULL
              OR (terminal_learners_ready_index IS NOT NULL
                  AND terminal_joint_membership_index > terminal_learners_ready_index))
         AND (terminal_uniform_membership_index IS NULL
              OR (terminal_joint_membership_index IS NOT NULL
                  AND terminal_uniform_membership_index > terminal_joint_membership_index))
         AND ((terminal_transition_outcome = 1
               AND terminal_joint_membership_index IS NULL
               AND terminal_uniform_membership_index IS NULL
               AND terminal_cutover_index IS NULL
               AND terminal_finalization_index IS NULL
               AND terminal_desired_configuration_id IS NOT NULL
               AND terminal_desired_configuration_epoch = current_configuration_epoch + 1
               AND terminal_desired_members_json IS NOT NULL
               AND terminal_desired_bindings_json IS NOT NULL
               AND terminal_abort_learners_json IS NOT NULL
               AND terminal_abort_decision_index IS NOT NULL
               AND terminal_abort_decision_index > terminal_transition_start_index
               AND (terminal_learners_ready_index IS NULL
                    OR terminal_abort_decision_index > terminal_learners_ready_index)
               AND (terminal_abort_cleanup_membership_index IS NULL
                    OR terminal_abort_cleanup_membership_index > terminal_abort_decision_index))
              OR (terminal_transition_outcome = 2
                  AND terminal_uniform_membership_index IS NOT NULL
                  AND terminal_cutover_index IS NOT NULL
                  AND terminal_cutover_index >= terminal_uniform_membership_index
                  AND (terminal_finalization_index IS NULL
                       OR terminal_finalization_index > terminal_cutover_index)
                  AND terminal_desired_configuration_id IS NULL
                  AND terminal_desired_configuration_epoch IS NULL
                  AND terminal_desired_members_json IS NULL
                  AND terminal_desired_bindings_json IS NULL
                  AND terminal_abort_learners_json IS NULL
                  AND terminal_abort_decision_index IS NULL
                  AND terminal_abort_cleanup_membership_index IS NULL)))
    ),
    FOREIGN KEY(storage_configuration_epoch)
        REFERENCES consensus_identity(configuration_epoch)
);

CREATE TABLE consensus_membership_history (
    configuration_epoch INTEGER PRIMARY KEY CHECK (configuration_epoch > 0),
    storage_configuration_epoch INTEGER NOT NULL CHECK (storage_configuration_epoch > 0),
    configuration_id BLOB NOT NULL CHECK (length(configuration_id) = 32),
    members_json BLOB NOT NULL CHECK (length(members_json) BETWEEN 2 AND 1024),
    transition_id BLOB NOT NULL CHECK (length(transition_id) = 16),
    transition_digest BLOB NOT NULL CHECK (length(transition_digest) = 32),
    transition_start_index INTEGER NOT NULL CHECK (transition_start_index >= 0),
    cutover_index INTEGER NOT NULL CHECK (
        cutover_index >= transition_start_index
    ),
    FOREIGN KEY(storage_configuration_epoch)
        REFERENCES consensus_identity(configuration_epoch)
);

CREATE TABLE consensus_membership_terminal_history (
    transition_id BLOB PRIMARY KEY CHECK (length(transition_id) = 16),
    storage_configuration_epoch INTEGER NOT NULL CHECK (storage_configuration_epoch > 0),
    transition_digest BLOB NOT NULL CHECK (length(transition_digest) = 32),
    outcome INTEGER NOT NULL CHECK (outcome IN (1, 2)),
    expected_member_count INTEGER NOT NULL CHECK (expected_member_count > 0),
    transition_start_index INTEGER NOT NULL CHECK (transition_start_index >= 0),
    learners_ready_index INTEGER CHECK (
        learners_ready_index IS NULL OR learners_ready_index > transition_start_index
    ),
    joint_membership_index INTEGER CHECK (
        joint_membership_index IS NULL
        OR (learners_ready_index IS NOT NULL
            AND joint_membership_index > learners_ready_index)
    ),
    uniform_membership_index INTEGER CHECK (
        uniform_membership_index IS NULL
        OR (joint_membership_index IS NOT NULL
            AND uniform_membership_index > joint_membership_index)
    ),
    cutover_index INTEGER CHECK (
        cutover_index IS NULL
        OR (uniform_membership_index IS NOT NULL
            AND cutover_index >= uniform_membership_index)
    ),
    finalization_index INTEGER CHECK (
        finalization_index IS NULL
        OR (cutover_index IS NOT NULL AND finalization_index > cutover_index)
    ),
    abort_decision_index INTEGER CHECK (
        abort_decision_index IS NULL OR abort_decision_index > transition_start_index
    ),
    abort_cleanup_membership_index INTEGER CHECK (
        abort_cleanup_membership_index IS NULL
        OR (abort_decision_index IS NOT NULL
            AND abort_cleanup_membership_index > abort_decision_index)
    ),
    CHECK (
        (outcome = 1
         AND joint_membership_index IS NULL
         AND uniform_membership_index IS NULL
         AND cutover_index IS NULL
         AND finalization_index IS NULL
         AND abort_decision_index IS NOT NULL
         AND abort_cleanup_membership_index IS NOT NULL)
        OR
        (outcome = 2
         AND joint_membership_index IS NOT NULL
         AND uniform_membership_index IS NOT NULL
         AND cutover_index IS NOT NULL
         AND finalization_index IS NOT NULL
         AND abort_decision_index IS NULL
         AND abort_cleanup_membership_index IS NULL)
    ),
    FOREIGN KEY(storage_configuration_epoch)
        REFERENCES consensus_identity(configuration_epoch)
);

CREATE TABLE consensus_candidate_bootstrap (
    singleton INTEGER PRIMARY KEY CHECK (singleton = 1),
    storage_configuration_epoch INTEGER NOT NULL CHECK (storage_configuration_epoch > 0),
    local_candidate_node_id INTEGER NOT NULL CHECK (local_candidate_node_id > 0),
    transition_id BLOB NOT NULL CHECK (length(transition_id) = 16),
    transition_digest BLOB NOT NULL CHECK (length(transition_digest) = 32),
    state INTEGER NOT NULL CHECK (state IN (1, 2)),
    FOREIGN KEY(storage_configuration_epoch)
        REFERENCES consensus_identity(configuration_epoch)
);

CREATE TABLE consensus_vote (
    singleton INTEGER PRIMARY KEY CHECK (singleton = 1),
    configuration_epoch INTEGER NOT NULL CHECK (configuration_epoch > 0),
    term INTEGER NOT NULL CHECK (term >= 0),
    node_id INTEGER CHECK (node_id > 0),
    vote_json BLOB NOT NULL,
    FOREIGN KEY(configuration_epoch) REFERENCES consensus_identity(configuration_epoch)
);

CREATE TABLE consensus_committed (
    singleton INTEGER PRIMARY KEY CHECK (singleton = 1),
    configuration_epoch INTEGER NOT NULL CHECK (configuration_epoch > 0),
    term INTEGER NOT NULL CHECK (term >= 0),
    log_index INTEGER NOT NULL CHECK (log_index >= 0),
    log_id_json BLOB NOT NULL,
    FOREIGN KEY(configuration_epoch) REFERENCES consensus_identity(configuration_epoch)
);

CREATE TABLE consensus_purged (
    singleton INTEGER PRIMARY KEY CHECK (singleton = 1),
    configuration_epoch INTEGER NOT NULL CHECK (configuration_epoch > 0),
    term INTEGER NOT NULL CHECK (term >= 0),
    log_index INTEGER NOT NULL CHECK (log_index >= 0),
    log_id_json BLOB NOT NULL,
    FOREIGN KEY(configuration_epoch) REFERENCES consensus_identity(configuration_epoch)
);

CREATE TABLE consensus_log (
    log_index INTEGER PRIMARY KEY CHECK (log_index >= 0),
    configuration_epoch INTEGER NOT NULL CHECK (configuration_epoch > 0),
    term INTEGER NOT NULL CHECK (term >= 0),
    entry_json BLOB NOT NULL CHECK (length(entry_json) > 0),
    FOREIGN KEY(configuration_epoch) REFERENCES consensus_identity(configuration_epoch)
);

CREATE TABLE consensus_applied (
    singleton INTEGER PRIMARY KEY CHECK (singleton = 1),
    configuration_epoch INTEGER NOT NULL CHECK (configuration_epoch > 0),
    term INTEGER NOT NULL CHECK (term >= 0),
    log_index INTEGER NOT NULL CHECK (log_index >= 0),
    log_id_json BLOB NOT NULL,
    FOREIGN KEY(configuration_epoch) REFERENCES consensus_identity(configuration_epoch)
);

CREATE TABLE consensus_membership (
    singleton INTEGER PRIMARY KEY CHECK (singleton = 1),
    configuration_epoch INTEGER NOT NULL CHECK (configuration_epoch > 0),
    membership_json BLOB NOT NULL,
    FOREIGN KEY(configuration_epoch) REFERENCES consensus_identity(configuration_epoch)
);

CREATE TABLE consensus_machine (
    singleton INTEGER PRIMARY KEY CHECK (singleton = 1),
    configuration_epoch INTEGER NOT NULL CHECK (configuration_epoch > 0),
    application_sequence INTEGER NOT NULL CHECK (application_sequence >= 0),
    last_digest BLOB NOT NULL CHECK (length(last_digest) = 32),
    logical_time TEXT,
    watch_sequence INTEGER NOT NULL CHECK (watch_sequence >= 0),
    FOREIGN KEY(configuration_epoch) REFERENCES consensus_identity(configuration_epoch)
);

CREATE TABLE consensus_request_outcomes (
    request_id BLOB PRIMARY KEY CHECK (length(request_id) = 16),
    configuration_epoch INTEGER NOT NULL CHECK (configuration_epoch > 0),
    payload_digest BLOB NOT NULL CHECK (length(payload_digest) = 32),
    response_json BLOB NOT NULL,
    FOREIGN KEY(configuration_epoch) REFERENCES consensus_identity(configuration_epoch)
);

CREATE TABLE consensus_fenced_transition_receipts (
    request_id BLOB NOT NULL PRIMARY KEY CHECK (
        length(request_id) = 16
        AND request_id != X'00000000000000000000000000000000'
    ),
    configuration_epoch INTEGER NOT NULL CHECK (configuration_epoch > 0),
    payload_digest BLOB NOT NULL CHECK (length(payload_digest) = 32),
    retained_until TEXT NOT NULL CHECK (octet_length(retained_until) = 30),
    binding_digest BLOB NOT NULL CHECK (length(binding_digest) = 32),
    response_json BLOB CHECK (
        response_json IS NULL
        OR length(response_json) BETWEEN 1 AND 17408
    ),
    response_digest BLOB CHECK (
        response_digest IS NULL OR length(response_digest) = 32
    ),
    CHECK (
        (response_json IS NULL AND response_digest IS NULL)
        OR (response_json IS NOT NULL AND response_digest IS NOT NULL)
    ),
    FOREIGN KEY(configuration_epoch) REFERENCES consensus_identity(configuration_epoch)
);

CREATE INDEX consensus_fenced_transition_receipts_due
    ON consensus_fenced_transition_receipts (retained_until, request_id)
    WHERE response_json IS NOT NULL;

CREATE TABLE consensus_fenced_transition_activation (
    singleton INTEGER PRIMARY KEY CHECK (singleton = 1),
    storage_configuration_epoch INTEGER NOT NULL CHECK (storage_configuration_epoch > 0),
    scope_configuration_id BLOB NOT NULL CHECK (length(scope_configuration_id) = 32),
    scope_configuration_epoch INTEGER NOT NULL CHECK (scope_configuration_epoch > 0),
    voter_set_digest BLOB NOT NULL CHECK (length(voter_set_digest) = 32),
    FOREIGN KEY(storage_configuration_epoch)
        REFERENCES consensus_identity(configuration_epoch)
);

CREATE TABLE consensus_snapshot (
    singleton INTEGER PRIMARY KEY CHECK (singleton = 1),
    configuration_epoch INTEGER NOT NULL CHECK (configuration_epoch > 0),
    meta_json BLOB NOT NULL,
    file_name TEXT NOT NULL CHECK (length(file_name) > 0),
    checksum BLOB NOT NULL CHECK (length(checksum) = 32),
    byte_length INTEGER NOT NULL CHECK (byte_length > 0),
    FOREIGN KEY(configuration_epoch) REFERENCES consensus_identity(configuration_epoch)
);

CREATE TABLE consensus_operator_recovery (
    singleton INTEGER PRIMARY KEY CHECK (singleton = 1),
    configuration_epoch INTEGER NOT NULL CHECK (configuration_epoch > 0),
    recovery_epoch INTEGER NOT NULL CHECK (recovery_epoch >= 0),
    last_plan_digest BLOB NOT NULL CHECK (length(last_plan_digest) = 32),
    pending_epoch INTEGER CHECK (pending_epoch > recovery_epoch),
    pending_plan_digest BLOB CHECK (
        pending_plan_digest IS NULL OR length(pending_plan_digest) = 32
    ),
    watch_cursor_invalidation_floor INTEGER NOT NULL CHECK (watch_cursor_invalidation_floor >= 0),
    CHECK (
        (pending_epoch IS NULL AND pending_plan_digest IS NULL)
        OR (pending_epoch IS NOT NULL AND pending_plan_digest IS NOT NULL)
    ),
    FOREIGN KEY(configuration_epoch) REFERENCES consensus_identity(configuration_epoch)
);
"#;

/// Install the exact consensus DDL used by production into an empty schema.
///
/// Recovery uses this only to derive a canonical, bounded schema manifest. A
/// boolean selects the supported add-on form created when an older current
/// database first gains the operator-recovery table.
pub(crate) fn install_recovery_validation_schema_sync(
    conn: &Connection,
    operator_recovery_add_on: bool,
) -> io::Result<()> {
    if operator_recovery_add_on {
        conn.execute_batch(OPERATOR_RECOVERY_SCHEMA)
            .map_err(db_error)?;
    } else {
        conn.execute_batch(CONSENSUS_SCHEMA).map_err(db_error)?;
    }
    Ok(())
}

/// Reproduce the supported pre-cursor operator-recovery schema migration.
///
/// SQLite records `ALTER TABLE ... ADD COLUMN` by appending the column to the
/// original `sqlite_master.sql` text, so its canonical DDL is distinct from a
/// table created directly at the current version. Recovery must recognize the
/// result without weakening validation to column-name checks.
pub(crate) fn install_migrated_operator_recovery_validation_schema_sync(
    conn: &Connection,
) -> io::Result<()> {
    conn.execute_batch(PRE_CURSOR_OPERATOR_RECOVERY_SCHEMA)
        .map_err(db_error)?;
    conn.execute_batch(OPERATOR_RECOVERY_CURSOR_MIGRATION)
        .map_err(db_error)
}

/// One store-scoped, coalescing SQLite PASSIVE checkpoint lane.
///
/// The primary writer keeps its existing automatic checkpoint fallback. This
/// lane only requests best-effort PASSIVE work after a durable consensus
/// commit; it has no authority to delay or alter that commit's response.
/// A descriptor-pinned identity check before and after every checkpoint makes
/// a renamed or replaced backing file a local worker failure rather than an
/// operation against a path-selected successor.
//
// The primary writer's unchanged 1,000-page automatic checkpoint remains the
// resource and durability fallback. This lane is only an optimization, so its
// fixed durable-write cadence is deliberately much smaller than that fallback
// in the least-dense one-WAL-page-per-write case, without claiming a page
// bound for larger bounded transactions.
const PROACTIVE_CHECKPOINT_DURABLE_WRITE_BATCH: u64 = 64;
/// Physical pruning is deliberately bounded independently of the logical
/// Openraft purge acknowledgement.  The floor is durable before this lane is
/// signalled, so a cancelled or failed turn may retain disk space but can
/// never resurrect a compacted log prefix.
const CONSENSUS_LOG_PRUNE_ROWS_PER_TURN: usize = 128;
const CONSENSUS_LOG_PRUNE_BYTES_PER_TURN: usize = 16 * 1024 * 1024;
/// This deliberately modest delay makes a held SQLite writer yield to the
/// primary connection and prevents a capacity-one worker from self-spinning.
const CONSENSUS_LOG_PRUNE_RETRY_PACING: Duration = Duration::from_millis(10);

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum ConsensusLogPruneTurnError {
    TransientContention,
    PreemptedByPrimary,
    Interrupted,
    Permanent,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct ConsensusLogPruneTurnCompletion {
    more: bool,
    rows_deleted: u64,
    encoded_bytes_deleted: u64,
}

fn classify_consensus_log_prune_sqlite_error(
    error: &rusqlite::Error,
) -> ConsensusLogPruneTurnError {
    match error {
        rusqlite::Error::SqliteFailure(failure, _)
            if matches!(
                failure.code,
                rusqlite::ErrorCode::DatabaseBusy | rusqlite::ErrorCode::DatabaseLocked
            ) =>
        {
            ConsensusLogPruneTurnError::TransientContention
        }
        rusqlite::Error::SqliteFailure(failure, _)
            if failure.code == rusqlite::ErrorCode::OperationInterrupted =>
        {
            ConsensusLogPruneTurnError::Interrupted
        }
        _ => ConsensusLogPruneTurnError::Permanent,
    }
}

fn consensus_log_prune_permanent<T>(_error: T) -> ConsensusLogPruneTurnError {
    ConsensusLogPruneTurnError::Permanent
}

#[cfg(all(test, target_os = "linux"))]
#[derive(Default)]
struct ConsensusLogPruneTurnGateState {
    armed: bool,
    entered: bool,
    released: bool,
    preempted: bool,
    progress_preempted: bool,
    progress_steps_before_preempt: usize,
    progress_steps_seen: usize,
    completed: bool,
}

#[cfg(all(test, target_os = "linux"))]
#[derive(Clone, Copy, Eq, PartialEq)]
enum ConsensusLogPruneTurnGatePoint {
    BeforeTransaction,
    BeforeActiveInterrupt,
    AfterWriterAcquired,
    BeforeAuthorityRead,
    BeforeReadPurged,
    BeforeDelete,
    MidDelete,
    BeforeCommit,
}

/// Test-only, directory-scoped gate for a real lane turn.  It is installed
/// only after the fixture is durable, so it cannot alter schema setup or any
/// unrelated temporary database.
#[cfg(all(test, target_os = "linux"))]
struct ConsensusLogPruneTurnGate {
    point: ConsensusLogPruneTurnGatePoint,
    state: Mutex<ConsensusLogPruneTurnGateState>,
    entered: Condvar,
    released: Condvar,
    completed: tokio::sync::Notify,
}

#[cfg(all(test, target_os = "linux"))]
impl ConsensusLogPruneTurnGate {
    fn wait_before_prune(&self) -> bool {
        if self.point != ConsensusLogPruneTurnGatePoint::BeforeTransaction {
            return false;
        }
        let mut state = self
            .state
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        if !state.armed {
            return false;
        }
        state.entered = true;
        self.entered.notify_all();
        while !state.released {
            state = self
                .released
                .wait(state)
                .unwrap_or_else(std::sync::PoisonError::into_inner);
        }
        state.armed = false;
        true
    }

    fn wait_before_active_interrupt(&self) {
        if self.point != ConsensusLogPruneTurnGatePoint::BeforeActiveInterrupt {
            return;
        }
        let mut state = self
            .state
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        if !state.armed {
            return;
        }
        state.entered = true;
        self.entered.notify_all();
        while !state.released {
            state = self
                .released
                .wait(state)
                .unwrap_or_else(std::sync::PoisonError::into_inner);
        }
        state.armed = false;
    }

    fn wait_after_writer_acquired(&self) -> bool {
        if self.point != ConsensusLogPruneTurnGatePoint::AfterWriterAcquired {
            return false;
        }
        let mut state = self
            .state
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        if !state.armed {
            return false;
        }
        state.entered = true;
        self.entered.notify_all();
        while !state.released && !state.preempted {
            state = self
                .released
                .wait(state)
                .unwrap_or_else(std::sync::PoisonError::into_inner);
        }
        state.armed = false;
        state.preempted
    }

    fn wait_at(&self, point: ConsensusLogPruneTurnGatePoint) {
        if self.point != point
            && !(self.point == ConsensusLogPruneTurnGatePoint::MidDelete
                && point == ConsensusLogPruneTurnGatePoint::BeforeDelete)
        {
            return;
        }
        let mut state = self
            .state
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        if !state.armed {
            return;
        }
        state.entered = true;
        self.entered.notify_all();
        while !state.released {
            state = self
                .released
                .wait(state)
                .unwrap_or_else(std::sync::PoisonError::into_inner);
        }
        state.armed = false;
    }

    fn release(&self) {
        let mut state = self
            .state
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        state.released = true;
        self.released.notify_all();
    }

    fn notify_preemption(&self) {
        let mut state = self
            .state
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        state.preempted = true;
        self.released.notify_all();
    }

    fn notify_progress_preemption(&self) {
        let mut state = self
            .state
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        state.progress_preempted = true;
        self.released.notify_all();
    }

    fn permit_progress_preemption(&self) -> bool {
        let mut state = self
            .state
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        state.progress_steps_seen = state.progress_steps_seen.saturating_add(1);
        state.progress_steps_seen > state.progress_steps_before_preempt
    }

    fn progress_preempted(&self) -> bool {
        self.state
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .progress_preempted
    }

    fn progress_steps_seen(&self) -> usize {
        self.state
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .progress_steps_seen
    }

    fn notify_completion(&self) {
        let mut state = self
            .state
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        state.completed = true;
        drop(state);
        self.completed.notify_one();
    }

    fn wait_until_entered(&self, timeout: Duration) -> bool {
        let state = self
            .state
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        let (state, _) = self
            .entered
            .wait_timeout_while(state, timeout, |state| !state.entered)
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        state.entered
    }

    async fn wait_until_completed(&self) {
        loop {
            let notified = self.completed.notified();
            if self
                .state
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner)
                .completed
            {
                return;
            }
            notified.await;
        }
    }
}

#[cfg(all(test, target_os = "linux"))]
fn consensus_log_prune_turn_gates()
-> &'static Mutex<BTreeMap<PathBuf, Weak<ConsensusLogPruneTurnGate>>> {
    static GATES: OnceLock<Mutex<BTreeMap<PathBuf, Weak<ConsensusLogPruneTurnGate>>>> =
        OnceLock::new();
    GATES.get_or_init(|| Mutex::new(BTreeMap::new()))
}

#[cfg(all(test, target_os = "linux"))]
fn consensus_log_prune_turn_gate_for_source(
    source: &crate::consensus::snapshot::PinnedSqliteFile,
) -> Option<Arc<ConsensusLogPruneTurnGate>> {
    let directory = std::fs::canonicalize(source.path().parent()?).ok()?;
    let mut gates = consensus_log_prune_turn_gates()
        .lock()
        .unwrap_or_else(std::sync::PoisonError::into_inner);
    let gate = gates.get(&directory).and_then(Weak::upgrade);
    if gate.is_none() {
        gates.remove(&directory);
    }
    gate
}

#[cfg(all(test, target_os = "linux"))]
pub(crate) struct ConsensusLogPruneTurnGateForTest {
    directory: PathBuf,
    gate: Arc<ConsensusLogPruneTurnGate>,
}

#[cfg(all(test, target_os = "linux"))]
impl ConsensusLogPruneTurnGateForTest {
    fn install(directory: &Path) -> Self {
        Self::install_at(directory, ConsensusLogPruneTurnGatePoint::BeforeTransaction)
    }

    pub(crate) fn install_after_writer_acquired(directory: &Path) -> Self {
        Self::install_at(
            directory,
            ConsensusLogPruneTurnGatePoint::AfterWriterAcquired,
        )
    }

    pub(crate) fn install_before_active_interrupt(directory: &Path) -> Self {
        Self::install_at(
            directory,
            ConsensusLogPruneTurnGatePoint::BeforeActiveInterrupt,
        )
    }

    pub(crate) fn install_before_delete(directory: &Path) -> Self {
        Self::install_at(directory, ConsensusLogPruneTurnGatePoint::BeforeDelete)
    }

    pub(crate) fn install_before_authority_read(directory: &Path) -> Self {
        Self::install_at(
            directory,
            ConsensusLogPruneTurnGatePoint::BeforeAuthorityRead,
        )
    }

    pub(crate) fn install_mid_delete(directory: &Path) -> Self {
        Self::install_at(directory, ConsensusLogPruneTurnGatePoint::MidDelete)
    }

    pub(crate) fn install_before_read_purged(directory: &Path) -> Self {
        Self::install_at(directory, ConsensusLogPruneTurnGatePoint::BeforeReadPurged)
    }

    pub(crate) fn install_before_commit(directory: &Path) -> Self {
        Self::install_at(directory, ConsensusLogPruneTurnGatePoint::BeforeCommit)
    }

    fn install_at(directory: &Path, point: ConsensusLogPruneTurnGatePoint) -> Self {
        let directory =
            std::fs::canonicalize(directory).expect("canonicalize prune gate directory");
        let gate = Arc::new(ConsensusLogPruneTurnGate {
            point,
            state: Mutex::new(ConsensusLogPruneTurnGateState {
                armed: true,
                entered: false,
                released: false,
                preempted: false,
                progress_preempted: false,
                progress_steps_before_preempt: usize::from(
                    point == ConsensusLogPruneTurnGatePoint::MidDelete,
                ) * 8,
                progress_steps_seen: 0,
                completed: false,
            }),
            entered: Condvar::new(),
            released: Condvar::new(),
            completed: tokio::sync::Notify::new(),
        });
        consensus_log_prune_turn_gates()
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .insert(directory.clone(), Arc::downgrade(&gate));
        Self { directory, gate }
    }

    pub(crate) fn release(&self) {
        self.gate.release();
    }

    pub(crate) fn wait_until_entered(&self, timeout: Duration) -> bool {
        self.gate.wait_until_entered(timeout)
    }

    pub(crate) fn progress_preempted(&self) -> bool {
        self.gate.progress_preempted()
    }

    pub(crate) fn progress_steps_seen(&self) -> usize {
        self.gate.progress_steps_seen()
    }

    pub(crate) async fn wait_until_completed(&self) {
        self.gate.wait_until_completed().await;
    }
}

#[cfg(all(test, target_os = "linux"))]
impl Drop for ConsensusLogPruneTurnGateForTest {
    fn drop(&mut self) {
        self.release();
        consensus_log_prune_turn_gates()
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .remove(&self.directory);
    }
}

/// Keeps a store-local primary consensus writer ahead of its physical-prune
/// lane from admission through completion of the SQLite write.
#[derive(Default)]
pub(crate) struct ConsensusLogPrunePrimaryPreemption {
    primary_writers: Option<Arc<AtomicUsize>>,
}

impl Drop for ConsensusLogPrunePrimaryPreemption {
    fn drop(&mut self) {
        if let Some(primary_writers) = self.primary_writers.take() {
            primary_writers.fetch_sub(1, Ordering::AcqRel);
        }
    }
}

/// One descriptor-pinned, coalescing physical log-prune lane.  It is only
/// installed for the fixed durable authority profile; the unsupported
/// in-memory shape retains the historical synchronous delete path.
pub(crate) struct ConsensusLogPruneLane {
    sender: tokio::sync::mpsc::Sender<()>,
    stop: tokio::sync::watch::Sender<bool>,
    stopping: AtomicBool,
    active_interrupt: Mutex<Option<Arc<InterruptHandle>>>,
    worker: tokio::sync::Mutex<Option<tokio::task::JoinHandle<()>>>,
    diagnostics: Option<Arc<ConsensusStoreDiagnosticCounters>>,
    primary_writers: Arc<AtomicUsize>,
    #[cfg(all(test, target_os = "linux"))]
    turn_gate: Option<Arc<ConsensusLogPruneTurnGate>>,
}

impl ConsensusLogPruneLane {
    fn start(
        source: Arc<crate::consensus::snapshot::PinnedSqliteFile>,
        vfs_name: Option<Arc<str>>,
        identity: SessionConsensusIdentity,
        expected_members: BTreeSet<SessionConsensusNodeId>,
        expected_bindings: BTreeMap<SessionConsensusNodeId, SessionTopologyMemberBinding>,
        fixed_placement_policy: Option<PlacementResiliencePolicy>,
        diagnostics: Option<Arc<ConsensusStoreDiagnosticCounters>>,
    ) -> Result<Arc<Self>, SessionConsensusStorageError> {
        verify_proactive_checkpoint_source(&source)
            .map_err(|_| SessionConsensusStorageError::BackendUnavailable)?;
        let flags = OpenFlags::SQLITE_OPEN_READ_WRITE | OpenFlags::SQLITE_OPEN_NO_MUTEX;
        let connection = match vfs_name {
            Some(vfs_name) => {
                Connection::open_with_flags_and_vfs(source.path(), flags, vfs_name.as_ref())
            }
            None => Connection::open_with_flags(source.path(), flags),
        }
        .map_err(|_| SessionConsensusStorageError::BackendUnavailable)?;
        verify_proactive_checkpoint_connection(&connection, &source)
            .map_err(|_| SessionConsensusStorageError::BackendUnavailable)?;
        configure_consensus_log_prune_connection(&connection)
            .map_err(|_| SessionConsensusStorageError::BackendUnavailable)?;
        verify_proactive_checkpoint_connection(&connection, &source)
            .map_err(|_| SessionConsensusStorageError::BackendUnavailable)?;
        let (sender, receiver) = tokio::sync::mpsc::channel(1);
        let (stop, stop_receiver) = tokio::sync::watch::channel(false);
        let lane = Arc::new(Self {
            sender,
            stop,
            stopping: AtomicBool::new(false),
            active_interrupt: Mutex::new(None),
            worker: tokio::sync::Mutex::new(None),
            diagnostics,
            primary_writers: Arc::new(AtomicUsize::new(0)),
            #[cfg(all(test, target_os = "linux"))]
            turn_gate: consensus_log_prune_turn_gate_for_source(&source),
        });
        let worker = tokio::spawn(run_consensus_log_prune_lane(
            receiver,
            stop_receiver,
            connection,
            source,
            Arc::downgrade(&lane),
            identity,
            expected_members,
            expected_bindings,
            fixed_placement_policy,
        ));
        *lane
            .worker
            .try_lock()
            .map_err(|_| SessionConsensusStorageError::BackendUnavailable)? = Some(worker);
        Ok(lane)
    }

    pub(crate) fn signal(&self) {
        if self.stopping.load(Ordering::Acquire) {
            return;
        }
        if self.sender.try_send(()).is_ok() {
            if let Some(diagnostics) = &self.diagnostics {
                diagnostics.observe_consensus_log_prune_signal();
            }
        }
    }

    pub(crate) fn request_primary_preemption(&self) -> ConsensusLogPrunePrimaryPreemption {
        if self.stopping.load(Ordering::Acquire) {
            return ConsensusLogPrunePrimaryPreemption::default();
        }
        let primary_writers = Arc::clone(&self.primary_writers);
        primary_writers.fetch_add(1, Ordering::AcqRel);
        let active_interrupt = self
            .active_interrupt
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        if let Some(interrupt) = active_interrupt.as_ref() {
            #[cfg(all(test, target_os = "linux"))]
            if let Some(gate) = &self.turn_gate {
                gate.notify_preemption();
            }
            interrupt.interrupt();
        }
        ConsensusLogPrunePrimaryPreemption {
            primary_writers: Some(primary_writers),
        }
    }

    pub(crate) async fn shutdown(&self) {
        self.stopping.store(true, Ordering::Release);
        if let Some(interrupt) = self
            .active_interrupt
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .clone()
        {
            interrupt.interrupt();
        }
        let _ = self.stop.send(true);
        let mut slot = self.worker.lock().await;
        if let Some(worker) = slot.as_mut() {
            let _ = worker.await;
        }
        slot.take();
    }
}

#[allow(clippy::too_many_arguments)]
async fn run_consensus_log_prune_lane(
    mut receiver: tokio::sync::mpsc::Receiver<()>,
    mut stop: tokio::sync::watch::Receiver<bool>,
    mut connection: Connection,
    source: Arc<crate::consensus::snapshot::PinnedSqliteFile>,
    lane: Weak<ConsensusLogPruneLane>,
    identity: SessionConsensusIdentity,
    expected_members: BTreeSet<SessionConsensusNodeId>,
    expected_bindings: BTreeMap<SessionConsensusNodeId, SessionTopologyMemberBinding>,
    fixed_placement_policy: Option<PlacementResiliencePolicy>,
) {
    let Some(first_lane) = lane.upgrade() else {
        return;
    };
    if let Some(diagnostics) = &first_lane.diagnostics {
        diagnostics.begin_consensus_log_prune_worker();
    }
    drop(first_lane);
    let _worker = ConsensusLogPruneWorkerGuard { lane: lane.clone() };
    loop {
        let signal = tokio::select! {
            changed = stop.changed() => { if changed.is_err() || *stop.borrow() { return; } continue; }
            signal = receiver.recv() => signal,
        };
        if signal.is_none() || *stop.borrow() {
            return;
        }
        let Some(lane) = lane.upgrade() else {
            return;
        };
        if lane.stopping.load(Ordering::Acquire) || *stop.borrow() {
            return;
        }
        #[cfg(all(test, target_os = "linux"))]
        if let Some(gate) = &lane.turn_gate {
            gate.wait_before_active_interrupt();
        }
        if lane.primary_writers.load(Ordering::Acquire) != 0 {
            if !wait_consensus_log_prune_pacing(&mut stop, &lane).await {
                return;
            }
            if lane.stopping.load(Ordering::Acquire) || *stop.borrow() {
                return;
            }
            lane.signal();
            continue;
        }
        let interrupt = Arc::new(connection.get_interrupt_handle());
        let primary_writer_waiting = {
            let mut active_interrupt = lane
                .active_interrupt
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner);
            *active_interrupt = Some(Arc::clone(&interrupt));
            if lane.primary_writers.load(Ordering::Acquire) != 0 {
                *active_interrupt = None;
                true
            } else {
                false
            }
        };
        if primary_writer_waiting {
            if !wait_consensus_log_prune_pacing(&mut stop, &lane).await {
                return;
            }
            if lane.stopping.load(Ordering::Acquire) || *stop.borrow() {
                return;
            }
            lane.signal();
            continue;
        }
        if lane.stopping.load(Ordering::Acquire) || *stop.borrow() {
            *lane
                .active_interrupt
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner) = None;
            return;
        }
        if let Some(diagnostics) = &lane.diagnostics {
            diagnostics.begin_consensus_log_prune_turn();
        }
        let source_for_turn = Arc::clone(&source);
        let expected_members_for_turn = expected_members.clone();
        let expected_bindings_for_turn = expected_bindings.clone();
        let primary_writers = Arc::clone(&lane.primary_writers);
        #[cfg(all(test, target_os = "linux"))]
        let turn_gate = lane.turn_gate.clone();
        let turn = tokio::task::spawn_blocking(move || {
            #[cfg(all(test, target_os = "linux"))]
            if turn_gate
                .as_ref()
                .is_some_and(|gate| gate.wait_before_prune())
            {
                return (connection, Err(ConsensusLogPruneTurnError::Interrupted));
            }
            let result = prune_consensus_log_turn_sync(
                &connection,
                &source_for_turn,
                identity,
                &expected_members_for_turn,
                &expected_bindings_for_turn,
                fixed_placement_policy,
                ConsensusLogPruneTurnControl {
                    primary_writers: Arc::clone(&primary_writers),
                    #[cfg(all(test, target_os = "linux"))]
                    turn_gate: turn_gate.clone(),
                },
            );
            let result = match result {
                Err(ConsensusLogPruneTurnError::Interrupted)
                    if primary_writers.load(Ordering::Acquire) != 0 =>
                {
                    Err(ConsensusLogPruneTurnError::PreemptedByPrimary)
                }
                result => result,
            };
            (connection, result)
        })
        .await;
        {
            let mut active_interrupt = lane
                .active_interrupt
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner);
            *active_interrupt = None;
        }
        match turn {
            Ok((returned, Ok(completion))) => {
                connection = returned;
                if let Some(diagnostics) = &lane.diagnostics {
                    diagnostics.complete_consensus_log_prune_turn(
                        completion.rows_deleted,
                        completion.encoded_bytes_deleted,
                        completion.more,
                    );
                }
                #[cfg(all(test, target_os = "linux"))]
                if !completion.more {
                    if let Some(gate) = &lane.turn_gate {
                        gate.notify_completion();
                    }
                }
                if completion.more {
                    if !wait_consensus_log_prune_pacing(&mut stop, &lane).await {
                        return;
                    }
                    if lane.stopping.load(Ordering::Acquire) || *stop.borrow() {
                        return;
                    }
                    lane.signal();
                }
            }
            Ok((
                returned,
                Err(
                    ConsensusLogPruneTurnError::TransientContention
                    | ConsensusLogPruneTurnError::PreemptedByPrimary,
                ),
            )) => {
                connection = returned;
                if lane.stopping.load(Ordering::Acquire) || *stop.borrow() {
                    if let Some(diagnostics) = &lane.diagnostics {
                        diagnostics.cancel_consensus_log_prune_turn();
                    }
                    return;
                }
                if let Some(diagnostics) = &lane.diagnostics {
                    diagnostics.retry_consensus_log_prune_turn();
                }
                if !wait_consensus_log_prune_pacing(&mut stop, &lane).await {
                    return;
                }
                if lane.stopping.load(Ordering::Acquire) || *stop.borrow() {
                    return;
                }
                lane.signal();
            }
            Ok((returned, Err(ConsensusLogPruneTurnError::Interrupted))) => {
                connection = returned;
                if lane.stopping.load(Ordering::Acquire) || *stop.borrow() {
                    if let Some(diagnostics) = &lane.diagnostics {
                        diagnostics.cancel_consensus_log_prune_turn();
                    }
                    return;
                }
                if let Some(diagnostics) = &lane.diagnostics {
                    diagnostics.retry_consensus_log_prune_turn();
                }
                // sqlite3_interrupt() may land after a primary writer has
                // announced itself but before the prune connection enters a
                // VDBE. SQLite then reports SQLITE_INTERRUPT to the first
                // operation of this next turn, after the primary guard has
                // already been released. The logical floor is durable and
                // this turn has rolled back, so retry the low-priority lane
                // rather than stranding its physical backlog.
                if !wait_consensus_log_prune_pacing(&mut stop, &lane).await {
                    return;
                }
                if lane.stopping.load(Ordering::Acquire) || *stop.borrow() {
                    return;
                }
                lane.signal();
            }
            Ok((returned, Err(ConsensusLogPruneTurnError::Permanent))) => {
                let _ = returned;
                if lane.stopping.load(Ordering::Acquire) || *stop.borrow() {
                    if let Some(diagnostics) = &lane.diagnostics {
                        diagnostics.cancel_consensus_log_prune_turn();
                    }
                    return;
                }
                if let Some(diagnostics) = &lane.diagnostics {
                    diagnostics.fail_consensus_log_prune_turn();
                }
                return;
            }
            Err(_) => {
                if lane.stopping.load(Ordering::Acquire) || *stop.borrow() {
                    if let Some(diagnostics) = &lane.diagnostics {
                        diagnostics.cancel_consensus_log_prune_turn();
                    }
                    return;
                }
                if let Some(diagnostics) = &lane.diagnostics {
                    diagnostics.fail_consensus_log_prune_turn();
                }
                return;
            }
        }
    }
}

/// The physical-prune worker is deliberately a low-priority SQLite client:
/// SQLite itself must return busy immediately so the lane's one fixed,
/// stop-selectable pacing point owns every retry delay.  Automatic
/// checkpointing is disabled on this secondary connection so a bounded prune
/// transaction cannot add an unbounded main-file checkpoint to its commit.
fn configure_consensus_log_prune_connection(conn: &Connection) -> Result<(), rusqlite::Error> {
    apply_pragma_profile(conn, false, false).map_err(|_| rusqlite::Error::InvalidQuery)?;
    conn.busy_timeout(Duration::ZERO)?;
    conn.pragma_update(None, "wal_autocheckpoint", 0_i32)?;
    let wal_autocheckpoint: i32 =
        conn.query_row("PRAGMA wal_autocheckpoint", [], |row| row.get(0))?;
    if wal_autocheckpoint != 0 {
        return Err(rusqlite::Error::InvalidQuery);
    }
    Ok(())
}

struct ConsensusLogPruneWorkerGuard {
    lane: Weak<ConsensusLogPruneLane>,
}

impl Drop for ConsensusLogPruneWorkerGuard {
    fn drop(&mut self) {
        if let Some(lane) = self.lane.upgrade() {
            if let Some(diagnostics) = &lane.diagnostics {
                diagnostics.end_consensus_log_prune_worker();
            }
        }
    }
}

async fn wait_consensus_log_prune_pacing(
    stop: &mut tokio::sync::watch::Receiver<bool>,
    lane: &ConsensusLogPruneLane,
) -> bool {
    tokio::select! {
        _ = tokio::time::sleep(CONSENSUS_LOG_PRUNE_RETRY_PACING) => !lane.stopping.load(Ordering::Acquire) && !*stop.borrow(),
        changed = stop.changed() => changed.is_ok() && !*stop.borrow() && !lane.stopping.load(Ordering::Acquire),
    }
}

struct ConsensusLogPruneTurnControl {
    primary_writers: Arc<AtomicUsize>,
    #[cfg(all(test, target_os = "linux"))]
    turn_gate: Option<Arc<ConsensusLogPruneTurnGate>>,
}

/// Interrupt every SQLite VM step in a prune turn once a primary writer has
/// announced itself. The lane publishes the connection interrupt handle
/// before entering this scope; this callback closes the interval where that
/// cross-thread interrupt arrives with no VDBE active and SQLite clears it.
struct ConsensusLogPruneProgressGuard<'a> {
    conn: &'a Connection,
}

impl<'a> ConsensusLogPruneProgressGuard<'a> {
    fn install(
        conn: &'a Connection,
        primary_writers: Arc<AtomicUsize>,
        observed_preemption: Arc<AtomicBool>,
        #[cfg(all(test, target_os = "linux"))] turn_gate: Option<Arc<ConsensusLogPruneTurnGate>>,
    ) -> Self {
        conn.progress_handler(
            1,
            Some(move || {
                let preempt = primary_writers.load(Ordering::Acquire) != 0;
                if preempt {
                    #[cfg(all(test, target_os = "linux"))]
                    if let Some(gate) = &turn_gate {
                        if !gate.permit_progress_preemption() {
                            return false;
                        }
                    }
                    observed_preemption.store(true, Ordering::Release);
                    #[cfg(all(test, target_os = "linux"))]
                    if let Some(gate) = &turn_gate {
                        gate.notify_progress_preemption();
                    }
                }
                preempt
            }),
        );
        Self { conn }
    }
}

impl Drop for ConsensusLogPruneProgressGuard<'_> {
    fn drop(&mut self) {
        self.conn.progress_handler(0, None::<fn() -> bool>);
    }
}

fn prune_consensus_log_turn_sync(
    conn: &Connection,
    source: &crate::consensus::snapshot::PinnedSqliteFile,
    identity: SessionConsensusIdentity,
    expected_members: &BTreeSet<SessionConsensusNodeId>,
    expected_bindings: &BTreeMap<SessionConsensusNodeId, SessionTopologyMemberBinding>,
    fixed_placement_policy: Option<PlacementResiliencePolicy>,
    control: ConsensusLogPruneTurnControl,
) -> Result<ConsensusLogPruneTurnCompletion, ConsensusLogPruneTurnError> {
    let observed_preemption = Arc::new(AtomicBool::new(false));
    let progress = ConsensusLogPruneProgressGuard::install(
        conn,
        Arc::clone(&control.primary_writers),
        Arc::clone(&observed_preemption),
        #[cfg(all(test, target_os = "linux"))]
        control.turn_gate.clone(),
    );
    let pre_transaction = (|| {
        verify_proactive_checkpoint_connection(conn, source)
            .map_err(consensus_log_prune_permanent)?;
        // Recheck after publication and handler installation. A primary that
        // arrived during that handoff must yield before BEGIN IMMEDIATE.
        preempt_consensus_log_prune_if_requested(control.primary_writers.as_ref())
    })();
    if let Err(error) = pre_transaction {
        drop(progress);
        return Err(error);
    }
    let mut tx = match Transaction::new_unchecked(conn, TransactionBehavior::Immediate) {
        Ok(tx) => tx,
        Err(error) => {
            drop(progress);
            return Err(classify_consensus_log_prune_sqlite_error(&error));
        }
    };
    let result = (|| {
        #[cfg(all(test, target_os = "linux"))]
        if control
            .turn_gate
            .as_deref()
            .is_some_and(ConsensusLogPruneTurnGate::wait_after_writer_acquired)
        {
            return Err(ConsensusLogPruneTurnError::Interrupted);
        }
        preempt_consensus_log_prune_if_requested(control.primary_writers.as_ref())?;
        #[cfg(all(test, target_os = "linux"))]
        if let Some(gate) = control.turn_gate.as_deref() {
            gate.wait_at(ConsensusLogPruneTurnGatePoint::BeforeAuthorityRead);
        }
        validate_durable_authority_for_raw_access(
            &tx,
            identity,
            ConsensusAuthorityProfile::FixedImmutable,
            expected_members,
            expected_bindings,
            fixed_placement_policy,
        )
        .map_err(consensus_log_prune_permanent)?;
        preempt_consensus_log_prune_if_requested(control.primary_writers.as_ref())?;
        #[cfg(all(test, target_os = "linux"))]
        if let Some(gate) = control.turn_gate.as_deref() {
            gate.wait_at(ConsensusLogPruneTurnGatePoint::BeforeReadPurged);
        }
        let Some(floor) = read_purged_for_prune_sync(&tx, identity)? else {
            preempt_consensus_log_prune_if_requested(control.primary_writers.as_ref())?;
            return Ok(ConsensusLogPruneTurnCompletion {
                more: false,
                rows_deleted: 0,
                encoded_bytes_deleted: 0,
            });
        };
        preempt_consensus_log_prune_if_requested(control.primary_writers.as_ref())?;
        let completion = prune_consensus_log_rows_in_tx(
            &tx,
            &floor,
            control.primary_writers.as_ref(),
            #[cfg(all(test, target_os = "linux"))]
            control.turn_gate.as_deref(),
        )?;
        verify_proactive_checkpoint_connection(conn, source)
            .map_err(consensus_log_prune_permanent)?;
        preempt_consensus_log_prune_if_requested(control.primary_writers.as_ref())?;
        #[cfg(all(test, target_os = "linux"))]
        if let Some(gate) = control.turn_gate.as_deref() {
            gate.wait_at(ConsensusLogPruneTurnGatePoint::BeforeCommit);
        }
        Ok(completion)
    })();
    let result = match result {
        Ok(completion) => {
            let commit = tx
                .execute_batch("COMMIT")
                .map_err(|error| classify_consensus_log_prune_sqlite_error(&error));
            tx.set_drop_behavior(DropBehavior::Ignore);
            drop(progress);
            if commit.is_err() {
                let rollback = rollback_consensus_log_prune_transaction(conn);
                drop(tx);
                rollback.map_err(|_| ConsensusLogPruneTurnError::Permanent)?;
            } else {
                drop(tx);
            }
            commit.map(|()| completion)
        }
        Err(error) => {
            // A progress callback may have interrupted an SQLite VM. Remove
            // it before the rollback/transaction drop so cleanup itself is
            // never interrupted and cannot strand the write lock.
            tx.set_drop_behavior(DropBehavior::Ignore);
            drop(progress);
            let rollback = rollback_consensus_log_prune_transaction(conn);
            drop(tx);
            rollback.map_err(|_| ConsensusLogPruneTurnError::Permanent)?;
            Err(error)
        }
    };
    match result {
        Err(ConsensusLogPruneTurnError::Interrupted | ConsensusLogPruneTurnError::Permanent)
            if observed_preemption.load(Ordering::Acquire)
                && control.primary_writers.load(Ordering::Acquire) != 0 =>
        {
            Err(ConsensusLogPruneTurnError::PreemptedByPrimary)
        }
        result => result,
    }
}

fn rollback_consensus_log_prune_transaction(
    conn: &Connection,
) -> Result<(), ConsensusLogPruneTurnError> {
    if conn.is_autocommit() {
        return Ok(());
    }
    conn.execute_batch("ROLLBACK")
        .map_err(|rollback_error| classify_consensus_log_prune_sqlite_error(&rollback_error))
}

fn preempt_consensus_log_prune_if_requested(
    primary_writers: &AtomicUsize,
) -> Result<(), ConsensusLogPruneTurnError> {
    if primary_writers.load(Ordering::Acquire) != 0 {
        Err(ConsensusLogPruneTurnError::PreemptedByPrimary)
    } else {
        Ok(())
    }
}

/// Read the physical-prune floor without erasing an SQLite interrupt. The
/// generic durable-read surface intentionally redacts backend failures into
/// `io::Error`; this dedicated lane path retains only the internal interrupt
/// classifier so a live primary guard can preempt before a transaction drop.
fn read_purged_for_prune_sync(
    conn: &Connection,
    identity: SessionConsensusIdentity,
) -> Result<Option<LogId<SessionConsensusNodeId>>, ConsensusLogPruneTurnError> {
    let row = conn
        .query_row(
            "SELECT configuration_epoch, term, log_index, log_id_json \
             FROM consensus_purged WHERE singleton = 1",
            [],
            |row| {
                Ok((
                    row.get::<_, i64>(0)?,
                    row.get::<_, i64>(1)?,
                    row.get::<_, i64>(2)?,
                    row.get::<_, Vec<u8>>(3)?,
                ))
            },
        )
        .optional()
        .map_err(|error| classify_consensus_log_prune_sqlite_error(&error))?;
    let Some((epoch, term, index, encoded)) = row else {
        return Ok(None);
    };
    validate_epoch(epoch, identity).map_err(consensus_log_prune_permanent)?;
    let log_id: LogId<SessionConsensusNodeId> =
        decode_json(&encoded).map_err(consensus_log_prune_permanent)?;
    if checked_u64(term).map_err(consensus_log_prune_permanent)? != log_id.leader_id.term
        || checked_u64(index).map_err(consensus_log_prune_permanent)? != log_id.index
    {
        return Err(ConsensusLogPruneTurnError::Permanent);
    }
    Ok(Some(log_id))
}

fn prune_consensus_log_rows_in_tx(
    tx: &Transaction<'_>,
    floor: &LogId<SessionConsensusNodeId>,
    primary_writers: &AtomicUsize,
    #[cfg(all(test, target_os = "linux"))] turn_gate: Option<&ConsensusLogPruneTurnGate>,
) -> Result<ConsensusLogPruneTurnCompletion, ConsensusLogPruneTurnError> {
    let mut statement = tx.prepare("SELECT log_index, length(entry_json) FROM consensus_log WHERE log_index <= ?1 ORDER BY log_index ASC LIMIT ?2").map_err(|error| classify_consensus_log_prune_sqlite_error(&error))?;
    let mut rows = statement
        .query(params![
            checked_i64(floor.index).map_err(consensus_log_prune_permanent)?,
            i64::try_from(CONSENSUS_LOG_PRUNE_ROWS_PER_TURN)
                .map_err(consensus_log_prune_permanent)?
        ])
        .map_err(|error| classify_consensus_log_prune_sqlite_error(&error))?;
    let mut selected = Vec::new();
    let mut bytes = 0_usize;
    while let Some(row) = rows
        .next()
        .map_err(|error| classify_consensus_log_prune_sqlite_error(&error))?
    {
        let index: i64 = row
            .get(0)
            .map_err(|error| classify_consensus_log_prune_sqlite_error(&error))?;
        let length: i64 = row
            .get(1)
            .map_err(|error| classify_consensus_log_prune_sqlite_error(&error))?;
        let length = usize::try_from(length).map_err(consensus_log_prune_permanent)?;
        if bytes
            .checked_add(length)
            .filter(|total| *total <= CONSENSUS_LOG_PRUNE_BYTES_PER_TURN)
            .is_none()
        {
            break;
        }
        bytes += length;
        selected.push(index);
    }
    drop(rows);
    drop(statement);
    preempt_consensus_log_prune_if_requested(primary_writers)?;
    #[cfg(all(test, target_os = "linux"))]
    if let Some(gate) = turn_gate {
        gate.wait_at(ConsensusLogPruneTurnGatePoint::BeforeDelete);
    }
    if let Some(last) = selected.last() {
        tx.execute("DELETE FROM consensus_log WHERE log_index <= ?1", [last])
            .map_err(|error| classify_consensus_log_prune_sqlite_error(&error))?;
    } else {
        let retained: bool = tx
            .query_row(
                "SELECT EXISTS(SELECT 1 FROM consensus_log WHERE log_index <= ?1)",
                [checked_i64(floor.index).map_err(consensus_log_prune_permanent)?],
                |row| row.get(0),
            )
            .map_err(|error| classify_consensus_log_prune_sqlite_error(&error))?;
        if retained {
            // A row larger than the fixed budget cannot be a supported
            // durable entry. Refuse a zero-progress requeue loop.
            return Err(ConsensusLogPruneTurnError::Permanent);
        }
    }
    preempt_consensus_log_prune_if_requested(primary_writers)?;
    let more: bool = tx
        .query_row(
            "SELECT EXISTS(SELECT 1 FROM consensus_log WHERE log_index <= ?1)",
            [checked_i64(floor.index).map_err(consensus_log_prune_permanent)?],
            |row| row.get(0),
        )
        .map_err(|error| classify_consensus_log_prune_sqlite_error(&error))?;
    Ok(ConsensusLogPruneTurnCompletion {
        more,
        rows_deleted: u64::try_from(selected.len()).map_err(consensus_log_prune_permanent)?,
        encoded_bytes_deleted: u64::try_from(bytes).map_err(consensus_log_prune_permanent)?,
    })
}

pub(crate) struct ProactiveCheckpointLane {
    sender: tokio::sync::mpsc::Sender<()>,
    stop: tokio::sync::watch::Sender<bool>,
    stopping: AtomicBool,
    /// A bounded, store-scoped countdown. It is never an accumulating write
    /// counter, so wraparound cannot turn a busy store into per-write work.
    durable_writes_until_signal: AtomicU64,
    active_interrupt: Mutex<Option<Arc<InterruptHandle>>>,
    worker: tokio::sync::Mutex<Option<tokio::task::JoinHandle<()>>>,
    diagnostics: Option<Arc<ConsensusStoreDiagnosticCounters>>,
    #[cfg(feature = "test-vfs")]
    shutdown_join_hook: Arc<super::ProactiveCheckpointShutdownJoinHook>,
}

impl ProactiveCheckpointLane {
    fn start(
        source: Arc<crate::consensus::snapshot::PinnedSqliteFile>,
        vfs_name: Option<Arc<str>>,
        diagnostics: Option<Arc<ConsensusStoreDiagnosticCounters>>,
        #[cfg(feature = "test-vfs")] idle_wait_hook: Arc<super::ProactiveCheckpointIdleWaitHook>,
        #[cfg(feature = "test-vfs")] worker_observation: Arc<
            super::ProactiveCheckpointWorkerObservation,
        >,
        #[cfg(feature = "test-vfs")] shutdown_join_hook: Arc<
            super::ProactiveCheckpointShutdownJoinHook,
        >,
    ) -> Result<Arc<Self>, SessionConsensusStorageError> {
        verify_proactive_checkpoint_source(&source)
            .map_err(|_| SessionConsensusStorageError::BackendUnavailable)?;
        let flags =
            rusqlite::OpenFlags::SQLITE_OPEN_READ_WRITE | rusqlite::OpenFlags::SQLITE_OPEN_NO_MUTEX;
        // This connection must never create a pathname-selected replacement.
        // The live primary already owns the pinned source descriptor.
        let connection = match vfs_name {
            Some(vfs_name) => {
                Connection::open_with_flags_and_vfs(source.path(), flags, vfs_name.as_ref())
            }
            None => Connection::open_with_flags(source.path(), flags),
        }
        .map_err(|_| SessionConsensusStorageError::BackendUnavailable)?;
        // Fence the opened descriptor before applying the pragma profile: the
        // profile contains persistent `journal_mode=WAL`, so an already
        // replaced same-path successor must be rejected before it is mutated.
        // The recheck below remains necessary because the primary can retire
        // while this lane is being constructed.
        verify_proactive_checkpoint_connection(&connection, &source)
            .map_err(|_| SessionConsensusStorageError::BackendUnavailable)?;
        apply_pragma_profile(&connection, false, false)
            .map_err(|_| SessionConsensusStorageError::BackendUnavailable)?;
        verify_proactive_checkpoint_connection(&connection, &source)
            .map_err(|_| SessionConsensusStorageError::BackendUnavailable)?;

        let (sender, receiver) = tokio::sync::mpsc::channel(1);
        let (stop, stop_receiver) = tokio::sync::watch::channel(false);
        let lane = Arc::new(Self {
            sender,
            stop,
            stopping: AtomicBool::new(false),
            durable_writes_until_signal: AtomicU64::new(PROACTIVE_CHECKPOINT_DURABLE_WRITE_BATCH),
            active_interrupt: Mutex::new(None),
            worker: tokio::sync::Mutex::new(None),
            diagnostics,
            #[cfg(feature = "test-vfs")]
            shutdown_join_hook,
        });
        let worker = tokio::spawn(run_proactive_checkpoint_lane(
            receiver,
            stop_receiver,
            connection,
            Arc::clone(&source),
            Arc::downgrade(&lane),
            #[cfg(feature = "test-vfs")]
            idle_wait_hook,
            #[cfg(feature = "test-vfs")]
            worker_observation,
        ));
        let mut slot = lane
            .worker
            .try_lock()
            .map_err(|_| SessionConsensusStorageError::BackendUnavailable)?;
        *slot = Some(worker);
        drop(slot);
        Ok(lane)
    }

    /// Account for one already-durable write, then periodically coalesce one
    /// checkpoint request into the fixed-capacity lane.
    ///
    /// The countdown is fixed at the store scope and the only response-path
    /// work after it expires is `try_send`: a full lane already retains one
    /// pending checkpoint, and a stopped lane is ignored. No accepted
    /// response awaits checkpoint work.
    pub(crate) fn signal(&self) {
        if self.stopping.load(Ordering::Acquire) {
            return;
        }
        if matches!(
            schedule_proactive_checkpoint_ticket(&self.durable_writes_until_signal, &self.sender),
            ProactiveCheckpointTicket::Enqueued
        ) {
            if let Some(diagnostics) = &self.diagnostics {
                diagnostics.observe_proactive_checkpoint_signal();
            }
        }
    }

    #[cfg(feature = "test-vfs")]
    pub(crate) fn reset_durable_write_budget_for_test(&self) {
        self.durable_writes_until_signal
            .store(PROACTIVE_CHECKPOINT_DURABLE_WRITE_BATCH, Ordering::Release);
    }

    #[cfg(feature = "test-vfs")]
    pub(crate) fn durable_write_budget_for_test(&self) -> u64 {
        self.durable_writes_until_signal.load(Ordering::Acquire)
    }

    #[cfg(feature = "test-vfs")]
    pub(crate) const fn durable_write_batch_for_test() -> u64 {
        PROACTIVE_CHECKPOINT_DURABLE_WRITE_BATCH
    }

    /// Retire the one worker after Openraft has stopped producing storage
    /// writes. The join is intentional: shutdown never detaches a checkpoint
    /// against a subsequently reopened store. SQLite interruption is best
    /// effort; a filesystem sync already in progress must return before its
    /// blocking worker can be joined.
    pub(crate) async fn shutdown(&self) {
        self.stopping.store(true, Ordering::Release);
        let interrupt = self
            .active_interrupt
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .clone();
        if let Some(interrupt) = interrupt {
            interrupt.interrupt();
        }
        let _ = self.stop.send(true);
        let mut slot = self.worker.lock().await;
        if let Some(worker) = slot.as_mut() {
            #[cfg(feature = "test-vfs")]
            self.shutdown_join_hook.observe();
            let _ = worker.await;
        }
        // Only remove a completed join handle. If this shutdown future is
        // cancelled while awaiting, the shared slot retains ownership so a
        // later shutdown can join the exact same worker.
        slot.take();
    }

    fn begin(&self) {
        if let Some(diagnostics) = &self.diagnostics {
            diagnostics.begin_proactive_checkpoint();
        }
    }

    fn complete(&self, incomplete: bool) {
        if let Some(diagnostics) = &self.diagnostics {
            diagnostics.complete_proactive_checkpoint(incomplete);
        }
    }

    fn fail(&self) {
        if let Some(diagnostics) = &self.diagnostics {
            diagnostics.fail_proactive_checkpoint();
        }
    }
}

/// Consume one successful primary durable-write event from the fixed
/// store-scoped cadence. The state remains in `1..=BATCH` for every normal
/// transition, so it never accumulates or wraps under sustained load.
fn consume_proactive_checkpoint_durable_write_budget(budget: &AtomicU64) -> bool {
    let mut remaining = budget.load(Ordering::Relaxed);
    loop {
        // This bounded countdown is initialized and reset only to the fixed
        // non-zero batch size. Treat a defensive zero as expired so it repairs
        // itself without underflowing or accumulating state.
        let expired = remaining <= 1;
        let next = if expired {
            PROACTIVE_CHECKPOINT_DURABLE_WRITE_BATCH
        } else {
            remaining - 1
        };
        match budget.compare_exchange_weak(remaining, next, Ordering::AcqRel, Ordering::Relaxed) {
            Ok(_) => return expired,
            Err(observed) => remaining = observed,
        }
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum ProactiveCheckpointTicket {
    BelowCadence,
    Enqueued,
    Full,
    Closed,
}

/// The exact `wal_checkpoint(PASSIVE)` outcome relevant to diagnostics.
///
/// SQLite reports a zero busy column when it made whatever progress was
/// possible, including when a pinned reader leaves newer frames in the WAL.
/// That is only a full completion when the reported checkpointed frame count
/// equals the WAL frame count.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum ProactivePassiveCheckpointDisposition {
    Drained,
    Incomplete,
}

/// Schedule one ticket only when the fixed durable-write cadence expires.
///
/// Resetting the bounded cadence before the nonblocking send means a full
/// channel still retains its one existing ticket while the next fixed batch
/// starts. That avoids retry tasks or an accumulating queue after a worker
/// falls behind.
fn schedule_proactive_checkpoint_ticket(
    budget: &AtomicU64,
    sender: &tokio::sync::mpsc::Sender<()>,
) -> ProactiveCheckpointTicket {
    if !consume_proactive_checkpoint_durable_write_budget(budget) {
        return ProactiveCheckpointTicket::BelowCadence;
    }
    match sender.try_send(()) {
        Ok(()) => ProactiveCheckpointTicket::Enqueued,
        Err(tokio::sync::mpsc::error::TrySendError::Full(_)) => ProactiveCheckpointTicket::Full,
        Err(tokio::sync::mpsc::error::TrySendError::Closed(_)) => ProactiveCheckpointTicket::Closed,
    }
}

async fn run_proactive_checkpoint_lane(
    mut receiver: tokio::sync::mpsc::Receiver<()>,
    mut stop: tokio::sync::watch::Receiver<bool>,
    mut connection: Connection,
    source: Arc<crate::consensus::snapshot::PinnedSqliteFile>,
    lane: Weak<ProactiveCheckpointLane>,
    #[cfg(feature = "test-vfs")] idle_wait_hook: Arc<super::ProactiveCheckpointIdleWaitHook>,
    #[cfg(feature = "test-vfs")] worker_observation: Arc<
        super::ProactiveCheckpointWorkerObservation,
    >,
) {
    #[cfg(feature = "test-vfs")]
    let _worker_observation = worker_observation.begin();
    loop {
        if *stop.borrow() {
            return;
        }
        #[cfg(feature = "test-vfs")]
        idle_wait_hook.wait_before_receive();
        let signal = tokio::select! {
            changed = stop.changed() => {
                if changed.is_err() || *stop.borrow() {
                    return;
                }
                continue;
            }
            signal = receiver.recv() => signal,
        };
        if signal.is_none() {
            return;
        }
        let Some(lane) = lane.upgrade() else {
            return;
        };
        if lane.stopping.load(Ordering::Acquire) {
            return;
        }

        lane.begin();
        let interrupt = Arc::new(connection.get_interrupt_handle());
        {
            let mut active = lane
                .active_interrupt
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner);
            *active = Some(Arc::clone(&interrupt));
        }
        let source = Arc::clone(&source);
        let checkpoint = tokio::task::spawn_blocking(move || {
            let result = run_proactive_passive_checkpoint(&connection, &source);
            (connection, result)
        })
        .await;
        {
            let mut active = lane
                .active_interrupt
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner);
            *active = None;
        }
        match checkpoint {
            Ok((returned_connection, Ok(disposition))) => {
                connection = returned_connection;
                lane.complete(matches!(
                    disposition,
                    ProactivePassiveCheckpointDisposition::Incomplete
                ));
            }
            Ok((returned_connection, Err(()))) => {
                connection = returned_connection;
                lane.fail();
            }
            Err(_) => {
                lane.fail();
                return;
            }
        }
    }
}

fn run_proactive_passive_checkpoint(
    connection: &Connection,
    source: &crate::consensus::snapshot::PinnedSqliteFile,
) -> Result<ProactivePassiveCheckpointDisposition, ()> {
    verify_proactive_checkpoint_connection(connection, source).map_err(|_| ())?;
    if !connection.is_autocommit() {
        return Err(());
    }
    let (busy, log_frames, checkpointed_frames) = connection
        .query_row("PRAGMA wal_checkpoint(PASSIVE)", [], |row| {
            Ok((
                row.get::<_, i64>(0)?,
                row.get::<_, i64>(1)?,
                row.get::<_, i64>(2)?,
            ))
        })
        .map_err(|_| ())?;
    let disposition =
        classify_proactive_passive_checkpoint(busy, log_frames, checkpointed_frames).ok_or(())?;
    if !connection.is_autocommit() {
        return Err(());
    }
    verify_proactive_checkpoint_connection(connection, source).map_err(|_| ())?;
    Ok(disposition)
}

/// Classify all three columns returned by `PRAGMA wal_checkpoint(PASSIVE)`.
/// `(-1, -1)` is SQLite's documented no-WAL sentinel; it is already drained
/// when the busy column is zero. Other malformed or impossible values are
/// treated as failures rather than being reported as a successful drain.
fn classify_proactive_passive_checkpoint(
    busy: i64,
    log_frames: i64,
    checkpointed_frames: i64,
) -> Option<ProactivePassiveCheckpointDisposition> {
    match (busy, log_frames, checkpointed_frames) {
        (0, -1, -1) => Some(ProactivePassiveCheckpointDisposition::Drained),
        // SQLite returns the same frame sentinel when another checkpoint owns
        // WAL_CKPT_LOCK. It is valid busy contention, not a failed PRAGMA.
        (1, -1, -1) => Some(ProactivePassiveCheckpointDisposition::Incomplete),
        (0 | 1, log_frames, checkpointed_frames)
            if log_frames >= 0 && checkpointed_frames >= 0 && checkpointed_frames <= log_frames =>
        {
            if busy == 0 && checkpointed_frames == log_frames {
                Some(ProactivePassiveCheckpointDisposition::Drained)
            } else {
                Some(ProactivePassiveCheckpointDisposition::Incomplete)
            }
        }
        _ => None,
    }
}

fn verify_proactive_checkpoint_source(
    source: &crate::consensus::snapshot::PinnedSqliteFile,
) -> io::Result<()> {
    source.verify_identity()
}

fn verify_proactive_checkpoint_connection(
    connection: &Connection,
    source: &crate::consensus::snapshot::PinnedSqliteFile,
) -> io::Result<()> {
    verify_proactive_checkpoint_source(source)?;
    if opc_sqlite_file_control_sys::main_file_has_moved(connection)
        .map_err(|_| invalid_data("session consensus checkpoint descriptor is unavailable"))?
    {
        return Err(invalid_data(
            "session consensus checkpoint descriptor moved",
        ));
    }
    let actual = crate::consensus::snapshot::PinnedSqliteFile::from_file(
        opc_sqlite_file_control_sys::main_file_descriptor(connection)
            .map_err(|_| invalid_data("session consensus checkpoint descriptor is unavailable"))?,
        source.path().to_path_buf(),
    )?;
    if actual.identity() != source.identity() {
        return Err(invalid_data(
            "session consensus checkpoint descriptor changed",
        ));
    }
    Ok(())
}

/// Shared persistence resources used by the log store, state machine, and
/// snapshot builder. One async mutex serializes every vote/log/state write.
#[derive(Clone)]
pub(crate) struct SqliteConsensusCore {
    pub(crate) conn: Arc<tokio::sync::Mutex<Connection>>,
    /// A duplicate of the actual live SQLite main-file descriptor, admitted
    /// from SQLite's VFS rather than from path metadata.
    pub(crate) database_file: Option<Arc<crate::consensus::snapshot::PinnedSqliteFile>>,
    /// One coalesced PASSIVE-checkpoint lane for this consensus store's exact
    /// live backing file. It is absent only for the unsupported in-memory
    /// backend shape.
    pub(crate) proactive_checkpoint_lane: Option<Arc<ProactiveCheckpointLane>>,
    /// Physical deletion follows the durable logical purge floor on this one
    /// store-scoped worker; it never uses the primary consensus connection.
    pub(crate) consensus_log_prune_lane: Option<Arc<ConsensusLogPruneLane>>,
    pub(crate) snapshot_observation: Arc<SnapshotBuildObservation>,
    /// Immutable database-incarnation identity used by legacy foreign keys.
    /// The active topology identity lives in `consensus_membership_scope`.
    pub(crate) storage_identity: SessionConsensusIdentity,
    pub(crate) authority_profile: ConsensusAuthorityProfile,
    pub(crate) fixed_placement_policy: Option<PlacementResiliencePolicy>,
    pub(crate) expected_members: BTreeSet<SessionConsensusNodeId>,
    pub(crate) expected_bindings: BTreeMap<SessionConsensusNodeId, SessionTopologyMemberBinding>,
    pub(crate) snapshot_dir: Arc<PathBuf>,
    /// A cancellation-safe staging cleanup failure. It is consumed only by a
    /// later operation holding the single snapshot gate.
    pub(crate) snapshot_cleanup_failed: Arc<AtomicBool>,
    pub(crate) caps: BackendCapabilities,
    pub(crate) snapshot_gate: Arc<tokio::sync::Mutex<()>>,
    /// Only one unvalidated receiver may own disk space for this core.
    pub(crate) snapshot_receive_admission: Arc<tokio::sync::Semaphore>,
    pub(crate) applied_progress: tokio::sync::watch::Sender<Option<LogId<SessionConsensusNodeId>>>,
    pub(crate) watchers: Arc<tokio::sync::Mutex<Vec<crate::replication_watch::ReplicationWatcher>>>,
    #[cfg(test)]
    pub(crate) apply_gate: Arc<tokio::sync::Semaphore>,
    #[cfg(test)]
    pub(crate) snapshot_capture_gate: Arc<SnapshotCaptureGate>,
}

impl SqliteConsensusCore {
    /// Request non-blocking PASSIVE checkpoint work after a primary commit.
    pub(crate) fn signal_proactive_checkpoint(&self) {
        if let Some(lane) = &self.proactive_checkpoint_lane {
            lane.signal();
        }
    }

    /// Return the store-scoped lane so the public store shutdown path can
    /// join it after Openraft has stopped every storage writer.
    pub(crate) fn proactive_checkpoint_lane(&self) -> Option<Arc<ProactiveCheckpointLane>> {
        self.proactive_checkpoint_lane.clone()
    }

    pub(crate) fn consensus_log_prune_lane(&self) -> Option<Arc<ConsensusLogPruneLane>> {
        self.consensus_log_prune_lane.clone()
    }

    /// Keep this core's low-priority physical-prune lane yielded for the
    /// lifetime of one primary consensus write.
    pub(crate) fn request_consensus_log_prune_preemption(
        &self,
    ) -> ConsensusLogPrunePrimaryPreemption {
        if let Some(lane) = &self.consensus_log_prune_lane {
            lane.request_primary_preemption()
        } else {
            ConsensusLogPrunePrimaryPreemption::default()
        }
    }

    #[cfg(test)]
    pub(crate) async fn initialize(
        backend: &SqliteSessionBackend,
        snapshot_dir: PathBuf,
        identity: SessionConsensusIdentity,
        expected_members: BTreeSet<SessionConsensusNodeId>,
        expected_bindings: BTreeMap<SessionConsensusNodeId, SessionTopologyMemberBinding>,
        authority_profile: ConsensusAuthorityProfile,
        fixed_placement_policy: Option<PlacementResiliencePolicy>,
    ) -> Result<Self, SessionConsensusStorageError> {
        Self::initialize_with_roster_attestation_root(
            backend,
            snapshot_dir,
            identity,
            expected_members,
            expected_bindings,
            authority_profile,
            fixed_placement_policy,
            None,
        )
        .await
    }

    #[allow(clippy::too_many_arguments)]
    pub(crate) async fn initialize_with_roster_attestation_root(
        backend: &SqliteSessionBackend,
        snapshot_dir: PathBuf,
        identity: SessionConsensusIdentity,
        expected_members: BTreeSet<SessionConsensusNodeId>,
        expected_bindings: BTreeMap<SessionConsensusNodeId, SessionTopologyMemberBinding>,
        authority_profile: ConsensusAuthorityProfile,
        fixed_placement_policy: Option<PlacementResiliencePolicy>,
        roster_attestation_trust_root: Option<RosterAttestationTrustRootV1>,
    ) -> Result<Self, SessionConsensusStorageError> {
        Self::initialize_inner(
            backend,
            snapshot_dir,
            identity,
            expected_members,
            expected_bindings,
            None,
            None,
            authority_profile,
            fixed_placement_policy,
            roster_attestation_trust_root,
        )
        .await
    }

    #[allow(clippy::too_many_arguments)]
    pub(crate) async fn initialize_with_pending_and_roster_attestation_root(
        backend: &SqliteSessionBackend,
        snapshot_dir: PathBuf,
        storage_identity: SessionConsensusIdentity,
        current_identity: SessionConsensusIdentity,
        current_members: BTreeSet<SessionConsensusNodeId>,
        current_bindings: BTreeMap<SessionConsensusNodeId, SessionTopologyMemberBinding>,
        pending: PendingMembershipBootstrap<'_>,
        authority_profile: ConsensusAuthorityProfile,
        fixed_placement_policy: Option<PlacementResiliencePolicy>,
        roster_attestation_trust_root: Option<RosterAttestationTrustRootV1>,
    ) -> Result<Self, SessionConsensusStorageError> {
        Self::initialize_inner(
            backend,
            snapshot_dir,
            current_identity,
            current_members,
            current_bindings,
            Some(storage_identity),
            Some(pending),
            authority_profile,
            fixed_placement_policy,
            roster_attestation_trust_root,
        )
        .await
    }

    #[allow(clippy::too_many_arguments)]
    async fn initialize_inner(
        backend: &SqliteSessionBackend,
        snapshot_dir: PathBuf,
        identity: SessionConsensusIdentity,
        expected_members: BTreeSet<SessionConsensusNodeId>,
        expected_bindings: BTreeMap<SessionConsensusNodeId, SessionTopologyMemberBinding>,
        required_storage_identity: Option<SessionConsensusIdentity>,
        pending: Option<PendingMembershipBootstrap<'_>>,
        authority_profile: ConsensusAuthorityProfile,
        fixed_placement_policy: Option<PlacementResiliencePolicy>,
        roster_attestation_trust_root: Option<RosterAttestationTrustRootV1>,
    ) -> Result<Self, SessionConsensusStorageError> {
        if !cfg!(target_os = "linux") {
            return Err(SessionConsensusStorageError::UnsupportedPlatform);
        }
        validate_member_set(&expected_members, false)
            .map_err(|_| SessionConsensusStorageError::InvalidIdentity)?;
        validate_member_bindings(&expected_members, &expected_bindings)
            .map_err(|_| SessionConsensusStorageError::InvalidIdentity)?;
        tokio::fs::create_dir_all(&snapshot_dir)
            .await
            .map_err(|_| SessionConsensusStorageError::BackendUnavailable)?;
        let canonical_snapshot_dir = tokio::fs::canonicalize(&snapshot_dir)
            .await
            .map_err(|_| SessionConsensusStorageError::BackendUnavailable)?;
        let (
            storage_identity,
            applied,
            database_file,
            proactive_checkpoint_lane,
            consensus_log_prune_lane,
        ) = {
            let conn = backend.conn.lock().await;
            let storage_identity = initialize_schema_with_storage_anchor_and_pending_and_bindings(
                &conn,
                required_storage_identity,
                identity,
                &expected_members,
                &expected_bindings,
                pending,
                authority_profile,
                fixed_placement_policy,
                roster_attestation_trust_root.as_ref(),
            )?;
            let applied = read_applied_sync(&conn, storage_identity)
                .map_err(|_| SessionConsensusStorageError::CorruptState)?;
            let database_file = match &backend.database_path {
                Some(path) => {
                    let file = opc_sqlite_file_control_sys::main_file_descriptor(&conn)
                        .map_err(|_| SessionConsensusStorageError::BackendUnavailable)?;
                    // The canonical path is only the reader's WAL lookup hint.
                    // The duplicated live descriptor remains authoritative.
                    let canonical_path = std::fs::canonicalize(path.as_ref())
                        .map_err(|_| SessionConsensusStorageError::BackendUnavailable)?;
                    let pinned = crate::consensus::snapshot::PinnedSqliteFile::from_file(
                        file,
                        canonical_path,
                    )
                    .map_err(|_| SessionConsensusStorageError::BackendUnavailable)?;
                    Some(Arc::new(pinned))
                }
                None => None,
            };
            // Construct the secondary connection while the primary is held:
            // no local write can race the descriptor comparison between the
            // live writer and this lane's exact backing file.
            let proactive_checkpoint_lane = database_file
                .as_ref()
                .map(|source| {
                    ProactiveCheckpointLane::start(
                        Arc::clone(source),
                        backend.checkpoint_vfs_name.clone(),
                        backend.consensus_diagnostics.clone(),
                        #[cfg(feature = "test-vfs")]
                        Arc::clone(&backend.proactive_checkpoint_idle_wait_hook),
                        #[cfg(feature = "test-vfs")]
                        Arc::clone(&backend.proactive_checkpoint_worker_observation),
                        #[cfg(feature = "test-vfs")]
                        Arc::clone(&backend.proactive_checkpoint_shutdown_join_hook),
                    )
                })
                .transpose()?;
            let consensus_log_prune_lane =
                if authority_profile == ConsensusAuthorityProfile::FixedImmutable {
                    database_file
                        .as_ref()
                        .map(|source| {
                            ConsensusLogPruneLane::start(
                                Arc::clone(source),
                                backend.checkpoint_vfs_name.clone(),
                                storage_identity,
                                expected_members.clone(),
                                expected_bindings.clone(),
                                fixed_placement_policy,
                                backend.consensus_diagnostics.clone(),
                            )
                        })
                        .transpose()?
                } else {
                    None
                };
            (
                storage_identity,
                applied,
                database_file,
                proactive_checkpoint_lane,
                consensus_log_prune_lane,
            )
        };
        let (applied_progress, _) = tokio::sync::watch::channel(applied);

        let core = Self {
            conn: Arc::clone(&backend.conn),
            database_file,
            proactive_checkpoint_lane,
            consensus_log_prune_lane,
            snapshot_observation: backend.snapshot_observation(),
            storage_identity,
            authority_profile,
            fixed_placement_policy,
            expected_members,
            expected_bindings,
            snapshot_dir: Arc::new(canonical_snapshot_dir),
            snapshot_cleanup_failed: Arc::new(AtomicBool::new(false)),
            // The core is shared by state-machine apply, snapshots, and
            // recovery/reopen paths. It must retain the consensus adapter's
            // advertised profile rather than SQLite's standalone ceiling.
            caps: backend.consensus_capabilities(),
            snapshot_gate: Arc::new(tokio::sync::Mutex::new(())),
            snapshot_receive_admission: Arc::new(tokio::sync::Semaphore::new(1)),
            applied_progress,
            watchers: Arc::clone(&backend.watchers),
            #[cfg(test)]
            apply_gate: Arc::clone(&backend.consensus_apply_gate),
            #[cfg(test)]
            snapshot_capture_gate: Arc::clone(&backend.consensus_snapshot_capture_gate),
        };
        if let Some(lane) = &core.consensus_log_prune_lane {
            lane.signal();
        }
        Ok(core)
    }
}

#[derive(Clone, Copy)]
pub(crate) struct PendingMembershipBootstrap<'a> {
    pub(crate) local_candidate_node_id: Option<SessionConsensusNodeId>,
    pub(crate) transition_id: [u8; MEMBERSHIP_TRANSITION_ID_BYTES],
    pub(crate) transition_digest: [u8; 32],
    pub(crate) desired_identity: SessionConsensusIdentity,
    pub(crate) desired_members: &'a BTreeSet<SessionConsensusNodeId>,
    pub(crate) desired_bindings: &'a BTreeMap<SessionConsensusNodeId, SessionTopologyMemberBinding>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum CandidateBootstrapState {
    Active,
    Cancelled,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct CandidateBootstrapMarker {
    local_candidate_node_id: SessionConsensusNodeId,
    transition_id: [u8; MEMBERSHIP_TRANSITION_ID_BYTES],
    transition_digest: [u8; 32],
    state: CandidateBootstrapState,
}

type CandidateBootstrapRow = (i64, i64, Vec<u8>, Vec<u8>, i64);

fn read_candidate_bootstrap_marker_sync(
    conn: &Connection,
    storage_identity: SessionConsensusIdentity,
) -> io::Result<Option<CandidateBootstrapMarker>> {
    if !table_exists(conn, "consensus_candidate_bootstrap").map_err(db_error)? {
        return Ok(None);
    }
    let row: Option<CandidateBootstrapRow> = conn
        .query_row(
            "SELECT storage_configuration_epoch, local_candidate_node_id, transition_id, transition_digest, state FROM consensus_candidate_bootstrap WHERE singleton = 1",
            [],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?, row.get(4)?)),
        )
        .optional()
        .map_err(db_error)?;
    let Some((storage_epoch, node_id, transition_id, transition_digest, state)) = row else {
        return Ok(None);
    };
    validate_epoch(storage_epoch, storage_identity)?;
    let node_id = SessionConsensusNodeId::new(checked_positive_u64(node_id)?)
        .map_err(|_| invalid_data("session consensus candidate node ID is invalid"))?;
    let transition_id = transition_id
        .try_into()
        .map_err(|_| invalid_data("session consensus candidate transition ID is invalid"))?;
    let transition_digest = transition_digest
        .try_into()
        .map_err(|_| invalid_data("session consensus candidate transition digest is invalid"))?;
    let state = match state {
        1 => CandidateBootstrapState::Active,
        2 => CandidateBootstrapState::Cancelled,
        _ => {
            return Err(invalid_data(
                "session consensus candidate bootstrap state is invalid",
            ));
        }
    };
    Ok(Some(CandidateBootstrapMarker {
        local_candidate_node_id: node_id,
        transition_id,
        transition_digest,
        state,
    }))
}

fn record_active_candidate_bootstrap_sync(
    conn: &Connection,
    storage_identity: SessionConsensusIdentity,
    local_candidate_node_id: SessionConsensusNodeId,
    transition_id: [u8; MEMBERSHIP_TRANSITION_ID_BYTES],
    transition_digest: [u8; 32],
) -> Result<(), SessionConsensusStorageError> {
    if read_candidate_bootstrap_marker_sync(conn, storage_identity)
        .map_err(|_| SessionConsensusStorageError::CorruptState)?
        .is_some_and(|marker| {
            marker.local_candidate_node_id != local_candidate_node_id
                || (marker.transition_id == transition_id
                    && (marker.transition_digest != transition_digest
                        || marker.state == CandidateBootstrapState::Cancelled))
        })
    {
        return Err(SessionConsensusStorageError::RecoveryRequired);
    }
    conn.execute(
        "INSERT INTO consensus_candidate_bootstrap (singleton, storage_configuration_epoch, local_candidate_node_id, transition_id, transition_digest, state) VALUES (1, ?1, ?2, ?3, ?4, 1) ON CONFLICT(singleton) DO UPDATE SET local_candidate_node_id = excluded.local_candidate_node_id, transition_id = excluded.transition_id, transition_digest = excluded.transition_digest, state = 1",
        params![
            epoch_i64(storage_identity)
                .map_err(|_| SessionConsensusStorageError::CorruptState)?,
            checked_positive_i64(local_candidate_node_id.get())
                .map_err(|_| SessionConsensusStorageError::InvalidIdentity)?,
            transition_id.as_slice(),
            transition_digest.as_slice(),
        ],
    )
    .map_err(|_| SessionConsensusStorageError::BackendUnavailable)?;
    Ok(())
}

