fn purge_logs_in_tx(
    tx: &Transaction<'_>,
    identity: SessionConsensusIdentity,
    through: &LogId<SessionConsensusNodeId>,
    index: i64,
) -> io::Result<()> {
    if let Some(current) = read_purged_sync(tx, identity)? {
        if through.index < current.index || (through.index == current.index && through != &current)
        {
            return Err(invalid_data("session consensus purged index regressed"));
        }
    }
    let applied = read_applied_sync(tx, identity)?
        .ok_or_else(|| invalid_data("session consensus cannot purge unapplied logs"))?;
    if through.index > applied.index {
        return Err(invalid_data(
            "session consensus cannot purge unapplied logs",
        ));
    }
    tx.execute("DELETE FROM consensus_log WHERE log_index <= ?1", [index])
        .map_err(db_error)?;
    save_log_pointer(tx, "consensus_purged", identity, through)?;
    Ok(())
}

pub(crate) fn read_applied_sync(
    conn: &Connection,
    identity: SessionConsensusIdentity,
) -> io::Result<Option<LogId<SessionConsensusNodeId>>> {
    read_log_pointer(conn, "consensus_applied", identity)
}

fn is_pristine_membership(
    membership: &StoredMembership<SessionConsensusNodeId, opc_consensus::engine::EmptyNode>,
) -> bool {
    membership.log_id().is_none()
        && membership.membership().get_joint_config().is_empty()
        && membership.nodes().next().is_none()
}

fn validate_uniform_membership(
    membership: &StoredMembership<SessionConsensusNodeId, opc_consensus::engine::EmptyNode>,
    expected_members: &BTreeSet<SessionConsensusNodeId>,
) -> io::Result<()> {
    validate_member_set(expected_members, false)?;
    let config = membership.membership().get_joint_config();
    let nodes = membership
        .nodes()
        .map(|(node_id, _)| *node_id)
        .collect::<BTreeSet<_>>();
    if config.len() != 1
        || config.first() != Some(expected_members)
        || nodes != *expected_members
        || membership.membership().learner_ids().next().is_some()
    {
        return Err(invalid_data(
            "session consensus membership does not match admitted topology",
        ));
    }
    Ok(())
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum MembershipShape {
    CurrentUniform,
    LearnersCatchingUp,
    Joint,
    DesiredUniform,
}

fn classify_transition_membership(
    membership: &StoredMembership<SessionConsensusNodeId, opc_consensus::engine::EmptyNode>,
    current_members: &BTreeSet<SessionConsensusNodeId>,
    desired_members: &BTreeSet<SessionConsensusNodeId>,
) -> io::Result<MembershipShape> {
    validate_member_set(current_members, true)?;
    validate_member_set(desired_members, true)?;
    let configs = membership.membership().get_joint_config();
    let nodes = membership
        .nodes()
        .map(|(node_id, _)| *node_id)
        .collect::<BTreeSet<_>>();
    let learners = membership
        .membership()
        .learner_ids()
        .collect::<BTreeSet<_>>();
    let union = current_members
        .union(desired_members)
        .copied()
        .collect::<BTreeSet<_>>();

    if configs.len() == 1 && configs.first() == Some(current_members) {
        if nodes == *current_members && learners.is_empty() {
            return Ok(MembershipShape::CurrentUniform);
        }
        let expected_learners = nodes
            .difference(current_members)
            .copied()
            .collect::<BTreeSet<_>>();
        if nodes.is_superset(current_members)
            && nodes.is_subset(&union)
            && !expected_learners.is_empty()
            && learners == expected_learners
            && expected_learners.is_subset(desired_members)
        {
            return Ok(MembershipShape::LearnersCatchingUp);
        }
    }

    if configs.len() == 2
        && configs.iter().any(|config| config == current_members)
        && configs.iter().any(|config| config == desired_members)
        && current_members != desired_members
        && nodes == union
        && learners.is_empty()
    {
        return Ok(MembershipShape::Joint);
    }

    if configs.len() == 1
        && configs.first() == Some(desired_members)
        && nodes == *desired_members
        && learners.is_empty()
    {
        return Ok(MembershipShape::DesiredUniform);
    }

    Err(invalid_data(
        "session consensus membership is outside the admitted transition",
    ))
}

fn validate_all_added_learners_present(
    membership: &StoredMembership<SessionConsensusNodeId, opc_consensus::engine::EmptyNode>,
    current_members: &BTreeSet<SessionConsensusNodeId>,
    desired_members: &BTreeSet<SessionConsensusNodeId>,
) -> io::Result<()> {
    let additions = desired_members
        .difference(current_members)
        .copied()
        .collect::<BTreeSet<_>>();
    if additions.is_empty() {
        return validate_uniform_membership(membership, current_members);
    }
    let expected_nodes = current_members
        .union(&additions)
        .copied()
        .collect::<BTreeSet<_>>();
    let configs = membership.membership().get_joint_config();
    let nodes = membership
        .nodes()
        .map(|(node_id, _)| *node_id)
        .collect::<BTreeSet<_>>();
    let learners = membership
        .membership()
        .learner_ids()
        .collect::<BTreeSet<_>>();
    if configs.len() != 1
        || configs.first() != Some(current_members)
        || nodes != expected_nodes
        || learners != additions
    {
        return Err(invalid_data(
            "session consensus added learners are not completely admitted",
        ));
    }
    Ok(())
}

fn abort_learners_from_membership(
    membership: &StoredMembership<SessionConsensusNodeId, opc_consensus::engine::EmptyNode>,
    current_members: &BTreeSet<SessionConsensusNodeId>,
    desired_members: &BTreeSet<SessionConsensusNodeId>,
) -> io::Result<BTreeSet<SessionConsensusNodeId>> {
    match classify_transition_membership(membership, current_members, desired_members)? {
        MembershipShape::CurrentUniform => Ok(BTreeSet::new()),
        MembershipShape::LearnersCatchingUp => Ok(membership
            .membership()
            .learner_ids()
            .collect::<BTreeSet<_>>()),
        MembershipShape::Joint | MembershipShape::DesiredUniform => Err(invalid_data(
            "session consensus abort followed an irreversible membership change",
        )),
    }
}

fn validate_aborted_membership_before_cleanup(
    membership: &StoredMembership<SessionConsensusNodeId, opc_consensus::engine::EmptyNode>,
    current_members: &BTreeSet<SessionConsensusNodeId>,
    learners: &BTreeSet<SessionConsensusNodeId>,
) -> io::Result<()> {
    let configs = membership.membership().get_joint_config();
    let nodes = membership
        .nodes()
        .map(|(node_id, _)| *node_id)
        .collect::<BTreeSet<_>>();
    let stored_learners = membership
        .membership()
        .learner_ids()
        .collect::<BTreeSet<_>>();
    let expected_nodes = current_members
        .union(learners)
        .copied()
        .collect::<BTreeSet<_>>();
    if configs.len() != 1
        || configs.first() != Some(current_members)
        || nodes != expected_nodes
        || stored_learners != *learners
    {
        return Err(invalid_data(
            "session consensus membership does not match the durable abort decision",
        ));
    }
    Ok(())
}

fn validate_membership_for_log(
    membership: &StoredMembership<SessionConsensusNodeId, opc_consensus::engine::EmptyNode>,
    scope: &MembershipValidationScope,
    log_index: u64,
) -> io::Result<()> {
    validate_membership_ids(membership)?;
    let predecessors = scope
        .history
        .iter()
        .chain(scope.predecessor.iter())
        .collect::<Vec<_>>();
    for (offset, predecessor) in predecessors.iter().enumerate() {
        let successor_members = predecessors
            .get(offset + 1)
            .map_or(&scope.current_members, |next| &next.members);
        if log_index < predecessor.transition_start_log_index {
            return validate_uniform_membership(membership, &predecessor.members);
        }
        if log_index <= predecessor.cutover_log_index {
            classify_transition_membership(membership, &predecessor.members, successor_members)?;
            return Ok(());
        }
    }
    if let Some(pending) = &scope.pending {
        let shape = classify_transition_membership(
            membership,
            &scope.current_members,
            &pending.desired_members,
        )?;
        if matches!(
            shape,
            MembershipShape::Joint | MembershipShape::DesiredUniform
        ) && (pending.learners_ready_log_index.is_none()
            || scope.application_authority_epoch != pending.desired_identity.configuration_epoch()
            || scope.application_authority_members != pending.desired_members)
        {
            return Err(invalid_data(
                "session consensus joint membership preceded durable learner readiness or its authority fence",
            ));
        }
        if log_index < pending.transition_start_log_index
            && shape != MembershipShape::CurrentUniform
        {
            return Err(invalid_data(
                "session consensus membership transition predates its durable scope",
            ));
        }
        return Ok(());
    }
    if let Some(cleanup) = scope
        .terminal
        .as_ref()
        .filter(|terminal| terminal.outcome == TerminalMembershipOutcome::Aborted)
        .and_then(|terminal| terminal.abort_cleanup.as_ref())
    {
        if log_index < cleanup.decision_log_index {
            return validate_aborted_membership_before_cleanup(
                membership,
                &scope.current_members,
                &cleanup.learners,
            );
        }
        if log_index == cleanup.decision_log_index {
            return Err(invalid_data(
                "session consensus membership collides with abort decision index",
            ));
        }
        validate_uniform_membership(membership, &scope.current_members)?;
        if cleanup
            .cleanup_log_index
            .is_some_and(|recorded| recorded != log_index)
        {
            return Err(invalid_data(
                "session consensus abort cleanup membership evidence conflicts",
            ));
        }
        return Ok(());
    }
    validate_uniform_membership(membership, &scope.current_members)
}

fn validate_persisted_membership_sync(
    conn: &Connection,
    storage_identity: SessionConsensusIdentity,
) -> io::Result<()> {
    let applied = read_applied_sync(conn, storage_identity)?;
    let membership = read_membership_unchecked_sync(conn, storage_identity)?;
    if is_pristine_membership(&membership) {
        if applied.is_none() {
            return Ok(());
        }
        return Err(invalid_data(
            "session consensus applied state has pristine membership",
        ));
    }
    let scope = read_membership_scope_sync(conn, storage_identity)?;
    let log_index = membership
        .log_id()
        .ok_or_else(|| invalid_data("session consensus membership log identity is missing"))?
        .index;
    validate_membership_for_log(&membership, &scope, log_index)
}

fn read_membership_unchecked_sync(
    conn: &Connection,
    identity: SessionConsensusIdentity,
) -> io::Result<StoredMembership<SessionConsensusNodeId, opc_consensus::engine::EmptyNode>> {
    let (epoch, encoded): (i64, Vec<u8>) = conn
        .query_row(
            "SELECT configuration_epoch, membership_json FROM consensus_membership WHERE singleton = 1",
            [],
            |row| Ok((row.get(0)?, row.get(1)?)),
        )
        .map_err(db_error)?;
    validate_epoch(epoch, identity)?;
    decode_json(&encoded)
}

pub(crate) fn read_membership_sync(
    conn: &Connection,
    storage_identity: SessionConsensusIdentity,
) -> io::Result<StoredMembership<SessionConsensusNodeId, opc_consensus::engine::EmptyNode>> {
    let membership = read_membership_unchecked_sync(conn, storage_identity)?;
    if is_pristine_membership(&membership) && read_applied_sync(conn, storage_identity)?.is_none() {
        return Ok(membership);
    }
    let scope = read_membership_scope_sync(conn, storage_identity)?;
    let log_index = membership
        .log_id()
        .ok_or_else(|| invalid_data("session consensus membership log identity is missing"))?
        .index;
    validate_membership_for_log(&membership, &scope, log_index)?;
    Ok(membership)
}

fn payload_digest(
    storage_identity: SessionConsensusIdentity,
    command: &SessionConsensusCommand,
) -> io::Result<[u8; 32]> {
    // Idempotency binds caller-owned semantics, not leader-owned sequence,
    // predecessor, or logical-time metadata. A retry after a committed
    // response is lost will be proposed by a new leader with new metadata but
    // must still recover the original durable outcome. Generic application
    // commands retain their historical authorized-authority binding below.
    // Fenced transitions are deliberately different: their complete caller
    // request is retained across a dynamic authority rollover, while every
    // access remains independently authorized at its own admission boundary.
    let encoded = match &command.intent {
        SessionMutationIntent::Authorized { mutation, .. }
            if fenced_transition_v2_request(mutation).is_some() =>
        {
            let request = fenced_transition_v2_request(mutation).expect("checked above");
            // Apply computes the caller payload commitment before dispatching
            // to the V2 terminal path.  A self-authenticated body conflict is
            // intentionally accepted into that path (and must win even after
            // reclamation), so it cannot make this preliminary digest step a
            // state-machine fault.  The ID-only canonical payload value is
            // unused by the conflict response; a valid bind still recomputes
            // and validates the complete body below.
            return match request.validate() {
                Ok(()) => fenced_transition_v2_payload_digest(storage_identity, request),
                Err(StoreError::FencedTransitionRequestConflict) => {
                    fenced_transition_v2_payload_digest_for_request_id(
                        storage_identity,
                        request.request_id().to_bytes(),
                    )
                }
                Err(_) => Err(invalid_data("fenced transition V2 request is invalid")),
            };
        }
        SessionMutationIntent::Authorized { mutation, .. }
            if fenced_transition_request(mutation).is_some() =>
        {
            return fenced_transition_payload_digest(
                storage_identity,
                fenced_transition_request(mutation).expect("checked above"),
            );
        }
        SessionMutationIntent::FencedTransition(request)
        | SessionMutationIntent::ActivateFencedTransition { request, .. } => {
            return fenced_transition_payload_digest(storage_identity, request);
        }
        SessionMutationIntent::FencedTransitionV2(request)
        | SessionMutationIntent::ActivateFencedTransitionV2 { request, .. } => {
            return match request.validate() {
                Ok(()) => fenced_transition_v2_payload_digest(storage_identity, request),
                Err(StoreError::FencedTransitionRequestConflict) => {
                    fenced_transition_v2_payload_digest_for_request_id(
                        storage_identity,
                        request.request_id().to_bytes(),
                    )
                }
                Err(_) => Err(invalid_data("fenced transition V2 request is invalid")),
            };
        }
        SessionMutationIntent::Authorized {
            authority_identity,
            mutation,
            ..
        } => {
            return authorized_mutation_payload_digest(
                storage_identity,
                *authority_identity,
                mutation.as_ref(),
            );
        }
        intent => encode_json(&(command.schema_version, command.identity, intent))?,
    };
    let mut hasher = Sha256::new();
    hasher.update(OUTCOME_DIGEST_DOMAIN);
    hasher.update(encoded);
    Ok(hasher.finalize().into())
}

/// Calculate the durable payload digest for the authenticated application
/// envelope without reconstructing a leader-owned command.  Receipt status
/// uses this for an already-authorized exact scope; it deliberately accepts
/// neither a client-supplied internal request ID nor an unbound digest.
fn authorized_mutation_payload_digest(
    storage_identity: SessionConsensusIdentity,
    authority_identity: SessionConsensusIdentity,
    mutation: &SessionMutationIntent,
) -> io::Result<[u8; 32]> {
    authorized_payload_digest(storage_identity, authority_identity, mutation)
}

fn authorized_payload_digest<T: serde::Serialize>(
    storage_identity: SessionConsensusIdentity,
    authority_identity: SessionConsensusIdentity,
    mutation: &T,
) -> io::Result<[u8; 32]> {
    let encoded = encode_json(&(
        SESSION_CONSENSUS_SCHEMA_VERSION,
        storage_identity,
        authority_identity,
        mutation,
    ))?;
    let mut hasher = Sha256::new();
    hasher.update(OUTCOME_DIGEST_DOMAIN);
    hasher.update(encoded);
    Ok(hasher.finalize().into())
}

/// Fixed, precomputed identifiers and commitments for one read-only prepared
/// CAS receipt lookup. This crosses the async SQLite boundary without the
/// sealed request body, so the blocking task never clones or reserializes it.
#[derive(Clone, Copy)]
pub(crate) struct ConsumerCompareAndSetReceiptLookup {
    pub(crate) binding_request_id: SessionConsensusRequestId,
    pub(crate) operation_request_id: SessionConsensusRequestId,
    binding_digest: [u8; 32],
    operation_digest: [u8; 32],
}

/// Read-only exact binding lookup used by the leader before proposing a
/// consumer binding marker. It distinguishes an absent ID from a retained
/// exact binding or a closed body/context conflict without copying an
/// application payload.
pub(crate) enum ConsumerRequestBindingLookup {
    Missing,
    Matched(Box<SessionConsensusResponse>),
    Conflict,
}

pub(crate) fn read_consumer_request_binding_sync(
    conn: &Connection,
    storage_identity: SessionConsensusIdentity,
    authority_identity: SessionConsensusIdentity,
    binding_request_id: SessionConsensusRequestId,
    request_commitment: [u8; 32],
) -> Result<ConsumerRequestBindingLookup, StoreError> {
    let binding_digest = authorized_mutation_payload_digest(
        storage_identity,
        authority_identity,
        &SessionMutationIntent::BindConsumerRequest { request_commitment },
    )
    .map_err(|_| StoreError::BackendUnavailable("consumer binding lookup is unavailable".into()))?;
    match read_outcome_sync(conn, storage_identity, binding_request_id).map_err(|_| {
        StoreError::BackendUnavailable("consumer binding lookup is unavailable".into())
    })? {
        Some((digest, response))
            if digest == binding_digest
                && matches!(&response.result, Ok(SessionMutationOutcome::Unit)) =>
        {
            Ok(ConsumerRequestBindingLookup::Matched(Box::new(response)))
        }
        Some(_) => Ok(ConsumerRequestBindingLookup::Conflict),
        None if request_id_has_fenced_transition_receipt_sync(
            conn,
            storage_identity,
            binding_request_id,
        )? =>
        {
            Ok(ConsumerRequestBindingLookup::Conflict)
        }
        None => Ok(ConsumerRequestBindingLookup::Missing),
    }
}

#[derive(serde::Serialize)]
enum BorrowedCompareAndSetIntent<'a> {
    CompareAndSet(&'a crate::backend::CompareAndSet),
}

/// Compute the exact ledger keys and payload digests once while the
/// authenticated service still borrows its canonical prepared CAS body.
pub(crate) fn consumer_compare_and_set_receipt_lookup(
    storage_identity: SessionConsensusIdentity,
    authority_identity: SessionConsensusIdentity,
    binding_request_id: SessionConsensusRequestId,
    operation_request_id: SessionConsensusRequestId,
    request_commitment: [u8; 32],
    operation: &crate::backend::CompareAndSet,
) -> io::Result<ConsumerCompareAndSetReceiptLookup> {
    let binding_digest = authorized_mutation_payload_digest(
        storage_identity,
        authority_identity,
        &SessionMutationIntent::BindConsumerRequest { request_commitment },
    )?;
    let operation_digest = authorized_payload_digest(
        storage_identity,
        authority_identity,
        &BorrowedCompareAndSetIntent::CompareAndSet(operation),
    )?;
    Ok(ConsumerCompareAndSetReceiptLookup {
        binding_request_id,
        operation_request_id,
        binding_digest,
        operation_digest,
    })
}

/// Return the sole fenced-transition request carried by an application
/// intent. Authority wrappers convey per-access admission, not caller request
/// semantics, so fenced receipt binding deliberately excludes the wrapper.
fn fenced_transition_request(intent: &SessionMutationIntent) -> Option<&FencedTransitionRequest> {
    match intent {
        SessionMutationIntent::FencedTransition(request) => Some(request),
        SessionMutationIntent::ActivateFencedTransition { request, .. } => Some(request),
        SessionMutationIntent::Authorized { mutation, .. } => match mutation.as_ref() {
            SessionMutationIntent::FencedTransition(request)
            | SessionMutationIntent::ActivateFencedTransition { request, .. } => Some(request),
            _ => None,
        },
        _ => None,
    }
}

enum RosterCommandRef<'a> {
    Admission(&'a ConsensusRosterAdmissionCommand),
    Terminal(&'a ConsensusRosterTerminalCommand),
}

fn roster_command(intent: &SessionMutationIntent) -> Option<RosterCommandRef<'_>> {
    let intent = match intent {
        SessionMutationIntent::Authorized { mutation, .. } => mutation.as_ref(),
        intent => intent,
    };
    match intent {
        SessionMutationIntent::RosterAdmission(command) => {
            Some(RosterCommandRef::Admission(command))
        }
        SessionMutationIntent::RosterTerminal(command) => Some(RosterCommandRef::Terminal(command)),
        _ => None,
    }
}

fn fenced_transition_v2_request(
    intent: &SessionMutationIntent,
) -> Option<&FencedTransitionV2Request> {
    match intent {
        SessionMutationIntent::FencedTransitionV2(request) => Some(request),
        SessionMutationIntent::ActivateFencedTransitionV2 { request, .. } => Some(request),
        SessionMutationIntent::Authorized { mutation, .. } => match mutation.as_ref() {
            SessionMutationIntent::FencedTransitionV2(request)
            | SessionMutationIntent::ActivateFencedTransitionV2 { request, .. } => Some(request),
            _ => None,
        },
        _ => None,
    }
}

/// Return the ordered V2 requests carried by a batch intent. A batch is
/// deliberately not treated as a singleton at any layer: each item retains
/// its own receipt identity, deterministic result, and ordered capacity
/// decision even though all items share one physical consensus position.
fn fenced_transition_v2_batch(
    intent: &SessionMutationIntent,
) -> Option<&[FencedTransitionV2Request]> {
    match intent {
        SessionMutationIntent::FencedTransitionV2Batch(requests) => Some(requests),
        SessionMutationIntent::Authorized { mutation, .. } => match mutation.as_ref() {
            SessionMutationIntent::FencedTransitionV2Batch(requests) => Some(requests),
            _ => None,
        },
        _ => None,
    }
}

fn fenced_transition_activation(
    intent: &SessionMutationIntent,
) -> Option<(SessionConsensusIdentity, [u8; 32])> {
    match intent {
        SessionMutationIntent::ActivateFencedTransition {
            scope_identity,
            voter_set_digest,
            ..
        } => Some((*scope_identity, *voter_set_digest)),
        SessionMutationIntent::ActivateFencedTransitionCapability {
            schema_version,
            scope_identity,
            voter_set_digest,
        } if *schema_version == FENCED_TRANSITION_SCHEMA_V1 => {
            Some((*scope_identity, *voter_set_digest))
        }
        SessionMutationIntent::Authorized { mutation, .. } => match mutation.as_ref() {
            SessionMutationIntent::ActivateFencedTransition {
                scope_identity,
                voter_set_digest,
                ..
            } => Some((*scope_identity, *voter_set_digest)),
            SessionMutationIntent::ActivateFencedTransitionCapability {
                schema_version,
                scope_identity,
                voter_set_digest,
            } if *schema_version == FENCED_TRANSITION_SCHEMA_V1 => {
                Some((*scope_identity, *voter_set_digest))
            }
            _ => None,
        },
        _ => None,
    }
}

fn fenced_transition_v2_activation(
    intent: &SessionMutationIntent,
) -> Option<(SessionConsensusIdentity, [u8; 32], [u8; 32])> {
    match intent {
        SessionMutationIntent::ActivateFencedTransitionV2 {
            scope_identity,
            voter_set_digest,
            profile_digest,
            ..
        } => Some((*scope_identity, *voter_set_digest, *profile_digest)),
        SessionMutationIntent::Authorized { mutation, .. } => match mutation.as_ref() {
            SessionMutationIntent::ActivateFencedTransitionV2 {
                scope_identity,
                voter_set_digest,
                profile_digest,
                ..
            } => Some((*scope_identity, *voter_set_digest, *profile_digest)),
            _ => None,
        },
        _ => None,
    }
}

/// Maintenance is intentionally a raw, SDK-internal intent.  In particular it
/// must never be smuggled through an application-authority wrapper and fall
/// into the generic outcome ledger: its only durable state is the V2 history
/// singleton and its bounded receipt table.
fn fenced_transition_v2_maintenance(
    intent: &SessionMutationIntent,
) -> Option<(u64, Option<FencedTransitionV2HistoryEpoch>, u64, u64)> {
    match intent {
        SessionMutationIntent::MaintainFencedTransitionV2History {
            expected_generation,
            expected_active_epoch,
            expected_retired_through,
            expected_bound_entries,
        } => Some((
            *expected_generation,
            *expected_active_epoch,
            *expected_retired_through,
            *expected_bound_entries,
        )),
        _ => None,
    }
}

/// Compute the stable fenced receipt binding used by application and status.
/// It binds the complete canonical request to the stable storage/consensus
/// identity, but intentionally excludes changing authority, leader timestamp,
/// and log metadata.
fn fenced_transition_payload_digest(
    storage_identity: SessionConsensusIdentity,
    request: &FencedTransitionRequest,
) -> io::Result<[u8; 32]> {
    let intent = SessionMutationIntent::FencedTransition(Box::new(request.clone()));
    let encoded = encode_json(&(FENCED_TRANSITION_SCHEMA_V1, storage_identity, intent))?;
    let mut hasher = Sha256::new();
    hasher.update(FENCED_TRANSITION_PAYLOAD_DIGEST_DOMAIN);
    hasher.update(encoded);
    Ok(hasher.finalize().into())
}

pub(crate) fn fenced_transition_v2_payload_digest(
    storage_identity: SessionConsensusIdentity,
    request: &FencedTransitionV2Request,
) -> io::Result<[u8; 32]> {
    // This is receipt protocol material, not a serde DTO.  In particular, a
    // serde representation can change field names, enum encodings, or array
    // handling without changing the self-authenticated V2 request.  Bind the
    // stable storage identity and every byte of that already-validated full
    // ID with fixed-width, profile-covered framing instead.
    request
        .validate()
        .map_err(|_| invalid_data("fenced transition V2 request is invalid"))?;
    fenced_transition_v2_payload_digest_for_request_id(
        storage_identity,
        request.request_id().to_bytes(),
    )
}

/// Canonical V2 payload commitment for a full already-validated request ID.
/// Receipts retain the self-authenticating 56-byte ID rather than a second
/// request-body copy, so reopen and attached-snapshot validation must derive
/// the same commitment directly from that durable identity.
pub(crate) fn fenced_transition_v2_payload_digest_for_request_id(
    storage_identity: SessionConsensusIdentity,
    request_id: [u8; FENCED_TRANSITION_V2_REQUEST_ID_BYTES],
) -> io::Result<[u8; 32]> {
    let mut hasher = Sha256::new();
    hasher.update(FENCED_TRANSITION_V2_PAYLOAD_DIGEST_DOMAIN);
    hasher.update(FENCED_TRANSITION_SCHEMA_V2.to_be_bytes());
    hasher.update(fenced_transition_v2_profile_digest());
    update_fenced_transition_v2_storage_identity(&mut hasher, storage_identity);
    hasher.update(request_id);
    Ok(hasher.finalize().into())
}

/// Stable primitive encoding shared by V2 payload and receipt commitments.
/// These fields are intentionally explicit: `ConsensusIdentity`'s serde
/// shape is not a V2 protocol dependency.
fn update_fenced_transition_v2_storage_identity(
    hasher: &mut Sha256,
    identity: SessionConsensusIdentity,
) {
    hasher.update(identity.cluster_id().as_bytes());
    hasher.update(identity.configuration_id().as_bytes());
    hasher.update(identity.configuration_epoch().get().to_be_bytes());
}

fn update_fenced_transition_v2_length_prefixed(
    hasher: &mut Sha256,
    bytes: &[u8],
) -> io::Result<()> {
    let length = u64::try_from(bytes.len())
        .map_err(|_| invalid_data("fenced transition V2 byte length is invalid"))?;
    hasher.update(length.to_be_bytes());
    hasher.update(bytes);
    Ok(())
}

fn fenced_transition_receipt_binding_digest(
    identity: SessionConsensusIdentity,
    request_id: SessionConsensusRequestId,
    payload_digest: [u8; 32],
    retained_until: &str,
) -> io::Result<[u8; 32]> {
    let encoded = encode_json(&(
        FENCED_TRANSITION_SCHEMA_V1,
        identity,
        request_id.as_bytes(),
        payload_digest,
        retained_until,
    ))?;
    let mut hasher = Sha256::new();
    hasher.update(FENCED_TRANSITION_RECEIPT_BINDING_DIGEST_DOMAIN);
    hasher.update(encoded);
    Ok(hasher.finalize().into())
}

fn fenced_transition_receipt_response_digest(
    binding_digest: [u8; 32],
    response: &SessionConsensusResponse,
) -> io::Result<[u8; 32]> {
    let encoded = encode_json(response)?;
    let mut hasher = Sha256::new();
    hasher.update(FENCED_TRANSITION_RECEIPT_RESPONSE_DIGEST_DOMAIN);
    hasher.update(binding_digest);
    hasher.update(encoded);
    Ok(hasher.finalize().into())
}

struct FencedTransitionReceipt {
    payload_digest: [u8; 32],
    retained_until: Timestamp,
    response: Option<SessionConsensusResponse>,
}

struct FencedTransitionV2Receipt {
    history_epoch: u64,
    payload_digest: [u8; 32],
    retained_until: Timestamp,
    response: Option<SessionConsensusResponse>,
}

pub(crate) fn fenced_transition_v2_receipt_binding_digest(
    identity: SessionConsensusIdentity,
    request_id: [u8; FENCED_TRANSITION_V2_REQUEST_ID_BYTES],
    history_epoch: u64,
    ordinal: u64,
    payload_digest: [u8; 32],
    retained_until: &str,
) -> io::Result<[u8; 32]> {
    let mut hasher = Sha256::new();
    hasher.update(FENCED_TRANSITION_V2_RECEIPT_BINDING_DIGEST_DOMAIN);
    hasher.update(FENCED_TRANSITION_SCHEMA_V2.to_be_bytes());
    hasher.update(fenced_transition_v2_profile_digest());
    update_fenced_transition_v2_storage_identity(&mut hasher, identity);
    hasher.update(request_id);
    hasher.update(history_epoch.to_be_bytes());
    hasher.update(ordinal.to_be_bytes());
    hasher.update(payload_digest);
    update_fenced_transition_v2_length_prefixed(&mut hasher, retained_until.as_bytes())?;
    Ok(hasher.finalize().into())
}

pub(crate) fn fenced_transition_v2_receipt_response_digest(
    binding_digest: [u8; 32],
    encoded_response: &[u8],
) -> io::Result<[u8; 32]> {
    let mut hasher = Sha256::new();
    hasher.update(FENCED_TRANSITION_V2_RECEIPT_RESPONSE_DIGEST_DOMAIN);
    hasher.update(binding_digest);
    update_fenced_transition_v2_length_prefixed(&mut hasher, encoded_response)?;
    Ok(hasher.finalize().into())
}

fn fenced_transition_v2_response_invalid() -> io::Error {
    invalid_data("persisted fenced transition V2 response is invalid")
}

fn append_fenced_transition_v2_response_length_prefixed(
    out: &mut Vec<u8>,
    value: &[u8],
) -> io::Result<()> {
    let length = u64::try_from(value.len()).map_err(|_| fenced_transition_v2_response_invalid())?;
    out.extend_from_slice(&length.to_be_bytes());
    out.extend_from_slice(value);
    Ok(())
}

fn append_fenced_transition_v2_response_timestamp(
    out: &mut Vec<u8>,
    value: Timestamp,
) -> io::Result<()> {
    if !fenced_transition_v2_timestamp_is_in_range(value) {
        return Err(fenced_transition_v2_response_invalid());
    }
    let value = value.as_offset_datetime();
    out.extend_from_slice(&value.unix_timestamp().to_be_bytes());
    out.extend_from_slice(&value.nanosecond().to_be_bytes());
    Ok(())
}

fn append_fenced_transition_v2_response_key(out: &mut Vec<u8>, key: &SessionKey) -> io::Result<()> {
    append_fenced_transition_v2_response_length_prefixed(out, key.tenant.as_str().as_bytes())?;
    append_fenced_transition_v2_response_length_prefixed(out, key.nf_kind.as_str().as_bytes())?;
    match &key.key_type {
        SessionKeyType::SubscriberContext => out.push(FENCED_TRANSITION_V2_KEY_SUBSCRIBER_CONTEXT),
        SessionKeyType::PduSession => out.push(FENCED_TRANSITION_V2_KEY_PDU_SESSION),
        SessionKeyType::TeidMapping => out.push(FENCED_TRANSITION_V2_KEY_TEID_MAPPING),
        SessionKeyType::PfcpSeid => out.push(FENCED_TRANSITION_V2_KEY_PFCP_SEID),
        SessionKeyType::HandoverTransaction => {
            out.push(FENCED_TRANSITION_V2_KEY_HANDOVER_TRANSACTION)
        }
        SessionKeyType::Other(value) => {
            out.push(FENCED_TRANSITION_V2_KEY_OTHER);
            append_fenced_transition_v2_response_length_prefixed(out, value.as_str().as_bytes())?;
        }
    }
    append_fenced_transition_v2_response_length_prefixed(out, key.stable_id.as_bytes())
}

fn append_fenced_transition_v2_response_lease(
    out: &mut Vec<u8>,
    lease: &LeaseGuard,
) -> io::Result<()> {
    append_fenced_transition_v2_response_key(out, lease.key())?;
    append_fenced_transition_v2_response_length_prefixed(out, lease.owner().as_str().as_bytes())?;
    out.extend_from_slice(&lease.fence().get().to_be_bytes());
    append_fenced_transition_v2_response_timestamp(out, lease.acquired_at())?;
    append_fenced_transition_v2_response_timestamp(out, lease.expires_at())?;
    out.extend_from_slice(&lease.credential_id().to_be_bytes());
    Ok(())
}

fn append_fenced_transition_v2_response_mutation(
    out: &mut Vec<u8>,
    mutation: FencedTransitionMutationResult,
) -> io::Result<()> {
    match mutation {
        FencedTransitionMutationResult::Created => out.push(FENCED_TRANSITION_V2_MUTATION_CREATED),
        FencedTransitionMutationResult::Updated => out.push(FENCED_TRANSITION_V2_MUTATION_UPDATED),
        FencedTransitionMutationResult::Deleted => out.push(FENCED_TRANSITION_V2_MUTATION_DELETED),
        FencedTransitionMutationResult::TtlRefreshed { expires_at } => {
            out.push(FENCED_TRANSITION_V2_MUTATION_TTL_REFRESHED);
            append_fenced_transition_v2_response_timestamp(out, expires_at)?;
        }
    }
    Ok(())
}

/// Encode the only receipt envelope forms V2 permits.  This is intentionally
/// not a general `SessionConsensusResponse` codec: accepting an unrelated
/// success or error would make a durable V2 retry result build-dependent.
pub(crate) fn encode_fenced_transition_v2_response(
    response: &SessionConsensusResponse,
) -> io::Result<Vec<u8>> {
    if response.sequence == 0
        || response.digest.is_none()
        || response.logical_time.is_none()
        || response.raft_log_index == 0
    {
        return Err(fenced_transition_v2_response_invalid());
    }
    let mut out = Vec::with_capacity(256);
    out.extend_from_slice(&FENCED_TRANSITION_V2_RECEIPT_RESPONSE_CODEC_MAGIC);
    out.push(FENCED_TRANSITION_V2_RECEIPT_RESPONSE_CODEC_REVISION);
    match &response.result {
        Ok(SessionMutationOutcome::FencedTransition(outcome)) => {
            outcome
                .validate()
                .map_err(|_| fenced_transition_v2_response_invalid())?;
            out.push(FENCED_TRANSITION_V2_RESPONSE_SUCCESS);
            append_fenced_transition_v2_response_lease(&mut out, outcome.lease())?;
            out.extend_from_slice(&outcome.committed_generation().get().to_be_bytes());
            append_fenced_transition_v2_response_mutation(&mut out, outcome.mutation())?;
            append_fenced_transition_v2_response_timestamp(&mut out, outcome.recorded_at())?;
        }
        Err(StoreError::PayloadTooLarge { actual, max }) => {
            let actual =
                u64::try_from(*actual).map_err(|_| fenced_transition_v2_response_invalid())?;
            let max = u64::try_from(*max).map_err(|_| fenced_transition_v2_response_invalid())?;
            if max != FENCED_TRANSITION_V2_MAX_RECORD_PAYLOAD_BYTES as u64
                || actual <= max
                || actual > FENCED_TRANSITION_V2_MAX_PAYLOAD_TOO_LARGE_ACTUAL_BYTES
            {
                return Err(fenced_transition_v2_response_invalid());
            }
            out.push(FENCED_TRANSITION_V2_RESPONSE_PAYLOAD_TOO_LARGE);
            out.extend_from_slice(&actual.to_be_bytes());
            out.extend_from_slice(&max.to_be_bytes());
        }
        Err(error) => out.push(fenced_transition_v2_response_error_tag(error)?),
        _ => return Err(fenced_transition_v2_response_invalid()),
    }
    out.extend_from_slice(&response.sequence.to_be_bytes());
    out.extend_from_slice(
        response
            .digest
            .expect("V2 response metadata is checked before encoding")
            .as_bytes(),
    );
    append_fenced_transition_v2_response_timestamp(
        &mut out,
        response
            .logical_time
            .expect("V2 response metadata is checked before encoding"),
    )?;
    out.extend_from_slice(&response.raft_log_index.to_be_bytes());
    if out.len() > FENCED_TRANSITION_V2_RECEIPT_RESPONSE_MAX_BYTES {
        return Err(invalid_data("fenced transition V2 receipt is too large"));
    }
    Ok(out)
}

fn fenced_transition_v2_response_error_tag(error: &StoreError) -> io::Result<u8> {
    let tag = match error {
        StoreError::TopologyAuthorityRevoked => {
            FENCED_TRANSITION_V2_RESPONSE_TOPOLOGY_AUTHORITY_REVOKED
        }
        StoreError::NotFound => FENCED_TRANSITION_V2_RESPONSE_NOT_FOUND,
        StoreError::StaleFence => FENCED_TRANSITION_V2_RESPONSE_STALE_FENCE,
        StoreError::CasConflict => FENCED_TRANSITION_V2_RESPONSE_CAS_CONFLICT,
        StoreError::InvalidSessionTtl => FENCED_TRANSITION_V2_RESPONSE_INVALID_SESSION_TTL,
        StoreError::InvalidRecordExpiry => FENCED_TRANSITION_V2_RESPONSE_INVALID_RECORD_EXPIRY,
        StoreError::LeaseHeld => FENCED_TRANSITION_V2_RESPONSE_LEASE_HELD,
        StoreError::LeaseExpired => FENCED_TRANSITION_V2_RESPONSE_LEASE_EXPIRED,
        StoreError::PayloadTooLarge { .. } => FENCED_TRANSITION_V2_RESPONSE_PAYLOAD_TOO_LARGE,
        StoreError::FencedTransitionStorageExhausted => {
            FENCED_TRANSITION_V2_RESPONSE_STORAGE_EXHAUSTED
        }
        _ => return Err(fenced_transition_v2_response_invalid()),
    };
    Ok(tag)
}

struct FencedTransitionV2ResponseDecoder<'a> {
    encoded: &'a [u8],
    cursor: usize,
}

impl<'a> FencedTransitionV2ResponseDecoder<'a> {
    fn new(encoded: &'a [u8]) -> Self {
        Self { encoded, cursor: 0 }
    }

    fn take(&mut self, length: usize) -> io::Result<&'a [u8]> {
        let end = self
            .cursor
            .checked_add(length)
            .ok_or_else(fenced_transition_v2_response_invalid)?;
        let value = self
            .encoded
            .get(self.cursor..end)
            .ok_or_else(fenced_transition_v2_response_invalid)?;
        self.cursor = end;
        Ok(value)
    }

    fn tag(&mut self) -> io::Result<u8> {
        Ok(*self
            .take(1)?
            .first()
            .ok_or_else(fenced_transition_v2_response_invalid)?)
    }

    fn u32(&mut self) -> io::Result<u32> {
        self.take(4)?
            .try_into()
            .map(u32::from_be_bytes)
            .map_err(|_| fenced_transition_v2_response_invalid())
    }

    fn u64(&mut self) -> io::Result<u64> {
        self.take(8)?
            .try_into()
            .map(u64::from_be_bytes)
            .map_err(|_| fenced_transition_v2_response_invalid())
    }

    fn i64(&mut self) -> io::Result<i64> {
        self.take(8)?
            .try_into()
            .map(i64::from_be_bytes)
            .map_err(|_| fenced_transition_v2_response_invalid())
    }

    fn bytes(&mut self, maximum: usize) -> io::Result<&'a [u8]> {
        let length =
            usize::try_from(self.u64()?).map_err(|_| fenced_transition_v2_response_invalid())?;
        if length > maximum {
            return Err(fenced_transition_v2_response_invalid());
        }
        self.take(length)
    }

    fn timestamp(&mut self) -> io::Result<Timestamp> {
        let seconds = self.i64()?;
        let nanoseconds = self.u32()?;
        if nanoseconds >= 1_000_000_000 {
            return Err(fenced_transition_v2_response_invalid());
        }
        let timestamp = time::OffsetDateTime::from_unix_timestamp(seconds)
            .map_err(|_| fenced_transition_v2_response_invalid())?
            .replace_nanosecond(nanoseconds)
            .map_err(|_| fenced_transition_v2_response_invalid())?;
        let timestamp = Timestamp::from_offset_datetime(timestamp);
        if !fenced_transition_v2_timestamp_is_in_range(timestamp) {
            return Err(fenced_transition_v2_response_invalid());
        }
        Ok(timestamp)
    }

    fn finish(self) -> io::Result<()> {
        if self.cursor == self.encoded.len() {
            Ok(())
        } else {
            Err(fenced_transition_v2_response_invalid())
        }
    }
}

fn decode_fenced_transition_v2_response_key(
    decoder: &mut FencedTransitionV2ResponseDecoder<'_>,
) -> io::Result<SessionKey> {
    let tenant = std::str::from_utf8(decoder.bytes(128)?)
        .map_err(|_| fenced_transition_v2_response_invalid())?;
    let nf_kind = std::str::from_utf8(decoder.bytes(64)?)
        .map_err(|_| fenced_transition_v2_response_invalid())?;
    let key_type = match decoder.tag()? {
        FENCED_TRANSITION_V2_KEY_SUBSCRIBER_CONTEXT => SessionKeyType::SubscriberContext,
        FENCED_TRANSITION_V2_KEY_PDU_SESSION => SessionKeyType::PduSession,
        FENCED_TRANSITION_V2_KEY_TEID_MAPPING => SessionKeyType::TeidMapping,
        FENCED_TRANSITION_V2_KEY_PFCP_SEID => SessionKeyType::PfcpSeid,
        FENCED_TRANSITION_V2_KEY_HANDOVER_TRANSACTION => SessionKeyType::HandoverTransaction,
        FENCED_TRANSITION_V2_KEY_OTHER => {
            let value = std::str::from_utf8(decoder.bytes(128)?)
                .map_err(|_| fenced_transition_v2_response_invalid())?;
            SessionKeyType::other(value.to_owned())
                .map_err(|_| fenced_transition_v2_response_invalid())?
        }
        _ => return Err(fenced_transition_v2_response_invalid()),
    };
    let stable_id = StableId::try_from(decoder.bytes(StableId::MAX_BYTES)?.to_vec())
        .map_err(|_| fenced_transition_v2_response_invalid())?;
    Ok(SessionKey {
        tenant: TenantId::new(tenant.to_owned())
            .map_err(|_| fenced_transition_v2_response_invalid())?,
        nf_kind: NetworkFunctionKind::new(nf_kind.to_owned())
            .map_err(|_| fenced_transition_v2_response_invalid())?,
        key_type,
        stable_id,
    })
}

fn decode_fenced_transition_v2_response_lease(
    decoder: &mut FencedTransitionV2ResponseDecoder<'_>,
) -> io::Result<LeaseGuard> {
    let key = decode_fenced_transition_v2_response_key(decoder)?;
    let owner = std::str::from_utf8(decoder.bytes(OwnerId::MAX_BYTES)?)
        .map_err(|_| fenced_transition_v2_response_invalid())?;
    let fence = FenceToken::new(decoder.u64()?);
    let acquired_at = decoder.timestamp()?;
    let expires_at = decoder.timestamp()?;
    let credential_id = decoder.u64()?;
    let lease = LeaseGuard::new(
        key,
        OwnerId::new(owner.to_owned()).map_err(|_| fenced_transition_v2_response_invalid())?,
        fence,
        acquired_at,
        expires_at,
        credential_id,
    );
    lease
        .validate_profile()
        .map_err(|_| fenced_transition_v2_response_invalid())?;
    Ok(lease)
}

fn decode_fenced_transition_v2_response_mutation(
    decoder: &mut FencedTransitionV2ResponseDecoder<'_>,
) -> io::Result<FencedTransitionMutationResult> {
    match decoder.tag()? {
        FENCED_TRANSITION_V2_MUTATION_CREATED => Ok(FencedTransitionMutationResult::Created),
        FENCED_TRANSITION_V2_MUTATION_UPDATED => Ok(FencedTransitionMutationResult::Updated),
        FENCED_TRANSITION_V2_MUTATION_DELETED => Ok(FencedTransitionMutationResult::Deleted),
        FENCED_TRANSITION_V2_MUTATION_TTL_REFRESHED => {
            Ok(FencedTransitionMutationResult::TtlRefreshed {
                expires_at: decoder.timestamp()?,
            })
        }
        _ => Err(fenced_transition_v2_response_invalid()),
    }
}

fn decode_fenced_transition_v2_response_error(
    tag: u8,
    decoder: &mut FencedTransitionV2ResponseDecoder<'_>,
) -> io::Result<StoreError> {
    let error = match tag {
        FENCED_TRANSITION_V2_RESPONSE_TOPOLOGY_AUTHORITY_REVOKED => {
            StoreError::TopologyAuthorityRevoked
        }
        FENCED_TRANSITION_V2_RESPONSE_NOT_FOUND => StoreError::NotFound,
        FENCED_TRANSITION_V2_RESPONSE_STALE_FENCE => StoreError::StaleFence,
        FENCED_TRANSITION_V2_RESPONSE_CAS_CONFLICT => StoreError::CasConflict,
        FENCED_TRANSITION_V2_RESPONSE_INVALID_SESSION_TTL => StoreError::InvalidSessionTtl,
        FENCED_TRANSITION_V2_RESPONSE_INVALID_RECORD_EXPIRY => StoreError::InvalidRecordExpiry,
        FENCED_TRANSITION_V2_RESPONSE_LEASE_HELD => StoreError::LeaseHeld,
        FENCED_TRANSITION_V2_RESPONSE_LEASE_EXPIRED => StoreError::LeaseExpired,
        FENCED_TRANSITION_V2_RESPONSE_PAYLOAD_TOO_LARGE => {
            let actual = decoder.u64()?;
            let max = decoder.u64()?;
            if max != FENCED_TRANSITION_V2_MAX_RECORD_PAYLOAD_BYTES as u64
                || actual <= max
                || actual > FENCED_TRANSITION_V2_MAX_PAYLOAD_TOO_LARGE_ACTUAL_BYTES
            {
                return Err(fenced_transition_v2_response_invalid());
            }
            let actual =
                usize::try_from(actual).map_err(|_| fenced_transition_v2_response_invalid())?;
            let max = usize::try_from(max).map_err(|_| fenced_transition_v2_response_invalid())?;
            return Ok(StoreError::PayloadTooLarge { actual, max });
        }
        FENCED_TRANSITION_V2_RESPONSE_STORAGE_EXHAUSTED => {
            StoreError::FencedTransitionStorageExhausted
        }
        _ => return Err(fenced_transition_v2_response_invalid()),
    };
    Ok(error)
}

/// Decode and fully frame-check one V2 receipt response.  Unknown tags,
/// noncanonical timestamps, overflowed lengths and any trailing byte reject
/// the ledger rather than silently changing an exact retry result.
pub(crate) fn decode_fenced_transition_v2_response(
    encoded: &[u8],
) -> io::Result<SessionConsensusResponse> {
    if encoded.len() > FENCED_TRANSITION_V2_RECEIPT_RESPONSE_MAX_BYTES {
        return Err(fenced_transition_v2_response_invalid());
    }
    let mut decoder = FencedTransitionV2ResponseDecoder::new(encoded);
    if decoder.take(FENCED_TRANSITION_V2_RECEIPT_RESPONSE_CODEC_MAGIC.len())?
        != FENCED_TRANSITION_V2_RECEIPT_RESPONSE_CODEC_MAGIC
        || decoder.tag()? != FENCED_TRANSITION_V2_RECEIPT_RESPONSE_CODEC_REVISION
    {
        return Err(fenced_transition_v2_response_invalid());
    }
    let result_tag = decoder.tag()?;
    let result = if result_tag == FENCED_TRANSITION_V2_RESPONSE_SUCCESS {
        let lease = decode_fenced_transition_v2_response_lease(&mut decoder)?;
        let generation = Generation::new(decoder.u64()?);
        let mutation = decode_fenced_transition_v2_response_mutation(&mut decoder)?;
        let recorded_at = decoder.timestamp()?;
        Ok(SessionMutationOutcome::FencedTransition(
            FencedTransitionOutcome::new(lease, generation, mutation, recorded_at)
                .map_err(|_| fenced_transition_v2_response_invalid())?,
        ))
    } else {
        Err(decode_fenced_transition_v2_response_error(
            result_tag,
            &mut decoder,
        )?)
    };
    let sequence = decoder.u64()?;
    let digest = SessionConsensusEntryDigest::from_bytes(
        decoder
            .take(32)?
            .try_into()
            .map_err(|_| fenced_transition_v2_response_invalid())?,
    );
    let logical_time = decoder.timestamp()?;
    let raft_log_index = decoder.u64()?;
    decoder.finish()?;
    if sequence == 0 || raft_log_index == 0 {
        return Err(fenced_transition_v2_response_invalid());
    }
    Ok(SessionConsensusResponse {
        result,
        sequence,
        digest: Some(digest),
        logical_time: Some(logical_time),
        raft_log_index,
    })
}

fn fenced_transition_v2_as_v1_request(
    request: &FencedTransitionV2Request,
) -> Result<FencedTransitionRequest, StoreError> {
    FencedTransitionRequest::new(
        FencedTransitionRequestId::from_bytes([1; FENCED_TRANSITION_REQUEST_ID_BYTES]),
        request.lease().clone(),
        request.mutation().clone(),
    )
}

fn validate_fenced_transition_v2_response_for_request(
    request: &FencedTransitionV2Request,
    response: &SessionConsensusResponse,
) -> io::Result<()> {
    let logical_time = response.logical_time.ok_or_else(|| {
        invalid_data("persisted fenced transition V2 receipt logical time is invalid")
    })?;
    if !fenced_transition_v2_timestamp_is_in_range(logical_time) {
        return Err(invalid_data(
            "persisted fenced transition V2 receipt logical time is invalid",
        ));
    }
    match &response.result {
        Ok(SessionMutationOutcome::FencedTransition(outcome))
            if outcome.recorded_at() == logical_time && outcome.matches_v2_request(request) =>
        {
            Ok(())
        }
        Err(error) if is_persistable_fenced_transition_error(error) => Ok(()),
        _ => Err(invalid_data(
            "persisted fenced transition V2 receipt does not match its request",
        )),
    }
}

fn validate_fenced_transition_v2_receipt_metadata(
    retained_until: Timestamp,
    response: &SessionConsensusResponse,
) -> io::Result<()> {
    if !fenced_transition_v2_timestamp_is_in_range(retained_until) {
        return Err(invalid_data(
            "persisted fenced transition V2 retention is invalid",
        ));
    }
    validate_fenced_transition_receipt(retained_until, response)?;
    let logical_time = response.logical_time.ok_or_else(|| {
        invalid_data("persisted fenced transition V2 receipt logical time is invalid")
    })?;
    if !fenced_transition_v2_timestamp_is_in_range(logical_time) {
        return Err(invalid_data(
            "persisted fenced transition V2 receipt logical time is invalid",
        ));
    }
    Ok(())
}

fn read_fenced_transition_v2_receipt_sync(
    conn: &Connection,
    identity: SessionConsensusIdentity,
    request: &FencedTransitionV2Request,
) -> io::Result<Option<FencedTransitionV2Receipt>> {
    let request_id = request.request_id().to_bytes();
    let row = conn
        .query_row(
            "SELECT request_id, history_epoch, ordinal, configuration_epoch, payload_digest, retained_until, binding_digest, response_json, response_digest FROM consensus_fenced_transition_v2_receipts WHERE request_id = ?1",
            [request_id.as_slice()],
            |row| {
                Ok((
                    row.get::<_, Vec<u8>>(0)?,
                    row.get::<_, i64>(1)?,
                    row.get::<_, i64>(2)?,
                    row.get::<_, i64>(3)?,
                    row.get::<_, Vec<u8>>(4)?,
                    row.get::<_, String>(5)?,
                    row.get::<_, Vec<u8>>(6)?,
                    row.get::<_, Option<Vec<u8>>>(7)?,
                    row.get::<_, Option<Vec<u8>>>(8)?,
                ))
            },
        )
        .optional()
        .map_err(db_error)?;
    let Some((
        stored_id,
        history_epoch,
        ordinal,
        configuration_epoch,
        payload_digest,
        retained_until,
        binding_digest,
        response_json,
        response_digest,
    )) = row
    else {
        return Ok(None);
    };
    validate_epoch(configuration_epoch, identity)?;
    let stored_id: [u8; FENCED_TRANSITION_V2_REQUEST_ID_BYTES] = stored_id
        .try_into()
        .map_err(|_| invalid_data("persisted fenced transition V2 request ID is invalid"))?;
    if stored_id != request_id {
        return Err(invalid_data(
            "persisted fenced transition V2 request ID is invalid",
        ));
    }
    let history_epoch = checked_positive_u64(history_epoch)?;
    if history_epoch != request.request_id().epoch().get()
        || u64::from_be_bytes(
            stored_id[..8].try_into().map_err(|_| {
                invalid_data("persisted fenced transition V2 request ID is invalid")
            })?,
        ) != history_epoch
    {
        return Err(invalid_data(
            "persisted fenced transition V2 epoch is invalid",
        ));
    }
    let ordinal = checked_positive_u64(ordinal)?;
    let payload_digest: [u8; 32] = payload_digest
        .try_into()
        .map_err(|_| invalid_data("persisted fenced transition V2 digest is invalid"))?;
    if payload_digest != fenced_transition_v2_payload_digest_for_request_id(identity, stored_id)? {
        return Err(invalid_data(
            "persisted fenced transition V2 digest is invalid",
        ));
    }
    let retained_until_timestamp = Timestamp::from_str(&retained_until)
        .map_err(|_| invalid_data("persisted fenced transition V2 retention is invalid"))?;
    if !fenced_transition_v2_timestamp_is_in_range(retained_until_timestamp)
        || ops::format_rfc3339_normalized(retained_until_timestamp) != retained_until
    {
        return Err(invalid_data(
            "persisted fenced transition V2 retention is invalid",
        ));
    }
    let binding_digest: [u8; 32] = binding_digest
        .try_into()
        .map_err(|_| invalid_data("persisted fenced transition V2 binding is invalid"))?;
    if binding_digest
        != fenced_transition_v2_receipt_binding_digest(
            identity,
            request_id,
            history_epoch,
            ordinal,
            payload_digest,
            &retained_until,
        )?
    {
        return Err(invalid_data(
            "persisted fenced transition V2 binding is invalid",
        ));
    }
    let response = match (response_json, response_digest) {
        (Some(encoded), Some(digest)) => {
            if encoded.len() > FENCED_TRANSITION_V2_RECEIPT_RESPONSE_MAX_BYTES {
                return Err(invalid_data(
                    "persisted fenced transition V2 receipt is invalid",
                ));
            }
            let response = decode_fenced_transition_v2_response(&encoded)?;
            validate_fenced_transition_v2_receipt_metadata(retained_until_timestamp, &response)?;
            validate_fenced_transition_v2_response_for_request(request, &response)?;
            let digest: [u8; 32] = digest
                .try_into()
                .map_err(|_| invalid_data("persisted fenced transition V2 response is invalid"))?;
            if digest != fenced_transition_v2_receipt_response_digest(binding_digest, &encoded)? {
                return Err(invalid_data(
                    "persisted fenced transition V2 response is invalid",
                ));
            }
            Some(response)
        }
        (None, None) => None,
        _ => {
            return Err(invalid_data(
                "persisted fenced transition V2 response is invalid",
            ));
        }
    };
    Ok(Some(FencedTransitionV2Receipt {
        history_epoch,
        payload_digest,
        retained_until: retained_until_timestamp,
        response,
    }))
}

fn store_fenced_transition_v2_receipt_sync(
    conn: &Connection,
    identity: SessionConsensusIdentity,
    request: &FencedTransitionV2Request,
    ordinal: u64,
    payload_digest: [u8; 32],
    retained_until: Timestamp,
    response: &SessionConsensusResponse,
) -> io::Result<()> {
    validate_fenced_transition_v2_receipt_metadata(retained_until, response)?;
    validate_fenced_transition_v2_response_for_request(request, response)?;
    let encoded = encode_fenced_transition_v2_response(response)?;
    if encoded.len() > FENCED_TRANSITION_V2_RECEIPT_RESPONSE_MAX_BYTES {
        return Err(invalid_data("fenced transition V2 receipt is too large"));
    }
    let retained_until = ops::format_rfc3339_normalized(retained_until);
    let binding_digest = fenced_transition_v2_receipt_binding_digest(
        identity,
        request.request_id().to_bytes(),
        request.request_id().epoch().get(),
        ordinal,
        payload_digest,
        &retained_until,
    )?;
    let response_digest = fenced_transition_v2_receipt_response_digest(binding_digest, &encoded)?;
    let history_epoch = request.request_id().epoch().get();
    let changed = conn
        .execute(
            "UPDATE consensus_fenced_transition_v2_history SET current_bound_count = current_bound_count + 1 WHERE singleton = 1 AND active_epoch = ?1 AND current_bound_count = ?2",
            params![checked_positive_i64(history_epoch)?, checked_i64(ordinal.checked_sub(1).ok_or_else(|| invalid_data("fenced transition V2 ordinal is invalid"))?)?],
        )
        .map_err(db_error)?;
    if changed != 1 {
        return Err(invalid_data(
            "fenced transition V2 history bind state is invalid",
        ));
    }
    conn.execute(
        "INSERT INTO consensus_fenced_transition_v2_receipts (request_id, history_epoch, ordinal, configuration_epoch, payload_digest, retained_until, binding_digest, response_json, response_digest) VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7, ?8, ?9)",
        params![
            request.request_id().to_bytes().as_slice(),
            checked_positive_i64(history_epoch)?,
            checked_positive_i64(ordinal)?,
            epoch_i64(identity)?,
            payload_digest.as_slice(),
            retained_until,
            binding_digest.as_slice(),
            encoded,
            response_digest.as_slice(),
        ],
    )
    .map_err(db_error)?;
    Ok(())
}

fn compact_fenced_transition_v2_receipt_sync(
    conn: &Connection,
    request: &FencedTransitionV2Request,
    logical_time: Timestamp,
) -> io::Result<()> {
    conn.execute(
        "UPDATE consensus_fenced_transition_v2_receipts SET response_json = NULL, response_digest = NULL WHERE request_id = ?1 AND retained_until <= ?2 AND response_json IS NOT NULL",
        params![
            request.request_id().to_bytes().as_slice(),
            ops::format_rfc3339_normalized(logical_time),
        ],
    )
    .map_err(db_error)?;
    Ok(())
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum FencedTransitionV2MaintenanceResult {
    Applied,
    /// The proposal exactly observed this history state, but no epoch can be
    /// retired yet.  It is a committed no-effect `Unit`, distinct from a
    /// stale compare-and-swap proposal.
    Noop,
    /// One of the proposal's observed lifecycle counters no longer matches.
    /// This is the sole path mapped to `HistoryEpochNotActive`.
    Rejected,
    Exhausted,
}

/// Execute one replicated, fixed-size V2 reclamation step.  The caller has
/// authenticated operator authority and supplies the effective committed
/// logical time; no wall-clock/local cleanup path exists.
fn maintain_fenced_transition_v2_history_sync(
    conn: &Connection,
    storage_identity: SessionConsensusIdentity,
    expected_generation: u64,
    expected_active_epoch: Option<FencedTransitionV2HistoryEpoch>,
    expected_retired_through: u64,
    expected_bound_entries: u64,
    effective_logical_time: Timestamp,
) -> io::Result<FencedTransitionV2MaintenanceResult> {
    let history = read_fenced_transition_v2_history_row_in_sync(conn, storage_identity, false)?;
    if history.generation != expected_generation
        || history.active_epoch != expected_active_epoch
        || history.retired_through != expected_retired_through
        || u64::try_from(history.current_bound_count)
            .map_err(|_| invalid_data("fenced transition V2 maintenance count is invalid"))?
            != expected_bound_entries
    {
        return Ok(FencedTransitionV2MaintenanceResult::Rejected);
    }
    // SQLite persists every V2 lifecycle counter in a signed INTEGER. The
    // public epoch profile also fences this at the same horizon. Treat these
    // reachable terminal counters as a replicated no-effect outcome before
    // changing the floor or deleting a receipt, never as an apply fault after
    // partially entering reclamation.
    if history.generation >= i64::MAX as u64
        || history
            .active_epoch
            .is_some_and(|epoch| epoch.get() >= i64::MAX as u64)
        || history
            .reclaim_epoch
            .is_some_and(|epoch| epoch >= i64::MAX as u64)
    {
        return Ok(FencedTransitionV2MaintenanceResult::Exhausted);
    }
    let next_generation = history
        .generation
        .checked_add(1)
        .ok_or_else(|| invalid_data("fenced transition V2 generation is exhausted"))?;
    let active = history
        .active_epoch
        .ok_or_else(|| invalid_data("fenced transition V2 active epoch is invalid"))?;
    // A full writable epoch opens its immediate successor without waiting for
    // the result window.  The old epoch remains in the contiguous exact
    // replay range above `retired_through`; only the eighth retained epoch
    // blocks another rotation.
    if history.reclaim_epoch.is_none() {
        let retained_epochs = active
            .get()
            .checked_sub(history.retired_through)
            .ok_or_else(|| invalid_data("fenced transition V2 lifecycle is invalid"))?;
        let maximum_retained_epochs = u64::try_from(FENCED_TRANSITION_V2_MAX_REPLAY_EPOCHS + 1)
            .map_err(|_| invalid_data("fenced transition V2 retained epoch bound is invalid"))?;
        if retained_epochs < maximum_retained_epochs {
            if history.current_bound_count < FENCED_TRANSITION_V2_MAX_HISTORY_ENTRIES {
                return Ok(FencedTransitionV2MaintenanceResult::Noop);
            }
            let successor = active
                .get()
                .checked_add(1)
                .ok_or_else(|| invalid_data("fenced transition V2 epoch is exhausted"))?;
            let changed = conn
                .execute(
                    "UPDATE consensus_fenced_transition_v2_history SET active_epoch = ?1, generation = ?2, current_bound_count = 0 WHERE singleton = 1 AND active_epoch = ?3 AND reclaim_epoch IS NULL AND generation = ?4 AND retired_through_epoch = ?5 AND current_bound_count = ?6",
                    params![
                        checked_positive_i64(successor)?,
                        checked_i64(next_generation)?,
                        checked_positive_i64(active.get())?,
                        checked_i64(expected_generation)?,
                        checked_i64(expected_retired_through)?,
                        checked_i64(expected_bound_entries)?,
                    ],
                )
                .map_err(db_error)?;
            return Ok(if changed == 1 {
                FencedTransitionV2MaintenanceResult::Applied
            } else {
                FencedTransitionV2MaintenanceResult::Rejected
            });
        }
    }

    // At the retained-epoch bound, only the oldest exact epoch can advance
    // the irreversible floor.  Its last receipt deadline gates the command;
    // the floor update and first ordered physical batch share this one
    // transaction/consensus linearization.
    let (reclaim_epoch, cursor, remaining, advancing_floor) = match history.reclaim_epoch {
        Some(epoch) => {
            let cursor = history
                .reclaim_cursor_ordinal
                .ok_or_else(|| invalid_data("fenced transition V2 reclaim cursor is invalid"))?;
            let remaining = history
                .reclaim_remaining
                .ok_or_else(|| invalid_data("fenced transition V2 reclaim count is invalid"))?;
            if !fenced_transition_v2_epoch_has_exact_ordinal_range_sync(
                conn,
                epoch,
                cursor.checked_add(1).ok_or_else(|| {
                    invalid_data("fenced transition V2 reclaim cursor is invalid")
                })?,
                remaining,
            )? {
                return Err(invalid_data(
                    "fenced transition V2 reclaim ordinal range is invalid",
                ));
            }
            (epoch, cursor, remaining, false)
        }
        None => {
            let oldest = history
                .retired_through
                .checked_add(1)
                .ok_or_else(|| invalid_data("fenced transition V2 epoch is exhausted"))?;
            if !fenced_transition_v2_epoch_has_complete_ordinals_sync(conn, oldest)? {
                return Err(invalid_data(
                    "fenced transition V2 retiring epoch is incomplete",
                ));
            }
            let maximum_retained_until: Option<String> = conn
                .query_row(
                    "SELECT retained_until FROM consensus_fenced_transition_v2_receipts WHERE history_epoch = ?1 ORDER BY ordinal DESC LIMIT 1",
                    [checked_positive_i64(oldest)?],
                    |row| row.get(0),
                )
                .optional()
                .map_err(db_error)?;
            let Some(maximum_retained_until) = maximum_retained_until else {
                return Err(invalid_data(
                    "fenced transition V2 retained epoch is missing",
                ));
            };
            let maximum_retained_until = Timestamp::from_str(&maximum_retained_until)
                .map_err(|_| invalid_data("fenced transition V2 retention is invalid"))?;
            if maximum_retained_until > effective_logical_time {
                return Ok(FencedTransitionV2MaintenanceResult::Noop);
            }
            let remaining: u64 = conn
                .query_row(
                    "SELECT COUNT(*) FROM consensus_fenced_transition_v2_receipts WHERE history_epoch = ?1",
                    [checked_positive_i64(oldest)?],
                    |row| row.get::<_, i64>(0),
                )
                .map_err(db_error)
                .and_then(checked_u64)?;
            if remaining != FENCED_TRANSITION_V2_MAX_HISTORY_ENTRIES as u64 {
                return Err(invalid_data(
                    "fenced transition V2 reclaim count is invalid",
                ));
            }
            (oldest, 0, remaining, true)
        }
    };
    if history.reclaimed_entries
        > (i64::MAX as u64).saturating_sub(
            remaining.min(
                u64::try_from(FENCED_TRANSITION_V2_RECLAIM_BATCH)
                    .map_err(|_| invalid_data("fenced transition V2 reclaim batch is invalid"))?,
            ),
        )
    {
        return Ok(FencedTransitionV2MaintenanceResult::Exhausted);
    }
    let mut statement = conn
        .prepare(
            "SELECT ordinal FROM consensus_fenced_transition_v2_receipts WHERE history_epoch = ?1 AND ordinal > ?2 ORDER BY history_epoch ASC, ordinal ASC LIMIT ?3",
        )
        .map_err(db_error)?;
    let ordinals = statement
        .query_map(
            params![
                checked_positive_i64(reclaim_epoch)?,
                checked_i64(cursor)?,
                i64::try_from(FENCED_TRANSITION_V2_RECLAIM_BATCH)
                    .map_err(|_| invalid_data("fenced transition V2 reclaim batch is invalid"))?,
            ],
            |row| row.get::<_, i64>(0),
        )
        .map_err(db_error)?
        .map(|row| row.map_err(db_error).and_then(checked_positive_u64))
        .collect::<io::Result<Vec<_>>>()?;
    let expected_batch = remaining.min(
        u64::try_from(FENCED_TRANSITION_V2_RECLAIM_BATCH)
            .map_err(|_| invalid_data("fenced transition V2 reclaim batch is invalid"))?,
    );
    if u64::try_from(ordinals.len())
        .map_err(|_| invalid_data("fenced transition V2 reclaim count is invalid"))?
        != expected_batch
    {
        return Err(invalid_data(
            "fenced transition V2 reclaim count is invalid",
        ));
    }
    let deleted = if let Some(last) = ordinals.last().copied() {
        let deleted = conn
            .execute(
                "DELETE FROM consensus_fenced_transition_v2_receipts WHERE history_epoch = ?1 AND ordinal > ?2 AND ordinal <= ?3",
                params![
                    checked_positive_i64(reclaim_epoch)?,
                    checked_i64(cursor)?,
                    checked_positive_i64(last)?,
                ],
            )
            .map_err(db_error)?;
        if deleted != ordinals.len() {
            return Err(invalid_data(
                "fenced transition V2 reclaim order is invalid",
            ));
        }
        (
            last,
            u64::try_from(deleted)
                .map_err(|_| invalid_data("fenced transition V2 reclaim count is invalid"))?,
        )
    } else {
        (cursor, 0)
    };
    let new_remaining = remaining
        .checked_sub(deleted.1)
        .ok_or_else(|| invalid_data("fenced transition V2 reclaim count is invalid"))?;
    let reclaimed_entries = history
        .reclaimed_entries
        .checked_add(deleted.1)
        .ok_or_else(|| invalid_data("fenced transition V2 reclaimed count is exhausted"))?;
    if new_remaining == 0 {
        let changed = conn
            .execute(
                "UPDATE consensus_fenced_transition_v2_history SET retired_through_epoch = CASE WHEN ?1 THEN ?2 ELSE retired_through_epoch END, generation = ?3, reclaim_epoch = NULL, reclaim_cursor_ordinal = NULL, reclaim_remaining = NULL, reclaimed_entries = ?4 WHERE singleton = 1 AND active_epoch = ?5 AND reclaim_epoch IS ?6 AND reclaim_cursor_ordinal IS ?7 AND reclaim_remaining IS ?8 AND generation = ?9 AND retired_through_epoch = ?10 AND current_bound_count = ?11",
                params![
                    advancing_floor,
                    checked_positive_i64(reclaim_epoch)?,
                    checked_i64(next_generation)?,
                    checked_i64(reclaimed_entries)?,
                    checked_positive_i64(active.get())?,
                    history.reclaim_epoch.map(checked_positive_i64).transpose()?,
                    history.reclaim_cursor_ordinal.map(checked_i64).transpose()?,
                    history.reclaim_remaining.map(checked_i64).transpose()?,
                    checked_i64(expected_generation)?,
                    checked_i64(expected_retired_through)?,
                    checked_i64(expected_bound_entries)?,
                ],
            )
            .map_err(db_error)?;
        if changed != 1 {
            return Err(invalid_data(
                "fenced transition V2 reclaim state is invalid",
            ));
        }
    } else {
        let changed = conn
            .execute(
                "UPDATE consensus_fenced_transition_v2_history SET retired_through_epoch = CASE WHEN ?1 THEN ?2 ELSE retired_through_epoch END, generation = ?3, reclaim_epoch = ?2, reclaim_cursor_ordinal = ?4, reclaim_remaining = ?5, reclaimed_entries = ?6 WHERE singleton = 1 AND active_epoch = ?7 AND reclaim_epoch IS ?8 AND reclaim_cursor_ordinal IS ?9 AND reclaim_remaining IS ?10 AND generation = ?11 AND retired_through_epoch = ?12 AND current_bound_count = ?13",
                params![
                    advancing_floor,
                    checked_positive_i64(reclaim_epoch)?,
                    checked_i64(next_generation)?,
                    checked_i64(deleted.0)?,
                    checked_i64(new_remaining)?,
                    checked_i64(reclaimed_entries)?,
                    checked_positive_i64(active.get())?,
                    history.reclaim_epoch.map(checked_positive_i64).transpose()?,
                    history.reclaim_cursor_ordinal.map(checked_i64).transpose()?,
                    history.reclaim_remaining.map(checked_i64).transpose()?,
                    checked_i64(expected_generation)?,
                    checked_i64(expected_retired_through)?,
                    checked_i64(expected_bound_entries)?,
                ],
            )
            .map_err(db_error)?;
        if changed != 1 {
            return Err(invalid_data(
                "fenced transition V2 reclaim state is invalid",
            ));
        }
    }
    Ok(FencedTransitionV2MaintenanceResult::Applied)
}

fn validate_fenced_transition_receipt(
    retained_until: Timestamp,
    response: &SessionConsensusResponse,
) -> io::Result<()> {
    if response.sequence == 0 || response.digest.is_none() || response.raft_log_index == 0 {
        return Err(invalid_data(
            "persisted fenced transition receipt metadata is invalid",
        ));
    }
    let logical_time = response.logical_time.ok_or_else(|| {
        invalid_data("persisted fenced transition receipt logical time is invalid")
    })?;
    let expected_retained_until =
        crate::ttl::checked_session_deadline(logical_time, FENCED_TRANSITION_OUTCOME_RETENTION)
            .map_err(|_| {
                invalid_data("persisted fenced transition receipt retention is invalid")
            })?;
    if retained_until != expected_retained_until {
        return Err(invalid_data(
            "persisted fenced transition receipt retention is invalid",
        ));
    }
    match &response.result {
        Ok(SessionMutationOutcome::FencedTransition(outcome)) => {
            outcome
                .validate()
                .map_err(|_| invalid_data("persisted fenced transition outcome is invalid"))?;
            if outcome.recorded_at() != logical_time || outcome.retained_until() != retained_until {
                return Err(invalid_data(
                    "persisted fenced transition outcome metadata is invalid",
                ));
            }
        }
        Err(error) if is_persistable_fenced_transition_error(error) => {}
        Err(_) => {
            return Err(invalid_data(
                "persisted fenced transition receipt error is invalid",
            ));
        }
        _ => {
            return Err(invalid_data(
                "persisted fenced transition receipt outcome is invalid",
            ));
        }
    }
    Ok(())
}

/// Only fixed deterministic results the fenced executor can durably record.
/// In particular, no caller-authored diagnostic string or node-local failure
/// may enter a receipt that status/reopen later deserializes.
fn is_persistable_fenced_transition_error(error: &StoreError) -> bool {
    matches!(
        error,
        StoreError::TopologyAuthorityRevoked
            | StoreError::NotFound
            | StoreError::StaleFence
            | StoreError::CasConflict
            | StoreError::InvalidSessionTtl
            | StoreError::InvalidRecordExpiry
            | StoreError::LeaseHeld
            | StoreError::LeaseExpired
            | StoreError::PayloadTooLarge { .. }
            | StoreError::FencedTransitionStorageExhausted
    )
}

fn validate_fenced_transition_response_for_request(
    request: &FencedTransitionRequest,
    response: &SessionConsensusResponse,
) -> io::Result<()> {
    let logical_time = response.logical_time.ok_or_else(|| {
        invalid_data("persisted fenced transition receipt logical time is invalid")
    })?;
    match &response.result {
        Ok(SessionMutationOutcome::FencedTransition(outcome))
            if outcome.matches_request_at(request, logical_time) =>
        {
            Ok(())
        }
        Err(error) if is_persistable_fenced_transition_error(error) => Ok(()),
        _ => Err(invalid_data(
            "persisted fenced transition receipt does not match its request",
        )),
    }
}

/// Validate SQLite storage classes and byte widths without returning any
/// attacker-sized value to rusqlite. `octet_length` reads the stored byte count
/// from SQLite's value metadata, and the inner LIMIT keeps even corrupt ledgers
/// within the lifetime protocol bound plus one.
pub(crate) fn validate_fenced_transition_receipt_storage_bounds_sync(
    conn: &Connection,
) -> io::Result<()> {
    let scan_limit = i64::try_from(
        FENCED_TRANSITION_MAX_HISTORY_ENTRIES
            .checked_add(1)
            .ok_or_else(|| invalid_data("fenced transition receipt bound is invalid"))?,
    )
    .map_err(|_| invalid_data("fenced transition receipt bound is invalid"))?;
    let request_id_bytes = i64::try_from(FENCED_TRANSITION_REQUEST_ID_BYTES)
        .map_err(|_| invalid_data("fenced transition receipt bound is invalid"))?;
    let timestamp_bytes = i64::try_from(FENCED_TRANSITION_RECEIPT_TIMESTAMP_BYTES)
        .map_err(|_| invalid_data("fenced transition receipt bound is invalid"))?;
    let response_bytes = i64::try_from(FENCED_TRANSITION_RECEIPT_MAX_RESPONSE_BYTES)
        .map_err(|_| invalid_data("fenced transition receipt bound is invalid"))?;
    let invalid_storage: bool = conn
        .query_row(
            r#"
SELECT EXISTS (
    SELECT 1
    FROM (
        SELECT request_id, configuration_epoch, payload_digest, retained_until,
               binding_digest, response_json, response_digest
        FROM consensus_fenced_transition_receipts
        LIMIT ?1
    ) AS bounded
    WHERE CASE WHEN
           typeof(request_id) = 'blob'
       AND octet_length(request_id) = ?2
       AND typeof(configuration_epoch) = 'integer'
       AND configuration_epoch > 0
       AND typeof(payload_digest) = 'blob'
       AND octet_length(payload_digest) = 32
       AND typeof(retained_until) = 'text'
       AND octet_length(retained_until) = ?3
       AND typeof(binding_digest) = 'blob'
       AND octet_length(binding_digest) = 32
       AND (
              (response_json IS NULL AND response_digest IS NULL)
           OR (
                  typeof(response_json) = 'blob'
              AND octet_length(response_json) BETWEEN 1 AND ?4
              AND typeof(response_digest) = 'blob'
              AND octet_length(response_digest) = 32
           )
       )
       THEN 0 ELSE 1 END = 1
    LIMIT 1
)
"#,
            params![
                scan_limit,
                request_id_bytes,
                timestamp_bytes,
                response_bytes
            ],
            |row| row.get(0),
        )
        .map_err(db_error)?;
    if invalid_storage {
        return Err(invalid_data(
            "persisted fenced transition receipt storage is invalid",
        ));
    }
    Ok(())
}

fn fenced_transition_receipt_storage_is_bounded_for_request_sync(
    conn: &Connection,
    request_id: SessionConsensusRequestId,
) -> io::Result<Option<bool>> {
    let request_id_bytes = i64::try_from(FENCED_TRANSITION_REQUEST_ID_BYTES)
        .map_err(|_| invalid_data("fenced transition receipt bound is invalid"))?;
    let timestamp_bytes = i64::try_from(FENCED_TRANSITION_RECEIPT_TIMESTAMP_BYTES)
        .map_err(|_| invalid_data("fenced transition receipt bound is invalid"))?;
    let response_bytes = i64::try_from(FENCED_TRANSITION_RECEIPT_MAX_RESPONSE_BYTES)
        .map_err(|_| invalid_data("fenced transition receipt bound is invalid"))?;
    conn.query_row(
        r#"
SELECT CASE WHEN
       typeof(request_id) = 'blob'
   AND octet_length(request_id) = ?2
   AND typeof(configuration_epoch) = 'integer'
   AND configuration_epoch > 0
   AND typeof(payload_digest) = 'blob'
   AND octet_length(payload_digest) = 32
   AND typeof(retained_until) = 'text'
   AND octet_length(retained_until) = ?3
   AND typeof(binding_digest) = 'blob'
   AND octet_length(binding_digest) = 32
   AND (
          (response_json IS NULL AND response_digest IS NULL)
       OR (
              typeof(response_json) = 'blob'
          AND octet_length(response_json) BETWEEN 1 AND ?4
          AND typeof(response_digest) = 'blob'
          AND octet_length(response_digest) = 32
       )
   )
   THEN 1 ELSE 0 END
FROM consensus_fenced_transition_receipts
WHERE request_id = ?1
"#,
        params![
            request_id.as_bytes().as_slice(),
            request_id_bytes,
            timestamp_bytes,
            response_bytes,
        ],
        |row| row.get(0),
    )
    .optional()
    .map_err(db_error)
}

fn read_fenced_transition_receipt_sync(
    conn: &Connection,
    identity: SessionConsensusIdentity,
    request_id: SessionConsensusRequestId,
) -> io::Result<Option<FencedTransitionReceipt>> {
    match fenced_transition_receipt_storage_is_bounded_for_request_sync(conn, request_id)? {
        None => return Ok(None),
        Some(false) => {
            return Err(invalid_data(
                "persisted fenced transition receipt storage is invalid",
            ));
        }
        Some(true) => {}
    }
    let row = conn
        .query_row(
            "SELECT request_id, configuration_epoch, payload_digest, retained_until, binding_digest, response_json, response_digest FROM consensus_fenced_transition_receipts WHERE request_id = ?1",
            [request_id.as_bytes().as_slice()],
            |row| {
                Ok((
                    row.get::<_, Vec<u8>>(0)?,
                    row.get::<_, i64>(1)?,
                    row.get::<_, Vec<u8>>(2)?,
                    row.get::<_, String>(3)?,
                    row.get::<_, Vec<u8>>(4)?,
                    row.get::<_, Option<Vec<u8>>>(5)?,
                    row.get::<_, Option<Vec<u8>>>(6)?,
                ))
            },
        )
        .optional()
        .map_err(db_error)?;
    let Some((
        stored_request_id,
        epoch,
        digest,
        retained_until,
        binding_digest,
        response,
        response_digest,
    )) = row
    else {
        return Err(invalid_data(
            "persisted fenced transition receipt disappeared during validation",
        ));
    };
    validate_epoch(epoch, identity)?;
    let stored_request_id: [u8; 16] = stored_request_id
        .try_into()
        .map_err(|_| invalid_data("persisted fenced transition receipt ID is invalid"))?;
    if stored_request_id != *request_id.as_bytes()
        || stored_request_id.iter().all(|byte| *byte == 0)
    {
        return Err(invalid_data(
            "persisted fenced transition receipt ID is invalid",
        ));
    }
    let payload_digest = digest.try_into().map_err(|_| {
        invalid_data("persisted fenced transition receipt digest has invalid length")
    })?;
    let retained_until_raw = retained_until;
    let retained_until = Timestamp::from_str(&retained_until_raw)
        .map_err(|_| invalid_data("persisted fenced transition receipt retention is invalid"))?;
    let normalized_retained_until = ops::format_rfc3339_normalized(retained_until);
    if normalized_retained_until != retained_until_raw {
        return Err(invalid_data(
            "persisted fenced transition receipt retention is invalid",
        ));
    }
    let binding_digest: [u8; 32] = binding_digest
        .try_into()
        .map_err(|_| invalid_data("persisted fenced transition receipt binding is invalid"))?;
    if binding_digest
        != fenced_transition_receipt_binding_digest(
            identity,
            request_id,
            payload_digest,
            &normalized_retained_until,
        )?
    {
        return Err(invalid_data(
            "persisted fenced transition receipt binding is invalid",
        ));
    }
    let response = match (response, response_digest) {
        (Some(encoded), Some(response_digest)) => {
            if encoded.len() > FENCED_TRANSITION_RECEIPT_MAX_RESPONSE_BYTES {
                return Err(invalid_data(
                    "persisted fenced transition receipt is invalid",
                ));
            }
            let response: SessionConsensusResponse = decode_json(&encoded)?;
            validate_fenced_transition_receipt(retained_until, &response)?;
            let response_digest: [u8; 32] = response_digest.try_into().map_err(|_| {
                invalid_data("persisted fenced transition receipt response is invalid")
            })?;
            if response_digest
                != fenced_transition_receipt_response_digest(binding_digest, &response)?
            {
                return Err(invalid_data(
                    "persisted fenced transition receipt response is invalid",
                ));
            }
            Some(response)
        }
        (None, None) => None,
        _ => {
            return Err(invalid_data(
                "persisted fenced transition receipt response is invalid",
            ));
        }
    };
    Ok(Some(FencedTransitionReceipt {
        payload_digest,
        retained_until,
        response,
    }))
}

/// Count only up to one more than the protocol cap. The receipt ledger is a
/// permanent lifetime namespace, so no caller path may perform an unbounded
/// scan merely to learn whether it can bind another request ID.
fn fenced_transition_receipt_count_sync(conn: &Connection) -> io::Result<usize> {
    let limit = i64::try_from(
        FENCED_TRANSITION_MAX_HISTORY_ENTRIES
            .checked_add(1)
            .ok_or_else(|| invalid_data("fenced transition receipt bound is invalid"))?,
    )
    .map_err(|_| invalid_data("fenced transition receipt bound is invalid"))?;
    let count: i64 = conn
        .query_row(
            "SELECT COUNT(*) FROM (SELECT request_id FROM consensus_fenced_transition_receipts LIMIT ?1)",
            [limit],
            |row| row.get(0),
        )
        .map_err(db_error)?;
    usize::try_from(count).map_err(|_| invalid_data("fenced transition receipt count is invalid"))
}

fn attached_snapshot_validation_views_are_active_sync(conn: &Connection) -> io::Result<bool> {
    conn.query_row(
        "SELECT EXISTS(SELECT 1 FROM temp.sqlite_master WHERE type = 'view' AND name = 'consensus_fenced_transition_receipts')",
        [],
        |row| row.get(0),
    )
    .map_err(db_error)
}

fn validate_generic_request_outcome_point_index_sync(
    conn: &Connection,
    attached: bool,
) -> io::Result<()> {
    let table_query = if attached {
        "SELECT CASE WHEN octet_length(sql) <= ?1 THEN sql END, octet_length(sql) FROM consensus_incoming.sqlite_master WHERE type = 'table' AND name = 'consensus_request_outcomes'"
    } else {
        "SELECT CASE WHEN octet_length(sql) <= ?1 THEN sql END, octet_length(sql) FROM main.sqlite_master WHERE type = 'table' AND name = 'consensus_request_outcomes'"
    };
    let table_sql = conn
        .query_row(
            table_query,
            [FENCED_TRANSITION_RECEIPT_SCHEMA_SQL_MAX_BYTES],
            |row| Ok((row.get::<_, Option<String>>(0)?, row.get::<_, i64>(1)?)),
        )
        .optional()
        .map_err(db_error)?;
    let exact_table = table_sql.is_some_and(|(sql, encoded_len)| {
        encoded_len <= FENCED_TRANSITION_RECEIPT_SCHEMA_SQL_MAX_BYTES
            && sql.is_some_and(|sql| {
                normalize_schema_sql(&sql)
                    == normalize_schema_sql(CONSENSUS_REQUEST_OUTCOME_TABLE_SCHEMA_SQL)
            })
    });
    let index_query = if attached {
        "SELECT EXISTS(SELECT 1 FROM consensus_incoming.sqlite_master WHERE type = 'index' AND name = 'sqlite_autoindex_consensus_request_outcomes_1' AND tbl_name = 'consensus_request_outcomes' AND sql IS NULL)"
    } else {
        "SELECT EXISTS(SELECT 1 FROM main.sqlite_master WHERE type = 'index' AND name = 'sqlite_autoindex_consensus_request_outcomes_1' AND tbl_name = 'consensus_request_outcomes' AND sql IS NULL)"
    };
    let exact_index: bool = conn
        .query_row(index_query, [], |row| row.get(0))
        .map_err(db_error)?;
    if !exact_table || !exact_index {
        return Err(invalid_data(
            "persisted session consensus outcome point index is invalid",
        ));
    }
    Ok(())
}

fn generic_request_outcome_exists_for_receipt_sync(
    conn: &Connection,
    attached: bool,
    request_id: SessionConsensusRequestId,
) -> io::Result<bool> {
    let query = if attached {
        "SELECT EXISTS(SELECT 1 FROM consensus_incoming.consensus_request_outcomes INDEXED BY sqlite_autoindex_consensus_request_outcomes_1 WHERE request_id = ?1 LIMIT 1)"
    } else {
        "SELECT EXISTS(SELECT 1 FROM main.consensus_request_outcomes INDEXED BY sqlite_autoindex_consensus_request_outcomes_1 WHERE request_id = ?1 LIMIT 1)"
    };
    conn.query_row(query, [request_id.as_bytes().as_slice()], |row| row.get(0))
        .map_err(db_error)
}

pub(crate) fn validate_fenced_transition_receipts_sync(
    conn: &Connection,
    identity: SessionConsensusIdentity,
) -> io::Result<()> {
    let attached = attached_snapshot_validation_views_are_active_sync(conn)?;
    match fenced_transition_receipt_ledger_layout_in_sync(conn, attached)? {
        FencedTransitionReceiptLedgerLayout::Activated => {
            validate_fenced_transition_activation_certificate_sync(conn, identity, attached)?;
        }
        FencedTransitionReceiptLedgerLayout::Prepared => {
            let activation_rows: i64 = conn
                .query_row(
                    if attached {
                        "SELECT COUNT(*) FROM consensus_incoming.consensus_fenced_transition_activation"
                    } else {
                        "SELECT COUNT(*) FROM consensus_fenced_transition_activation"
                    },
                    [],
                    |row| row.get(0),
                )
                .map_err(db_error)?;
            let receipt_rows: i64 = conn
                .query_row(
                    if attached {
                        "SELECT COUNT(*) FROM consensus_incoming.consensus_fenced_transition_receipts"
                    } else {
                        "SELECT COUNT(*) FROM consensus_fenced_transition_receipts"
                    },
                    [],
                    |row| row.get(0),
                )
                .map_err(db_error)?;
            if activation_rows != 0 || receipt_rows != 0 {
                return Err(invalid_data(
                    "unactivated fenced transition ledger contains durable state",
                ));
            }
            return Ok(());
        }
        // The accepted markerless attached layouts are the exact published
        // #684 products and the exact older Dynamic snapshot shape. Their
        // missing ledger is canonically empty, so no receipt rows remain to
        // validate through the temporary projection.
        FencedTransitionReceiptLedgerLayout::Published684 if attached => return Ok(()),
        FencedTransitionReceiptLedgerLayout::Published684 => {
            return Err(invalid_data(
                "persisted fenced transition receipt activation is invalid",
            ));
        }
    }
    let receipt_count = fenced_transition_receipt_count_sync(conn)?;
    if receipt_count > FENCED_TRANSITION_MAX_HISTORY_ENTRIES {
        return Err(invalid_data(
            "persisted fenced transition receipt history exceeds protocol bound",
        ));
    }
    validate_fenced_transition_receipt_storage_bounds_sync(conn)?;
    let (machine_sequence, _, machine_logical_time, _) = read_machine_sync(conn, identity)?;
    if u64::try_from(receipt_count)
        .map_err(|_| invalid_data("persisted fenced transition receipt count is invalid"))?
        > machine_sequence
    {
        return Err(invalid_data(
            "persisted fenced transition receipt history exceeds application sequence",
        ));
    }
    if receipt_count != 0 {
        validate_generic_request_outcome_point_index_sync(conn, attached)?;
    }
    let applied_index = read_applied_sync(conn, identity)?.map(|log_id| log_id.index);
    let mut statement = conn
        .prepare(
            "SELECT request_id FROM consensus_fenced_transition_receipts ORDER BY request_id LIMIT ?1",
        )
        .map_err(db_error)?;
    let request_ids = statement
        .query_map(
            [i64::try_from(FENCED_TRANSITION_MAX_HISTORY_ENTRIES)
                .map_err(|_| invalid_data("fenced transition receipt bound is invalid"))?],
            |row| row.get::<_, Vec<u8>>(0),
        )
        .map_err(db_error)?;
    for request_id in request_ids {
        let request_id: [u8; 16] = request_id
            .map_err(db_error)?
            .try_into()
            .map_err(|_| invalid_data("persisted fenced transition receipt ID is invalid"))?;
        if request_id.iter().all(|byte| *byte == 0) {
            return Err(invalid_data(
                "persisted fenced transition receipt ID is invalid",
            ));
        }
        let request_id = SessionConsensusRequestId::from_bytes(request_id);
        if generic_request_outcome_exists_for_receipt_sync(conn, attached, request_id)? {
            return Err(invalid_data(
                "persisted session consensus request receipt namespace is invalid",
            ));
        }
        let receipt = read_fenced_transition_receipt_sync(conn, identity, request_id)?
            .ok_or_else(|| invalid_data("persisted fenced transition receipt is missing"))?;
        validate_fenced_transition_receipt_against_floors(
            &receipt,
            machine_sequence,
            machine_logical_time,
            applied_index,
        )?;
    }
    Ok(())
}

/// Validate the V2 receipt/history image independently of V1.  The retained
/// V2 row contains a full self-authenticating ID but deliberately not a copy
/// of the caller body, so this validator verifies the durable namespace,
/// binding/response commitments, and lifecycle counters. The caller-supplied
/// body commitment is recomputed before every status/apply lookup.
pub(crate) fn validate_fenced_transition_v2_receipts_sync(
    conn: &Connection,
    identity: SessionConsensusIdentity,
) -> io::Result<()> {
    let attached = attached_snapshot_validation_views_are_active_sync(conn)?;
    if fenced_transition_v2_ledger_layout_in_sync(conn, attached)?
        == FencedTransitionV2LedgerLayout::Absent
    {
        return Ok(());
    }
    validate_fenced_transition_v2_activation_certificate_in_sync(conn, identity, attached)?;
    let history = read_fenced_transition_v2_history_row_in_sync(conn, identity, attached)?;
    let source = if attached {
        "consensus_incoming.consensus_fenced_transition_v2_receipts"
    } else {
        "main.consensus_fenced_transition_v2_receipts"
    };
    let maximum = i64::try_from(
        FENCED_TRANSITION_V2_MAX_RETAINED_HISTORY_ENTRIES
            .checked_add(1)
            .ok_or_else(|| invalid_data("fenced transition V2 bound is invalid"))?,
    )
    .map_err(|_| invalid_data("fenced transition V2 bound is invalid"))?;
    let rows: i64 = conn
        .query_row(
            &format!("SELECT COUNT(*) FROM (SELECT request_id FROM {source} LIMIT ?1)"),
            [maximum],
            |row| row.get(0),
        )
        .map_err(db_error)?;
    let rows = usize::try_from(rows)
        .map_err(|_| invalid_data("fenced transition V2 receipt count is invalid"))?;
    if rows > FENCED_TRANSITION_V2_MAX_RETAINED_HISTORY_ENTRIES {
        return Err(invalid_data(
            "fenced transition V2 receipt history exceeds bound",
        ));
    }
    let active = history
        .active_epoch
        .ok_or_else(|| invalid_data("fenced transition V2 active epoch is invalid"))?
        .get();
    let minimum_epoch = if history.reclaim_epoch.is_some() {
        history.retired_through
    } else {
        history
            .retired_through
            .checked_add(1)
            .ok_or_else(|| invalid_data("persisted fenced transition V2 epoch is exhausted"))?
    };
    // `consensus_machine` and `consensus_applied` resolve through the
    // attached validation views when validating an incoming snapshot.  Apply
    // the same floor checks as V1 to every V2 row, so a copied response cannot
    // claim a future application sequence/index/time and a tombstone cannot
    // appear before the incoming committed clock reaches its deadline.
    let (machine_sequence, _, machine_logical_time, _) = read_machine_sync(conn, identity)?;
    let applied_index = read_applied_sync(conn, identity)?.map(|log_id| log_id.index);
    let mut statement = conn
        .prepare(&format!(
            "SELECT request_id, history_epoch, ordinal, configuration_epoch, payload_digest, retained_until, binding_digest, response_json, response_digest FROM {source} ORDER BY history_epoch ASC, ordinal ASC LIMIT ?1"
        ))
        .map_err(db_error)?;
    let receipts = statement
        .query_map([maximum], |row| {
            Ok((
                row.get::<_, Vec<u8>>(0)?,
                row.get::<_, i64>(1)?,
                row.get::<_, i64>(2)?,
                row.get::<_, i64>(3)?,
                row.get::<_, Vec<u8>>(4)?,
                row.get::<_, String>(5)?,
                row.get::<_, Vec<u8>>(6)?,
                row.get::<_, Option<Vec<u8>>>(7)?,
                row.get::<_, Option<Vec<u8>>>(8)?,
            ))
        })
        .map_err(db_error)?;
    let mut previous_ordinals = BTreeMap::<u64, u64>::new();
    let mut epoch_counts = BTreeMap::<u64, usize>::new();
    let mut previous_retained_until = None;
    for receipt in receipts {
        let (
            request_id,
            history_epoch,
            ordinal,
            configuration_epoch,
            payload_digest,
            retained_until,
            binding_digest,
            response_json,
            response_digest,
        ) = receipt.map_err(db_error)?;
        validate_epoch(configuration_epoch, identity)?;
        let request_id: [u8; FENCED_TRANSITION_V2_REQUEST_ID_BYTES] = request_id
            .try_into()
            .map_err(|_| invalid_data("persisted fenced transition V2 request ID is invalid"))?;
        let history_epoch = checked_positive_u64(history_epoch)?;
        let ordinal = checked_positive_u64(ordinal)?;
        if !(minimum_epoch..=active).contains(&history_epoch)
            || u64::from_be_bytes(request_id[..8].try_into().map_err(|_| {
                invalid_data("persisted fenced transition V2 request ID is invalid")
            })?) != history_epoch
            || ordinal
                != previous_ordinals
                    .get(&history_epoch)
                    .copied()
                    .unwrap_or_else(|| {
                        if history.reclaim_epoch == Some(history_epoch) {
                            history.reclaim_cursor_ordinal.unwrap_or(0)
                        } else {
                            0
                        }
                    })
                    .checked_add(1)
                    .ok_or_else(|| {
                        invalid_data("persisted fenced transition V2 ordinal is exhausted")
                    })?
        {
            return Err(invalid_data(
                "persisted fenced transition V2 lifecycle is invalid",
            ));
        }
        previous_ordinals.insert(history_epoch, ordinal);
        let count = epoch_counts.entry(history_epoch).or_default();
        *count = count
            .checked_add(1)
            .ok_or_else(|| invalid_data("persisted fenced transition V2 count is invalid"))?;
        if *count > FENCED_TRANSITION_V2_MAX_HISTORY_ENTRIES {
            return Err(invalid_data(
                "persisted fenced transition V2 count is invalid",
            ));
        }
        let payload_digest: [u8; 32] = payload_digest
            .try_into()
            .map_err(|_| invalid_data("persisted fenced transition V2 digest is invalid"))?;
        if payload_digest
            != fenced_transition_v2_payload_digest_for_request_id(identity, request_id)?
        {
            return Err(invalid_data(
                "persisted fenced transition V2 digest is invalid",
            ));
        }
        let retained_until_timestamp = Timestamp::from_str(&retained_until)
            .map_err(|_| invalid_data("persisted fenced transition V2 retention is invalid"))?;
        if !fenced_transition_v2_timestamp_is_in_range(retained_until_timestamp)
            || ops::format_rfc3339_normalized(retained_until_timestamp) != retained_until
        {
            return Err(invalid_data(
                "persisted fenced transition V2 retention is invalid",
            ));
        }
        if previous_retained_until
            .is_some_and(|previous: Timestamp| retained_until_timestamp < previous)
        {
            return Err(invalid_data(
                "persisted fenced transition V2 retention order is invalid",
            ));
        }
        previous_retained_until = Some(retained_until_timestamp);
        let binding_digest: [u8; 32] = binding_digest
            .try_into()
            .map_err(|_| invalid_data("persisted fenced transition V2 binding is invalid"))?;
        if binding_digest
            != fenced_transition_v2_receipt_binding_digest(
                identity,
                request_id,
                history_epoch,
                ordinal,
                payload_digest,
                &retained_until,
            )?
        {
            return Err(invalid_data(
                "persisted fenced transition V2 binding is invalid",
            ));
        }
        match (response_json, response_digest) {
            (Some(response_json), Some(response_digest)) => {
                if response_json.len() > FENCED_TRANSITION_V2_RECEIPT_RESPONSE_MAX_BYTES {
                    return Err(invalid_data(
                        "persisted fenced transition V2 receipt is invalid",
                    ));
                }
                let response = decode_fenced_transition_v2_response(&response_json)?;
                validate_fenced_transition_v2_receipt_metadata(
                    retained_until_timestamp,
                    &response,
                )?;
                validate_fenced_transition_receipt_against_floors(
                    &FencedTransitionReceipt {
                        payload_digest,
                        retained_until: retained_until_timestamp,
                        response: Some(response.clone()),
                    },
                    machine_sequence,
                    machine_logical_time,
                    applied_index,
                )?;
                let response_digest: [u8; 32] = response_digest.try_into().map_err(|_| {
                    invalid_data("persisted fenced transition V2 response is invalid")
                })?;
                if response_digest
                    != fenced_transition_v2_receipt_response_digest(binding_digest, &response_json)?
                {
                    return Err(invalid_data(
                        "persisted fenced transition V2 response is invalid",
                    ));
                }
            }
            (None, None) => {
                if !fenced_transition_v2_timestamp_is_in_range(retained_until_timestamp) {
                    return Err(invalid_data(
                        "persisted fenced transition V2 retention is invalid",
                    ));
                }
                validate_fenced_transition_receipt_against_floors(
                    &FencedTransitionReceipt {
                        payload_digest,
                        retained_until: retained_until_timestamp,
                        response: None,
                    },
                    machine_sequence,
                    machine_logical_time,
                    applied_index,
                )?
            }
            _ => {
                return Err(invalid_data(
                    "persisted fenced transition V2 response is invalid",
                ));
            }
        }
    }
    if epoch_counts.get(&active).copied().unwrap_or(0) != history.current_bound_count {
        return Err(invalid_data("fenced transition V2 active count is invalid"));
    }
    for epoch in minimum_epoch..=active {
        let count = epoch_counts.get(&epoch).copied().unwrap_or(0);
        if !fenced_transition_v2_closed_epoch_is_exact(
            epoch,
            active,
            history.reclaim_epoch,
            history.reclaim_cursor_ordinal,
            history.reclaim_remaining,
            count,
        ) {
            return Err(invalid_data(
                "fenced transition V2 closed epoch is incomplete",
            ));
        }
    }
    Ok(())
}

fn validate_fenced_transition_receipt_against_floors(
    receipt: &FencedTransitionReceipt,
    machine_sequence: u64,
    machine_logical_time: Option<Timestamp>,
    applied_index: Option<u64>,
) -> io::Result<()> {
    match receipt.response.as_ref() {
        Some(response) => {
            let response_logical_time = response.logical_time.ok_or_else(|| {
                invalid_data("persisted fenced transition receipt logical time is invalid")
            })?;
            if response.sequence > machine_sequence
                || machine_logical_time
                    .is_none_or(|logical_time| response_logical_time > logical_time)
                || applied_index.is_none_or(|index| response.raft_log_index > index)
            {
                return Err(invalid_data(
                    "persisted fenced transition receipt exceeds applied state",
                ));
            }
        }
        None if machine_logical_time
            .is_none_or(|logical_time| receipt.retained_until > logical_time) =>
        {
            return Err(invalid_data(
                "persisted fenced transition receipt was compacted before expiry",
            ));
        }
        None => {}
    }
    Ok(())
}

fn store_fenced_transition_receipt_sync(
    conn: &Connection,
    identity: SessionConsensusIdentity,
    request_id: SessionConsensusRequestId,
    payload_digest: [u8; 32],
    retained_until: Timestamp,
    response: &SessionConsensusResponse,
) -> io::Result<()> {
    validate_fenced_transition_receipt(retained_until, response)?;
    let encoded = encode_json(response)?;
    if encoded.len() > FENCED_TRANSITION_RECEIPT_MAX_RESPONSE_BYTES {
        return Err(invalid_data("fenced transition receipt is too large"));
    }
    let retained_until = ops::format_rfc3339_normalized(retained_until);
    let binding_digest = fenced_transition_receipt_binding_digest(
        identity,
        request_id,
        payload_digest,
        &retained_until,
    )?;
    let response_digest = fenced_transition_receipt_response_digest(binding_digest, response)?;
    conn.execute(
        "INSERT INTO consensus_fenced_transition_receipts (request_id, configuration_epoch, payload_digest, retained_until, binding_digest, response_json, response_digest) VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7)",
        params![
            request_id.as_bytes().as_slice(),
            epoch_i64(identity)?,
            payload_digest.as_slice(),
            retained_until,
            binding_digest.as_slice(),
            encoded,
            response_digest.as_slice(),
        ],
    )
    .map_err(db_error)?;
    Ok(())
}

/// Compact only the receipt being replayed. This is deterministic bounded
/// work and retains the request/body tombstone indefinitely.
fn compact_fenced_transition_receipt_sync(
    conn: &Connection,
    request_id: SessionConsensusRequestId,
    logical_time: Timestamp,
) -> io::Result<()> {
    conn.execute(
        "UPDATE consensus_fenced_transition_receipts SET response_json = NULL, response_digest = NULL WHERE request_id = ?1 AND retained_until <= ?2 AND response_json IS NOT NULL",
        params![
            request_id.as_bytes().as_slice(),
            ops::format_rfc3339_normalized(logical_time),
        ],
    )
    .map_err(db_error)?;
    Ok(())
}

/// Tombstone no more than one expired receipt per newly executed command.
/// The partial index makes the selection bounded and deterministic without a
/// full-ledger sweep; the permanent ID/body digest remains in the row.
fn compact_one_due_fenced_transition_receipt_sync(
    conn: &Connection,
    logical_time: Timestamp,
) -> io::Result<()> {
    conn.execute(
        "UPDATE consensus_fenced_transition_receipts SET response_json = NULL, response_digest = NULL WHERE request_id = (SELECT request_id FROM consensus_fenced_transition_receipts WHERE response_json IS NOT NULL AND retained_until <= ?1 ORDER BY retained_until ASC, request_id ASC LIMIT 1)",
        [ops::format_rfc3339_normalized(logical_time)],
    )
    .map_err(db_error)?;
    Ok(())
}

/// Read one durable fenced-transition receipt without changing ledger state.
/// The caller has already linearized and authorized its current authority
/// context. That changing authority is not part of the durable receipt
/// binding, which instead uses the stable consensus identity.
pub(crate) fn read_fenced_transition_status_sync(
    conn: &Connection,
    storage_identity: SessionConsensusIdentity,
    _command_identity: SessionConsensusIdentity,
    request: &FencedTransitionRequest,
) -> Result<FencedTransitionStatus, StoreError> {
    request.validate()?;
    let request_id = SessionConsensusRequestId::from_bytes(*request.request_id().as_bytes());
    let digest = fenced_transition_payload_digest(storage_identity, request).map_err(|_| {
        StoreError::BackendUnavailable("fenced transition status is unavailable".into())
    })?;
    let machine = read_machine_sync(conn, storage_identity).map_err(|_| {
        StoreError::BackendUnavailable("fenced transition status is unavailable".into())
    })?;
    let applied_index = read_applied_sync(conn, storage_identity)
        .map_err(|_| {
            StoreError::BackendUnavailable("fenced transition status is unavailable".into())
        })?
        .map(|log_id| log_id.index);
    if let Some(receipt) = read_fenced_transition_receipt_sync(conn, storage_identity, request_id)
        .map_err(|_| {
        StoreError::BackendUnavailable("fenced transition status is unavailable".into())
    })? {
        // A fenced receipt is authoritative even if an incompatible generic
        // outcome also exists; reopen validation rejects that persisted
        // namespace collision, but status must never invert receipt precedence.
        validate_fenced_transition_receipt_against_floors(
            &receipt,
            machine.0,
            machine.2,
            applied_index,
        )
        .map_err(|_| {
            StoreError::BackendUnavailable("fenced transition status is unavailable".into())
        })?;
        if receipt.payload_digest != digest {
            return Ok(FencedTransitionStatus::RequestConflict);
        }
        if let Some(response) = receipt.response.as_ref() {
            validate_fenced_transition_response_for_request(request, response).map_err(|_| {
                StoreError::BackendUnavailable("fenced transition status is unavailable".into())
            })?;
        }
        if machine.2.is_some_and(|now| receipt.retained_until <= now) || receipt.response.is_none()
        {
            return Ok(FencedTransitionStatus::Expired);
        }
        return match receipt.response.expect("checked above").result {
            Ok(SessionMutationOutcome::FencedTransition(outcome)) => {
                Ok(FencedTransitionStatus::Recorded(Box::new(Ok(outcome))))
            }
            Err(error) => Ok(FencedTransitionStatus::Recorded(Box::new(Err(error)))),
            Ok(_) => Err(StoreError::BackendUnavailable(
                "fenced transition status is unavailable".into(),
            )),
        };
    }

    // Fenced and generic consensus outcomes share one request-ID namespace.
    // An absent fenced receipt therefore must consult the generic ledger
    // before reporting either capacity or absence.
    if read_outcome_sync(conn, storage_identity, request_id)
        .map_err(|_| {
            StoreError::BackendUnavailable("fenced transition status is unavailable".into())
        })?
        .is_some()
    {
        return Ok(FencedTransitionStatus::RequestConflict);
    }
    if fenced_transition_receipt_count_sync(conn).map_err(|_| {
        StoreError::BackendUnavailable("fenced transition status is unavailable".into())
    })? >= FENCED_TRANSITION_MAX_HISTORY_ENTRIES
    {
        return Ok(FencedTransitionStatus::HistoryFull);
    }
    if machine.2.is_some_and(|logical_time| {
        crate::ttl::checked_session_deadline(logical_time, FENCED_TRANSITION_OUTCOME_RETENTION)
            .is_err()
    }) {
        return Ok(FencedTransitionStatus::RetentionExhausted);
    }
    Ok(FencedTransitionStatus::NotFound)
}

/// Read the exact binding and operation outcomes for an ordinary consumer
/// lease mutation without applying a consensus command or evaluating current
/// lease state.
///
/// The caller supplies only IDs derived at the authenticated server boundary.
/// The complete original consumer request is still required here to rebuild
/// both expected commitments.  A matching public ID with a changed body is a
/// conflict; an absent row is merely an observation at the caller's completed
/// linearizable read barrier.
pub(crate) fn read_consumer_lease_mutation_status_sync(
    conn: &Connection,
    storage_identity: SessionConsensusIdentity,
    authority_identity: SessionConsensusIdentity,
    binding_request_id: SessionConsensusRequestId,
    operation_request_id: SessionConsensusRequestId,
    request: &crate::consumer::SessionConsumerRequest,
) -> Result<crate::consumer::SessionConsumerLeaseMutationStatus, StoreError> {
    use crate::consumer::{
        SessionConsumerLeaseMutationOperation, SessionConsumerLeaseMutationStatus,
        SessionConsumerOperation,
    };

    request.validate().map_err(|_| {
        StoreError::BackendUnavailable("consumer lease receipt status is unavailable".into())
    })?;
    if request.scope().consensus_identity() != authority_identity {
        return Err(StoreError::BackendUnavailable(
            "consumer lease receipt status is unavailable".into(),
        ));
    }
    let lease_operation = match request.operation() {
        SessionConsumerOperation::AcquireLease { key, owner, ttl } => {
            SessionConsumerLeaseMutationOperation::Acquire {
                key: key.clone(),
                owner: owner.clone(),
                ttl: *ttl,
            }
        }
        SessionConsumerOperation::RenewLease { lease, ttl } => {
            SessionConsumerLeaseMutationOperation::Renew {
                lease: lease.clone(),
                ttl: *ttl,
            }
        }
        SessionConsumerOperation::ReleaseLease { lease } => {
            SessionConsumerLeaseMutationOperation::Release {
                lease: lease.clone(),
            }
        }
        _ => {
            return Err(StoreError::BackendUnavailable(
                "consumer lease receipt status is unavailable".into(),
            ));
        }
    };
    let commitment = crate::consumer::consumer_request_commitment(request).map_err(|_| {
        StoreError::BackendUnavailable("consumer lease receipt status is unavailable".into())
    })?;
    let binding_digest = authorized_mutation_payload_digest(
        storage_identity,
        authority_identity,
        &SessionMutationIntent::BindConsumerRequest {
            request_commitment: commitment,
        },
    )
    .map_err(|_| {
        StoreError::BackendUnavailable("consumer lease receipt status is unavailable".into())
    })?;
    let operation_intent = match &lease_operation {
        SessionConsumerLeaseMutationOperation::Acquire { key, owner, ttl } => {
            SessionMutationIntent::AcquireLease {
                key: key.clone(),
                owner: owner.clone(),
                ttl: *ttl,
            }
        }
        SessionConsumerLeaseMutationOperation::Renew { lease, ttl } => {
            SessionMutationIntent::RenewLease {
                lease: lease.clone(),
                ttl: *ttl,
            }
        }
        SessionConsumerLeaseMutationOperation::Release { lease } => {
            SessionMutationIntent::ReleaseLease(lease.clone())
        }
    };
    let operation_digest =
        authorized_mutation_payload_digest(storage_identity, authority_identity, &operation_intent)
            .map_err(|_| {
                StoreError::BackendUnavailable(
                    "consumer lease receipt status is unavailable".into(),
                )
            })?;

    let binding = read_outcome_sync(conn, storage_identity, binding_request_id).map_err(|_| {
        StoreError::BackendUnavailable("consumer lease receipt status is unavailable".into())
    })?;
    let binding_matches = match binding {
        Some((digest, response)) if digest == binding_digest => {
            matches!(response.result, Ok(SessionMutationOutcome::Unit))
        }
        Some(_) => return Ok(SessionConsumerLeaseMutationStatus::RequestConflict),
        None => false,
    };
    if !binding_matches {
        if request_id_is_occupied_sync(conn, storage_identity, binding_request_id)?
            || request_id_is_occupied_sync(conn, storage_identity, operation_request_id)?
        {
            return Ok(SessionConsumerLeaseMutationStatus::RequestConflict);
        }
        return Ok(SessionConsumerLeaseMutationStatus::NotFound);
    }

    let Some((digest, response)) = read_outcome_sync(conn, storage_identity, operation_request_id)
        .map_err(|_| {
            StoreError::BackendUnavailable("consumer lease receipt status is unavailable".into())
        })?
    else {
        if request_id_is_occupied_sync(conn, storage_identity, operation_request_id)? {
            return Ok(SessionConsumerLeaseMutationStatus::RequestConflict);
        }
        return Ok(SessionConsumerLeaseMutationStatus::NotFound);
    };
    if digest != operation_digest {
        return Ok(SessionConsumerLeaseMutationStatus::RequestConflict);
    }
    let recorded = consumer_lease_mutation_result_from_response(&lease_operation, &response)?;
    Ok(SessionConsumerLeaseMutationStatus::Recorded(Box::new(
        recorded,
    )))
}

/// Read the exact binding and compare-and-set outcomes for one prepared
/// consumer request without applying a consensus command or reading the
/// current session row.
pub(crate) fn read_consumer_compare_and_set_status_sync(
    conn: &Connection,
    storage_identity: SessionConsensusIdentity,
    lookup: ConsumerCompareAndSetReceiptLookup,
) -> Result<crate::consumer::SessionConsumerCompareAndSetStatus, StoreError> {
    use crate::consumer::{
        SessionConsumerCompareAndSetReceiptOutcome, SessionConsumerCompareAndSetStatus,
        SessionConsumerStoreError,
    };

    let binding =
        read_outcome_sync(conn, storage_identity, lookup.binding_request_id).map_err(|_| {
            StoreError::BackendUnavailable("consumer compare-and-set status is unavailable".into())
        })?;
    let binding_matches = match binding {
        Some((digest, response)) if digest == lookup.binding_digest => {
            matches!(response.result, Ok(SessionMutationOutcome::Unit))
        }
        Some(_) => return Ok(SessionConsumerCompareAndSetStatus::RequestConflict),
        None => false,
    };
    if !binding_matches {
        if request_id_has_fenced_transition_receipt_sync(
            conn,
            storage_identity,
            lookup.binding_request_id,
        )? || request_id_is_occupied_sync(conn, storage_identity, lookup.operation_request_id)?
        {
            return Ok(SessionConsumerCompareAndSetStatus::RequestConflict);
        }
        return Ok(SessionConsumerCompareAndSetStatus::NotFound);
    }

    let Some((digest, response)) =
        read_outcome_sync(conn, storage_identity, lookup.operation_request_id).map_err(|_| {
            StoreError::BackendUnavailable("consumer compare-and-set status is unavailable".into())
        })?
    else {
        if request_id_has_fenced_transition_receipt_sync(
            conn,
            storage_identity,
            lookup.operation_request_id,
        )? {
            return Ok(SessionConsumerCompareAndSetStatus::RequestConflict);
        }
        return Ok(SessionConsumerCompareAndSetStatus::NotFound);
    };
    if digest != lookup.operation_digest {
        return Ok(SessionConsumerCompareAndSetStatus::RequestConflict);
    }
    let recorded = match response.result {
        Ok(SessionMutationOutcome::CompareAndSet(CompareAndSetResult::Success)) => {
            SessionConsumerCompareAndSetReceiptOutcome::Applied
        }
        Ok(SessionMutationOutcome::CompareAndSet(CompareAndSetResult::Conflict { .. })) => {
            SessionConsumerCompareAndSetReceiptOutcome::Conflict
        }
        Err(error) => SessionConsumerCompareAndSetReceiptOutcome::Rejected(
            SessionConsumerStoreError::from(error),
        ),
        Ok(_) => {
            return Err(StoreError::BackendUnavailable(
                "consumer compare-and-set status is unavailable".into(),
            ));
        }
    };
    Ok(SessionConsumerCompareAndSetStatus::Recorded(recorded))
}

fn request_id_has_fenced_transition_receipt_sync(
    conn: &Connection,
    identity: SessionConsensusIdentity,
    request_id: SessionConsensusRequestId,
) -> Result<bool, StoreError> {
    read_fenced_transition_receipt_sync(conn, identity, request_id)
        .map(|receipt| receipt.is_some())
        .map_err(|_| {
            StoreError::BackendUnavailable(
                "consumer compare-and-set receipt status is unavailable".into(),
            )
        })
}

fn request_id_is_occupied_sync(
    conn: &Connection,
    identity: SessionConsensusIdentity,
    request_id: SessionConsensusRequestId,
) -> Result<bool, StoreError> {
    if read_outcome_sync(conn, identity, request_id)
        .map_err(|_| {
            StoreError::BackendUnavailable("consumer lease receipt status is unavailable".into())
        })?
        .is_some()
    {
        return Ok(true);
    }
    read_fenced_transition_receipt_sync(conn, identity, request_id)
        .map(|receipt| receipt.is_some())
        .map_err(|_| {
            StoreError::BackendUnavailable("consumer lease receipt status is unavailable".into())
        })
}

fn consumer_lease_mutation_result_from_response(
    operation: &crate::consumer::SessionConsumerLeaseMutationOperation,
    response: &SessionConsensusResponse,
) -> Result<
    Result<
        crate::consumer::SessionConsumerLeaseMutationResult,
        crate::consumer::SessionConsumerLeaseError,
    >,
    StoreError,
> {
    use crate::consumer::{
        SessionConsumerLeaseError, SessionConsumerLeaseMutationOperation,
        SessionConsumerLeaseMutationResult,
    };

    let unavailable =
        || StoreError::BackendUnavailable("consumer lease receipt status is unavailable".into());
    let deterministic_error = |error: &StoreError, permits: &[SessionConsumerLeaseError]| {
        let projected = match error {
            StoreError::LeaseHeld => SessionConsumerLeaseError::AlreadyHeld,
            StoreError::LeaseExpired => SessionConsumerLeaseError::Expired,
            StoreError::StaleFence | StoreError::TopologyAuthorityRevoked => {
                SessionConsumerLeaseError::StaleFence
            }
            StoreError::NotFound => SessionConsumerLeaseError::NotFound,
            StoreError::InvalidSessionTtl => SessionConsumerLeaseError::InvalidTtl,
            _ => return None,
        };
        permits.contains(&projected).then_some(projected)
    };
    match operation {
        SessionConsumerLeaseMutationOperation::Acquire { key, owner, ttl } => {
            match &response.result {
                Ok(SessionMutationOutcome::Lease(guard)) => {
                    guard.validate_profile().map_err(|_| unavailable())?;
                    if guard.key() != key
                        || guard.owner() != owner
                        || guard.acquired_at() != response.logical_time.ok_or_else(unavailable)?
                        || guard.expires_at()
                            != crate::ttl::checked_session_deadline(
                                response.logical_time.ok_or_else(unavailable)?,
                                *ttl,
                            )
                            .map_err(|_| unavailable())?
                    {
                        return Err(unavailable());
                    }
                    Ok(Ok(SessionConsumerLeaseMutationResult::Acquire(
                        guard.clone(),
                    )))
                }
                Err(error) => deterministic_error(
                    error,
                    &[
                        SessionConsumerLeaseError::AlreadyHeld,
                        SessionConsumerLeaseError::StaleFence,
                        SessionConsumerLeaseError::InvalidTtl,
                    ],
                )
                .map(Err)
                .ok_or_else(unavailable),
                Ok(_) => Err(unavailable()),
            }
        }
        SessionConsumerLeaseMutationOperation::Renew { lease, ttl } => match &response.result {
            Ok(SessionMutationOutcome::Lease(guard)) => {
                guard.validate_profile().map_err(|_| unavailable())?;
                if guard.key() != lease.key()
                    || guard.owner() != lease.owner()
                    || guard.fence() != lease.fence()
                    || guard.credential_id() != lease.credential_id()
                    || guard.acquired_at() != lease.acquired_at()
                    || guard.expires_at()
                        != crate::ttl::checked_session_deadline(
                            response.logical_time.ok_or_else(unavailable)?,
                            *ttl,
                        )
                        .map_err(|_| unavailable())?
                {
                    return Err(unavailable());
                }
                Ok(Ok(SessionConsumerLeaseMutationResult::Renew(guard.clone())))
            }
            Err(error) => deterministic_error(
                error,
                &[
                    SessionConsumerLeaseError::AlreadyHeld,
                    SessionConsumerLeaseError::Expired,
                    SessionConsumerLeaseError::StaleFence,
                    SessionConsumerLeaseError::NotFound,
                    SessionConsumerLeaseError::InvalidTtl,
                ],
            )
            .map(Err)
            .ok_or_else(unavailable),
            Ok(_) => Err(unavailable()),
        },
        SessionConsumerLeaseMutationOperation::Release { lease: _ } => match &response.result {
            Ok(SessionMutationOutcome::Unit) => Ok(Ok(SessionConsumerLeaseMutationResult::Release)),
            Err(error) => deterministic_error(
                error,
                &[
                    SessionConsumerLeaseError::AlreadyHeld,
                    SessionConsumerLeaseError::StaleFence,
                    SessionConsumerLeaseError::NotFound,
                ],
            )
            .map(Err)
            .ok_or_else(unavailable),
            Ok(_) => Err(unavailable()),
        },
    }
}

/// Resolve V2 status from its full self-authenticating identity.  No V1
/// request-ID namespace or capacity scan participates in this lookup.
pub(crate) fn read_fenced_transition_v2_status_sync(
    conn: &Connection,
    storage_identity: SessionConsensusIdentity,
    _command_identity: SessionConsensusIdentity,
    request: &FencedTransitionV2Request,
) -> Result<FencedTransitionV2Status, StoreError> {
    // This must be before receipt/floor lookup: an altered serialized body is
    // a conflict even if the matching epoch's rows have since been reclaimed.
    match request.validate() {
        Ok(()) => {}
        Err(StoreError::FencedTransitionRequestConflict) => {
            return Ok(FencedTransitionV2Status::RequestConflict);
        }
        Err(error) => return Err(error),
    }
    if fenced_transition_v2_ledger_layout_sync(conn).map_err(|_| {
        StoreError::BackendUnavailable("fenced transition V2 status is unavailable".into())
    })? == FencedTransitionV2LedgerLayout::Absent
    {
        if request.request_id().epoch().get() != FENCED_TRANSITION_V2_INITIAL_HISTORY_EPOCH {
            return Ok(FencedTransitionV2Status::EpochNotActive);
        }
        let machine = read_machine_sync(conn, storage_identity).map_err(|_| {
            StoreError::BackendUnavailable("fenced transition V2 status is unavailable".into())
        })?;
        return Ok(if fenced_transition_v2_retention_is_exhausted(machine.2) {
            FencedTransitionV2Status::RetentionExhausted
        } else {
            FencedTransitionV2Status::NotFound
        });
    }
    let history = read_fenced_transition_v2_history_row_in_sync(conn, storage_identity, false)
        .map_err(|_| {
            StoreError::BackendUnavailable("fenced transition V2 status is unavailable".into())
        })?;
    let epoch = request.request_id().epoch().get();
    if epoch <= history.retired_through {
        return Ok(FencedTransitionV2Status::Retired);
    }
    if let Some(receipt) = read_fenced_transition_v2_receipt_sync(conn, storage_identity, request)
        .map_err(|_| {
        StoreError::BackendUnavailable("fenced transition V2 status is unavailable".into())
    })? {
        if receipt.history_epoch != epoch {
            return Err(StoreError::BackendUnavailable(
                "fenced transition V2 status is unavailable".into(),
            ));
        }
        let digest =
            fenced_transition_v2_payload_digest(storage_identity, request).map_err(|_| {
                StoreError::BackendUnavailable("fenced transition V2 status is unavailable".into())
            })?;
        if receipt.payload_digest != digest {
            return Ok(FencedTransitionV2Status::RequestConflict);
        }
        let machine = read_machine_sync(conn, storage_identity).map_err(|_| {
            StoreError::BackendUnavailable("fenced transition V2 status is unavailable".into())
        })?;
        let applied = read_applied_sync(conn, storage_identity)
            .map_err(|_| {
                StoreError::BackendUnavailable("fenced transition V2 status is unavailable".into())
            })?
            .map(|log_id| log_id.index);
        validate_fenced_transition_receipt_against_floors(
            &FencedTransitionReceipt {
                payload_digest: receipt.payload_digest,
                retained_until: receipt.retained_until,
                response: receipt.response.clone(),
            },
            machine.0,
            machine.2,
            applied,
        )
        .map_err(|_| {
            StoreError::BackendUnavailable("fenced transition V2 status is unavailable".into())
        })?;
        if receipt.response.is_none()
            || machine.2.is_some_and(|time| receipt.retained_until <= time)
        {
            return Ok(FencedTransitionV2Status::Expired);
        }
        return match receipt.response.expect("checked above").result {
            Ok(SessionMutationOutcome::FencedTransition(outcome)) => {
                Ok(FencedTransitionV2Status::Recorded(Box::new(Ok(outcome))))
            }
            Err(error) => Ok(FencedTransitionV2Status::Recorded(Box::new(Err(error)))),
            Ok(_) => Err(StoreError::BackendUnavailable(
                "fenced transition V2 status is unavailable".into(),
            )),
        };
    }
    if history.active_epoch != Some(request.request_id().epoch()) {
        return Ok(FencedTransitionV2Status::EpochNotActive);
    }
    if history.current_bound_count >= FENCED_TRANSITION_V2_MAX_HISTORY_ENTRIES {
        return Ok(FencedTransitionV2Status::HistoryFull);
    }
    let machine = read_machine_sync(conn, storage_identity).map_err(|_| {
        StoreError::BackendUnavailable("fenced transition V2 status is unavailable".into())
    })?;
    if fenced_transition_v2_retention_is_exhausted(machine.2) {
        return Ok(FencedTransitionV2Status::RetentionExhausted);
    }
    Ok(FencedTransitionV2Status::NotFound)
}

/// Report whether a fresh V2 request cannot bind its exact-result window at
/// the persisted logical time. The fixed V2 timestamp profile is stricter
/// than the optional local parser range, so status follows the same check as
/// the unbound apply and follower-projection paths.
fn fenced_transition_v2_retention_is_exhausted(logical_time: Option<Timestamp>) -> bool {
    logical_time.is_some_and(|logical_time| {
        !fenced_transition_v2_timestamp_is_in_range(logical_time)
            || !crate::ttl::checked_session_deadline(
                logical_time,
                FENCED_TRANSITION_OUTCOME_RETENTION,
            )
            .is_ok_and(fenced_transition_v2_timestamp_is_in_range)
    })
}

fn replay_conflict_response(
    machine: &(u64, SessionConsensusEntryDigest, Option<Timestamp>, u64),
    raft_log_index: u64,
    error: StoreError,
) -> SessionConsensusResponse {
    SessionConsensusResponse {
        result: Err(error),
        sequence: machine.0,
        digest: Some(machine.1),
        logical_time: machine.2,
        raft_log_index,
    }
}

/// Advance only the committed logical clock for a fenced replay-style result.
/// Such results keep the current application/digest/watch state while still
/// consuming their ordered log entry through the applied pointer.
fn advance_fenced_replay_logical_time_sync(
    conn: &Connection,
    identity: SessionConsensusIdentity,
    command_logical_time: Timestamp,
    machine: &mut (u64, SessionConsensusEntryDigest, Option<Timestamp>, u64),
) -> io::Result<()> {
    if machine
        .2
        .is_none_or(|logical_time| command_logical_time > logical_time)
    {
        let changed = conn
            .execute(
                "UPDATE consensus_machine SET logical_time = ?1 WHERE singleton = 1 AND configuration_epoch = ?2",
                params![
                    ops::format_rfc3339_normalized(command_logical_time),
                    epoch_i64(identity)?,
                ],
            )
            .map_err(db_error)?;
        if changed != 1 {
            return Err(invalid_data("session consensus machine state is missing"));
        }
        machine.2 = Some(command_logical_time);
    }
    Ok(())
}

fn replay_fenced_transition_receipt_sync(
    conn: &Connection,
    identity: SessionConsensusIdentity,
    command: &SessionConsensusCommand,
    digest: [u8; 32],
    machine: &(u64, SessionConsensusEntryDigest, Option<Timestamp>, u64),
    raft_log_index: u64,
) -> io::Result<Option<SessionConsensusResponse>> {
    let Some(receipt) = read_fenced_transition_receipt_sync(conn, identity, command.request_id)?
    else {
        // Request IDs are a single durable namespace. A generic receipt is a
        // closed conflict for a later fenced transition even though it lives
        // in the legacy outcome ledger.
        return Ok(
            read_outcome_sync(conn, identity, command.request_id)?.map(|_| {
                replay_conflict_response(
                    machine,
                    raft_log_index,
                    StoreError::FencedTransitionRequestConflict,
                )
            }),
        );
    };
    validate_fenced_transition_receipt_against_floors(
        &receipt,
        machine.0,
        machine.2,
        Some(raft_log_index.saturating_sub(1)),
    )?;
    if receipt.payload_digest != digest {
        return Ok(Some(replay_conflict_response(
            machine,
            raft_log_index,
            StoreError::FencedTransitionRequestConflict,
        )));
    }
    if let Some(response) = receipt.response.as_ref() {
        validate_fenced_transition_response_for_request(
            fenced_transition_request(&command.intent)
                .ok_or_else(|| invalid_data("fenced transition replay request is missing"))?,
            response,
        )?;
    }
    let replay_time = machine.2.map_or(command.logical_time, |last_time| {
        last_time.max(command.logical_time)
    });
    if receipt.retained_until <= replay_time || receipt.response.is_none() {
        compact_fenced_transition_receipt_sync(conn, command.request_id, replay_time)?;
        return Ok(Some(replay_conflict_response(
            machine,
            raft_log_index,
            StoreError::FencedTransitionRequestExpired,
        )));
    }
    Ok(receipt.response)
}

fn fenced_transition_v2_singleton_intent(
    intent: &SessionMutationIntent,
    request: &FencedTransitionV2Request,
) -> io::Result<SessionMutationIntent> {
    let singleton = SessionMutationIntent::FencedTransitionV2(Box::new(request.clone()));
    match intent {
        SessionMutationIntent::FencedTransitionV2Batch(_) => Ok(singleton),
        SessionMutationIntent::Authorized {
            origin,
            authority_identity,
            mutation,
        } if matches!(
            mutation.as_ref(),
            SessionMutationIntent::FencedTransitionV2Batch(_)
        ) =>
        {
            Ok(SessionMutationIntent::Authorized {
                origin: *origin,
                authority_identity: *authority_identity,
                mutation: Box::new(singleton),
            })
        }
        _ => Err(invalid_data(
            "fenced transition V2 batch authority envelope is invalid",
        )),
    }
}

fn fenced_transition_v2_replayed_outcome(
    receipt: &FencedTransitionV2Receipt,
    payload_digest: [u8; 32],
    logical_time: Timestamp,
) -> io::Result<Result<FencedTransitionOutcome, StoreError>> {
    if receipt.payload_digest != payload_digest {
        return Ok(Err(StoreError::FencedTransitionRequestConflict));
    }
    if receipt.response.is_none() || receipt.retained_until <= logical_time {
        return Ok(Err(StoreError::FencedTransitionRequestExpired));
    }
    match receipt
        .response
        .as_ref()
        .expect("checked above")
        .result
        .clone()
    {
        Ok(SessionMutationOutcome::FencedTransition(outcome)) => Ok(Ok(outcome)),
        Err(error) => Ok(Err(error)),
        _ => Err(invalid_data(
            "persisted fenced transition V2 receipt result is invalid",
        )),
    }
}

/// Apply one ordered V2 batch under the already-open outer SQLite
/// transaction. Fresh identities consume the remaining receipt capacity in
/// slot order; deterministic item failures bind and return in slot order,
/// while any infrastructure failure aborts this entire outer apply.
#[allow(clippy::too_many_arguments)]
fn apply_fenced_transition_v2_batch_command_sync(
    tx: &mut Transaction<'_>,
    storage_identity: SessionConsensusIdentity,
    scope: &MembershipValidationScope,
    caps: &BackendCapabilities,
    command: &SessionConsensusCommand,
    raft_log_index: u64,
    machine: &mut (u64, SessionConsensusEntryDigest, Option<Timestamp>, u64),
    notifications: &mut Vec<ReplicationEntry>,
) -> io::Result<SessionConsensusResponse> {
    let requests = fenced_transition_v2_batch(&command.intent)
        .ok_or_else(|| invalid_data("fenced transition V2 batch is missing"))?;
    validate_fenced_transition_v2_batch(requests)
        .map_err(|_| invalid_data("fenced transition V2 batch is invalid"))?;
    if !fenced_transition_v2_timestamp_is_in_range(command.logical_time) {
        return Err(invalid_data(
            "fenced transition V2 batch logical time is outside the profiled range",
        ));
    }
    let logical_time = machine
        .2
        .map_or(command.logical_time, |time| time.max(command.logical_time));
    let access_is_authorized =
        fenced_transition_access_is_authorized_sync(scope, storage_identity, &command.intent)?;
    if !access_is_authorized {
        let outcomes = requests
            .iter()
            .map(|request| match request.validate() {
                Err(StoreError::FencedTransitionRequestConflict) => {
                    Err(StoreError::FencedTransitionRequestConflict)
                }
                _ => Err(StoreError::TopologyAuthorityRevoked),
            })
            .collect::<Vec<_>>();
        validate_fenced_transition_v2_batch_outcomes(&outcomes)
            .map_err(|_| invalid_data("fenced transition V2 batch outcome is invalid"))?;
        advance_fenced_replay_logical_time_sync(tx, storage_identity, logical_time, machine)?;
        return Ok(SessionConsensusResponse {
            result: Ok(SessionMutationOutcome::FencedTransitionV2Batch(outcomes)),
            sequence: machine.0,
            digest: Some(machine.1),
            logical_time: Some(logical_time),
            raft_log_index,
        });
    }
    if fenced_transition_v2_ledger_layout_sync(tx)? != FencedTransitionV2LedgerLayout::Activated
        || !fenced_transition_v2_activation_matches_scope_sync(
            tx,
            storage_identity,
            scope.current_identity,
            &scope.current_members,
            crate::fenced_transition::fenced_transition_v2_profile_digest(),
        )?
    {
        return Err(invalid_data(
            "fenced transition V2 batch lacks an exact activation certificate",
        ));
    }
    let history = read_fenced_transition_v2_history_row_in_sync(tx, storage_identity, false)?;
    let mut outcomes = vec![None; requests.len()];
    let mut fresh = Vec::new();
    for (slot, request) in requests.iter().enumerate() {
        if matches!(
            request.validate(),
            Err(StoreError::FencedTransitionRequestConflict)
        ) {
            outcomes[slot] = Some(Err(StoreError::FencedTransitionRequestConflict));
            continue;
        }
        let payload_digest = fenced_transition_v2_payload_digest(storage_identity, request)?;
        let epoch = request.request_id().epoch().get();
        if epoch <= history.retired_through {
            outcomes[slot] = Some(Err(StoreError::FencedTransitionHistoryEpochRetired));
            continue;
        }
        if let Some(receipt) =
            read_fenced_transition_v2_receipt_sync(tx, storage_identity, request)?
        {
            outcomes[slot] = Some(fenced_transition_v2_replayed_outcome(
                &receipt,
                payload_digest,
                logical_time,
            )?);
            continue;
        }
        if history.active_epoch != Some(request.request_id().epoch()) {
            outcomes[slot] = Some(Err(StoreError::FencedTransitionHistoryEpochNotActive));
            continue;
        }
        fresh.push((slot, payload_digest));
    }
    let remaining = FENCED_TRANSITION_V2_MAX_HISTORY_ENTRIES
        .checked_sub(history.current_bound_count)
        .ok_or_else(|| invalid_data("fenced transition V2 history count is invalid"))?;
    let retained_until = match crate::ttl::checked_session_deadline(
        logical_time,
        FENCED_TRANSITION_OUTCOME_RETENTION,
    ) {
        Ok(until) if fenced_transition_v2_timestamp_is_in_range(until) => Some(until),
        Ok(_) | Err(_) => None,
    };
    if remaining == 0 {
        // Capacity precedes the retention horizon for an unbound singleton,
        // so an already-full epoch returns HistoryFull for every fresh item.
        for (slot, _) in &fresh {
            outcomes[*slot] = Some(Err(StoreError::FencedTransitionHistoryFull));
        }
    } else if retained_until.is_none() {
        // Retention exhaustion binds no receipt, so it consumes no capacity:
        // every fresh item observes the same result as consecutive singleton
        // commands while at least one slot remains.
        for (slot, _) in &fresh {
            outcomes[*slot] = Some(Err(StoreError::FencedTransitionRetentionExhausted));
        }
    } else if fresh.len() > remaining {
        // A batch is only a physical consensus optimization. Its ordered
        // items retain the same independent effects they would have had as
        // consecutive singleton commands, so the remaining receipt slots
        // bind the fresh prefix and only the capacity-exceeding suffix is
        // rejected. Replays and earlier deterministic rejections do not
        // consume a slot and therefore never displace a later fresh item.
        for (slot, _) in fresh.iter().skip(remaining) {
            outcomes[*slot] = Some(Err(StoreError::FencedTransitionHistoryFull));
        }
    }
    let binds = retained_until.is_some() && fresh.iter().any(|(slot, _)| outcomes[*slot].is_none());
    let (sequence, command_digest) = if binds && machine.0 < i64::MAX as u64 {
        let sequence = machine
            .0
            .checked_add(1)
            .ok_or_else(|| invalid_data("session consensus application sequence exhausted"))?;
        let digest = command
            .calculate_applied_digest(sequence, machine.1, logical_time)
            .map_err(|_| invalid_data("session consensus batch digest failed"))?;
        (sequence, digest)
    } else {
        (machine.0, machine.1)
    };
    let mut ordinal = u64::try_from(history.current_bound_count)
        .map_err(|_| invalid_data("fenced transition V2 ordinal is invalid"))?;
    for (slot, payload_digest) in fresh {
        if outcomes[slot].is_some() {
            continue;
        }
        let request = &requests[slot];
        ordinal = ordinal
            .checked_add(1)
            .ok_or_else(|| invalid_data("fenced transition V2 ordinal is exhausted"))?;
        let result = if machine.0 >= i64::MAX as u64 {
            Err(StoreError::FencedTransitionStorageExhausted)
        } else {
            let singleton = fenced_transition_v2_singleton_intent(&command.intent, request)?;
            let mut savepoint = tx.savepoint().map_err(db_error)?;
            match execute_intent_sync(
                &savepoint,
                storage_identity,
                raft_log_index,
                &singleton,
                caps,
                logical_time,
            ) {
                Ok((SessionMutationOutcome::FencedTransition(outcome), replication)) => {
                    savepoint.commit().map_err(db_error)?;
                    if let Some(replication) = replication {
                        machine.3 = machine.3.checked_add(1).ok_or_else(|| {
                            invalid_data("session consensus watch sequence exhausted")
                        })?;
                        notifications.push(store_replication_notification_sync(
                            tx,
                            storage_identity,
                            machine.3,
                            SessionConsensusRequestId::from_bytes(
                                fenced_transition_v2_outer_request_id(request.request_id()),
                            ),
                            replication,
                            logical_time,
                        )?);
                    }
                    Ok(outcome)
                }
                Ok((_, _)) => {
                    savepoint.rollback().map_err(db_error)?;
                    return Err(invalid_data("fenced transition V2 batch result is invalid"));
                }
                Err(error) if is_deterministic_intent_rejection(&error) => {
                    savepoint.rollback().map_err(db_error)?;
                    Err(error)
                }
                Err(_) => {
                    savepoint.rollback().map_err(db_error)?;
                    return Err(state_machine_intent_fault());
                }
            }
        };
        let response = SessionConsensusResponse {
            result: result.clone().map(SessionMutationOutcome::FencedTransition),
            sequence,
            digest: Some(command_digest),
            logical_time: Some(logical_time),
            raft_log_index,
        };
        store_fenced_transition_v2_receipt_sync(
            tx,
            storage_identity,
            request,
            ordinal,
            payload_digest,
            retained_until.expect("checked above"),
            &response,
        )?;
        outcomes[slot] = Some(result);
    }
    let outcomes = outcomes
        .into_iter()
        .collect::<Option<Vec<_>>>()
        .ok_or_else(|| invalid_data("fenced transition V2 batch outcome is missing"))?;
    validate_fenced_transition_v2_batch_outcomes(&outcomes)
        .map_err(|_| invalid_data("fenced transition V2 batch outcome is invalid"))?;
    if binds && machine.0 < i64::MAX as u64 {
        let changed = tx
            .execute(
                "UPDATE consensus_machine SET application_sequence = ?1, last_digest = ?2, logical_time = ?3 WHERE singleton = 1 AND configuration_epoch = ?4",
                params![
                    checked_positive_i64(sequence)?,
                    command_digest.as_bytes().as_slice(),
                    ops::format_rfc3339_normalized(logical_time),
                    epoch_i64(storage_identity)?,
                ],
            )
            .map_err(db_error)?;
        if changed != 1 {
            return Err(invalid_data("session consensus machine state is missing"));
        }
        machine.0 = sequence;
        machine.1 = command_digest;
        machine.2 = Some(logical_time);
    } else {
        advance_fenced_replay_logical_time_sync(tx, storage_identity, logical_time, machine)?;
    }
    Ok(SessionConsensusResponse {
        result: Ok(SessionMutationOutcome::FencedTransitionV2Batch(outcomes)),
        sequence: machine.0,
        digest: Some(machine.1),
        logical_time: Some(logical_time),
        raft_log_index,
    })
}

#[allow(clippy::too_many_arguments)]
fn apply_fenced_transition_v2_command_sync(
    tx: &mut Transaction<'_>,
    storage_identity: SessionConsensusIdentity,
    scope: &MembershipValidationScope,
    caps: &BackendCapabilities,
    command: &SessionConsensusCommand,
    payload_digest: [u8; 32],
    raft_log_index: u64,
    machine: &mut (u64, SessionConsensusEntryDigest, Option<Timestamp>, u64),
    notifications: &mut Vec<ReplicationEntry>,
) -> io::Result<SessionConsensusResponse> {
    let request = fenced_transition_v2_request(&command.intent)
        .ok_or_else(|| invalid_data("fenced transition V2 request is missing"))?;
    // Command timestamp validity is an admission property, so do not let an
    // altered request body turn an out-of-profile command into a replay-style
    // conflict which advances only this replica's logical clock.
    if !fenced_transition_v2_timestamp_is_in_range(command.logical_time) {
        return Err(invalid_data(
            "fenced transition V2 logical time is outside the profiled range",
        ));
    }
    // Self-authentication is evaluated before any durable row lookup or
    // retired-floor test. A caller-provided ID/body mismatch is terminal even
    // after physical reclamation of the original epoch.
    if matches!(
        request.validate(),
        Err(StoreError::FencedTransitionRequestConflict)
    ) {
        advance_fenced_replay_logical_time_sync(
            tx,
            storage_identity,
            command.logical_time,
            machine,
        )?;
        return Ok(replay_conflict_response(
            machine,
            raft_log_index,
            StoreError::FencedTransitionRequestConflict,
        ));
    }
    request
        .validate()
        .map_err(|_| invalid_data("fenced transition V2 request is invalid"))?;
    let access_is_authorized =
        fenced_transition_access_is_authorized_sync(scope, storage_identity, &command.intent)?;
    // Self-authentication deliberately remains first so an altered body is a
    // permanent closed identity conflict even after physical reclamation.
    // Every *valid* request from a revoked scope is then masked before any
    // V2 floor, receipt, cap, retention, or activation observation.
    if !access_is_authorized {
        advance_fenced_replay_logical_time_sync(
            tx,
            storage_identity,
            command.logical_time,
            machine,
        )?;
        return Ok(replay_conflict_response(
            machine,
            raft_log_index,
            StoreError::TopologyAuthorityRevoked,
        ));
    }
    let layout = fenced_transition_v2_ledger_layout_sync(tx)?;
    if layout == FencedTransitionV2LedgerLayout::Absent
        && request.request_id().epoch().get() != FENCED_TRANSITION_V2_INITIAL_HISTORY_EPOCH
    {
        // The first epoch is a protocol constant, not leader-selected state.
        // Reject an arbitrary first epoch without DDL, certificate, receipt,
        // or business side effect so a malformed caller cannot burn the V2
        // namespace or make replicas diverge over an invented retired floor.
        advance_fenced_replay_logical_time_sync(
            tx,
            storage_identity,
            command.logical_time,
            machine,
        )?;
        return Ok(replay_conflict_response(
            machine,
            raft_log_index,
            StoreError::FencedTransitionHistoryEpochNotActive,
        ));
    }
    match fenced_transition_v2_activation(&command.intent) {
        Some((scope_identity, voters, profile)) => {
            if scope_identity != scope.current_identity
                || voters
                    != fenced_transition_voter_set_digest(
                        scope.current_identity,
                        &scope.current_members,
                    )
                || profile != crate::fenced_transition::fenced_transition_v2_profile_digest()
            {
                return Err(invalid_data(
                    "fenced transition V2 activation scope is stale",
                ));
            }
            activate_fenced_transition_v2_scope_sync(
                tx,
                storage_identity,
                scope.current_identity,
                &scope.current_members,
                profile,
                request.request_id().epoch(),
            )?;
        }
        None if !fenced_transition_v2_activation_matches_scope_sync(
            tx,
            storage_identity,
            scope.current_identity,
            &scope.current_members,
            crate::fenced_transition::fenced_transition_v2_profile_digest(),
        )? =>
        {
            return Err(invalid_data(
                "fenced transition V2 lacks an exact activation certificate",
            ));
        }
        None => {}
    }
    let history = read_fenced_transition_v2_history_row_in_sync(tx, storage_identity, false)?;
    let request_epoch = request.request_id().epoch().get();
    if request_epoch <= history.retired_through {
        advance_fenced_replay_logical_time_sync(
            tx,
            storage_identity,
            command.logical_time,
            machine,
        )?;
        return Ok(replay_conflict_response(
            machine,
            raft_log_index,
            StoreError::FencedTransitionHistoryEpochRetired,
        ));
    }
    if let Some(receipt) = read_fenced_transition_v2_receipt_sync(tx, storage_identity, request)? {
        let replay_time = machine
            .2
            .map_or(command.logical_time, |time| time.max(command.logical_time));
        let response = if receipt.payload_digest != payload_digest {
            replay_conflict_response(
                machine,
                raft_log_index,
                StoreError::FencedTransitionRequestConflict,
            )
        } else if receipt.response.is_none() || receipt.retained_until <= replay_time {
            compact_fenced_transition_v2_receipt_sync(tx, request, replay_time)?;
            replay_conflict_response(
                machine,
                raft_log_index,
                StoreError::FencedTransitionRequestExpired,
            )
        } else {
            receipt.response.expect("checked above")
        };
        advance_fenced_replay_logical_time_sync(
            tx,
            storage_identity,
            command.logical_time,
            machine,
        )?;
        return Ok(if access_is_authorized {
            response
        } else {
            replay_conflict_response(
                machine,
                raft_log_index,
                StoreError::TopologyAuthorityRevoked,
            )
        });
    }
    // A valid full identity in a future epoch (or while a reclaim is in
    // progress) is not a permanently retired retry.  Keep that terminal
    // state distinct from a request at or below the retired floor.
    if history.active_epoch != Some(request.request_id().epoch()) {
        advance_fenced_replay_logical_time_sync(
            tx,
            storage_identity,
            command.logical_time,
            machine,
        )?;
        return Ok(replay_conflict_response(
            machine,
            raft_log_index,
            StoreError::FencedTransitionHistoryEpochNotActive,
        ));
    }
    if history.current_bound_count >= FENCED_TRANSITION_V2_MAX_HISTORY_ENTRIES {
        advance_fenced_replay_logical_time_sync(
            tx,
            storage_identity,
            command.logical_time,
            machine,
        )?;
        return Ok(replay_conflict_response(
            machine,
            raft_log_index,
            if access_is_authorized {
                StoreError::FencedTransitionHistoryFull
            } else {
                StoreError::TopologyAuthorityRevoked
            },
        ));
    }
    let logical_time = machine
        .2
        .map_or(command.logical_time, |time| time.max(command.logical_time));
    let retained_until = match crate::ttl::checked_session_deadline(
        logical_time,
        FENCED_TRANSITION_OUTCOME_RETENTION,
    ) {
        Ok(until) if fenced_transition_v2_timestamp_is_in_range(until) => until,
        Ok(_) | Err(_) => {
            advance_fenced_replay_logical_time_sync(tx, storage_identity, logical_time, machine)?;
            return Ok(replay_conflict_response(
                machine,
                raft_log_index,
                if access_is_authorized {
                    StoreError::FencedTransitionRetentionExhausted
                } else {
                    StoreError::TopologyAuthorityRevoked
                },
            ));
        }
    };
    let ordinal = u64::try_from(history.current_bound_count)
        .map_err(|_| invalid_data("fenced transition V2 ordinal is invalid"))?
        .checked_add(1)
        .ok_or_else(|| invalid_data("fenced transition V2 ordinal is exhausted"))?;
    if machine.0 >= i64::MAX as u64 {
        // Keep the terminal sequence behavior identical to V1: establish the
        // normal deterministic transition result in a savepoint, but never
        // let an otherwise successful operation mutate records, leases,
        // fences, restore state, or watches once SQLite's signed sequence
        // horizon has been reached.
        let result = if access_is_authorized {
            let mut savepoint = tx.savepoint().map_err(db_error)?;
            let result = match execute_intent_sync(
                &savepoint,
                storage_identity,
                raft_log_index,
                &command.intent,
                caps,
                logical_time,
            ) {
                Ok(_) => Err(StoreError::FencedTransitionStorageExhausted),
                Err(error) if is_deterministic_intent_rejection(&error) => Err(error),
                Err(_) => {
                    savepoint.rollback().map_err(db_error)?;
                    return Err(state_machine_intent_fault());
                }
            };
            savepoint.rollback().map_err(db_error)?;
            result
        } else {
            Err(StoreError::TopologyAuthorityRevoked)
        };
        let response = SessionConsensusResponse {
            result,
            sequence: machine.0,
            digest: Some(machine.1),
            logical_time: Some(logical_time),
            raft_log_index,
        };
        store_fenced_transition_v2_receipt_sync(
            tx,
            storage_identity,
            request,
            ordinal,
            payload_digest,
            retained_until,
            &response,
        )?;
        advance_fenced_replay_logical_time_sync(tx, storage_identity, logical_time, machine)?;
        return Ok(response);
    }
    let sequence = machine
        .0
        .checked_add(1)
        .ok_or_else(|| invalid_data("session consensus application sequence exhausted"))?;
    let command_digest = command
        .calculate_applied_digest(sequence, machine.1, logical_time)
        .map_err(|_| invalid_data("session consensus command digest failed"))?;
    let (result, replication) = if access_is_authorized {
        let mut savepoint = tx.savepoint().map_err(db_error)?;
        match execute_intent_sync(
            &savepoint,
            storage_identity,
            raft_log_index,
            &command.intent,
            caps,
            logical_time,
        ) {
            Ok((outcome, replication)) => {
                savepoint.commit().map_err(db_error)?;
                (Ok(outcome), replication)
            }
            Err(error) if is_deterministic_intent_rejection(&error) => {
                savepoint.rollback().map_err(db_error)?;
                (Err(error), None)
            }
            Err(_) => {
                savepoint.rollback().map_err(db_error)?;
                return Err(state_machine_intent_fault());
            }
        }
    } else {
        (Err(StoreError::TopologyAuthorityRevoked), None)
    };
    let response = SessionConsensusResponse {
        result,
        sequence,
        digest: Some(command_digest),
        logical_time: Some(logical_time),
        raft_log_index,
    };
    store_fenced_transition_v2_receipt_sync(
        tx,
        storage_identity,
        request,
        ordinal,
        payload_digest,
        retained_until,
        &response,
    )?;
    let changed = tx
        .execute(
            "UPDATE consensus_machine SET application_sequence = ?1, last_digest = ?2, logical_time = ?3 WHERE singleton = 1 AND configuration_epoch = ?4",
            params![
                checked_positive_i64(sequence)?,
                command_digest.as_bytes().as_slice(),
                ops::format_rfc3339_normalized(logical_time),
                epoch_i64(storage_identity)?,
            ],
        )
        .map_err(db_error)?;
    if changed != 1 {
        return Err(invalid_data("session consensus machine state is missing"));
    }
    machine.0 = sequence;
    machine.1 = command_digest;
    machine.2 = Some(logical_time);
    if let Some(replication) = replication {
        machine.3 = machine
            .3
            .checked_add(1)
            .ok_or_else(|| invalid_data("session consensus watch sequence exhausted"))?;
        notifications.push(store_replication_notification_sync(
            tx,
            storage_identity,
            machine.3,
            command.request_id,
            replication,
            logical_time,
        )?);
    }
    Ok(response)
}

fn lease_error_to_store(error: LeaseError) -> StoreError {
    match error {
        LeaseError::AlreadyHeld => StoreError::LeaseHeld,
        LeaseError::Expired => StoreError::LeaseExpired,
        LeaseError::StaleFence => StoreError::StaleFence,
        LeaseError::NotFound => StoreError::NotFound,
        LeaseError::InvalidSessionTtl => StoreError::InvalidSessionTtl,
        LeaseError::OperationOutcomeUnavailable => StoreError::BackendOperationOutcomeUnavailable,
        LeaseError::Backend(_) => {
            StoreError::BackendUnavailable("session consensus lease application failed".into())
        }
    }
}

fn execute_fenced_transition_sync(
    conn: &Connection,
    request: &FencedTransitionRequest,
    caps: &BackendCapabilities,
    logical_time: Timestamp,
) -> Result<(FencedTransitionOutcome, ReplicationOp), StoreError> {
    // Apply reaches this point only after the durable fenced-receipt lookup
    // has missed. Keep all admission-time arithmetic here so an exact replay
    // can return its original result even after its finite record, lease, or
    // a newly calculated retention deadline would no longer be representable.
    request.validate_at(logical_time)?;
    if !caps.monotonic_fencing_token {
        return Err(StoreError::CapabilityNotSupported(
            "atomic_fenced_transition".into(),
        ));
    }
    if matches!(
        request.mutation(),
        FencedTransitionMutation::Create { .. } | FencedTransitionMutation::Update { .. }
    ) && !caps.atomic_compare_and_set
    {
        return Err(StoreError::CapabilityNotSupported(
            "atomic_fenced_transition".into(),
        ));
    }
    if matches!(
        request.mutation(),
        FencedTransitionMutation::RefreshTtl { .. }
    ) && !caps.per_key_ttl
    {
        return Err(StoreError::CapabilityNotSupported(
            "atomic_fenced_transition".into(),
        ));
    }

    if let Some(record) = request.mutation().record() {
        super::validate_consensus_record(record)?;
    }

    // Fence/credential authority is checked before the record expectation.
    // These reads do not prune or otherwise mutate state.
    match request.lease() {
        FencedTransitionLease::Acquire {
            key,
            expected_fence,
            ..
        } => {
            if ops::current_fence_sync(conn, key)? != expected_fence.get() {
                return Err(StoreError::StaleFence);
            }
        }
        FencedTransitionLease::Renew { lease, .. } => {
            ops::validate_fenced_mutation_sync(conn, lease, logical_time)?;
        }
    }

    let current = ops::get_sync(conn, request.lease().key(), logical_time)?;
    match (request.mutation().expected_generation(), current.as_ref()) {
        (None, None) => {}
        (Some(expected), Some(record)) if record.generation == expected => {}
        _ => return Err(StoreError::CasConflict),
    }

    // Renew keeps the existing fence. Every mutation of a live record must
    // therefore prove that the record itself is still owned by that exact
    // guard; a matching generation alone is not authorization. Acquire is
    // different by design: it may take over and replace/delete an old-owner
    // record after minting the observed fence successor.
    if matches!(request.lease(), FencedTransitionLease::Renew { .. })
        && request.mutation().expected_generation().is_some()
    {
        let record = current.as_ref().ok_or(StoreError::CasConflict)?;
        if record.owner != *request.lease().owner()
            || record.fence != request.lease().committed_fence()?
        {
            return Err(StoreError::StaleFence);
        }
    }

    if let FencedTransitionLease::Acquire { key, .. } = request.lease() {
        validate_exact_fenced_acquire_live_lease_sync(conn, key, logical_time)?;
    }

    ensure_session_record_unreserved_sync(conn, request.lease().key())?;

    // All checks above establish the ordinary request semantics first.  Only
    // an otherwise-admissible transition is allowed to observe SQLite's
    // signed-counter horizon, so stale-fence, CAS, and live-lease outcomes
    // retain their established deterministic precedence.
    fenced_transition_counter_admission_sync(conn, request)?;

    let (guard, lease_replication) = match request.lease() {
        FencedTransitionLease::Acquire {
            key,
            owner,
            expected_fence,
            ttl,
        } => {
            let guard = lease::acquire_exact_sync(
                conn,
                key,
                owner.clone(),
                *expected_fence,
                *ttl,
                logical_time,
            )
            .map_err(lease_error_to_store)?;
            let replication = ReplicationOp::AcquireLease {
                key: key.clone(),
                owner: owner.clone(),
                fence: guard.fence(),
                credential_id: guard.credential_id(),
                ttl: *ttl,
                expires_at: guard.expires_at(),
            };
            (guard, replication)
        }
        FencedTransitionLease::Renew {
            lease: existing,
            ttl,
        } => {
            let guard = lease::renew_exact_sync(conn, existing, *ttl, logical_time)
                .map_err(lease_error_to_store)?;
            let replication = ReplicationOp::RenewLease {
                key: guard.key().clone(),
                owner: guard.owner().clone(),
                fence: guard.fence(),
                credential_id: guard.credential_id(),
                ttl: *ttl,
                expires_at: guard.expires_at(),
            };
            (guard, replication)
        }
    };

    let (committed_generation, mutation_result, mutation_replication) = match request.mutation() {
        FencedTransitionMutation::Create { record } => {
            ops::insert_or_replace_record_sync(conn, record)?;
            ops::insert_or_replace_fence_sync(conn, &record.key, record.fence.get())?;
            (
                record.generation,
                FencedTransitionMutationResult::Created,
                ReplicationOp::CompareAndSet {
                    key: record.key.clone(),
                    expected_generation: None,
                    credential_id: guard.credential_id(),
                    guard_expires_at: guard.expires_at(),
                    new_record: record.as_ref().clone(),
                },
            )
        }
        FencedTransitionMutation::Update {
            expected_generation,
            record,
        } => {
            ops::insert_or_replace_record_sync(conn, record)?;
            ops::insert_or_replace_fence_sync(conn, &record.key, record.fence.get())?;
            (
                record.generation,
                FencedTransitionMutationResult::Updated,
                ReplicationOp::CompareAndSet {
                    key: record.key.clone(),
                    expected_generation: Some(*expected_generation),
                    credential_id: guard.credential_id(),
                    guard_expires_at: guard.expires_at(),
                    new_record: record.as_ref().clone(),
                },
            )
        }
        FencedTransitionMutation::Delete {
            expected_generation,
        } => {
            let removed = conn
                    .execute(
                        "DELETE FROM session_records WHERE tenant = ?1 AND nf_kind = ?2 AND key_type = ?3 AND stable_id = ?4",
                        params![
                            guard.key().tenant.as_str(),
                            guard.key().nf_kind.as_str(),
                            guard.key().key_type.to_string(),
                            guard.key().stable_id.as_ref(),
                        ],
                    )
                    .map_err(|_| {
                        StoreError::BackendUnavailable(
                            "session fenced transition persistence failed".into(),
                        )
                    })?;
            if removed != 1 {
                return Err(StoreError::BackendUnavailable(
                    "session fenced transition persistence failed".into(),
                ));
            }
            ops::advance_restore_scan_revision_sync(conn)?;
            ops::insert_or_replace_fence_sync(conn, guard.key(), guard.fence().get())?;
            (
                *expected_generation,
                FencedTransitionMutationResult::Deleted,
                ReplicationOp::DeleteFenced {
                    key: guard.key().clone(),
                    owner: guard.owner().clone(),
                    fence: guard.fence(),
                },
            )
        }
        FencedTransitionMutation::RefreshTtl {
            expected_generation,
            ttl,
        } => {
            let expires_at = crate::ttl::checked_session_deadline(logical_time, *ttl)?;
            let mut record = current.ok_or(StoreError::CasConflict)?;
            record.expires_at = Some(expires_at);
            ops::insert_or_replace_record_sync(conn, &record)?;
            ops::insert_or_replace_fence_sync(conn, guard.key(), guard.fence().get())?;
            (
                *expected_generation,
                FencedTransitionMutationResult::TtlRefreshed { expires_at },
                ReplicationOp::RefreshTtl {
                    key: guard.key().clone(),
                    owner: guard.owner().clone(),
                    fence: guard.fence(),
                    ttl: *ttl,
                    expires_at,
                },
            )
        }
    };

    let outcome =
        FencedTransitionOutcome::new(guard, committed_generation, mutation_result, logical_time)?;
    let replication = ReplicationOp::Batch {
        ops: vec![lease_replication, mutation_replication],
    };
    replication.validate_structure()?;
    Ok((outcome, replication))
}

/// Mirror the exact-acquire live-lease admission before the counter gate.
/// `lease::acquire_exact_sync` performs the authoritative check again before
/// writing; this read-only copy prevents a terminal counter from masking the
/// established `LeaseHeld` result.
fn validate_exact_fenced_acquire_live_lease_sync(
    conn: &Connection,
    key: &crate::model::SessionKey,
    logical_time: Timestamp,
) -> Result<(), StoreError> {
    let lease = conn
        .query_row(
            "SELECT active, guard_expires_at FROM leases WHERE tenant = ?1 AND nf_kind = ?2 AND key_type = ?3 AND stable_id = ?4",
            params![
                key.tenant.as_str(),
                key.nf_kind.as_str(),
                key.key_type.to_string(),
                key.stable_id.as_ref(),
            ],
            |row| Ok((row.get::<_, i32>(0)?, row.get::<_, String>(1)?)),
        )
        .optional()
        .map_err(|_| StoreError::BackendUnavailable("session fenced transition persistence failed".into()))?;
    let Some((active, expires_at)) = lease else {
        return Ok(());
    };
    if active != 0
        && Timestamp::from_str(&expires_at)
            .ok()
            .is_some_and(|expires_at| expires_at > logical_time)
    {
        return Err(StoreError::LeaseHeld);
    }
    if active != 0 && Timestamp::from_str(&expires_at).is_err() {
        return Err(StoreError::BackendUnavailable(
            "session fenced transition persistence failed".into(),
        ));
    }
    Ok(())
}

/// Ensure every counter a successful fenced transition would advance remains
/// representable by SQLite's signed INTEGER storage. This runs after the
/// read-only lease/CAS admission in `execute_fenced_transition_sync` and
/// before its first write, making exhaustion a fixed no-effect result.
fn fenced_transition_counter_admission_sync(
    conn: &Connection,
    request: &FencedTransitionRequest,
) -> Result<(), StoreError> {
    const SQLITE_COUNTER_MAX: u64 = i64::MAX as u64;

    if let Some(record) = request.mutation().record() {
        if record.generation.get() > SQLITE_COUNTER_MAX || record.fence.get() > SQLITE_COUNTER_MAX {
            return Err(StoreError::FencedTransitionStorageExhausted);
        }
    }

    if let FencedTransitionLease::Acquire { expected_fence, .. } = request.lease() {
        // Exact acquire issues expected+1 and records a global successor of
        // at least expected+2. Both values must fit SQLite even if the global
        // high-water is already larger (and therefore remains unchanged).
        if expected_fence.get() > SQLITE_COUNTER_MAX.saturating_sub(2) {
            return Err(StoreError::FencedTransitionStorageExhausted);
        }
        let next_fence: i64 = conn
            .query_row(
                "SELECT val FROM lease_globals WHERE key = 'next_fence'",
                [],
                |row| row.get(0),
            )
            .map_err(|_| {
                StoreError::BackendUnavailable(
                    "session fenced transition persistence failed".into(),
                )
            })?;
        if next_fence <= 0 {
            return Err(StoreError::BackendUnavailable(
                "session fenced transition persistence failed".into(),
            ));
        }
        let next_credential_id: i64 = conn
            .query_row(
                "SELECT val FROM lease_globals WHERE key = 'next_credential_id'",
                [],
                |row| row.get(0),
            )
            .map_err(|_| {
                StoreError::BackendUnavailable(
                    "session fenced transition persistence failed".into(),
                )
            })?;
        if next_credential_id <= 0 {
            return Err(StoreError::BackendUnavailable(
                "session fenced transition persistence failed".into(),
            ));
        }
        if next_credential_id as u64 >= SQLITE_COUNTER_MAX {
            return Err(StoreError::FencedTransitionStorageExhausted);
        }
    }

    let (_, revision, _) = ops::read_restore_scan_state_sync(conn)?;
    if revision >= SQLITE_COUNTER_MAX {
        return Err(StoreError::FencedTransitionStorageExhausted);
    }
    let watch_sequence: i64 = conn
        .query_row(
            "SELECT watch_sequence FROM consensus_machine WHERE singleton = 1",
            [],
            |row| row.get(0),
        )
        .map_err(|_| {
            StoreError::BackendUnavailable("session fenced transition persistence failed".into())
        })?;
    if watch_sequence < 0 {
        return Err(StoreError::BackendUnavailable(
            "session fenced transition persistence failed".into(),
        ));
    }
    if watch_sequence as u64 >= SQLITE_COUNTER_MAX {
        return Err(StoreError::FencedTransitionStorageExhausted);
    }
    Ok(())
}

/// Whether a state-machine rejection is a deterministic result of the
/// committed command and previously committed state.
///
/// Backend capability, persistence, serialization, crypto, and restore/log
/// errors describe a node-local fault or corrupt/incompatible state rather than
/// a caller-visible command outcome. Persisting one of those errors would let a
/// faulty replica advance its applied/application state while healthy replicas
/// apply the mutation, permanently diverging the deterministic state machine.
fn is_deterministic_intent_rejection(error: &StoreError) -> bool {
    match error {
        StoreError::NotFound
        | StoreError::StaleFence
        | StoreError::CasConflict
        | StoreError::InvalidKey(_)
        | StoreError::TopologyAuthorityRevoked
        | StoreError::InvalidSessionTtl
        | StoreError::InvalidRecordExpiry
        | StoreError::LeaseHeld
        | StoreError::LeaseExpired
        | StoreError::SessionRecordReserved
        | StoreError::PayloadTooLarge { .. }
        | StoreError::FencedTransitionRequestExpired
        | StoreError::FencedTransitionStorageExhausted => true,
        StoreError::CapabilityNotSupported(_)
        | StoreError::CasIdempotencyConflict
        | StoreError::CasIdempotencyOutcomeUnavailable
        | StoreError::FencedTransitionRequestConflict
        | StoreError::FencedTransitionOutcomeUnknown
        | StoreError::FencedTransitionHistoryFull
        | StoreError::FencedTransitionHistoryEpochRetired
        | StoreError::FencedTransitionHistoryEpochNotActive
        | StoreError::FencedTransitionRetentionExhausted
        | StoreError::BackendOperationOutcomeUnavailable
        | StoreError::BackendUnavailable(_)
        | StoreError::InvalidReplicationSequence
        | StoreError::InvalidReplicationLogRange
        | StoreError::ReplicationLogPageTooLarge { .. }
        | StoreError::ReplicationLogCursorCompacted { .. }
        | StoreError::ReplicationWatchCatchUpRequired
        | StoreError::ReplicationOperationLimitExceeded
        | StoreError::RecordExpiryPreflightLimitExceeded
        | StoreError::Crypto(_)
        | StoreError::Serialization(_)
        | StoreError::InvalidRestoreScanRequest(_)
        | StoreError::InvalidRestoreScanResponse(_)
        | StoreError::RestoreScanPageTooLarge { .. }
        | StoreError::RestoreScanCursorStale
        | StoreError::RestoreScanWorkBudgetExceeded
        | StoreError::RestoreScanResponseTooLarge { .. } => false,
    }
}

fn state_machine_intent_fault() -> io::Error {
    io::Error::other("session consensus state-machine operation failed")
}

#[derive(Debug)]
pub(crate) struct AppliedBatch {
    pub(crate) responses: Vec<SessionConsensusResponse>,
    pub(crate) notifications: Vec<ReplicationEntry>,
}

fn read_machine_sync(
    conn: &Connection,
    identity: SessionConsensusIdentity,
) -> io::Result<(u64, SessionConsensusEntryDigest, Option<Timestamp>, u64)> {
    let (epoch, sequence, digest, logical_time, watch_sequence): (
        i64,
        i64,
        Vec<u8>,
        Option<String>,
        i64,
    ) = conn
        .query_row(
            "SELECT configuration_epoch, application_sequence, last_digest, logical_time, watch_sequence FROM consensus_machine WHERE singleton = 1",
            [],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?, row.get(4)?)),
        )
        .map_err(db_error)?;
    validate_epoch(epoch, identity)?;
    let digest: [u8; 32] = digest
        .try_into()
        .map_err(|_| invalid_data("persisted session consensus digest has invalid length"))?;
    let logical_time = logical_time
        .map(|value| {
            Timestamp::from_str(&value)
                .map_err(|_| invalid_data("persisted session consensus logical time is invalid"))
        })
        .transpose()?;
    Ok((
        checked_u64(sequence)?,
        SessionConsensusEntryDigest::from_bytes(digest),
        logical_time,
        checked_u64(watch_sequence)?,
    ))
}

#[cfg(test)]
pub(crate) fn proposal_state_sync(
    conn: &Connection,
    identity: SessionConsensusIdentity,
) -> io::Result<(u64, SessionConsensusEntryDigest, Option<Timestamp>)> {
    let (sequence, digest, logical_time, _) = read_machine_sync(conn, identity)?;
    Ok((sequence, digest, logical_time))
}

pub(crate) fn logical_time_sync(
    conn: &Connection,
    identity: SessionConsensusIdentity,
) -> io::Result<Option<Timestamp>> {
    read_machine_sync(conn, identity).map(|(_, _, logical_time, _)| logical_time)
}

pub(crate) fn validate_consensus_outcome_records(
    outcome: &SessionMutationOutcome,
) -> Result<(), StoreError> {
    match outcome {
        SessionMutationOutcome::ConsumerRecord(Some(record))
        | SessionMutationOutcome::CompareAndSet(CompareAndSetResult::Conflict {
            current: Some(record),
        }) => super::validate_consensus_record(record),
        SessionMutationOutcome::FencedTransition(outcome) => outcome.validate(),
        SessionMutationOutcome::FencedTransitionV2Batch(outcomes) => {
            validate_fenced_transition_v2_batch_outcomes(outcomes)
        }
        SessionMutationOutcome::RosterAdmission(_) | SessionMutationOutcome::RosterTerminal(_) => {
            Err(StoreError::Serialization(
                "roster outcome reached generic consensus ledger".into(),
            ))
        }
        SessionMutationOutcome::CompareAndSet(_)
        | SessionMutationOutcome::ConsumerRecord(None)
        | SessionMutationOutcome::Lease(_)
        | SessionMutationOutcome::Unit => Ok(()),
    }
}

fn read_outcome_sync(
    conn: &Connection,
    identity: SessionConsensusIdentity,
    request_id: SessionConsensusRequestId,
) -> io::Result<Option<([u8; 32], SessionConsensusResponse)>> {
    let row = conn
        .query_row(
            "SELECT configuration_epoch, payload_digest, response_json FROM consensus_request_outcomes WHERE request_id = ?1",
            [request_id.as_bytes().as_slice()],
            |row| {
                Ok((
                    row.get::<_, i64>(0)?,
                    row.get::<_, Vec<u8>>(1)?,
                    row.get::<_, Vec<u8>>(2)?,
                ))
            },
        )
        .optional()
        .map_err(db_error)?;
    let Some((epoch, digest, response)) = row else {
        return Ok(None);
    };
    validate_epoch(epoch, identity)?;
    let digest = digest.try_into().map_err(|_| {
        invalid_data("persisted session consensus request digest has invalid length")
    })?;
    let response: SessionConsensusResponse = decode_json(&response)?;
    if let Ok(outcome) = &response.result {
        validate_consensus_outcome_records(outcome)
            .map_err(|_| invalid_data("persisted session consensus outcome record is invalid"))?;
    }
    Ok(Some((digest, response)))
}

fn validate_membership_ids(
    membership: &StoredMembership<SessionConsensusNodeId, opc_consensus::engine::EmptyNode>,
) -> io::Result<()> {
    if let Some(log_id) = membership.log_id() {
        validate_log_id(log_id)?;
    }
    for node_id in membership.voter_ids() {
        checked_positive_i64(node_id.get())?;
    }
    for (node_id, _) in membership.nodes() {
        checked_positive_i64(node_id.get())?;
    }
    Ok(())
}

fn store_membership_sync(
    tx: &Transaction<'_>,
    storage_identity: SessionConsensusIdentity,
    membership: &StoredMembership<SessionConsensusNodeId, opc_consensus::engine::EmptyNode>,
) -> io::Result<()> {
    validate_membership_ids(membership)?;
    let scope = read_membership_scope_sync(tx, storage_identity)?;
    let log_index = membership
        .log_id()
        .ok_or_else(|| invalid_data("session consensus membership log identity is missing"))?
        .index;
    validate_membership_for_log(membership, &scope, log_index)?;
    tx.execute(
        "UPDATE consensus_membership SET configuration_epoch = ?1, membership_json = ?2 WHERE singleton = 1",
        params![epoch_i64(storage_identity)?, encode_json(membership)?],
    )
    .map_err(db_error)?;
    Ok(())
}

fn execute_application_intent_sync(
    conn: &Connection,
    intent: &SessionMutationIntent,
    caps: &BackendCapabilities,
    logical_time: Timestamp,
) -> Result<(SessionMutationOutcome, Option<ReplicationOp>), StoreError> {
    match intent {
        SessionMutationIntent::AdvanceLogicalTime
        | SessionMutationIntent::BindConsumerRequest { .. }
        | SessionMutationIntent::ActivateFencedTransitionCapability { .. } => {
            Ok((SessionMutationOutcome::Unit, None))
        }
        SessionMutationIntent::ReadConsumerRecord { key } => {
            let record = ops::get_sync(conn, key, logical_time)?;
            if let Some(record) = &record {
                super::validate_consensus_record(record)?;
            }
            Ok((SessionMutationOutcome::ConsumerRecord(record), None))
        }
        SessionMutationIntent::FencedTransition(request)
        | SessionMutationIntent::ActivateFencedTransition { request, .. } => {
            let (outcome, replication) =
                execute_fenced_transition_sync(conn, request, caps, logical_time)?;
            Ok((
                SessionMutationOutcome::FencedTransition(outcome),
                Some(replication),
            ))
        }
        SessionMutationIntent::FencedTransitionV2(request)
        | SessionMutationIntent::ActivateFencedTransitionV2 { request, .. } => {
            // Do not let the V1 executor bridge bypass V2's profiled logical
            // timestamp range. The response correlation path below performs
            // the same V2 validation against its persisted response time.
            request.validate_at(logical_time)?;
            let request = fenced_transition_v2_as_v1_request(request)?;
            let (outcome, replication) =
                execute_fenced_transition_sync(conn, &request, caps, logical_time)?;
            Ok((
                SessionMutationOutcome::FencedTransition(outcome),
                Some(replication),
            ))
        }
        SessionMutationIntent::CompareAndSet(op) => {
            ensure_session_record_unreserved_sync(conn, &op.key)?;
            if op.new_record.payload.encoding() != SessionPayloadEncoding::EnvelopeV1 {
                return Err(StoreError::Serialization(
                    "session consensus requires a sealed record payload".into(),
                ));
            }
            let result = ops::compare_and_set_sync(conn, op, caps, logical_time)?;
            let replication = matches!(result, CompareAndSetResult::Success).then(|| {
                ReplicationOp::CompareAndSet {
                    key: op.key.clone(),
                    expected_generation: op.expected_generation,
                    credential_id: op.lease.credential_id(),
                    guard_expires_at: op.lease.expires_at(),
                    new_record: op.new_record.clone(),
                }
            });
            Ok((SessionMutationOutcome::CompareAndSet(result), replication))
        }
        SessionMutationIntent::DeleteFenced(guard) => {
            ensure_session_record_unreserved_sync(conn, guard.key())?;
            ops::delete_fenced_sync(conn, guard, caps, logical_time)?;
            Ok((
                SessionMutationOutcome::Unit,
                Some(ReplicationOp::DeleteFenced {
                    key: guard.key().clone(),
                    owner: guard.owner().clone(),
                    fence: guard.fence(),
                }),
            ))
        }
        SessionMutationIntent::RefreshTtl { lease: guard, ttl } => {
            ensure_session_record_unreserved_sync(conn, guard.key())?;
            ops::refresh_ttl_sync(conn, guard, *ttl, caps, logical_time)?;
            let expires_at = crate::ttl::checked_session_deadline(logical_time, *ttl)?;
            Ok((
                SessionMutationOutcome::Unit,
                Some(ReplicationOp::RefreshTtl {
                    key: guard.key().clone(),
                    owner: guard.owner().clone(),
                    fence: guard.fence(),
                    ttl: *ttl,
                    expires_at,
                }),
            ))
        }
        SessionMutationIntent::AcquireLease { key, owner, ttl } => {
            let guard = lease::acquire_sync(conn, key, owner.clone(), *ttl, logical_time)
                .map_err(lease_error_to_store)?;
            Ok((
                SessionMutationOutcome::Lease(guard.clone()),
                Some(ReplicationOp::AcquireLease {
                    key: key.clone(),
                    owner: owner.clone(),
                    fence: guard.fence(),
                    credential_id: guard.credential_id(),
                    ttl: *ttl,
                    expires_at: guard.expires_at(),
                }),
            ))
        }
        SessionMutationIntent::RenewLease { lease: guard, ttl } => {
            let renewed =
                lease::renew_sync(conn, guard, *ttl, logical_time).map_err(lease_error_to_store)?;
            Ok((
                SessionMutationOutcome::Lease(renewed.clone()),
                Some(ReplicationOp::RenewLease {
                    key: guard.key().clone(),
                    owner: guard.owner().clone(),
                    fence: guard.fence(),
                    credential_id: guard.credential_id(),
                    ttl: *ttl,
                    expires_at: renewed.expires_at(),
                }),
            ))
        }
        SessionMutationIntent::ReleaseLease(guard) => {
            lease::release_sync(conn, guard.clone(), logical_time).map_err(lease_error_to_store)?;
            Ok((
                SessionMutationOutcome::Unit,
                Some(ReplicationOp::ReleaseLease {
                    key: guard.key().clone(),
                    owner: guard.owner().clone(),
                    fence: guard.fence(),
                    credential_id: guard.credential_id(),
                }),
            ))
        }
        SessionMutationIntent::FinalizeOperatorRecovery {
            recovery_epoch,
            plan_digest,
            fence_high_water,
            credential_high_water,
        } => match finalize_operator_recovery_sync(
            conn,
            // The identity is validated before this function and all state
            // machine writes use the same fixed configuration epoch.
            read_identity_for_recovery_sync(conn)?,
            *recovery_epoch,
            *plan_digest,
            *fence_high_water,
            *credential_high_water,
        )
        .map_err(|_| {
            StoreError::BackendUnavailable("session consensus recovery application failed".into())
        })? {
            OperatorRecoveryApply::Applied | OperatorRecoveryApply::Idempotent => {
                Ok((SessionMutationOutcome::Unit, None))
            }
            OperatorRecoveryApply::Rejected => Err(StoreError::InvalidKey(
                "operator_recovery_epoch_rejected".into(),
            )),
        },
        SessionMutationIntent::PrepareTopologyTransition { .. }
        | SessionMutationIntent::MarkTopologyLearnersReady { .. }
        | SessionMutationIntent::FenceTopologyAuthority { .. }
        | SessionMutationIntent::AbortTopologyTransition { .. }
        | SessionMutationIntent::FinalizeTopologyTransition { .. }
        | SessionMutationIntent::PreflightFencedTransitionCapability
        | SessionMutationIntent::MaintainFencedTransitionV2History { .. }
        | SessionMutationIntent::FencedTransitionV2Batch(_)
        | SessionMutationIntent::RosterAdmission(_)
        | SessionMutationIntent::RosterTerminal(_)
        | SessionMutationIntent::Authorized { .. } => Err(StoreError::BackendUnavailable(
            "session consensus internal intent reached application executor".into(),
        )),
    }
}

fn membership_mutation_store_error(error: MembershipScopeMutationError) -> StoreError {
    match error {
        MembershipScopeMutationError::InvalidScope
        | MembershipScopeMutationError::ConflictingTransition
        | MembershipScopeMutationError::CompactionRequired
        | MembershipScopeMutationError::TransitionNotQuiescent => {
            StoreError::InvalidKey("topology_transition_rejected".into())
        }
        MembershipScopeMutationError::BackendUnavailable
        | MembershipScopeMutationError::CorruptState => {
            StoreError::BackendUnavailable("session topology state is unavailable".into())
        }
    }
}

fn untouched_initial_membership_scope(
    scope: &MembershipValidationScope,
    storage_identity: SessionConsensusIdentity,
) -> bool {
    let pending_is_only_provisional = scope.pending.as_ref().is_none_or(|pending| {
        pending.transition_start_log_index == 0
            && pending.learners_ready_log_index.is_none()
            && pending.joint_membership_log_index.is_none()
            && pending.uniform_membership_log_index.is_none()
    });
    scope.current_identity == storage_identity
        && scope.application_authority_epoch == storage_identity.configuration_epoch()
        && scope.application_authority_members == scope.current_members
        && scope.history.is_empty()
        && scope.predecessor.is_none()
        && pending_is_only_provisional
        && scope.terminal.is_none()
}

/// Validate the authority envelope for this exact fenced access without
/// executing its lease/record intent. Receipt binding deliberately survives a
/// topology rollover, but a predecessor process must not recover the retained
/// result, conflict state, or ledger terminal after its authority is revoked.
fn fenced_transition_access_is_authorized_sync(
    scope: &MembershipValidationScope,
    storage_identity: SessionConsensusIdentity,
    intent: &SessionMutationIntent,
) -> io::Result<bool> {
    match intent {
        SessionMutationIntent::Authorized {
            origin,
            authority_identity,
            mutation,
        } if matches!(
            mutation.as_ref(),
            SessionMutationIntent::FencedTransition(_)
                | SessionMutationIntent::ActivateFencedTransition { .. }
                | SessionMutationIntent::ActivateFencedTransitionCapability { .. }
                | SessionMutationIntent::FencedTransitionV2(_)
                | SessionMutationIntent::FencedTransitionV2Batch(_)
                | SessionMutationIntent::ActivateFencedTransitionV2 { .. }
        ) =>
        {
            Ok(application_authority_matches(
                scope,
                *origin,
                *authority_identity,
            ))
        }
        SessionMutationIntent::FencedTransition(_)
        | SessionMutationIntent::ActivateFencedTransition { .. }
        | SessionMutationIntent::FencedTransitionV2(_)
        | SessionMutationIntent::FencedTransitionV2Batch(_)
        | SessionMutationIntent::ActivateFencedTransitionV2 { .. } => {
            Ok(untouched_initial_membership_scope(scope, storage_identity))
        }
        SessionMutationIntent::ActivateFencedTransitionCapability { .. } => Err(invalid_data(
            "fenced transition activation lacks an authority envelope",
        )),
        _ => Err(invalid_data(
            "fenced transition authority envelope is invalid",
        )),
    }
}

fn execute_intent_sync(
    conn: &Connection,
    storage_identity: SessionConsensusIdentity,
    log_index: u64,
    intent: &SessionMutationIntent,
    caps: &BackendCapabilities,
    logical_time: Timestamp,
) -> Result<(SessionMutationOutcome, Option<ReplicationOp>), StoreError> {
    match intent {
        SessionMutationIntent::PrepareTopologyTransition {
            transition_id,
            request_digest,
            desired_identity,
            desired_members,
            desired_bindings,
        } => stage_membership_scope_in_tx(
            conn,
            storage_identity,
            *transition_id,
            *request_digest,
            *desired_identity,
            desired_members,
            desired_bindings,
            log_index,
        )
        .map_err(membership_mutation_store_error)
        .map(|_| (SessionMutationOutcome::Unit, None)),
        SessionMutationIntent::MarkTopologyLearnersReady {
            transition_id,
            request_digest,
        } => mark_membership_learners_ready_in_tx(
            conn,
            storage_identity,
            *transition_id,
            *request_digest,
            log_index,
        )
        .map_err(membership_mutation_store_error)
        .map(|_| (SessionMutationOutcome::Unit, None)),
        SessionMutationIntent::FenceTopologyAuthority {
            transition_id,
            request_digest,
        } => fence_application_authority_in_tx(
            conn,
            storage_identity,
            *transition_id,
            *request_digest,
        )
        .map_err(membership_mutation_store_error)
        .map(|_| (SessionMutationOutcome::Unit, None)),
        SessionMutationIntent::AbortTopologyTransition {
            transition_id,
            request_digest,
        } => restore_and_abort_membership_scope_in_tx(
            conn,
            storage_identity,
            *transition_id,
            *request_digest,
            log_index,
        )
        .map_err(membership_mutation_store_error)
        .map(|_| (SessionMutationOutcome::Unit, None)),
        SessionMutationIntent::FinalizeTopologyTransition {
            transition_id,
            request_digest,
        } => finalize_membership_transition_in_tx(
            conn,
            storage_identity,
            *transition_id,
            *request_digest,
            log_index,
        )
        .map_err(membership_mutation_store_error)
        .map(|_| (SessionMutationOutcome::Unit, None)),
        SessionMutationIntent::Authorized {
            origin,
            authority_identity,
            mutation,
        } => {
            let scope = read_membership_scope_sync(conn, storage_identity).map_err(|_| {
                StoreError::BackendUnavailable("session topology authority is unavailable".into())
            })?;
            if matches!(
                mutation.as_ref(),
                SessionMutationIntent::PrepareTopologyTransition { .. }
                    | SessionMutationIntent::MarkTopologyLearnersReady { .. }
                    | SessionMutationIntent::FenceTopologyAuthority { .. }
                    | SessionMutationIntent::AbortTopologyTransition { .. }
                    | SessionMutationIntent::FinalizeTopologyTransition { .. }
                    | SessionMutationIntent::FinalizeOperatorRecovery { .. }
                    | SessionMutationIntent::Authorized { .. }
            ) || !application_authority_matches(&scope, *origin, *authority_identity)
            {
                return Err(StoreError::TopologyAuthorityRevoked);
            }
            execute_application_intent_sync(conn, mutation, caps, logical_time)
        }
        SessionMutationIntent::FinalizeOperatorRecovery { .. } => {
            execute_application_intent_sync(conn, intent, caps, logical_time)
        }
        legacy_application => {
            let scope = read_membership_scope_sync(conn, storage_identity).map_err(|_| {
                StoreError::BackendUnavailable("session topology state is unavailable".into())
            })?;
            if !untouched_initial_membership_scope(&scope, storage_identity) {
                return Err(StoreError::TopologyAuthorityRevoked);
            }
            execute_application_intent_sync(conn, legacy_application, caps, logical_time)
        }
    }
}

fn read_identity_for_recovery_sync(
    conn: &Connection,
) -> Result<SessionConsensusIdentity, StoreError> {
    let (cluster, configuration, epoch): (Vec<u8>, Vec<u8>, i64) = conn
        .query_row(
            "SELECT cluster_id, configuration_id, configuration_epoch FROM consensus_identity WHERE singleton = 1",
            [],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
        )
        .map_err(|_| StoreError::BackendUnavailable(
            "session consensus recovery identity read failed".into(),
        ))?;
    let cluster: [u8; 32] = cluster.try_into().map_err(|_| {
        StoreError::BackendUnavailable("session consensus recovery identity is invalid".into())
    })?;
    let configuration: [u8; 32] = configuration.try_into().map_err(|_| {
        StoreError::BackendUnavailable("session consensus recovery identity is invalid".into())
    })?;
    let epoch = checked_positive_u64(epoch).map_err(|_| {
        StoreError::BackendUnavailable("session consensus recovery identity is invalid".into())
    })?;
    let epoch = crate::consensus::SessionConsensusConfigurationEpoch::new(epoch).map_err(|_| {
        StoreError::BackendUnavailable("session consensus recovery identity is invalid".into())
    })?;
    Ok(SessionConsensusIdentity::new(
        crate::consensus::SessionConsensusClusterId::from_bytes(cluster),
        crate::consensus::SessionConsensusConfigurationId::from_bytes(configuration),
        epoch,
    ))
}

fn store_replication_notification_sync(
    tx: &Transaction<'_>,
    identity: SessionConsensusIdentity,
    watch_sequence: u64,
    request_id: SessionConsensusRequestId,
    op: ReplicationOp,
    logical_time: Timestamp,
) -> io::Result<ReplicationEntry> {
    let entry = ReplicationEntry {
        sequence: watch_sequence,
        tx_id: ReplicationTxId::from_request_bytes(*request_id.as_bytes()),
        op,
        timestamp: logical_time,
    };
    entry
        .validate()
        .map_err(|_| invalid_data("committed session replication notification is invalid"))?;
    tx.execute(
        "INSERT INTO session_replication_log (sequence, tx_id, entry_json, timestamp) VALUES (?1, ?2, ?3, ?4)",
        params![
            checked_positive_i64(entry.sequence)?,
            entry.tx_id.as_str(),
            serde_json::to_string(&entry).map_err(|_| invalid_data("session replication notification encoding failed"))?,
            ops::format_rfc3339_normalized(entry.timestamp),
        ],
    )
    .map_err(db_error)?;
    let epoch = epoch_i64(identity)?;
    let changed = tx
        .execute(
            "UPDATE consensus_machine SET watch_sequence = ?1 WHERE singleton = 1 AND configuration_epoch = ?2",
            params![checked_i64(watch_sequence)?, epoch],
        )
        .map_err(db_error)?;
    if changed != 1 {
        return Err(invalid_data("session consensus machine state is missing"));
    }
    Ok(entry)
}

struct ProtectedRosterCommandApplyInput<'a> {
    identity: SessionConsensusIdentity,
    command: &'a SessionConsensusCommand,
    roster: RosterCommandRef<'a>,
    raft_log_index: u64,
}

fn apply_protected_roster_command_sync(
    tx: &mut Transaction<'_>,
    input: ProtectedRosterCommandApplyInput<'_>,
    machine: &mut (u64, SessionConsensusEntryDigest, Option<Timestamp>, u64),
    notifications: &mut Vec<ReplicationEntry>,
    #[cfg(any(test, feature = "test-control"))] terminal_transaction_remainder_started: &mut Option<
        Instant,
    >,
) -> io::Result<SessionConsensusResponse> {
    let ProtectedRosterCommandApplyInput {
        identity,
        command,
        roster,
        raft_log_index,
    } = input;
    let logical_time = machine.2.map_or(command.logical_time, |last_time| {
        last_time.max(command.logical_time)
    });
    let sequence = machine
        .0
        .checked_add(1)
        .ok_or_else(|| invalid_data("session consensus application sequence exhausted"))?;
    let command_digest = command
        .calculate_applied_digest(sequence, machine.1, logical_time)
        .map_err(|_| invalid_data("session consensus command digest failed"))?;

    // This fence belongs to the outer Raft-apply transaction, deliberately
    // outside the roster rejection savepoint. A canonical admission which
    // deterministically loses a capacity/authority race still publishes format four,
    // whereas a storage failure rolls the whole apply position back.
    match roster {
        RosterCommandRef::Admission(_) => activate_protected_roster_schema_sync(tx)?,
        RosterCommandRef::Terminal(_)
            if protected_roster_layout_in_sync(tx, false)? != ProtectedRosterLayout::Activated =>
        {
            return Err(invalid_data(
                "protected roster terminal precedes activation",
            ));
        }
        RosterCommandRef::Terminal(_) => {}
    }

    let (outcome, roster_replication) = {
        let mut savepoint = tx.savepoint().map_err(db_error)?;
        let applied: Result<
            (SessionMutationOutcome, Option<ReplicationOp>),
            Option<SessionMutationOutcome>,
        > = match roster {
            RosterCommandRef::Admission(roster) => {
                match apply_protected_roster_admission_sync(
                    &savepoint,
                    identity,
                    raft_log_index,
                    logical_time,
                    roster,
                ) {
                    Ok(outcome) => Ok((SessionMutationOutcome::RosterAdmission(outcome), None)),
                    Err(ProtectedRosterCommandApplyError::Rejected(rejection)) => {
                        let outcome = ConsensusRosterAdmissionOutcome::rejected(roster, rejection)
                            .map(SessionMutationOutcome::RosterAdmission)
                            .map_err(|_| {
                                invalid_data("session consensus roster outcome binding is invalid")
                            })?;
                        Err(Some(outcome))
                    }
                    Err(ProtectedRosterCommandApplyError::Fatal) => Err(None),
                }
            }
            RosterCommandRef::Terminal(roster) => {
                match apply_protected_roster_terminal_sync(
                    &savepoint,
                    identity,
                    sequence,
                    raft_log_index,
                    logical_time,
                    roster,
                ) {
                    Ok((outcome, replication)) => {
                        Ok((SessionMutationOutcome::RosterTerminal(outcome), replication))
                    }
                    Err(ProtectedRosterCommandApplyError::Rejected(rejection)) => {
                        let outcome = ConsensusRosterTerminalOutcome::rejected(roster, rejection)
                            .map(SessionMutationOutcome::RosterTerminal)
                            .map_err(|_| {
                                invalid_data("session consensus roster outcome binding is invalid")
                            })?;
                        Err(Some(outcome))
                    }
                    Err(ProtectedRosterCommandApplyError::Fatal) => Err(None),
                }
            }
        };
        match applied {
            Ok((outcome, replication)) => {
                savepoint.commit().map_err(db_error)?;
                (outcome, replication)
            }
            Err(Some(outcome)) => {
                savepoint.rollback().map_err(db_error)?;
                (outcome, None)
            }
            Err(None) => {
                savepoint.rollback().map_err(db_error)?;
                return Err(invalid_data(
                    "session consensus protected roster storage failed",
                ));
            }
        }
    };

    let changed = tx
        .execute(
            "UPDATE consensus_machine SET application_sequence=?1, last_digest=?2, logical_time=?3 WHERE singleton=1 AND configuration_epoch=?4",
            params![
                checked_positive_i64(sequence)?,
                command_digest.as_bytes().as_slice(),
                ops::format_rfc3339_normalized(logical_time),
                epoch_i64(identity)?,
            ],
        )
        .map_err(db_error)?;
    if changed != 1 {
        return Err(invalid_data("session consensus machine state is missing"));
    }
    machine.0 = sequence;
    machine.1 = command_digest;
    machine.2 = Some(logical_time);
    if let Some(replication) = roster_replication {
        machine.3 = machine
            .3
            .checked_add(1)
            .ok_or_else(|| invalid_data("session consensus watch sequence exhausted"))?;
        #[cfg(any(test, feature = "test-control"))]
        let replication_notification_started = Instant::now();
        notifications.push(store_replication_notification_sync(
            tx,
            identity,
            machine.3,
            command.request_id,
            replication,
            logical_time,
        )?);
        #[cfg(any(test, feature = "test-control"))]
        record_protected_roster_terminal_apply_timing(
            &PROTECTED_ROSTER_TERMINAL_APPLY_TIMINGS.replication_notification_count,
            &PROTECTED_ROSTER_TERMINAL_APPLY_TIMINGS.replication_notification_nanos,
            replication_notification_started,
        );
    }
    #[cfg(any(test, feature = "test-control"))]
    if matches!(
        &outcome,
        SessionMutationOutcome::RosterTerminal(ConsensusRosterTerminalOutcome::Committed { .. })
    ) {
        *terminal_transaction_remainder_started = Some(Instant::now());
    }
    Ok(SessionConsensusResponse {
        result: Ok(outcome),
        sequence,
        digest: Some(command_digest),
        logical_time: Some(logical_time),
        raft_log_index,
    })
}

#[cfg(test)]
pub(crate) fn apply_entries_sync(
    conn: &Connection,
    identity: SessionConsensusIdentity,
    caps: &BackendCapabilities,
    entries: Vec<Entry<SessionRaftTypeConfig>>,
) -> io::Result<AppliedBatch> {
    apply_entries_with_authority_sync(
        conn,
        identity,
        caps,
        ConsensusAuthorityProfile::Dynamic,
        &BTreeSet::new(),
        &BTreeMap::new(),
        None,
        entries,
    )
}

#[allow(clippy::too_many_arguments)]
pub(crate) fn apply_entries_with_authority_sync(
    conn: &Connection,
    identity: SessionConsensusIdentity,
    caps: &BackendCapabilities,
    authority_profile: ConsensusAuthorityProfile,
    expected_members: &BTreeSet<SessionConsensusNodeId>,
    expected_bindings: &BTreeMap<SessionConsensusNodeId, SessionTopologyMemberBinding>,
    fixed_placement_policy: Option<PlacementResiliencePolicy>,
    entries: Vec<Entry<SessionRaftTypeConfig>>,
) -> io::Result<AppliedBatch> {
    if entries.is_empty() && authority_profile == ConsensusAuthorityProfile::Dynamic {
        return Ok(AppliedBatch {
            responses: Vec::new(),
            notifications: Vec::new(),
        });
    }
    let mut tx =
        Transaction::new_unchecked(conn, TransactionBehavior::Immediate).map_err(db_error)?;
    let mut last_applied = read_applied_sync(&tx, identity)?;
    let allows_initial_formation = last_applied.is_none()
        && entries.first().is_some_and(|entry| {
            matches!(
                &entry.payload,
                EntryPayload::Membership(membership)
                    if fixed_uniform_membership_matches(membership, expected_members)
            )
        });
    if authority_profile == ConsensusAuthorityProfile::FixedImmutable
        && !fixed_quorum_authority_is_exact_sync(
            &tx,
            identity,
            expected_members,
            expected_bindings,
            fixed_placement_policy.ok_or_else(|| {
                invalid_data("session consensus fixed placement policy is missing")
            })?,
            allows_initial_formation,
        )?
    {
        return Err(invalid_data(
            "session consensus fixed authority is no longer exact",
        ));
    }
    if entries.is_empty() {
        return Ok(AppliedBatch {
            responses: Vec::new(),
            notifications: Vec::new(),
        });
    }
    if authority_profile == ConsensusAuthorityProfile::FixedImmutable {
        for entry in &entries {
            validate_fixed_log_id(&entry.log_id)?;
        }
    }
    let mut machine = read_machine_sync(&tx, identity)?;
    let mut responses = Vec::with_capacity(entries.len());
    let mut notifications = Vec::new();
    #[cfg(any(test, feature = "test-control"))]
    let mut terminal_transaction_remainder_started = None;

    for entry in entries {
        if authority_profile == ConsensusAuthorityProfile::FixedImmutable
            && fixed_profile_entry_changes_topology(&entry, expected_members)
        {
            return Err(invalid_data(
                "fixed session consensus authority rejects topology transitions",
            ));
        }
        // A preceding application command in this same committed batch may
        // have staged, fenced, or aborted a transition. Validate each entry
        // against the scope visible at its exact apply position.
        let scope = read_membership_scope_sync(&tx, identity)?;
        validate_entry_for_apply(&entry, identity, &scope)?;
        let expected_index = last_applied
            .as_ref()
            .map(|log_id| {
                log_id
                    .index
                    .checked_add(1)
                    .ok_or_else(|| invalid_data("session consensus applied index exhausted"))
            })
            .transpose()?
            .unwrap_or(0);
        if entry.log_id.index != expected_index {
            return Err(invalid_data("session consensus apply is not contiguous"));
        }

        // Roster application is a self-contained two-command namespace. It
        // intentionally bypasses `consensus_request_outcomes`: that absorbing
        // ledger cannot represent an admitted-but-unterminalized roster or its
        // exact durable terminal composite. Complete it before the unchanged
        // generic match so rustfmt does not obscure that mature apply path.
        if let EntryPayload::Normal(command) = &entry.payload {
            if let Some(roster) = roster_command(&command.intent) {
                let response = apply_protected_roster_command_sync(
                    &mut tx,
                    ProtectedRosterCommandApplyInput {
                        identity,
                        command,
                        roster,
                        raft_log_index: entry.log_id.index,
                    },
                    &mut machine,
                    &mut notifications,
                    #[cfg(any(test, feature = "test-control"))]
                    &mut terminal_transaction_remainder_started,
                )?;
                // Q1 and Q2 are the two irreducible fresh-path mutations.
                // Never fold unrelated retention work into either command:
                // doing so would violate the frozen profile, couple a valid
                // attach to another tenant's maintenance health, and make the
                // externally observed mutation wider than its exact roster.
                // Ordinary logical-time commands below retain the bounded
                // deterministic maintenance lane.
                save_log_pointer(&tx, "consensus_applied", identity, &entry.log_id)?;
                last_applied = Some(entry.log_id);
                responses.push(response);
                continue;
            }
        }

        let response = match entry.payload {
            EntryPayload::Blank => SessionConsensusResponse {
                result: Ok(SessionMutationOutcome::Unit),
                sequence: 0,
                digest: None,
                logical_time: None,
                raft_log_index: entry.log_id.index,
            },
            EntryPayload::Membership(membership) => {
                let stored = StoredMembership::new(Some(entry.log_id), membership);
                store_membership_sync(&tx, identity, &stored)?;
                record_membership_transition_evidence_in_tx(&tx, identity, &stored)?;
                promote_membership_scope_if_quiescent_in_tx(&tx, identity)
                    .map_err(membership_scope_error)?;
                SessionConsensusResponse {
                    result: Ok(SessionMutationOutcome::Unit),
                    sequence: 0,
                    digest: None,
                    logical_time: None,
                    raft_log_index: entry.log_id.index,
                }
            }
            EntryPayload::Normal(command) => {
                let digest = payload_digest(identity, &command)?;
                if let Some((
                    expected_generation,
                    expected_active_epoch,
                    expected_retired_through,
                    expected_bound_entries,
                )) = fenced_transition_v2_maintenance(&command.intent)
                {
                    // This is duplicated from follower log admission so a
                    // direct state-machine call cannot advance the durable
                    // clock or mutate lifecycle state for a timestamp that
                    // falls outside the fixed V2 profile.
                    if !fenced_transition_v2_timestamp_is_in_range(command.logical_time) {
                        return Err(invalid_data(
                            "fenced transition V2 maintenance logical time is outside the profiled range",
                        ));
                    }
                    if fenced_transition_v2_ledger_layout_sync(&tx)?
                        != FencedTransitionV2LedgerLayout::Activated
                    {
                        advance_fenced_replay_logical_time_sync(
                            &tx,
                            identity,
                            command.logical_time,
                            &mut machine,
                        )?;
                        replay_conflict_response(
                            &machine,
                            entry.log_id.index,
                            StoreError::FencedTransitionHistoryEpochNotActive,
                        )
                    } else {
                        let logical_time = machine
                            .2
                            .map_or(command.logical_time, |time| time.max(command.logical_time));
                        // Maintenance normally commits a Unit response and
                        // therefore increments application_sequence.  Probe
                        // the exact lifecycle CAS before invoking the helper
                        // so SQLite's signed sequence horizon is a typed
                        // replay-style result *before* the helper can retire
                        // an epoch or delete any receipt.  Preserve stale-CAS
                        // precedence: an inexact command still reaches the
                        // helper and returns HistoryEpochNotActive below.
                        let history =
                            read_fenced_transition_v2_history_row_in_sync(&tx, identity, false)?;
                        let matches_exact_lifecycle = history.generation == expected_generation
                            && history.active_epoch == expected_active_epoch
                            && history.retired_through == expected_retired_through
                            && u64::try_from(history.current_bound_count).map_err(|_| {
                                invalid_data("fenced transition V2 maintenance count is invalid")
                            })? == expected_bound_entries;
                        if matches_exact_lifecycle && machine.0 >= i64::MAX as u64 {
                            advance_fenced_replay_logical_time_sync(
                                &tx,
                                identity,
                                logical_time,
                                &mut machine,
                            )?;
                            replay_conflict_response(
                                &machine,
                                entry.log_id.index,
                                StoreError::FencedTransitionStorageExhausted,
                            )
                        } else {
                            let maintenance = maintain_fenced_transition_v2_history_sync(
                                &tx,
                                identity,
                                expected_generation,
                                expected_active_epoch,
                                expected_retired_through,
                                expected_bound_entries,
                                logical_time,
                            )?;
                            if matches!(
                                maintenance,
                                FencedTransitionV2MaintenanceResult::Rejected
                                    | FencedTransitionV2MaintenanceResult::Exhausted
                            ) {
                                advance_fenced_replay_logical_time_sync(
                                    &tx,
                                    identity,
                                    logical_time,
                                    &mut machine,
                                )?;
                                replay_conflict_response(
                                    &machine,
                                    entry.log_id.index,
                                    match maintenance {
                                        FencedTransitionV2MaintenanceResult::Rejected => {
                                            StoreError::FencedTransitionHistoryEpochNotActive
                                        }
                                        FencedTransitionV2MaintenanceResult::Exhausted => {
                                            StoreError::FencedTransitionStorageExhausted
                                        }
                                        FencedTransitionV2MaintenanceResult::Applied
                                        | FencedTransitionV2MaintenanceResult::Noop => {
                                            unreachable!("applied maintenance is handled above")
                                        }
                                    },
                                )
                            } else {
                                // Maintenance changes only the V2 lifecycle.  It has no
                                // application/lease/watch side effect and deliberately
                                // receives no generic outcome-table binding.
                                let sequence = machine.0.checked_add(1).ok_or_else(|| {
                                    invalid_data("session consensus application sequence exhausted")
                                })?;
                                let command_digest = command
                                    .calculate_applied_digest(sequence, machine.1, logical_time)
                                    .map_err(|_| {
                                        invalid_data("session consensus command digest failed")
                                    })?;
                                let changed = tx
                            .execute(
                                "UPDATE consensus_machine SET application_sequence = ?1, last_digest = ?2, logical_time = ?3 WHERE singleton = 1 AND configuration_epoch = ?4",
                                params![
                                    checked_positive_i64(sequence)?,
                                    command_digest.as_bytes().as_slice(),
                                    ops::format_rfc3339_normalized(logical_time),
                                    epoch_i64(identity)?,
                                ],
                            )
                            .map_err(db_error)?;
                                if changed != 1 {
                                    return Err(invalid_data(
                                        "session consensus machine state is missing",
                                    ));
                                }
                                machine.0 = sequence;
                                machine.1 = command_digest;
                                machine.2 = Some(logical_time);
                                SessionConsensusResponse {
                                    result: Ok(SessionMutationOutcome::Unit),
                                    sequence,
                                    digest: Some(command_digest),
                                    logical_time: Some(logical_time),
                                    raft_log_index: entry.log_id.index,
                                }
                            }
                        }
                    }
                } else if fenced_transition_v2_batch(&command.intent).is_some() {
                    apply_fenced_transition_v2_batch_command_sync(
                        &mut tx,
                        identity,
                        &scope,
                        caps,
                        &command,
                        entry.log_id.index,
                        &mut machine,
                        &mut notifications,
                    )?
                } else if fenced_transition_v2_request(&command.intent).is_some() {
                    apply_fenced_transition_v2_command_sync(
                        &mut tx,
                        identity,
                        &scope,
                        caps,
                        &command,
                        digest,
                        entry.log_id.index,
                        &mut machine,
                        &mut notifications,
                    )?
                } else {
                    let is_fenced_transition = fenced_transition_request(&command.intent).is_some();
                    let is_capability_activation = !is_fenced_transition
                        && fenced_transition_activation(&command.intent).is_some();
                    if is_capability_activation {
                        let access_is_authorized = fenced_transition_access_is_authorized_sync(
                            &scope,
                            identity,
                            &command.intent,
                        )?;
                        if access_is_authorized {
                            let (scope_identity, voter_set_digest) =
                                fenced_transition_activation(&command.intent)
                                    .expect("checked capability activation");
                            if scope_identity != scope.current_identity
                                || voter_set_digest
                                    != fenced_transition_voter_set_digest(
                                        scope.current_identity,
                                        &scope.current_members,
                                    )
                            {
                                return Err(invalid_data(
                                    "fenced transition activation scope is stale",
                                ));
                            }
                            // This cluster-scope command has no tenant/session
                            // body. Its generic authenticated outcome and this
                            // certificate must commit in the same transaction.
                            activate_fenced_transition_scope_sync(
                                &tx,
                                identity,
                                scope.current_identity,
                                &scope.current_members,
                            )?;
                        }
                    }
                    if is_fenced_transition {
                        let access_is_authorized = fenced_transition_access_is_authorized_sync(
                            &scope,
                            identity,
                            &command.intent,
                        )?;
                        let receipt_ledger_layout =
                            fenced_transition_receipt_ledger_layout_sync(&tx)?;
                        let preactivation_revoked_no_effect = !access_is_authorized
                            && receipt_ledger_layout
                                == FencedTransitionReceiptLedgerLayout::Prepared;
                        if !preactivation_revoked_no_effect {
                            match fenced_transition_activation(&command.intent) {
                                Some((scope_identity, voter_set_digest))
                                    if access_is_authorized =>
                                {
                                    if scope_identity != scope.current_identity
                                        || voter_set_digest
                                            != fenced_transition_voter_set_digest(
                                                scope.current_identity,
                                                &scope.current_members,
                                            )
                                    {
                                        return Err(invalid_data(
                                            "fenced transition activation scope is stale",
                                        ));
                                    }
                                    // A current, authenticated activation is the
                                    // only path that may publish a certificate.
                                    activate_fenced_transition_scope_sync(
                                        &tx,
                                        identity,
                                        scope.current_identity,
                                        &scope.current_members,
                                    )?;
                                }
                                None if access_is_authorized
                                    && !fenced_transition_activation_matches_scope_sync(
                                        &tx,
                                        identity,
                                        scope.current_identity,
                                        &scope.current_members,
                                    )? =>
                                {
                                    return Err(invalid_data(
                                        "fenced transition lacks an exact activation certificate",
                                    ));
                                }
                                // A revoked envelope cannot publish a certificate
                                // or execute its body. In V2 it may still bind the
                                // deterministic rejection; before V1 activates it
                                // is intentionally left unbound below.
                                Some(_) | None => {}
                            }
                        }
                        if preactivation_revoked_no_effect {
                            advance_fenced_replay_logical_time_sync(
                                &tx,
                                identity,
                                command.logical_time,
                                &mut machine,
                            )?;
                            replay_conflict_response(
                                &machine,
                                entry.log_id.index,
                                StoreError::TopologyAuthorityRevoked,
                            )
                        } else if let Some(replayed) = replay_fenced_transition_receipt_sync(
                            &tx,
                            identity,
                            &command,
                            digest,
                            &machine,
                            entry.log_id.index,
                        )? {
                            // A historical request never advances the application
                            // sequence or produces another record/lease effect,
                            // but its committed admission time still advances the
                            // state-machine clock. Receipt expiry/compaction is
                            // evaluated against that same clock, so the time and
                            // any resulting tombstone must commit atomically.
                            advance_fenced_replay_logical_time_sync(
                                &tx,
                                identity,
                                command.logical_time,
                                &mut machine,
                            )?;
                            if access_is_authorized {
                                replayed
                            } else {
                                replay_conflict_response(
                                    &machine,
                                    entry.log_id.index,
                                    StoreError::TopologyAuthorityRevoked,
                                )
                            }
                        } else if fenced_transition_receipt_count_sync(&tx)?
                            >= FENCED_TRANSITION_MAX_HISTORY_ENTRIES
                        {
                            // The permanent tombstone namespace is absorbing.
                            // This ID was not bound, so the deterministic capacity
                            // rejection must neither execute nor record a receipt.
                            // It follows replay semantics: only logical time and
                            // the unconditional applied pointer advance.
                            advance_fenced_replay_logical_time_sync(
                                &tx,
                                identity,
                                command.logical_time,
                                &mut machine,
                            )?;
                            compact_one_due_fenced_transition_receipt_sync(
                                &tx,
                                machine.2.ok_or_else(|| {
                                    invalid_data(
                                        "session consensus machine logical time is missing",
                                    )
                                })?,
                            )?;
                            replay_conflict_response(
                                &machine,
                                entry.log_id.index,
                                if access_is_authorized {
                                    StoreError::FencedTransitionHistoryFull
                                } else {
                                    StoreError::TopologyAuthorityRevoked
                                },
                            )
                        } else {
                            let logical_time =
                                machine.2.map_or(command.logical_time, |last_time| {
                                    last_time.max(command.logical_time)
                                });
                            match crate::ttl::checked_session_deadline(
                                logical_time,
                                FENCED_TRANSITION_OUTCOME_RETENTION,
                            ) {
                                Err(_) => {
                                    // The exact V1 retention window is no longer
                                    // representable. This is an absorbing global
                                    // no-effect condition for every still-unbound
                                    // ID because committed logical time cannot
                                    // regress. Keep receipt/generic/cap precedence
                                    // above and do not create a request binding.
                                    advance_fenced_replay_logical_time_sync(
                                        &tx,
                                        identity,
                                        logical_time,
                                        &mut machine,
                                    )?;
                                    compact_one_due_fenced_transition_receipt_sync(
                                        &tx,
                                        logical_time,
                                    )?;
                                    replay_conflict_response(
                                        &machine,
                                        entry.log_id.index,
                                        if access_is_authorized {
                                            StoreError::FencedTransitionRetentionExhausted
                                        } else {
                                            StoreError::TopologyAuthorityRevoked
                                        },
                                    )
                                }
                                Ok(retained_until) => {
                                    if machine.0 >= i64::MAX as u64 {
                                        // The receipt itself remains representable at the
                                        // terminal application sequence. Probe the normal
                                        // admission in a savepoint solely to preserve the
                                        // established stale/CAS/lease/authority precedence;
                                        // an otherwise successful transition is converted
                                        // into the fixed exhaustion receipt without any
                                        // lease, record, fence, restore, or watch effect.
                                        let result = {
                                            let mut savepoint = tx.savepoint().map_err(db_error)?;
                                            let result = match execute_intent_sync(
                                                &savepoint,
                                                identity,
                                                entry.log_id.index,
                                                &command.intent,
                                                caps,
                                                logical_time,
                                            ) {
                                                Ok(_) => Err(
                                                    StoreError::FencedTransitionStorageExhausted,
                                                ),
                                                Err(error)
                                                    if is_deterministic_intent_rejection(
                                                        &error,
                                                    ) =>
                                                {
                                                    Err(error)
                                                }
                                                Err(_) => {
                                                    savepoint.rollback().map_err(db_error)?;
                                                    return Err(state_machine_intent_fault());
                                                }
                                            };
                                            savepoint.rollback().map_err(db_error)?;
                                            result
                                        };
                                        let response = SessionConsensusResponse {
                                            result,
                                            sequence: machine.0,
                                            digest: Some(machine.1),
                                            logical_time: Some(logical_time),
                                            raft_log_index: entry.log_id.index,
                                        };
                                        store_fenced_transition_receipt_sync(
                                            &tx,
                                            identity,
                                            command.request_id,
                                            digest,
                                            retained_until,
                                            &response,
                                        )?;
                                        compact_one_due_fenced_transition_receipt_sync(
                                            &tx,
                                            logical_time,
                                        )?;
                                        advance_fenced_replay_logical_time_sync(
                                            &tx,
                                            identity,
                                            logical_time,
                                            &mut machine,
                                        )?;
                                        response
                                    } else {
                                        let sequence =
                                            machine.0.checked_add(1).ok_or_else(|| {
                                                invalid_data(
                                            "session consensus application sequence exhausted",
                                        )
                                            })?;
                                        let command_digest = command
                                            .calculate_applied_digest(
                                                sequence,
                                                machine.1,
                                                logical_time,
                                            )
                                            .map_err(|_| {
                                                invalid_data(
                                                    "session consensus command digest failed",
                                                )
                                            })?;

                                        let (result, replication) = {
                                            let mut savepoint = tx.savepoint().map_err(db_error)?;
                                            match execute_intent_sync(
                                                &savepoint,
                                                identity,
                                                entry.log_id.index,
                                                &command.intent,
                                                caps,
                                                logical_time,
                                            ) {
                                                Ok((outcome, replication)) => {
                                                    savepoint.commit().map_err(db_error)?;
                                                    (Ok(outcome), replication)
                                                }
                                                Err(error)
                                                    if is_deterministic_intent_rejection(
                                                        &error,
                                                    ) =>
                                                {
                                                    savepoint.rollback().map_err(db_error)?;
                                                    (Err(error), None)
                                                }
                                                Err(_) => {
                                                    savepoint.rollback().map_err(db_error)?;
                                                    return Err(state_machine_intent_fault());
                                                }
                                            }
                                        };

                                        let response = SessionConsensusResponse {
                                            result,
                                            sequence,
                                            digest: Some(command_digest),
                                            logical_time: Some(logical_time),
                                            raft_log_index: entry.log_id.index,
                                        };
                                        store_fenced_transition_receipt_sync(
                                            &tx,
                                            identity,
                                            command.request_id,
                                            digest,
                                            retained_until,
                                            &response,
                                        )?;
                                        compact_one_due_fenced_transition_receipt_sync(
                                            &tx,
                                            logical_time,
                                        )?;
                                        let changed = tx
                                    .execute(
                                        "UPDATE consensus_machine SET application_sequence = ?1, last_digest = ?2, logical_time = ?3 WHERE singleton = 1 AND configuration_epoch = ?4",
                                        params![
                                            checked_positive_i64(sequence)?,
                                            command_digest.as_bytes().as_slice(),
                                            ops::format_rfc3339_normalized(logical_time),
                                            epoch_i64(identity)?,
                                        ],
                                    )
                                    .map_err(db_error)?;
                                        if changed != 1 {
                                            return Err(invalid_data(
                                                "session consensus machine state is missing",
                                            ));
                                        }
                                        machine.0 = sequence;
                                        machine.1 = command_digest;
                                        machine.2 = Some(logical_time);
                                        if let Some(replication) = replication {
                                            machine.3 =
                                                machine.3.checked_add(1).ok_or_else(|| {
                                                    invalid_data(
                                                "session consensus watch sequence exhausted",
                                            )
                                                })?;
                                            notifications.push(
                                                store_replication_notification_sync(
                                                    &tx,
                                                    identity,
                                                    machine.3,
                                                    command.request_id,
                                                    replication,
                                                    logical_time,
                                                )?,
                                            );
                                        }
                                        response
                                    }
                                }
                            }
                        }
                    } else if read_fenced_transition_receipt_sync(
                        &tx,
                        identity,
                        command.request_id,
                    )?
                    .is_some()
                    {
                        replay_conflict_response(
                            &machine,
                            entry.log_id.index,
                            StoreError::CasIdempotencyConflict,
                        )
                    } else if let Some((persisted_digest, persisted_response)) =
                        read_outcome_sync(&tx, identity, command.request_id)?
                    {
                        if persisted_digest != digest {
                            // A caller can reuse an opaque durable request ID with
                            // another payload. That must be a closed domain
                            // conflict, never a storage fault that prevents the
                            // replicated log from applying.
                            replay_conflict_response(
                                &machine,
                                entry.log_id.index,
                                StoreError::CasIdempotencyConflict,
                            )
                        } else {
                            persisted_response
                        }
                    } else {
                        let sequence = machine.0.checked_add(1).ok_or_else(|| {
                            invalid_data("session consensus application sequence exhausted")
                        })?;
                        let logical_time = machine.2.map_or(command.logical_time, |last_time| {
                            last_time.max(command.logical_time)
                        });
                        let command_digest = command
                            .calculate_applied_digest(sequence, machine.1, logical_time)
                            .map_err(|_| invalid_data("session consensus command digest failed"))?;

                        let (result, replication) = {
                            let mut savepoint = tx.savepoint().map_err(db_error)?;
                            match execute_intent_sync(
                                &savepoint,
                                identity,
                                entry.log_id.index,
                                &command.intent,
                                caps,
                                logical_time,
                            ) {
                                Ok((outcome, replication)) => {
                                    savepoint.commit().map_err(db_error)?;
                                    (Ok(outcome), replication)
                                }
                                Err(error) if is_deterministic_intent_rejection(&error) => {
                                    savepoint.rollback().map_err(db_error)?;
                                    (Err(error), None)
                                }
                                Err(_) => {
                                    savepoint.rollback().map_err(db_error)?;
                                    return Err(state_machine_intent_fault());
                                }
                            }
                        };

                        let response = SessionConsensusResponse {
                            result,
                            sequence,
                            digest: Some(command_digest),
                            logical_time: Some(logical_time),
                            raft_log_index: entry.log_id.index,
                        };
                        tx.execute(
                        "INSERT INTO consensus_request_outcomes (request_id, configuration_epoch, payload_digest, response_json) VALUES (?1, ?2, ?3, ?4)",
                        params![
                            command.request_id.as_bytes().as_slice(),
                            epoch_i64(identity)?,
                            digest.as_slice(),
                            encode_json(&response)?,
                        ],
                    )
                    .map_err(db_error)?;
                        compact_one_due_fenced_transition_receipt_sync(&tx, logical_time)?;
                        let changed = tx
                        .execute(
                            "UPDATE consensus_machine SET application_sequence = ?1, last_digest = ?2, logical_time = ?3 WHERE singleton = 1 AND configuration_epoch = ?4",
                            params![
                                checked_positive_i64(sequence)?,
                                command_digest.as_bytes().as_slice(),
                                ops::format_rfc3339_normalized(logical_time),
                                epoch_i64(identity)?,
                            ],
                        )
                        .map_err(db_error)?;
                        if changed != 1 {
                            return Err(invalid_data("session consensus machine state is missing"));
                        }
                        machine.0 = sequence;
                        machine.1 = command_digest;
                        machine.2 = Some(logical_time);
                        if let Some(replication) = replication {
                            machine.3 = machine.3.checked_add(1).ok_or_else(|| {
                                invalid_data("session consensus watch sequence exhausted")
                            })?;
                            notifications.push(store_replication_notification_sync(
                                &tx,
                                identity,
                                machine.3,
                                command.request_id,
                                replication,
                                logical_time,
                            )?);
                        }
                        response
                    }
                }
            }
        };

        // Retained protected-roster rows age solely against the replicated
        // logical clock.  Fold one deterministic reclaim turn into every
        // normal command that advances or observes that clock; the helper is
        // an indexed no-op unless an activated roster has an eligible row.
        // This is maintenance within this Raft apply transaction, never a
        // separately proposed command and never a replication/watch event.
        if let Some(logical_time) = response.logical_time {
            maintain_due_protected_roster_reclaim_sync(&tx, identity, logical_time)
                .map_err(|_| invalid_data("protected roster maintenance failed"))?;
        }

        save_log_pointer(&tx, "consensus_applied", identity, &entry.log_id)?;
        last_applied = Some(entry.log_id);
        responses.push(response);
    }

    if authority_profile == ConsensusAuthorityProfile::FixedImmutable
        && !fixed_quorum_authority_is_exact_sync(
            &tx,
            identity,
            expected_members,
            expected_bindings,
            fixed_placement_policy.ok_or_else(|| {
                invalid_data("session consensus fixed placement policy is missing")
            })?,
            false,
        )?
    {
        return Err(invalid_data(
            "session consensus fixed authority changed while applying entries",
        ));
    }

    validate_persisted_membership_sync(&tx, identity)?;
    tx.commit().map_err(db_error)?;
    #[cfg(any(test, feature = "test-control"))]
    if let Some(started) = terminal_transaction_remainder_started {
        record_protected_roster_terminal_apply_timing(
            &PROTECTED_ROSTER_TERMINAL_APPLY_TIMINGS.transaction_remainder_commit_count,
            &PROTECTED_ROSTER_TERMINAL_APPLY_TIMINGS.transaction_remainder_commit_nanos,
            started,
        );
    }
    Ok(AppliedBatch {
        responses,
        notifications,
    })
}

pub(crate) fn fixed_quorum_authority_is_exact_sync(
    conn: &Connection,
    identity: SessionConsensusIdentity,
    expected_members: &BTreeSet<SessionConsensusNodeId>,
    expected_bindings: &BTreeMap<SessionConsensusNodeId, SessionTopologyMemberBinding>,
    expected_placement_policy: PlacementResiliencePolicy,
    allow_pristine_membership: bool,
) -> io::Result<bool> {
    if !matches!(expected_members.len(), 3 | 5)
        || validate_member_bindings(expected_members, expected_bindings).is_err()
    {
        return Ok(false);
    }
    if read_fixed_placement_policy_sync(conn)
        .map_err(|_| invalid_data("session consensus fixed placement policy is invalid"))?
        != Some(expected_placement_policy)
    {
        return Ok(false);
    }
    if read_consensus_authority_profile_sync(conn)
        .map_err(|_| invalid_data("session consensus fixed authority profile is invalid"))?
        != ConsensusAuthorityProfile::FixedImmutable
    {
        return Ok(false);
    }
    if read_storage_identity_sync(conn)
        .map_err(|_| invalid_data("session consensus fixed storage identity is invalid"))?
        != identity
    {
        return Ok(false);
    }
    let scope = read_scope_for_mutation(conn, identity)
        .map_err(|_| invalid_data("session consensus fixed scope is invalid"))?;
    let membership = read_membership_sync(conn, identity)?;
    let applied_membership_is_exact = membership.log_id().is_some()
        && fixed_uniform_membership_matches(membership.membership(), expected_members);
    Ok(scope.current_identity == identity
        && scope.current_members == *expected_members
        && scope.current_bindings == *expected_bindings
        && scope.application_authority_epoch == identity.configuration_epoch()
        && scope.application_authority_members == *expected_members
        && scope.pending.is_none()
        && scope.predecessor.is_none()
        && scope.history.is_empty()
        && scope.terminal_history.is_empty()
        && scope.terminal.is_none()
        && validate_fixed_live_durable_state_sync(conn, identity, expected_members).is_ok()
        && (applied_membership_is_exact
            || (allow_pristine_membership && membership.log_id().is_none())))
}

fn validate_fixed_vote_member(
    vote: &Vote<SessionConsensusNodeId>,
    expected_members: &BTreeSet<SessionConsensusNodeId>,
) -> io::Result<()> {
    if vote
        .leader_id
        .voted_for()
        .is_some_and(|node_id| !expected_members.contains(&node_id))
    {
        return Err(invalid_data(
            "session consensus fixed vote names a nonmember",
        ));
    }
    Ok(())
}

fn validate_fixed_log_id(log_id: &LogId<SessionConsensusNodeId>) -> io::Result<()> {
    // The pinned Openraft `single-term-leader` profile serializes committed
    // leader IDs as a term only. Its `LogId` therefore carries no recoverable
    // node identity to compare here; membership-bearing state and votes retain
    // their node IDs and are checked by the fixed-authority validators.
    validate_log_id(log_id).map(|_| ())
}

fn ensure_log_id_not_after(
    earlier: &LogId<SessionConsensusNodeId>,
    later: &LogId<SessionConsensusNodeId>,
    message: &'static str,
) -> io::Result<()> {
    if earlier.index > later.index {
        return Err(invalid_data(message));
    }
    if earlier.index == later.index && earlier != later {
        return Err(invalid_data(message));
    }
    Ok(())
}

fn validate_fixed_snapshot_metadata(
    meta: &opc_consensus::engine::SnapshotMeta<
        SessionConsensusNodeId,
        opc_consensus::engine::EmptyNode,
    >,
    expected_members: &BTreeSet<SessionConsensusNodeId>,
) -> io::Result<()> {
    if let Some(last_log_id) = meta.last_log_id.as_ref() {
        validate_fixed_log_id(last_log_id)?;
    }
    if is_pristine_membership(&meta.last_membership) {
        if meta.last_log_id.is_some() {
            return Err(invalid_data(
                "session consensus fixed snapshot has pristine membership after a log",
            ));
        }
        return Ok(());
    }
    validate_uniform_membership(&meta.last_membership, expected_members)?;
    let membership_log_id = meta.last_membership.log_id().ok_or_else(|| {
        invalid_data("session consensus fixed snapshot membership log identity is missing")
    })?;
    validate_fixed_log_id(&membership_log_id)?;
    let last_log_id = meta.last_log_id.as_ref().ok_or_else(|| {
        invalid_data("session consensus fixed snapshot membership is beyond its last log")
    })?;
    ensure_log_id_not_after(
        &membership_log_id,
        last_log_id,
        "session consensus fixed snapshot membership is beyond its last log",
    )
}

fn validate_fixed_live_durable_state_sync(
    conn: &Connection,
    identity: SessionConsensusIdentity,
    expected_members: &BTreeSet<SessionConsensusNodeId>,
) -> io::Result<()> {
    if let Some(vote) = read_vote_sync(conn, identity)? {
        validate_fixed_vote_member(&vote, expected_members)?;
    }

    let committed = read_committed_sync(conn, identity)?;
    let purged = read_purged_sync(conn, identity)?;
    let applied = read_applied_sync(conn, identity)?;
    for log_id in [&committed, &purged, &applied].into_iter().flatten() {
        validate_fixed_log_id(log_id)?;
    }
    match (&purged, &applied) {
        (Some(purged), Some(applied)) => ensure_log_id_not_after(
            purged,
            applied,
            "session consensus fixed purged pointer is beyond applied state",
        )?,
        (Some(_), None) => {
            return Err(invalid_data(
                "session consensus fixed purged pointer lacks applied state",
            ));
        }
        (None, _) => {}
    }

    let membership = read_membership_sync(conn, identity)?;
    if !is_pristine_membership(&membership) {
        validate_uniform_membership(&membership, expected_members)?;
        let membership_log_id = membership.log_id().ok_or_else(|| {
            invalid_data("session consensus fixed membership log identity is missing")
        })?;
        validate_fixed_log_id(&membership_log_id)?;
        let applied = applied.as_ref().ok_or_else(|| {
            invalid_data("session consensus fixed membership is beyond applied state")
        })?;
        ensure_log_id_not_after(
            &membership_log_id,
            applied,
            "session consensus fixed membership is beyond applied state",
        )?;
    } else if applied.is_some() {
        return Err(invalid_data(
            "session consensus fixed applied state has pristine membership",
        ));
    }

    if let Some((meta, _, _, _)) = read_current_snapshot_sync(conn, identity)? {
        validate_fixed_snapshot_metadata(&meta, expected_members)?;
        match (meta.last_log_id.as_ref(), applied.as_ref()) {
            (Some(snapshot), Some(applied)) => ensure_log_id_not_after(
                snapshot,
                applied,
                "session consensus fixed snapshot is beyond applied state",
            )?,
            (Some(_), None) => {
                return Err(invalid_data(
                    "session consensus fixed snapshot is beyond applied state",
                ));
            }
            (None, _) => {}
        }
    }

    Ok(())
}

/// Deeply validate retained fixed-quorum state at startup/reopen. Live engine
/// admission uses [`validate_fixed_live_durable_state_sync`] so authenticated
/// heartbeats and ordinary writes remain bounded independently of retained log
/// length. Incoming entries are validated before their individual raw writes.
fn validate_fixed_durable_state_sync(
    conn: &Connection,
    identity: SessionConsensusIdentity,
    expected_members: &BTreeSet<SessionConsensusNodeId>,
) -> io::Result<()> {
    validate_fixed_live_durable_state_sync(conn, identity, expected_members)?;
    let floor = read_purged_sync(conn, identity)?
        .map(|log| checked_i64(log.index))
        .transpose()?
        .unwrap_or(-1);
    let mut statement = conn
        .prepare(
            "SELECT configuration_epoch, term, log_index, entry_json FROM consensus_log WHERE log_index > ?1 ORDER BY log_index ASC",
        )
        .map_err(db_error)?;
    let mut rows = statement.query([floor]).map_err(db_error)?;
    let mut expected = if floor < 0 {
        0
    } else {
        u64::try_from(floor)
            .map_err(|_| invalid_data("session consensus fixed retained log index is invalid"))?
            .checked_add(1)
            .ok_or_else(|| {
                invalid_data("session consensus fixed retained log index is exhausted")
            })?
    };
    while let Some(row) = rows.next().map_err(db_error)? {
        let epoch: i64 = row.get(0).map_err(db_error)?;
        let term: i64 = row.get(1).map_err(db_error)?;
        let index: i64 = row.get(2).map_err(db_error)?;
        let encoded: Vec<u8> = row.get(3).map_err(db_error)?;
        validate_epoch(epoch, identity)?;
        let entry: Entry<SessionRaftTypeConfig> = decode_json(&encoded)?;
        validate_fixed_log_id(&entry.log_id)?;
        if let EntryPayload::Normal(command) = &entry.payload {
            validate_command_for_log(command, identity)?;
        }
        if checked_u64(term)? != entry.log_id.leader_id.term
            || checked_u64(index)? != entry.log_id.index
            || fixed_profile_entry_changes_topology(&entry, expected_members)
        {
            return Err(invalid_data("session consensus fixed log entry is invalid"));
        }
        if entry.log_id.index != expected {
            return Err(invalid_data(
                "session consensus fixed retained log contains a hole",
            ));
        }
        expected = expected.checked_add(1).ok_or_else(|| {
            invalid_data("session consensus fixed retained log index is exhausted")
        })?;
    }
    Ok(())
}

fn fixed_profile_entry_changes_topology(
    entry: &Entry<SessionRaftTypeConfig>,
    expected_members: &BTreeSet<SessionConsensusNodeId>,
) -> bool {
    match &entry.payload {
        EntryPayload::Membership(membership) => {
            !fixed_uniform_membership_matches(membership, expected_members)
        }
        EntryPayload::Normal(command) => fixed_profile_intent_changes_topology(&command.intent),
        EntryPayload::Blank => false,
    }
}

fn fixed_profile_intent_changes_topology(intent: &SessionMutationIntent) -> bool {
    match intent {
        SessionMutationIntent::PrepareTopologyTransition { .. }
        | SessionMutationIntent::MarkTopologyLearnersReady { .. }
        | SessionMutationIntent::FenceTopologyAuthority { .. }
        | SessionMutationIntent::AbortTopologyTransition { .. }
        | SessionMutationIntent::FinalizeTopologyTransition { .. } => true,
        SessionMutationIntent::Authorized { mutation, .. } => {
            fixed_profile_intent_changes_topology(mutation)
        }
        _ => false,
    }
}

/// Revalidate fixed-quorum authority inside a raw Openraft durable access.
///
/// The pristine exception is limited to the initial formation interval:
/// `read_membership_sync` rejects a pristine membership once any application
/// state exists, while the scope/profile checks bind that interval to the
/// configured immutable quorum.
fn validate_durable_authority_for_raw_access(
    conn: &Connection,
    identity: SessionConsensusIdentity,
    authority_profile: ConsensusAuthorityProfile,
    expected_members: &BTreeSet<SessionConsensusNodeId>,
    expected_bindings: &BTreeMap<SessionConsensusNodeId, SessionTopologyMemberBinding>,
    fixed_placement_policy: Option<PlacementResiliencePolicy>,
) -> io::Result<()> {
    if authority_profile == ConsensusAuthorityProfile::FixedImmutable
        && !fixed_quorum_authority_is_exact_sync(
            conn,
            identity,
            expected_members,
            expected_bindings,
            fixed_placement_policy.ok_or_else(|| {
                invalid_data("session consensus fixed placement policy is missing")
            })?,
            true,
        )?
    {
        return Err(invalid_data(
            "session consensus fixed authority is no longer exact",
        ));
    }
    Ok(())
}

/// Admit one raw Openraft metadata read against an exact fixed durable head.
///
/// Fixed stores acquire a SQLite read transaction before checking the durable
/// authority tuple, then perform the caller's entire read through that same
/// snapshot. This prevents a persisted profile, placement-policy, identity,
/// binding, scope, or applied-membership drift from racing between admission
/// and return. Dynamic stores retain their existing read path unchanged.
pub(crate) fn with_durable_authority_raw_read_sync<T>(
    conn: &Connection,
    identity: SessionConsensusIdentity,
    authority_profile: ConsensusAuthorityProfile,
    expected_members: &BTreeSet<SessionConsensusNodeId>,
    expected_bindings: &BTreeMap<SessionConsensusNodeId, SessionTopologyMemberBinding>,
    fixed_placement_policy: Option<PlacementResiliencePolicy>,
    read: impl FnOnce(&Connection) -> io::Result<T>,
) -> io::Result<T> {
    if authority_profile == ConsensusAuthorityProfile::Dynamic {
        return read(conn);
    }

    let tx = Transaction::new_unchecked(conn, TransactionBehavior::Deferred).map_err(db_error)?;
    validate_durable_authority_for_raw_access(
        &tx,
        identity,
        authority_profile,
        expected_members,
        expected_bindings,
        fixed_placement_policy,
    )?;
    let value = read(&tx)?;
    tx.commit().map_err(db_error)?;
    Ok(value)
}

fn fixed_uniform_membership_matches(
    membership: &Membership<SessionConsensusNodeId, opc_consensus::engine::EmptyNode>,
    expected_members: &BTreeSet<SessionConsensusNodeId>,
) -> bool {
    let nodes = membership
        .nodes()
        .map(|(node_id, _)| *node_id)
        .collect::<BTreeSet<_>>();
    membership.get_joint_config().len() == 1
        && membership.get_joint_config().first() == Some(expected_members)
        && membership.learner_ids().next().is_none()
        && nodes == *expected_members
}

pub(crate) fn validate_sealed_state_sync(conn: &Connection) -> io::Result<()> {
    let invalid_stable_id = conn
        .query_row(
            r#"
            SELECT EXISTS(
                SELECT 1 FROM session_records
                WHERE typeof(stable_id) != 'blob'
                   OR length(stable_id) NOT BETWEEN 1 AND 64
            )
            "#,
            [],
            |row| row.get::<_, bool>(0),
        )
        .map_err(db_error)?;
    if invalid_stable_id {
        return Err(invalid_data(
            "session consensus snapshot stable identifier is invalid",
        ));
    }

    let mut record_stmt = conn
        .prepare(
            r#"
            SELECT tenant, nf_kind, key_type, stable_id, generation, owner,
                   fence, state_class, state_type, expires_at, payload, encoding
            FROM session_records
            "#,
        )
        .map_err(db_error)?;
    let records = record_stmt
        .query_map([], |row| {
            Ok((
                row.get::<_, String>(0)?,
                row.get::<_, String>(1)?,
                row.get::<_, String>(2)?,
                row.get::<_, Vec<u8>>(3)?,
                row.get::<_, i64>(4)?,
                row.get::<_, String>(5)?,
                row.get::<_, i64>(6)?,
                row.get::<_, String>(7)?,
                row.get::<_, String>(8)?,
                row.get::<_, Option<String>>(9)?,
                row.get::<_, Vec<u8>>(10)?,
                row.get::<_, i64>(11)?,
            ))
        })
        .map_err(db_error)?;
    for row in records {
        let (
            tenant,
            nf_kind,
            key_type,
            stable_id,
            generation,
            owner,
            fence,
            state_class,
            state_type,
            expires_at,
            payload,
            encoding,
        ) = row.map_err(db_error)?;
        let record = ops::stored_record_from_row(
            tenant,
            nf_kind,
            key_type,
            stable_id,
            generation,
            owner,
            fence,
            state_class,
            state_type,
            expires_at,
            payload,
            encoding,
        )
        .map_err(|_| invalid_data("session consensus snapshot record is invalid"))?;
        super::validate_consensus_record(&record).map_err(|error| match error {
            StoreError::PayloadTooLarge { .. } => invalid_data(
                "session consensus snapshot record exceeds the consensus payload limit",
            ),
            StoreError::Crypto(_)
                if record.payload.encoding() != SessionPayloadEncoding::EnvelopeV1 =>
            {
                invalid_data("session consensus snapshot contains an unsealed record payload")
            }
            _ => invalid_data("session consensus snapshot envelope is invalid"),
        })?;
    }

    validate_lease_state_sync(conn)?;

    let mut stmt = conn
        .prepare(
            r#"
            SELECT sequence,
                   CASE
                       WHEN typeof(tx_id) = 'text'
                        AND length(CAST(tx_id AS BLOB)) BETWEEN ?1 AND ?2
                       THEN tx_id
                   END,
                   entry_json
            FROM session_replication_log
            ORDER BY sequence ASC
            "#,
        )
        .map_err(db_error)?;
    let rows = stmt
        .query_map(
            params![REPLICATION_TX_ID_MIN_BYTES, REPLICATION_TX_ID_MAX_BYTES],
            |row| {
                Ok((
                    row.get::<_, i64>(0)?,
                    row.get::<_, Option<String>>(1)?,
                    row.get::<_, String>(2)?,
                ))
            },
        )
        .map_err(db_error)?;
    let mut expected = read_watch_cursor_invalidation_floor_sync(conn)?
        .checked_add(1)
        .ok_or_else(|| invalid_data("session replication sequence exhausted"))?;
    for row in rows {
        let (stored_sequence, stored_tx_id, encoded) = row.map_err(db_error)?;
        let stored_sequence = checked_u64(stored_sequence)?;
        let stored_tx_id: ReplicationTxId = stored_tx_id
            .ok_or_else(|| invalid_data("persisted session replication transaction ID is invalid"))?
            .try_into()
            .map_err(|_| invalid_data("persisted session replication transaction ID is invalid"))?;
        let entry: ReplicationEntry = serde_json::from_str(&encoded)
            .map_err(|_| invalid_data("persisted session replication entry is invalid"))?;
        if stored_sequence != expected || entry.sequence != stored_sequence {
            return Err(invalid_data(
                "persisted session replication log is not contiguous",
            ));
        }
        if entry.tx_id != stored_tx_id {
            return Err(invalid_data(
                "persisted session replication transaction ID is inconsistent",
            ));
        }
        entry
            .validate()
            .map_err(|_| invalid_data("persisted session replication entry is invalid"))?;
        validate_sealed_replication_op(&entry.op)?;
        expected = expected
            .checked_add(1)
            .ok_or_else(|| invalid_data("session replication sequence exhausted"))?;
    }
    let observed_head = expected
        .checked_sub(1)
        .ok_or_else(|| invalid_data("session replication sequence underflow"))?;
    if table_exists(conn, "consensus_machine").map_err(db_error)? {
        let watch_sequence: i64 = conn
            .query_row(
                "SELECT watch_sequence FROM consensus_machine WHERE singleton = 1",
                [],
                |row| row.get(0),
            )
            .map_err(db_error)?;
        if checked_u64(watch_sequence)? != observed_head {
            return Err(invalid_data(
                "session replication cursor does not match the persisted log",
            ));
        }
    }
    Ok(())
}

pub(crate) fn validate_lease_state_sync(conn: &Connection) -> io::Result<()> {
    let invalid_lease_state = || invalid_data("session consensus snapshot lease state is invalid");
    let mut maximum_fence = 0_u64;
    let mut maximum_credential = 0_u64;

    let mut lease_stmt = conn
        .prepare(
            r#"
            SELECT tenant, nf_kind, key_type, stable_id, active, credential_id,
                   owner, fence, acquired_at, expires_at_unix_ms, guard_expires_at
            FROM leases
            "#,
        )
        .map_err(db_error)?;
    let leases = lease_stmt
        .query_map([], |row| {
            Ok((
                row.get::<_, String>(0)?,
                row.get::<_, String>(1)?,
                row.get::<_, String>(2)?,
                row.get::<_, Vec<u8>>(3)?,
                row.get::<_, i64>(4)?,
                row.get::<_, i64>(5)?,
                row.get::<_, String>(6)?,
                row.get::<_, i64>(7)?,
                row.get::<_, Option<String>>(8)?,
                row.get::<_, i64>(9)?,
                row.get::<_, String>(10)?,
            ))
        })
        .map_err(db_error)?;
    for row in leases {
        let (
            tenant,
            nf_kind,
            key_type,
            stable_id,
            active,
            credential,
            owner,
            fence,
            acquired_at,
            expires_at_unix_ms,
            guard_expires_at,
        ) = row.map_err(db_error)?;
        ops::persisted_session_key(tenant, nf_kind, key_type, stable_id)
            .map_err(|_| invalid_lease_state())?;
        if !matches!(active, 0 | 1) {
            return Err(invalid_lease_state());
        }
        let credential = checked_positive_u64(credential).map_err(|_| invalid_lease_state())?;
        let fence = checked_positive_u64(fence).map_err(|_| invalid_lease_state())?;
        ops::persisted_owner_id(owner).map_err(|_| invalid_lease_state())?;
        let guard_expires_at_text = guard_expires_at;
        let guard_expires_at =
            Timestamp::from_str(&guard_expires_at_text).map_err(|_| invalid_lease_state())?;
        if ops::format_rfc3339_normalized(guard_expires_at) != guard_expires_at_text {
            return Err(invalid_lease_state());
        }
        // `NULL` is the bounded marker for rows migrated from the pre-V1
        // schema. They remain recoverable, but no V1 guard operation accepts
        // them because it cannot prove the serialized acquisition timestamp.
        if acquired_at.is_some_and(|acquired_at| {
            ops::persisted_normalized_timestamp(Some(acquired_at))
                .is_none_or(|acquired_at| acquired_at > guard_expires_at)
        }) {
            return Err(invalid_lease_state());
        }
        let guard_expires_at_unix_ms =
            ops::timestamp_unix_millis(guard_expires_at).map_err(|_| invalid_lease_state())?;
        if (active == 1 && expires_at_unix_ms != guard_expires_at_unix_ms)
            || (active == 0 && expires_at_unix_ms < guard_expires_at_unix_ms)
        {
            return Err(invalid_lease_state());
        }
        maximum_fence = maximum_fence.max(fence);
        maximum_credential = maximum_credential.max(credential);
    }

    let mut fence_stmt = conn
        .prepare("SELECT tenant, nf_kind, key_type, stable_id, fence FROM key_fences")
        .map_err(db_error)?;
    let fences = fence_stmt
        .query_map([], |row| {
            Ok((
                row.get::<_, String>(0)?,
                row.get::<_, String>(1)?,
                row.get::<_, String>(2)?,
                row.get::<_, Vec<u8>>(3)?,
                row.get::<_, i64>(4)?,
            ))
        })
        .map_err(db_error)?;
    for row in fences {
        let (tenant, nf_kind, key_type, stable_id, fence) = row.map_err(db_error)?;
        ops::persisted_session_key(tenant, nf_kind, key_type, stable_id)
            .map_err(|_| invalid_lease_state())?;
        maximum_fence =
            maximum_fence.max(checked_positive_u64(fence).map_err(|_| invalid_lease_state())?);
    }

    let stale_or_missing_fence = conn
        .query_row(
            r#"
            SELECT EXISTS(
                SELECT 1
                FROM session_records AS record
                LEFT JOIN key_fences AS fence
                  ON fence.tenant = record.tenant
                 AND fence.nf_kind = record.nf_kind
                 AND fence.key_type = record.key_type
                 AND fence.stable_id = record.stable_id
                WHERE fence.fence IS NULL OR fence.fence < record.fence
                UNION ALL
                SELECT 1
                FROM leases AS lease
                LEFT JOIN key_fences AS fence
                  ON fence.tenant = lease.tenant
                 AND fence.nf_kind = lease.nf_kind
                 AND fence.key_type = lease.key_type
                 AND fence.stable_id = lease.stable_id
                WHERE fence.fence IS NULL OR fence.fence != lease.fence
                UNION ALL
                SELECT 1
                FROM session_records AS record
                JOIN leases AS lease
                  ON lease.tenant = record.tenant
                 AND lease.nf_kind = record.nf_kind
                 AND lease.key_type = record.key_type
                 AND lease.stable_id = record.stable_id
                 AND lease.fence = record.fence
                WHERE record.owner != lease.owner
            )
            "#,
            [],
            |row| row.get::<_, bool>(0),
        )
        .map_err(db_error)?;
    if stale_or_missing_fence {
        return Err(invalid_lease_state());
    }

    let mut next_fence = None;
    let mut next_credential = None;
    let mut globals_stmt = conn
        .prepare("SELECT key, val FROM lease_globals ORDER BY key")
        .map_err(db_error)?;
    let globals = globals_stmt
        .query_map([], |row| {
            Ok((row.get::<_, String>(0)?, row.get::<_, i64>(1)?))
        })
        .map_err(db_error)?;
    for row in globals {
        let (key, value) = row.map_err(db_error)?;
        let value = checked_positive_u64(value).map_err(|_| invalid_lease_state())?;
        let slot = match key.as_str() {
            "next_fence" => &mut next_fence,
            "next_credential_id" => &mut next_credential,
            _ => return Err(invalid_lease_state()),
        };
        if slot.replace(value).is_some() {
            return Err(invalid_lease_state());
        }
    }
    if next_fence.is_none_or(|next| next <= maximum_fence)
        || next_credential.is_none_or(|next| next <= maximum_credential)
    {
        return Err(invalid_lease_state());
    }
    Ok(())
}

pub(crate) fn validate_sealed_replication_op(root: &ReplicationOp) -> io::Result<()> {
    super::replication::validate_replication_payloads(
        root,
        super::SQLITE_CONSENSUS_MAX_VALUE_BYTES,
    )
    .map_err(|_| invalid_data("session replication log violates consensus admission"))?;
    let mut pending = vec![root];
    let mut visited = 0_usize;
    while let Some(op) = pending.pop() {
        visited = visited
            .checked_add(1)
            .ok_or_else(|| invalid_data("session replication operation count overflow"))?;
        if visited > crate::backend::MAX_REPLICATION_OPERATIONS_PER_ENTRY {
            return Err(invalid_data("session replication operation limit exceeded"));
        }
        match op {
            ReplicationOp::CompareAndSet { new_record, .. } => {
                super::validate_consensus_record(new_record).map_err(|_| {
                    invalid_data("session replication log contains an invalid envelope")
                })?;
            }
            ReplicationOp::Batch { ops } => pending.extend(ops),
            _ => {}
        }
    }
    Ok(())
}

#[allow(dead_code)]
pub(crate) fn build_snapshot_database_sync(
    conn: &Connection,
    identity: SessionConsensusIdentity,
    path: &std::path::Path,
) -> io::Result<ConsensusAppliedMembership> {
    build_snapshot_database_with_capture_hook_sync(conn, identity, path, || {})
}

pub(crate) fn build_snapshot_database_with_capture_hook_sync(
    conn: &Connection,
    identity: SessionConsensusIdentity,
    path: &std::path::Path,
    capture_hook: impl FnOnce(),
) -> io::Result<ConsensusAppliedMembership> {
    let tx = Transaction::new_unchecked(conn, TransactionBehavior::Deferred).map_err(db_error)?;
    validate_sealed_state_sync(&tx)?;
    validate_fenced_transition_receipts_sync(&tx, identity)?;
    let destination = create_pinned_snapshot_database(path)?;
    let (snapshot, mut destination) = build_snapshot_database_from_pinned_with_capture_hook_sync(
        &tx,
        identity,
        destination,
        capture_hook,
    )?;
    tx.commit().map_err(db_error)?;
    destination.disarm_cleanup();
    Ok(snapshot)
}

pub(crate) struct SnapshotBuildAuthority<'a> {
    pub(crate) identity: SessionConsensusIdentity,
    pub(crate) profile: ConsensusAuthorityProfile,
    pub(crate) expected_members: &'a BTreeSet<SessionConsensusNodeId>,
    pub(crate) expected_bindings:
        &'a BTreeMap<SessionConsensusNodeId, SessionTopologyMemberBinding>,
    pub(crate) fixed_placement_policy: Option<PlacementResiliencePolicy>,
}

pub(crate) fn build_snapshot_database_pinned_with_authority_sync(
    conn: &Connection,
    authority: SnapshotBuildAuthority<'_>,
    path: &std::path::Path,
) -> io::Result<(
    ConsensusAppliedMembership,
    crate::consensus::snapshot::PinnedSqliteFile,
)> {
    build_snapshot_database_pinned_with_authority_and_capture_hook_sync(
        conn,
        authority,
        path,
        || {},
    )
}

pub(crate) fn build_snapshot_database_pinned_with_authority_and_capture_hook_sync(
    conn: &Connection,
    authority: SnapshotBuildAuthority<'_>,
    path: &std::path::Path,
    capture_hook: impl FnOnce(),
) -> io::Result<(
    ConsensusAppliedMembership,
    crate::consensus::snapshot::PinnedSqliteFile,
)> {
    let tx = Transaction::new_unchecked(conn, TransactionBehavior::Deferred).map_err(db_error)?;
    validate_durable_authority_for_raw_access(
        &tx,
        authority.identity,
        authority.profile,
        authority.expected_members,
        authority.expected_bindings,
        authority.fixed_placement_policy,
    )?;
    validate_sealed_state_sync(&tx)?;
    validate_fenced_transition_receipts_sync(&tx, authority.identity)?;
    // Do not create even an empty snapshot artifact until the durable fixed
    // authority check has succeeded under the source read transaction.
    let destination = create_pinned_snapshot_database(path)?;
    let (snapshot, destination) = build_snapshot_database_from_pinned_with_capture_hook_sync(
        &tx,
        authority.identity,
        destination,
        capture_hook,
    )?;
    tx.commit().map_err(db_error)?;
    Ok((snapshot, destination))
}

#[allow(dead_code)]
pub(crate) fn build_snapshot_database_with_authority_sync(
    conn: &Connection,
    identity: SessionConsensusIdentity,
    authority_profile: ConsensusAuthorityProfile,
    expected_members: &BTreeSet<SessionConsensusNodeId>,
    expected_bindings: &BTreeMap<SessionConsensusNodeId, SessionTopologyMemberBinding>,
    fixed_placement_policy: Option<PlacementResiliencePolicy>,
    path: &std::path::Path,
) -> io::Result<ConsensusAppliedMembership> {
    build_snapshot_database_pinned_with_authority_sync(
        conn,
        SnapshotBuildAuthority {
            identity,
            profile: authority_profile,
            expected_members,
            expected_bindings,
            fixed_placement_policy,
        },
        path,
    )
    .map(|(snapshot, mut destination)| {
        destination.disarm_cleanup();
        snapshot
    })
}

fn build_snapshot_database_from_pinned_with_capture_hook_sync(
    conn: &Connection,
    identity: SessionConsensusIdentity,
    destination: crate::consensus::snapshot::PinnedSqliteFile,
    capture_hook: impl FnOnce(),
) -> io::Result<(
    ConsensusAppliedMembership,
    crate::consensus::snapshot::PinnedSqliteFile,
)> {
    capture_and_finalize_snapshot_database_sync(conn, identity, destination, capture_hook)
}

#[allow(dead_code)]
fn create_pinned_snapshot_database(
    path: &std::path::Path,
) -> io::Result<crate::consensus::snapshot::PinnedSqliteFile> {
    #[cfg(target_os = "linux")]
    {
        use std::os::unix::fs::OpenOptionsExt as _;

        let mut options = OpenOptions::new();
        options
            .create_new(true)
            .read(true)
            .write(true)
            .mode(0o600)
            .custom_flags(libc::O_NOFOLLOW | libc::O_CLOEXEC);
        crate::consensus::snapshot::PinnedSqliteFile::from_new_file(
            options.open(path)?,
            path.to_path_buf(),
        )
    }
    #[cfg(not(target_os = "linux"))]
    {
        let _ = path;
        Err(io::Error::new(
            io::ErrorKind::Unsupported,
            "pinned SQLite snapshot binding requires Linux",
        ))
    }
}

fn refresh_pinned_snapshot_database(
    pinned: crate::consensus::snapshot::PinnedSqliteFile,
) -> io::Result<crate::consensus::snapshot::PinnedSqliteFile> {
    pinned.refresh_identity()
}

#[cfg(target_os = "linux")]
fn pinned_snapshot_uri(
    pinned: &crate::consensus::snapshot::PinnedSqliteFile,
    read_only: bool,
) -> String {
    let mode = if read_only { "ro" } else { "rw" };
    format!(
        "file:/proc/self/fd/{}?mode={mode}&cache=private{}{}",
        pinned.raw_fd(),
        if read_only { "&immutable=1" } else { "" },
        snapshot_test_vfs_uri_parameter(),
    )
}

// A child unit-test process enables the feature-gated safe VFS registration in
// `opc-sqlite-file-control-sys` and flips this local selector.  Production
// never builds or selects that VFS.
#[cfg(all(test, target_os = "linux"))]
fn snapshot_test_vfs_uri_parameter() -> String {
    if SNAPSHOT_TEST_TEMP_PATH_FAILURE_VFS.load(Ordering::Acquire) {
        format!(
            "&vfs={}",
            opc_sqlite_file_control_sys::TEST_TEMP_PATH_FAILURE_VFS_NAME
        )
    } else {
        String::new()
    }
}

#[cfg(all(not(test), target_os = "linux"))]
fn snapshot_test_vfs_uri_parameter() -> String {
    String::new()
}

#[cfg(not(target_os = "linux"))]
fn pinned_snapshot_uri(
    _pinned: &crate::consensus::snapshot::PinnedSqliteFile,
    _read_only: bool,
) -> String {
    String::new()
}

#[cfg(target_os = "linux")]
fn open_pinned_snapshot_database(
    pinned: &crate::consensus::snapshot::PinnedSqliteFile,
) -> io::Result<Connection> {
    pinned.verify_identity()?;
    let uri = pinned_snapshot_uri(pinned, false);
    let destination = Connection::open_with_flags(
        uri,
        OpenFlags::SQLITE_OPEN_READ_WRITE
            | OpenFlags::SQLITE_OPEN_URI
            | OpenFlags::SQLITE_OPEN_NO_MUTEX,
    )
    .map_err(db_error)?;
    destination
        .query_row("PRAGMA schema_version", [], |_| Ok(()))
        .map_err(db_error)?;
    verify_pinned_snapshot_descriptor(pinned, &destination)?;
    Ok(destination)
}

#[cfg(not(target_os = "linux"))]
fn open_pinned_snapshot_database(
    _pinned: &crate::consensus::snapshot::PinnedSqliteFile,
) -> io::Result<Connection> {
    Err(io::Error::new(
        io::ErrorKind::Unsupported,
        "pinned SQLite snapshot binding requires Linux",
    ))
}

#[cfg(target_os = "linux")]
fn verify_pinned_snapshot_descriptor(
    pinned: &crate::consensus::snapshot::PinnedSqliteFile,
    connection: &Connection,
) -> io::Result<()> {
    pinned.verify_identity()?;
    if opc_sqlite_file_control_sys::main_file_has_moved(connection)
        .map_err(|_| invalid_data("SQLite pinned snapshot descriptor is unavailable"))?
    {
        return Err(invalid_data("SQLite pinned snapshot descriptor moved"));
    }
    let actual = crate::consensus::snapshot::PinnedSqliteFile::from_file(
        opc_sqlite_file_control_sys::main_file_descriptor(connection)
            .map_err(|_| invalid_data("SQLite pinned snapshot descriptor is unavailable"))?,
        pinned.path().to_path_buf(),
    )?;
    if actual.identity() != pinned.identity() {
        return Err(invalid_data(
            "SQLite opened a different pinned snapshot descriptor",
        ));
    }
    Ok(())
}

#[cfg(not(target_os = "linux"))]
fn verify_pinned_snapshot_descriptor(
    _pinned: &crate::consensus::snapshot::PinnedSqliteFile,
    _connection: &Connection,
) -> io::Result<()> {
    Err(io::Error::new(
        io::ErrorKind::Unsupported,
        "pinned SQLite snapshot binding requires Linux",
    ))
}

/// Verify SQLite's named attached-database handle against the descriptor that
/// was pinned before `ATTACH`. No process-wide descriptor enumeration is used.
#[cfg(target_os = "linux")]
fn verify_attached_snapshot_descriptor(
    pinned: &crate::consensus::snapshot::PinnedSqliteFile,
    connection: &Connection,
    database: &str,
) -> io::Result<()> {
    pinned.verify_identity()?;
    let actual = crate::consensus::snapshot::PinnedSqliteFile::from_file(
        opc_sqlite_file_control_sys::database_file_descriptor(connection, database)
            .map_err(|_| invalid_data("SQLite attached snapshot descriptor is unavailable"))?,
        pinned.path().to_path_buf(),
    )?;
    if actual.identity() != pinned.identity() {
        return Err(invalid_data(
            "SQLite opened a different attached snapshot descriptor",
        ));
    }
    Ok(())
}

#[cfg(not(target_os = "linux"))]
fn verify_attached_snapshot_descriptor(
    _pinned: &crate::consensus::snapshot::PinnedSqliteFile,
    _connection: &Connection,
    _database: &str,
) -> io::Result<()> {
    Err(io::Error::new(
        io::ErrorKind::Unsupported,
        "pinned SQLite snapshot binding requires Linux",
    ))
}

// A reader can retain WAL frames only while one snapshot is being copied. Its
// fixed envelope is deliberately no larger than the sealed snapshot envelope:
// a corrupt or stalled source cannot retain more than one snapshot's worth of
// additional database state.
const SNAPSHOT_DATABASE_MAX_BYTES: u64 = 64 * 1024 * 1024 * 1024;
const SNAPSHOT_SOURCE_WAL_MAX_BYTES: u64 = SNAPSHOT_DATABASE_MAX_BYTES;
const SNAPSHOT_BACKUP_STEP_PAGES: i32 = 128;
const SNAPSHOT_BACKUP_BUSY_RETRY_LIMIT: usize = 8;
const SNAPSHOT_BACKUP_STEP_LIMIT: usize =
    (SNAPSHOT_DATABASE_MAX_BYTES as usize / 512 / SNAPSHOT_BACKUP_STEP_PAGES as usize) + 1;

/// One VFS-verified, independently pinned SQLite snapshot reader.
///
/// The live consensus connection is never moved into this reader. The reader
/// is admitted only after its SQLite-owned main descriptor is compared with
/// the duplicated descriptor taken from that live connection.
pub(crate) struct SnapshotReadConnection {
    pub(crate) connection: Connection,
    source: crate::consensus::snapshot::PinnedSqliteFile,
    wal: Mutex<Option<crate::consensus::snapshot::PinnedSqliteFile>>,
}

fn verify_snapshot_read_connection(reader: &SnapshotReadConnection) -> io::Result<()> {
    reader.source.verify_identity()?;
    if opc_sqlite_file_control_sys::main_file_has_moved(&reader.connection)
        .map_err(|_| invalid_data("session consensus snapshot reader descriptor is unavailable"))?
    {
        return Err(invalid_data(
            "session consensus snapshot reader main file moved",
        ));
    }
    let actual_source = crate::consensus::snapshot::PinnedSqliteFile::from_file(
        opc_sqlite_file_control_sys::main_file_descriptor(&reader.connection).map_err(|_| {
            invalid_data("session consensus snapshot reader descriptor is unavailable")
        })?,
        reader.source.path().to_path_buf(),
    )?;
    if actual_source.identity() != reader.source.identity() {
        return Err(invalid_data(
            "session consensus snapshot reader source descriptor changed",
        ));
    }
    Ok(())
}

/// Open one read-only, file-backed snapshot reader without sharing the live
/// consensus connection. Its caller must still create exactly one read
/// transaction before admitting a source cut.
pub(crate) fn open_snapshot_read_connection(
    source: &crate::consensus::snapshot::PinnedSqliteFile,
) -> io::Result<SnapshotReadConnection> {
    #[cfg(target_os = "linux")]
    {
        source.verify_identity()?;
        let source = source.try_clone()?;
        let conn = Connection::open_with_flags(
            source.path(),
            OpenFlags::SQLITE_OPEN_READ_ONLY | OpenFlags::SQLITE_OPEN_NO_MUTEX,
        )
        .map_err(db_error)?;
        conn.execute_batch("PRAGMA foreign_keys = ON; PRAGMA query_only = ON;")
            .map_err(db_error)?;
        let foreign_keys: i64 = conn
            .query_row("PRAGMA foreign_keys", [], |row| row.get(0))
            .map_err(db_error)?;
        if foreign_keys != 1 {
            return Err(invalid_data(
                "session consensus snapshot reader has no foreign key enforcement",
            ));
        }
        let journal_mode: String = conn
            .query_row("PRAGMA journal_mode", [], |row| row.get(0))
            .map_err(db_error)?;
        if !journal_mode.eq_ignore_ascii_case("wal") {
            return Err(invalid_data(
                "session consensus snapshot reader requires WAL mode",
            ));
        }
        let reader = SnapshotReadConnection {
            connection: conn,
            source,
            wal: Mutex::new(None),
        };
        verify_snapshot_read_connection(&reader)?;
        Ok(reader)
    }
    #[cfg(not(target_os = "linux"))]
    {
        let _ = source;
        Err(io::Error::new(
            io::ErrorKind::Unsupported,
            "session consensus snapshot readers require Linux",
        ))
    }
}

/// Read the exact applied/membership cut that names one SQLite snapshot.
pub(crate) fn snapshot_applied_membership_sync(
    conn: &Connection,
    identity: SessionConsensusIdentity,
) -> io::Result<ConsensusAppliedMembership> {
    let applied = read_applied_sync(conn, identity)?;
    let membership = read_membership_sync(conn, identity)?;
    validate_membership_ids(&membership)?;
    Ok((applied, membership))
}

/// Begin the sole snapshot-reader transaction and establish its source cut.
pub(crate) fn begin_snapshot_read_sync(
    reader: &SnapshotReadConnection,
    identity: SessionConsensusIdentity,
) -> io::Result<ConsensusAppliedMembership> {
    verify_snapshot_read_connection(reader)?;
    reader
        .connection
        .execute_batch("BEGIN DEFERRED TRANSACTION;")
        .map_err(db_error)?;
    match snapshot_applied_membership_sync(&reader.connection, identity) {
        Ok(cut) => match pin_snapshot_reader_wal(reader) {
            Ok(()) => Ok(cut),
            Err(error) => match reader
                .connection
                .execute_batch("ROLLBACK;")
                .map_err(db_error)
            {
                Ok(()) => Err(error),
                Err(release_error) => Err(release_error),
            },
        },
        Err(error) => match reader
            .connection
            .execute_batch("ROLLBACK;")
            .map_err(db_error)
        {
            Ok(()) => Err(error),
            Err(release_error) => Err(release_error),
        },
    }
}

/// Release a source reader as soon as its backup has completed.
pub(crate) fn release_snapshot_read_sync(reader: &SnapshotReadConnection) -> io::Result<()> {
    // This is deliberately the only operation on the reader at backup exit:
    // source identity checks, paths, destination validation, and offline
    // VACUUM all follow this unconditional transaction release.
    reader
        .connection
        .execute_batch("ROLLBACK;")
        .map_err(db_error)
}

/// Enforce a caller-selected WAL ceiling without identifying the source.
pub(crate) fn enforce_snapshot_source_wal_bound(bytes: u64, maximum: u64) -> io::Result<()> {
    if bytes > maximum {
        return Err(invalid_data(
            "session consensus snapshot source WAL exceeds its fixed bound",
        ));
    }
    Ok(())
}

fn validate_snapshot_reader_wal_bound(
    reader: &SnapshotReadConnection,
    maximum: u64,
) -> io::Result<u64> {
    let bytes = verify_snapshot_reader_wal(reader)?;
    enforce_snapshot_source_wal_bound(bytes, maximum)?;
    Ok(bytes)
}

/// Return the length from the exact WAL descriptor owned by the reader.
/// A replacement or unlink changes the retained descriptor or link count and
/// is rejected. It can never become a path-derived zero sample.
fn verify_snapshot_reader_wal(reader: &SnapshotReadConnection) -> io::Result<u64> {
    let stored = match reader.wal.lock() {
        Ok(stored) => stored,
        Err(poisoned) => poisoned.into_inner(),
    };
    let wal = stored
        .as_ref()
        .ok_or_else(|| invalid_data("session consensus snapshot reader WAL is not pinned"))?;
    #[cfg(target_os = "linux")]
    wal.verify_linked_identity()?;
    let actual_wal = crate::consensus::snapshot::PinnedSqliteFile::from_file(
        opc_sqlite_file_control_sys::main_journal_descriptor(&reader.connection).map_err(|_| {
            invalid_data("session consensus snapshot reader WAL descriptor is unavailable")
        })?,
        wal.path().to_path_buf(),
    )?;
    if actual_wal.identity() != wal.identity() {
        return Err(invalid_data(
            "session consensus snapshot reader WAL descriptor changed",
        ));
    }
    Ok(wal.file().metadata()?.len())
}

fn pin_snapshot_reader_wal(reader: &SnapshotReadConnection) -> io::Result<()> {
    let mut wal_path = reader.source.path().as_os_str().to_os_string();
    wal_path.push("-wal");
    let wal = crate::consensus::snapshot::PinnedSqliteFile::from_file(
        opc_sqlite_file_control_sys::main_journal_descriptor(&reader.connection)
            .map_err(|_| invalid_data("session consensus snapshot reader has no WAL descriptor"))?,
        PathBuf::from(wal_path),
    )?;
    let mut stored = match reader.wal.lock() {
        Ok(stored) => stored,
        Err(poisoned) => poisoned.into_inner(),
    };
    if stored.is_some() {
        return Err(invalid_data(
            "session consensus snapshot reader WAL was already pinned",
        ));
    }
    *stored = Some(wal);
    Ok(())
}

/// Copy a reader-owned SQLite snapshot in bounded steps.
/// The WAL descriptor is verified and bounded before the first step, after
/// each bounded step, and immediately before every continuation. A transient
/// SQLite lock is not retried under a retained reader.
fn backup_snapshot_reader_bounded(
    reader: &SnapshotReadConnection,
    destination: &mut Connection,
    wal_maximum: u64,
) -> io::Result<u64> {
    backup_snapshot_reader_bounded_with_hook_and_step(
        reader,
        destination,
        wal_maximum,
        || {},
        |backup| backup.step(SNAPSHOT_BACKUP_STEP_PAGES),
    )
}

/// The hook is intentionally internal: production supplies a zero-work
/// closure, while deterministic tests inject WAL growth between two bounded
/// steps without scheduling or timing assumptions.
#[cfg(all(test, target_os = "linux"))]
fn backup_snapshot_reader_bounded_with_hook<F>(
    reader: &SnapshotReadConnection,
    destination: &mut Connection,
    wal_maximum: u64,
    after_step: F,
) -> io::Result<u64>
where
    F: FnMut(),
{
    backup_snapshot_reader_bounded_with_hook_and_step(
        reader,
        destination,
        wal_maximum,
        after_step,
        |backup| backup.step(SNAPSHOT_BACKUP_STEP_PAGES),
    )
}

/// Keep step result injection confined to this private test seam: production
/// supplies the exact `Backup::step` call above, while the test can prove a
/// post-step WAL overflow wins over a SQLite step error.
fn backup_snapshot_reader_bounded_with_hook_and_step<F, S>(
    reader: &SnapshotReadConnection,
    destination: &mut Connection,
    wal_maximum: u64,
    mut after_step: F,
    mut step: S,
) -> io::Result<u64>
where
    F: FnMut(),
    S: for<'a, 'b> FnMut(
        &rusqlite::backup::Backup<'a, 'b>,
    ) -> rusqlite::Result<rusqlite::backup::StepResult>,
{
    let mut wal_peak = validate_snapshot_reader_wal_bound(reader, wal_maximum)?;
    let backup =
        rusqlite::backup::Backup::new(&reader.connection, destination).map_err(db_error)?;
    loop {
        verify_snapshot_read_connection(reader)?;
        // This is deliberately repeated for every continuation rather than
        // inferred from the preceding post-step sample.
        let before_step = validate_snapshot_reader_wal_bound(reader, wal_maximum)?;
        wal_peak = wal_peak.max(before_step);
        // Preserve the SQLite result until the reader-owned WAL has been
        // sampled. Even a failed step can have retained or extended WAL frames.
        let result = step(&backup);
        after_step();
        let observed = validate_snapshot_reader_wal_bound(reader, wal_maximum)?;
        wal_peak = wal_peak.max(observed);
        let result = result.map_err(db_error)?;
        match result {
            rusqlite::backup::StepResult::Done => return Ok(wal_peak),
            rusqlite::backup::StepResult::More => {}
            rusqlite::backup::StepResult::Busy | rusqlite::backup::StepResult::Locked => {
                return Err(invalid_data(
                    "session consensus bounded snapshot backup lost its SQLite read lock",
                ));
            }
            _ => {
                return Err(invalid_data(
                    "session consensus bounded snapshot backup returned an unknown result",
                ));
            }
        }
    }
}

fn validate_snapshot_database_extent(
    page_count: i64,
    page_size: i64,
    maximum_bytes: u64,
) -> io::Result<(i32, u64)> {
    let page_count = i32::try_from(page_count)
        .ok()
        .filter(|count| *count >= 0)
        .ok_or_else(|| invalid_data("session consensus snapshot page count is invalid"))?;
    let page_size = u64::try_from(page_size)
        .ok()
        .filter(|size| (512..=65_536).contains(size) && size.is_power_of_two())
        .ok_or_else(|| invalid_data("session consensus snapshot page size is invalid"))?;
    let bytes = u64::try_from(page_count)
        .ok()
        .and_then(|count| count.checked_mul(page_size))
        .ok_or_else(|| invalid_data("session consensus snapshot size is invalid"))?;
    if bytes > maximum_bytes {
        return Err(invalid_data(
            "session consensus snapshot exceeds its fixed bound",
        ));
    }
    Ok((page_count, page_size))
}

fn snapshot_database_extent_sync(conn: &Connection) -> io::Result<(i32, u64)> {
    let page_count = conn
        .query_row("PRAGMA page_count", [], |row| row.get::<_, i64>(0))
        .map_err(db_error)?;
    let page_size = conn
        .query_row("PRAGMA page_size", [], |row| row.get::<_, i64>(0))
        .map_err(db_error)?;
    validate_snapshot_database_extent(page_count, page_size, SNAPSHOT_DATABASE_MAX_BYTES)
}

/// Copy one already-fixed source reader image into a descriptor-pinned raw
/// snapshot. This never performs destination cleanup or validation while the
/// source reader remains open.
#[allow(clippy::too_many_arguments)]
pub(crate) fn capture_snapshot_database_from_reader_sync(
    reader: &SnapshotReadConnection,
    identity: SessionConsensusIdentity,
    authority_profile: ConsensusAuthorityProfile,
    expected_members: &BTreeSet<SessionConsensusNodeId>,
    expected_bindings: &BTreeMap<SessionConsensusNodeId, SessionTopologyMemberBinding>,
    fixed_placement_policy: Option<PlacementResiliencePolicy>,
    expected_cut: &ConsensusAppliedMembership,
    path: &Path,
) -> io::Result<(
    ConsensusAppliedMembership,
    crate::consensus::snapshot::PinnedSqliteFile,
    u64,
)> {
    verify_snapshot_read_connection(reader)?;
    validate_existing_schema(&reader.connection, identity)
        .map_err(|_| invalid_data("session consensus snapshot source schema is invalid"))?;
    validate_durable_authority_for_raw_access(
        &reader.connection,
        identity,
        authority_profile,
        expected_members,
        expected_bindings,
        fixed_placement_policy,
    )?;
    validate_sealed_state_sync(&reader.connection)?;
    let observed_cut = snapshot_applied_membership_sync(&reader.connection, identity)?;
    if &observed_cut != expected_cut {
        return Err(invalid_data(
            "session consensus snapshot source cut differs from the live cut",
        ));
    }
    let mut pinned = create_pinned_snapshot_database(path)?;
    let mut destination = open_pinned_snapshot_database(&pinned)?;
    destination
        .execute_batch("PRAGMA journal_mode = OFF;")
        .map_err(db_error)?;
    let wal_bytes =
        backup_snapshot_reader_bounded(reader, &mut destination, SNAPSHOT_SOURCE_WAL_MAX_BYTES)?;
    drop(destination);
    pinned.capture_created_sidecars();
    Ok((observed_cut, pinned, wal_bytes))
}

/// Finish a raw snapshot only after its reader has been released.
#[allow(clippy::too_many_arguments)]
pub(crate) fn finalize_captured_snapshot_database_sync(
    identity: SessionConsensusIdentity,
    authority_profile: ConsensusAuthorityProfile,
    expected_members: &BTreeSet<SessionConsensusNodeId>,
    expected_bindings: &BTreeMap<SessionConsensusNodeId, SessionTopologyMemberBinding>,
    fixed_placement_policy: Option<PlacementResiliencePolicy>,
    expected_cut: &ConsensusAppliedMembership,
    pinned: crate::consensus::snapshot::PinnedSqliteFile,
    vacuum_path: &Path,
) -> io::Result<crate::consensus::snapshot::PinnedSqliteFile> {
    // `VACUUM` asks SQLite's VFS for a process-global temporary directory.
    // The stateful image deliberately has no writable root or `/tmp`, while
    // this UUID-named sibling is in the durable snapshot directory.  Create
    // and retain its descriptor before SQLite sees it: a bare pathname would
    // leave a replacement window and does not guarantee O_EXCL/O_NOFOLLOW.
    let mut compacted = create_pinned_snapshot_database(vacuum_path)?;
    compacted.verify_linked_identity()?;
    let vacuum_uri = pinned_snapshot_uri(&compacted, false);
    let destination = open_pinned_snapshot_database(&pinned)?;
    destination
        .execute_batch(
            r#"
        DELETE FROM consensus_vote;
        DELETE FROM consensus_committed;
        DELETE FROM consensus_purged;
        DELETE FROM consensus_log;
        DELETE FROM consensus_snapshot;
        "#,
        )
        .map_err(db_error)?;
    ops::rotate_restore_scan_epoch_sync(&destination)
        .map_err(|_| invalid_data("built session consensus snapshot restore metadata failed"))?;
    validate_existing_schema(&destination, identity)
        .map_err(|_| invalid_data("built session consensus snapshot failed validation"))?;
    validate_sealed_state_sync(&destination)?;
    let observed_cut = snapshot_applied_membership_sync(&destination, identity)?;
    if &observed_cut != expected_cut {
        return Err(invalid_data(
            "session consensus snapshot metadata differs from its captured cut",
        ));
    }
    verify_pinned_snapshot_descriptor(&pinned, &destination)?;
    drop(destination);
    // The URI resolves this process's already-pinned descriptor.  SQLite
    // accepts the pre-created empty output, and cannot create or redirect a
    // pathname outside that descriptor binding.
    let source = open_pinned_snapshot_database(&pinned)?;
    source
        .execute("VACUUM INTO ?1", params![vacuum_uri])
        .map_err(db_error)?;
    verify_pinned_snapshot_descriptor(&pinned, &source)?;
    drop(source);

    compacted.verify_linked_identity()?;
    compacted.file().sync_all()?;
    sync_snapshot_parent_directory(vacuum_path)?;
    let compacted_connection = open_pinned_snapshot_database(&compacted)?;
    validate_durable_authority_for_raw_access(
        &compacted_connection,
        identity,
        authority_profile,
        expected_members,
        expected_bindings,
        fixed_placement_policy,
    )?;
    validate_existing_schema(&compacted_connection, identity).map_err(|_| {
        invalid_data("built session consensus compacted snapshot failed validation")
    })?;
    validate_sealed_state_sync(&compacted_connection)?;
    let observed_cut = snapshot_applied_membership_sync(&compacted_connection, identity)?;
    if &observed_cut != expected_cut {
        return Err(invalid_data(
            "session consensus compacted snapshot metadata differs from its captured cut",
        ));
    }
    compacted = refresh_pinned_snapshot_database(compacted)?;
    verify_pinned_snapshot_descriptor(&compacted, &compacted_connection)?;
    if !compacted.path_matches_identity(vacuum_path)? {
        return Err(invalid_data(
            "session consensus compacted snapshot path was replaced",
        ));
    }
    drop(compacted_connection);
    compacted.capture_created_sidecars();
    Ok(compacted)
}

fn sync_snapshot_parent_directory(path: &Path) -> io::Result<()> {
    let parent = path
        .parent()
        .ok_or_else(|| invalid_data("session consensus vacuum snapshot has no parent"))?;
    File::open(parent)?.sync_all()
}

/// Capture the source image while the caller holds the SQLite transaction that
/// admitted it. The fixed-authority validation and backup therefore observe
/// the same pinned source snapshot.
fn capture_and_finalize_snapshot_database_sync(
    conn: &Connection,
    identity: SessionConsensusIdentity,
    mut pinned: crate::consensus::snapshot::PinnedSqliteFile,
    capture_hook: impl FnOnce(),
) -> io::Result<(
    ConsensusAppliedMembership,
    crate::consensus::snapshot::PinnedSqliteFile,
)> {
    validate_sealed_state_sync(conn)?;
    let applied = read_applied_sync(conn, identity)?;
    let membership = read_membership_sync(conn, identity)?;
    validate_membership_ids(&membership)?;
    capture_hook();
    let (expected_pages, page_size) = snapshot_database_extent_sync(conn)?;

    let mut destination = open_pinned_snapshot_database(&pinned)?;
    destination
        .execute_batch("PRAGMA journal_mode = OFF;")
        .map_err(db_error)?;
    {
        let backup = rusqlite::backup::Backup::new(conn, &mut destination).map_err(db_error)?;
        let mut busy_retries = 0_usize;
        let mut completed = false;
        for _ in 0..SNAPSHOT_BACKUP_STEP_LIMIT {
            let result = backup.step(SNAPSHOT_BACKUP_STEP_PAGES).map_err(db_error)?;
            let progress = backup.progress();
            if progress.remaining < 0
                || progress.pagecount != expected_pages
                || progress.remaining > progress.pagecount
                || u64::try_from(progress.pagecount)
                    .ok()
                    .and_then(|count| count.checked_mul(page_size))
                    .is_none_or(|bytes| bytes > SNAPSHOT_DATABASE_MAX_BYTES)
            {
                return Err(invalid_data(
                    "session consensus snapshot backup progress is invalid",
                ));
            }
            match result {
                StepResult::Done if progress.remaining == 0 => {
                    completed = true;
                    break;
                }
                StepResult::Done => {
                    return Err(invalid_data(
                        "session consensus snapshot backup completed inconsistently",
                    ));
                }
                StepResult::More => busy_retries = 0,
                StepResult::Busy | StepResult::Locked => {
                    busy_retries = busy_retries.saturating_add(1);
                    if busy_retries > SNAPSHOT_BACKUP_BUSY_RETRY_LIMIT {
                        return Err(invalid_data(
                            "session consensus snapshot backup remained busy",
                        ));
                    }
                }
                _ => {
                    return Err(invalid_data(
                        "session consensus snapshot backup status is invalid",
                    ));
                }
            }
        }
        if !completed {
            return Err(invalid_data(
                "session consensus snapshot backup exceeded its fixed step limit",
            ));
        }
    }
    pinned = refresh_pinned_snapshot_database(pinned)?;
    verify_pinned_snapshot_descriptor(&pinned, &destination)?;
    destination
        .execute_batch(
            r#"
            DELETE FROM consensus_vote;
            DELETE FROM consensus_committed;
            DELETE FROM consensus_purged;
            DELETE FROM consensus_log;
            DELETE FROM consensus_snapshot;
            PRAGMA journal_mode = OFF;
            VACUUM;
            "#,
        )
        .map_err(db_error)?;
    ops::rotate_restore_scan_epoch_sync(&destination)
        .map_err(|_| invalid_data("built session consensus snapshot restore metadata failed"))?;
    validate_existing_schema(&destination, identity)
        .map_err(|_| invalid_data("built session consensus snapshot failed validation"))?;
    validate_sealed_state_sync(&destination)?;
    pinned = refresh_pinned_snapshot_database(pinned)?;
    verify_pinned_snapshot_descriptor(&pinned, &destination)?;
    drop(destination);
    Ok(((applied, membership), pinned))
}

fn transition_start_is_compatible(local: u64, incoming: u64) -> bool {
    // A pristine candidate has no copy of the source log from which to derive
    // the prepare-entry index and records zero until it receives authoritative
    // state. Every non-zero locally observed index is exact and immutable.
    local == 0 || local == incoming
}

fn optional_transition_index_is_not_behind(local: Option<u64>, incoming: Option<u64>) -> bool {
    local.is_none() || local == incoming
}

fn pending_transition_is_not_behind(
    local: &PendingMembershipScope,
    incoming: &PendingMembershipScope,
) -> bool {
    local.transition_id == incoming.transition_id
        && local.transition_digest == incoming.transition_digest
        && local.desired_identity == incoming.desired_identity
        && local.desired_members == incoming.desired_members
        && local.desired_bindings == incoming.desired_bindings
        && transition_start_is_compatible(
            local.transition_start_log_index,
            incoming.transition_start_log_index,
        )
        && optional_transition_index_is_not_behind(
            local.learners_ready_log_index,
            incoming.learners_ready_log_index,
        )
        && optional_transition_index_is_not_behind(
            local.joint_membership_log_index,
            incoming.joint_membership_log_index,
        )
        && optional_transition_index_is_not_behind(
            local.uniform_membership_log_index,
            incoming.uniform_membership_log_index,
        )
}

fn terminal_matches_pending_progress(
    local: &PendingMembershipScope,
    terminal: &TerminalMembershipTransition,
) -> bool {
    let abort_scope_matches = match terminal.outcome {
        TerminalMembershipOutcome::Aborted => {
            terminal.abort_cleanup.as_ref().is_some_and(|cleanup| {
                cleanup.desired_identity == local.desired_identity
                    && cleanup.desired_members == local.desired_members
                    && cleanup.desired_bindings == local.desired_bindings
            })
        }
        TerminalMembershipOutcome::Promoted => terminal.abort_cleanup.is_none(),
    };
    local.transition_id == terminal.transition_id
        && local.transition_digest == terminal.transition_digest
        && abort_scope_matches
        && transition_start_is_compatible(
            local.transition_start_log_index,
            terminal.transition_start_log_index,
        )
        && optional_transition_index_is_not_behind(
            local.learners_ready_log_index,
            terminal.learners_ready_log_index,
        )
        && optional_transition_index_is_not_behind(
            local.joint_membership_log_index,
            terminal.joint_membership_log_index,
        )
        && optional_transition_index_is_not_behind(
            local.uniform_membership_log_index,
            terminal.uniform_membership_log_index,
        )
}

fn finalized_terminal_is_not_behind(
    local: &TerminalMembershipTransition,
    incoming: &TerminalMembershipTransition,
) -> bool {
    let abort_cleanup_is_not_behind = match (&local.abort_cleanup, &incoming.abort_cleanup) {
        (None, None) => true,
        (Some(local), Some(incoming)) => {
            local.desired_identity == incoming.desired_identity
                && local.desired_members == incoming.desired_members
                && local.desired_bindings == incoming.desired_bindings
                && local.learners == incoming.learners
                && local.decision_log_index == incoming.decision_log_index
                && (local.cleanup_log_index.is_none()
                    || local.cleanup_log_index == incoming.cleanup_log_index)
        }
        (None, Some(_)) | (Some(_), None) => false,
    };
    local.transition_id == incoming.transition_id
        && local.transition_digest == incoming.transition_digest
        && local.outcome == incoming.outcome
        && local.transition_start_log_index == incoming.transition_start_log_index
        && local.learners_ready_log_index == incoming.learners_ready_log_index
        && local.joint_membership_log_index == incoming.joint_membership_log_index
        && local.uniform_membership_log_index == incoming.uniform_membership_log_index
        && local.cutover_log_index == incoming.cutover_log_index
        && abort_cleanup_is_not_behind
        && (local.finalization_log_index.is_none()
            || local.finalization_log_index == incoming.finalization_log_index)
}

fn retained_lineage_is_not_behind(
    local_history: &[MembershipPredecessorScope],
    local_predecessor: Option<&MembershipPredecessorScope>,
    incoming_history: &[MembershipPredecessorScope],
    incoming_predecessor: Option<&MembershipPredecessorScope>,
) -> bool {
    let local_is_empty = local_history.is_empty() && local_predecessor.is_none();
    let incoming_is_compacted = incoming_history.is_empty() && incoming_predecessor.is_none();
    let exact_lineage = local_history
        .iter()
        .chain(local_predecessor)
        .eq(incoming_history.iter().chain(incoming_predecessor));
    local_is_empty || incoming_is_compacted || exact_lineage
}

fn retained_terminal_history_is_not_behind(
    local: &[RetainedTerminalMembershipTransition],
    incoming: &[RetainedTerminalMembershipTransition],
) -> bool {
    local.iter().all(|local_terminal| {
        incoming
            .iter()
            .any(|incoming_terminal| incoming_terminal == local_terminal)
    })
}

fn retained_terminal_state_is_not_behind(
    local: &MembershipValidationScope,
    incoming: &MembershipValidationScope,
) -> bool {
    let Some(local_terminal) = local.terminal.as_ref() else {
        return true;
    };
    if incoming.terminal.as_ref().is_some_and(|incoming_terminal| {
        finalized_terminal_is_not_behind(local_terminal, incoming_terminal)
    }) {
        return true;
    }
    completed_terminal_from_scope(local)
        .ok()
        .flatten()
        .is_some_and(|local_terminal| {
            incoming
                .terminal_history
                .iter()
                .any(|incoming_terminal| incoming_terminal == &local_terminal)
        })
}

fn incoming_lineage_contains_current_scope(
    local: &MembershipValidationScope,
    incoming: &MembershipValidationScope,
) -> bool {
    incoming
        .history
        .iter()
        .chain(incoming.predecessor.iter())
        .any(|predecessor| {
            predecessor.identity == local.current_identity
                && predecessor.members == local.current_members
        })
}

fn incoming_lineage_contains_pending_transition(
    local: &MembershipValidationScope,
    pending: &PendingMembershipScope,
    incoming: &MembershipValidationScope,
) -> bool {
    let lineage = incoming
        .history
        .iter()
        .chain(incoming.predecessor.iter())
        .collect::<Vec<_>>();
    lineage.iter().enumerate().any(|(offset, predecessor)| {
        let successor_identity = lineage
            .get(offset + 1)
            .map_or(incoming.current_identity, |next| next.identity);
        let successor_members = lineage
            .get(offset + 1)
            .map_or(&incoming.current_members, |next| &next.members);
        predecessor.identity == local.current_identity
            && predecessor.members == local.current_members
            && predecessor.transition_id == pending.transition_id
            && predecessor.transition_digest == pending.transition_digest
            && transition_start_is_compatible(
                pending.transition_start_log_index,
                predecessor.transition_start_log_index,
            )
            && successor_identity == pending.desired_identity
            && successor_members == &pending.desired_members
    })
}

fn validate_incoming_membership_scope(
    local: &MembershipValidationScope,
    incoming: &MembershipValidationScope,
) -> io::Result<()> {
    if local == incoming {
        return Ok(());
    }
    if local.current_identity.cluster_id() != incoming.current_identity.cluster_id() {
        return Err(invalid_data(
            "session consensus snapshot membership cluster mismatch",
        ));
    }
    if !retained_terminal_history_is_not_behind(&local.terminal_history, &incoming.terminal_history)
        || !retained_terminal_state_is_not_behind(local, incoming)
    {
        return Err(invalid_data(
            "session consensus snapshot terminal history regressed or diverged",
        ));
    }

    if local.pending.is_none()
        && incoming.pending.is_none()
        && local.current_identity == incoming.current_identity
        && local.current_members == incoming.current_members
        && local.application_authority_epoch == incoming.application_authority_epoch
        && local.application_authority_members == incoming.application_authority_members
        && retained_lineage_is_not_behind(
            &local.history,
            local.predecessor.as_ref(),
            &incoming.history,
            incoming.predecessor.as_ref(),
        )
    {
        return Ok(());
    }

    if local.pending.is_none()
        && incoming.pending.is_some()
        && local.current_identity == incoming.current_identity
        && local.current_members == incoming.current_members
        && retained_lineage_is_not_behind(
            &local.history,
            local.predecessor.as_ref(),
            &incoming.history,
            incoming.predecessor.as_ref(),
        )
    {
        return Ok(());
    }

    if local.pending.is_none()
        && incoming.current_identity.configuration_epoch()
            > local.current_identity.configuration_epoch()
        && incoming_lineage_contains_current_scope(local, incoming)
    {
        return Ok(());
    }

    if let Some(local_pending) = local.pending.as_ref() {
        if incoming.current_identity.configuration_epoch()
            > local.current_identity.configuration_epoch()
            && incoming_lineage_contains_pending_transition(local, local_pending, incoming)
        {
            return Ok(());
        }
    }

    let Some(local_pending) = local.pending.as_ref() else {
        return Err(invalid_data(
            "session consensus snapshot membership scope regressed or diverged",
        ));
    };
    if let Some(incoming_pending) = incoming.pending.as_ref() {
        let same_current = incoming.current_identity == local.current_identity
            && incoming.current_members == local.current_members
            && retained_lineage_is_not_behind(
                &local.history,
                local.predecessor.as_ref(),
                &incoming.history,
                incoming.predecessor.as_ref(),
            );
        let authority_not_behind = local.application_authority_epoch
            == local.current_identity.configuration_epoch()
            || (incoming.application_authority_epoch
                == local_pending.desired_identity.configuration_epoch()
                && incoming.application_authority_members == local_pending.desired_members);
        if same_current
            && authority_not_behind
            && pending_transition_is_not_behind(local_pending, incoming_pending)
        {
            return Ok(());
        }
        return Err(invalid_data(
            "session consensus snapshot pending transition regressed or diverged",
        ));
    }

    let terminal = incoming.terminal.as_ref().ok_or_else(|| {
        invalid_data("session consensus snapshot lost pending transition evidence")
    })?;
    if !terminal_matches_pending_progress(local_pending, terminal) {
        return Err(invalid_data(
            "session consensus snapshot terminal transition diverged",
        ));
    }

    match terminal.outcome {
        TerminalMembershipOutcome::Aborted => {
            let restored = incoming.current_identity == local.current_identity
                && incoming.current_members == local.current_members
                && incoming.application_authority_epoch
                    == local.current_identity.configuration_epoch()
                && incoming.application_authority_members == local.current_members
                && incoming.predecessor.is_none()
                && terminal.cutover_log_index.is_none();
            if restored {
                Ok(())
            } else {
                Err(invalid_data(
                    "session consensus snapshot abort scope is inconsistent",
                ))
            }
        }
        TerminalMembershipOutcome::Promoted => {
            let predecessor_matches = incoming.predecessor.as_ref().is_some_and(|predecessor| {
                predecessor.transition_id == local_pending.transition_id
                    && predecessor.transition_digest == local_pending.transition_digest
                    && predecessor.identity == local.current_identity
                    && predecessor.members == local.current_members
                    && transition_start_is_compatible(
                        local_pending.transition_start_log_index,
                        predecessor.transition_start_log_index,
                    )
                    && terminal.cutover_log_index == Some(predecessor.cutover_log_index)
            });
            let promoted = incoming.current_identity == local_pending.desired_identity
                && incoming.current_members == local_pending.desired_members
                && incoming.application_authority_epoch
                    == local_pending.desired_identity.configuration_epoch()
                && incoming.application_authority_members == local_pending.desired_members
                && retained_lineage_is_not_behind(
                    &local.history,
                    local.predecessor.as_ref(),
                    &incoming.history,
                    None,
                )
                && predecessor_matches;
            if promoted {
                Ok(())
            } else {
                Err(invalid_data(
                    "session consensus snapshot promotion scope is inconsistent",
                ))
            }
        }
    }
}

fn validate_fixed_immutable_membership_scope(
    storage_identity: SessionConsensusIdentity,
    expected: &MembershipValidationScope,
    incoming: &MembershipValidationScope,
) -> io::Result<()> {
    let exact_fixed_scope = incoming == expected
        && incoming.current_identity == storage_identity
        && matches!(incoming.current_members.len(), 3 | 5)
        && incoming.current_bindings.len() == incoming.current_members.len()
        && incoming
            .current_bindings
            .keys()
            .copied()
            .collect::<BTreeSet<_>>()
            == incoming.current_members
        && incoming.application_authority_epoch == storage_identity.configuration_epoch()
        && incoming.application_authority_members == incoming.current_members
        && incoming.predecessor.is_none()
        && incoming.history.is_empty()
        && incoming.terminal_history.is_empty()
        && incoming.pending.is_none()
        && incoming.terminal.is_none();
    if exact_fixed_scope {
        Ok(())
    } else {
        Err(invalid_data(
            "fixed session consensus snapshot membership scope is not exact",
        ))
    }
}

