    #[test]
    fn fenced_transition_v2_closed_epoch_integrity_is_fail_closed() {
        const SMALL_MAXIMUM: u64 = 4;

        assert!(fenced_transition_v2_closed_epoch_is_exact_with_maximum(
            2,
            2,
            None,
            None,
            None,
            1,
            SMALL_MAXIMUM,
        ));
        assert!(!fenced_transition_v2_closed_epoch_is_exact_with_maximum(
            1,
            2,
            None,
            None,
            None,
            3,
            SMALL_MAXIMUM,
        ));
        assert!(fenced_transition_v2_closed_epoch_is_exact_with_maximum(
            1,
            2,
            None,
            None,
            None,
            4,
            SMALL_MAXIMUM,
        ));
        assert!(!fenced_transition_v2_closed_epoch_is_exact_with_maximum(
            1,
            2,
            Some(1),
            Some(0),
            Some(3),
            3,
            SMALL_MAXIMUM,
        ));
        assert!(!fenced_transition_v2_closed_epoch_is_exact_with_maximum(
            1,
            2,
            Some(1),
            Some(1),
            Some(2),
            2,
            SMALL_MAXIMUM,
        ));
        assert!(fenced_transition_v2_closed_epoch_is_exact_with_maximum(
            1,
            2,
            Some(1),
            Some(1),
            Some(3),
            3,
            SMALL_MAXIMUM,
        ));
    }

