    #[tokio::test]
    async fn limited_log_read_crossing_purged_floor_starts_after_the_floor() {
        let backend = backend_with_blank_logs(3).await;
        let conn = backend.conn.lock().await;
        let applied = vec![
            membership_entry(),
            blank_entry(1),
            blank_entry(2),
            blank_entry(3),
        ];
        apply_entries_sync(&conn, identity(), &backend.caps, applied).expect("apply log fixtures");
        purge_logs_sync(&conn, identity(), &log_id(1)).expect("purge applied prefix");

        let entries = read_limited_log_range_sync(
            &conn,
            identity(),
            0,
            4,
            opc_consensus::DURABLE_OPENRAFT_MAX_PAYLOAD_ENTRIES,
        )
        .expect("range crosses purged floor");
        assert_eq!(
            entries
                .iter()
                .map(|entry| entry.log_id.index)
                .collect::<Vec<_>>(),
            vec![2, 3]
        );
    }

    fn acquire_entry(
        index: u64,
        request_id: [u8; 16],
        owner: &'static str,
    ) -> Entry<SessionRaftTypeConfig> {
        Entry {
            log_id: log_id(index),
            payload: EntryPayload::Normal(SessionConsensusCommand {
                schema_version: SESSION_CONSENSUS_SCHEMA_VERSION,
                identity: identity(),
                request_id: SessionConsensusRequestId::from_bytes(request_id),
                logical_time: timestamp(u8::try_from(index).expect("test index fits timestamp")),
                intent: SessionMutationIntent::AcquireLease {
                    key: key(),
                    owner: OwnerId::new(owner).expect("owner"),
                    ttl: Duration::from_secs(300),
                },
            }),
        }
    }

    fn fenced_transition_request_with_payload(
        request_byte: u8,
        owner: &'static str,
        payload_len: usize,
    ) -> FencedTransitionRequest {
        let owner = OwnerId::new(owner).expect("owner");
        let lease = FencedTransitionLease::acquire(
            key(),
            owner.clone(),
            crate::FenceToken::new(0),
            Duration::from_secs(300),
        )
        .expect("valid fenced lease");
        let mut record = sealed_record_for_key(key(), payload_len);
        record.owner = owner;
        record.fence = crate::FenceToken::new(1);
        FencedTransitionRequest::new(
            crate::FencedTransitionRequestId::from_bytes([request_byte; 16]),
            lease,
            FencedTransitionMutation::create(record),
        )
        .expect("valid fenced transition")
    }

    fn fenced_transition_request(request_byte: u8, owner: &'static str) -> FencedTransitionRequest {
        fenced_transition_request_with_payload(request_byte, owner, 1_024)
    }

    fn finite_fenced_transition_create_request(
        request_byte: u8,
        owner: &'static str,
        expires_at: Timestamp,
    ) -> FencedTransitionRequest {
        let owner = OwnerId::new(owner).expect("owner");
        let lease = FencedTransitionLease::acquire(
            key(),
            owner.clone(),
            crate::FenceToken::new(0),
            Duration::from_secs(300),
        )
        .expect("valid fenced lease");
        let mut record = sealed_record_for_key(key(), 1_024);
        record.owner = owner;
        record.fence = lease.committed_fence().expect("committed fence");
        record.expires_at = Some(expires_at);
        record.payload = sealed_payload_for_record(&record, 1_024);
        FencedTransitionRequest::new(
            crate::FencedTransitionRequestId::from_bytes([request_byte; 16]),
            lease,
            FencedTransitionMutation::create(record),
        )
        .expect("finite fenced transition")
    }

    fn fenced_transition_entry(
        index: u64,
        request: FencedTransitionRequest,
        logical_time: Timestamp,
    ) -> Entry<SessionRaftTypeConfig> {
        fenced_transition_entry_for_voters(index, request, logical_time, &expected_members())
    }

    fn fenced_transition_entry_for_voters(
        index: u64,
        request: FencedTransitionRequest,
        logical_time: Timestamp,
        voters: &BTreeSet<SessionConsensusNodeId>,
    ) -> Entry<SessionRaftTypeConfig> {
        activating_fenced_transition_authorized_entry(
            index,
            request,
            logical_time,
            node_id(),
            identity(),
            identity(),
            voters,
        )
    }

    fn fenced_transition_authorized_entry(
        index: u64,
        request: FencedTransitionRequest,
        logical_time: Timestamp,
        origin: SessionConsensusNodeId,
        authority_identity: SessionConsensusIdentity,
    ) -> Entry<SessionRaftTypeConfig> {
        Entry {
            log_id: log_id(index),
            payload: EntryPayload::Normal(SessionConsensusCommand {
                schema_version: SESSION_CONSENSUS_SCHEMA_VERSION,
                identity: identity(),
                request_id: SessionConsensusRequestId::from_bytes(*request.request_id().as_bytes()),
                logical_time,
                intent: SessionMutationIntent::Authorized {
                    origin,
                    authority_identity,
                    mutation: Box::new(SessionMutationIntent::FencedTransition(Box::new(request))),
                },
            }),
        }
    }

    fn activating_fenced_transition_authorized_entry(
        index: u64,
        request: FencedTransitionRequest,
        logical_time: Timestamp,
        origin: SessionConsensusNodeId,
        authority_identity: SessionConsensusIdentity,
        scope_identity: SessionConsensusIdentity,
        voters: &BTreeSet<SessionConsensusNodeId>,
    ) -> Entry<SessionRaftTypeConfig> {
        Entry {
            log_id: log_id(index),
            payload: EntryPayload::Normal(SessionConsensusCommand {
                schema_version: SESSION_CONSENSUS_SCHEMA_VERSION,
                identity: identity(),
                request_id: SessionConsensusRequestId::from_bytes(*request.request_id().as_bytes()),
                logical_time,
                intent: SessionMutationIntent::Authorized {
                    origin,
                    authority_identity,
                    mutation: Box::new(SessionMutationIntent::ActivateFencedTransition {
                        request: Box::new(request),
                        scope_identity,
                        voter_set_digest: fenced_transition_voter_set_digest(
                            scope_identity,
                            voters,
                        ),
                    }),
                },
            }),
        }
    }

    fn fenced_transition_v2_request(
        request_byte: u8,
        epoch: u64,
        owner: &'static str,
    ) -> FencedTransitionV2Request {
        let request = fenced_transition_request(request_byte, owner);
        FencedTransitionV2Request::new(
            FencedTransitionV2HistoryEpoch::new(epoch).expect("valid V2 epoch"),
            crate::fenced_transition::FencedTransitionV2CallerNonce::from_bytes([request_byte; 16]),
            request.lease().clone(),
            request.mutation().clone(),
        )
        .expect("valid V2 fenced transition")
    }

    fn altered_fenced_transition_v2_request(
        request: &FencedTransitionV2Request,
    ) -> FencedTransitionV2Request {
        // Keep the durable full ID while substituting a body field, exactly as
        // an untrusted decoded caller request could do.  V2 materializes this
        // structurally valid value so persistence can return the committed
        // RequestConflict before every receipt/floor lookup.
        let mut encoded = serde_json::to_value(request).expect("serialize V2 request");
        let record = encoded
            .get_mut("mutation")
            .and_then(serde_json::Value::as_object_mut)
            .and_then(|mutation| mutation.get_mut("create"))
            .and_then(serde_json::Value::as_object_mut)
            .and_then(|create| create.get_mut("record"))
            .and_then(serde_json::Value::as_object_mut)
            .expect("V2 create request record");
        record.insert(
            "state_type".to_owned(),
            serde_json::Value::String("altered-v2-state".to_owned()),
        );
        serde_json::from_value(encoded).expect("deserialize altered V2 request")
    }

